CREATE OR REPLACE FUNCTION "public"."_allocate_business_slug_token_v1"("desired" "text", "current_business_id" "uuid") RETURNS "text"
    LANGUAGE "plpgsql"
    AS $$
declare
  base_slug text := coalesce(
    public._normalize_public_slug_v1(desired),
    substr(coalesce(current_business_id::text, gen_random_uuid()::text), 1, 12)
  );
  candidate text := base_slug;
  suffix int := 0;
begin
  while exists (
    select 1
    from public.businesses b
    where (current_business_id is null or b.id <> current_business_id)
      and (
        lower(coalesce(b.slug, '')) = lower(candidate)
        or lower(coalesce(b.public_slug, '')) = lower(candidate)
      )
  ) loop
    suffix := suffix + 1;
    candidate := base_slug || '-' || suffix::text;
  end loop;

  return candidate;
end;
$$;


ALTER FUNCTION "public"."_allocate_business_slug_token_v1"("desired" "text", "current_business_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_assign_business_public_slug_v1"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
declare
  base_slug text;
  candidate text;
  suffix int := 0;
begin
  base_slug := coalesce(
    public._normalize_public_slug_v1(new.public_slug),
    public._normalize_public_slug_v1(new.slug),
    public._normalize_public_slug_v1(new.name),
    substr(coalesce(new.id::text, gen_random_uuid()::text), 1, 12)
  );

  candidate := base_slug;
  while exists (
    select 1
    from public.businesses b
    where lower(b.public_slug) = lower(candidate)
      and (new.id is null or b.id <> new.id)
  ) loop
    suffix := suffix + 1;
    candidate := base_slug || '-' || suffix::text;
  end loop;

  new.public_slug := candidate;
  return new;
end;
$$;


ALTER FUNCTION "public"."_assign_business_public_slug_v1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_assign_business_public_slug_v2"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
declare
  desired text;
  candidate text;
begin
  desired := coalesce(new.public_slug, new.slug, new.name, new.id::text);
  candidate := public._allocate_business_slug_token_v1(desired, new.id);

  -- Web resolver'i slug ve public_slug alanlarini ayni public token olarak ele alir.
  new.slug := candidate;
  new.public_slug := candidate;
  return new;
end;
$$;


ALTER FUNCTION "public"."_assign_business_public_slug_v2"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_normalize_public_slug_v1"("input" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    AS $$
  select nullif(
    trim(
      both '-'
      from regexp_replace(
        regexp_replace(lower(coalesce(input, '')), '[^a-z0-9]+', '-', 'g'),
        '-{2,}',
        '-',
        'g'
      )
    ),
    ''
  )
$$;


ALTER FUNCTION "public"."_normalize_public_slug_v1"("input" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."accept_group_offer_v1"("p_offer_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_request_id uuid;
  v_request_owner uuid;
begin
  select o.request_id, r.created_by
  into v_request_id, v_request_owner
  from public.group_offers o
  join public.group_requests r on r.id = o.request_id
  where o.id = p_offer_id;

  if v_request_id is null then
    return jsonb_build_object('ok', false, 'code', 'not_found');
  end if;
  if v_request_owner <> auth.uid() and not public.is_admin() then
    return jsonb_build_object('ok', false, 'code', 'not_owner');
  end if;

  update public.group_requests
    set status = 'awarded'
    where id = v_request_id;

  update public.group_offers
    set status = case when id = p_offer_id then 'accepted' else 'rejected' end
    where request_id = v_request_id
      and status in ('submitted','accepted');

  return jsonb_build_object('ok', true);
end;
$$;


ALTER FUNCTION "public"."accept_group_offer_v1"("p_offer_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."add_business_media_v1"("p_business_id" "uuid", "p_url" "text", "p_url_large" "text" DEFAULT NULL::"text", "p_url_thumb" "text" DEFAULT NULL::"text", "p_provider" "text" DEFAULT 'wp'::"text", "p_kind" "text" DEFAULT 'venue'::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_shadow boolean := false;
  v_rate jsonb;
begin
  if auth.uid() is null then
    return jsonb_build_object('ok', false, 'error', 'not_authenticated');
  end if;

  if p_business_id is null then
    return jsonb_build_object('ok', false, 'error', 'missing_business_id');
  end if;

  v_rate := public.consume_rate_limit_v1('business_media', 15);
  if coalesce((v_rate->>'ok')::boolean, false) is false then
    return jsonb_build_object('ok', false, 'error', 'business_media_daily_rate_limited');
  end if;

  v_shadow := public.is_shadow_banned_v1();

  insert into public.business_media(
    business_id, kind, url, url_large, url_thumb, provider, created_by, is_shadow
  ) values (
    p_business_id, coalesce(p_kind, 'venue'), p_url, p_url_large, p_url_thumb, p_provider, auth.uid(), v_shadow
  );

  return jsonb_build_object('ok', true, 'shadowed', v_shadow);
end;
$$;


ALTER FUNCTION "public"."add_business_media_v1"("p_business_id" "uuid", "p_url" "text", "p_url_large" "text", "p_url_thumb" "text", "p_provider" "text", "p_kind" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."add_menu_item_photo_v1"("p_menu_item_id" "uuid", "p_url" "text", "p_url_large" "text" DEFAULT NULL::"text", "p_url_thumb" "text" DEFAULT NULL::"text", "p_provider" "text" DEFAULT 'supabase_storage'::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_business_id uuid;
  v_photo_id uuid;
  v_shadow boolean := false;
  v_rate jsonb;
begin
  if auth.uid() is null then
    return jsonb_build_object('ok', false, 'error', 'not_authenticated');
  end if;

  select business_id into v_business_id
  from public.menu_items
  where id = p_menu_item_id;

  if v_business_id is null then
    return jsonb_build_object('ok', false, 'error', 'not_found');
  end if;

  v_rate := public.consume_rate_limit_v1('menu_photo', 20);
  if coalesce((v_rate->>'ok')::boolean, false) is false then
    return jsonb_build_object('ok', false, 'error', 'menu_photo_daily_rate_limited');
  end if;

  v_shadow := public.is_shadow_banned_v1();

  insert into public.menu_item_photos(
    menu_item_id,
    business_id,
    url,
    url_large,
    url_thumb,
    provider,
    created_by,
    is_shadow,
    status,
    is_hidden
  )
  values (
    p_menu_item_id,
    v_business_id,
    p_url,
    p_url_large,
    p_url_thumb,
    p_provider,
    auth.uid(),
    v_shadow,
    'pending',
    false
  )
  returning id into v_photo_id;

  return jsonb_build_object('ok', true, 'photo_id', v_photo_id, 'shadowed', v_shadow, 'pending', true);
end;
$$;


ALTER FUNCTION "public"."add_menu_item_photo_v1"("p_menu_item_id" "uuid", "p_url" "text", "p_url_large" "text", "p_url_thumb" "text", "p_provider" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."add_moderation_strike_v1"("p_user_id" "uuid", "p_reason" "text" DEFAULT NULL::"text", "p_source" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_recent int := 0;
  v_shadow boolean := false;
begin
  if p_user_id is null then
    return jsonb_build_object('ok', false, 'error', 'missing_user');
  end if;

  insert into public.user_moderation_strikes(user_id, reason, source)
  values (p_user_id, nullif(trim(p_reason), ''), nullif(trim(p_source), ''));

  select count(*) into v_recent
  from public.user_moderation_strikes s
  where s.user_id = p_user_id
    and s.created_at >= now() - interval '30 days';

  if v_recent >= 3 then
    update public.user_profiles
    set shadow_banned = true
    where user_id = p_user_id;
    v_shadow := true;
  end if;

  return jsonb_build_object(
    'ok', true,
    'recent_strikes_30d', v_recent,
    'shadow_banned', v_shadow
  );
end;
$$;


ALTER FUNCTION "public"."add_moderation_strike_v1"("p_user_id" "uuid", "p_reason" "text", "p_source" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."add_to_collection_v1"("p_collection_id" "uuid", "p_business_id" "uuid", "p_note" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  if not exists (
    select 1 from public.collections c
    where c.id = p_collection_id and c.user_id = auth.uid()
  ) then
    return jsonb_build_object('ok', false, 'code', 'not_owner');
  end if;

  insert into public.collection_items (collection_id, business_id, note)
  values (p_collection_id, p_business_id, p_note)
  on conflict (collection_id, business_id) do update set note = excluded.note;

  return jsonb_build_object('ok', true);
end;
$$;


ALTER FUNCTION "public"."add_to_collection_v1"("p_collection_id" "uuid", "p_business_id" "uuid", "p_note" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_apply_user_safety_action_v1"("p_user_id" "uuid", "p_action" "text", "p_minutes" integer DEFAULT 60, "p_reason" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_action text := lower(trim(coalesce(p_action, '')));
  v_until timestamptz := now() + make_interval(mins => greatest(p_minutes, 1));
  v_reason text := nullif(trim(coalesce(p_reason, '')), '');
begin
  if not public.is_admin() then
    return jsonb_build_object('ok', false, 'error', 'forbidden');
  end if;

  if p_user_id is null then
    return jsonb_build_object('ok', false, 'error', 'missing_user_id');
  end if;

  if v_reason is null then
    return jsonb_build_object('ok', false, 'error', 'reason_required');
  end if;

  insert into public.user_safety_actions(user_id, updated_at)
  values (p_user_id, now())
  on conflict (user_id) do nothing;

  if v_action = 'soft_limit' then
    update public.user_safety_actions
      set soft_limited_until = greatest(coalesce(soft_limited_until, now()), v_until),
          updated_at = now()
    where user_id = p_user_id;
  elsif v_action = 'auto_pending' then
    update public.user_safety_actions
      set auto_pending_until = greatest(coalesce(auto_pending_until, now()), v_until),
          updated_at = now()
    where user_id = p_user_id;
  elsif v_action = 'shadow_ban' then
    update public.user_safety_actions
      set shadow_banned_until = greatest(coalesce(shadow_banned_until, now()), v_until),
          auto_pending_until = greatest(coalesce(auto_pending_until, now()), v_until),
          updated_at = now()
    where user_id = p_user_id;
    update public.user_profiles
      set shadow_banned = true
    where user_id = p_user_id;
  elsif v_action = 'clear' then
    update public.user_safety_actions
      set soft_limited_until = null,
          auto_pending_until = null,
          shadow_banned_until = null,
          updated_at = now()
    where user_id = p_user_id;
    update public.user_profiles
      set shadow_banned = false
    where user_id = p_user_id;
  else
    return jsonb_build_object('ok', false, 'error', 'bad_action');
  end if;

  insert into public.admin_audit_log(action, target_table, target_id, meta)
  values (
    'user.safety_action',
    'user_profiles',
    p_user_id::text,
    jsonb_build_object(
      'actor_id', auth.uid(),
      'action', v_action,
      'minutes', greatest(p_minutes, 1),
      'reason', v_reason
    )
  );

  return jsonb_build_object('ok', true);
end;
$$;


ALTER FUNCTION "public"."admin_apply_user_safety_action_v1"("p_user_id" "uuid", "p_action" "text", "p_minutes" integer, "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_approve_business_submission_v1"("p_submission_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_sub record;
  v_business_id uuid;
begin
  if not public.is_admin() then
    return jsonb_build_object('ok', false, 'error', 'not_admin');
  end if;

  select *
    into v_sub
  from public.business_submissions
  where id = p_submission_id;

  if not found then
    return jsonb_build_object('ok', false, 'error', 'not_found');
  end if;

  if v_sub.status <> 'new' then
    return jsonb_build_object('ok', false, 'error', 'invalid_status');
  end if;

  insert into public.businesses(
    name, category, address, city, district, phone, source, source_id
  )
  values (
    v_sub.name, v_sub.category, v_sub.address, v_sub.city, v_sub.district, v_sub.phone,
    'submission', v_sub.id::text
  )
  returning id into v_business_id;

  insert into public.owner_claims(
    business_id, user_id, status, created_at
  )
  values (
    v_business_id, v_sub.submitted_by, 'approved', now()
  )
  on conflict do nothing;

  update public.business_submissions
  set status = 'approved'
  where id = v_sub.id;

  return jsonb_build_object('ok', true, 'business_id', v_business_id);
end;
$$;


ALTER FUNCTION "public"."admin_approve_business_submission_v1"("p_submission_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_approve_business_suggestion_v1"("p_suggestion_id" "uuid", "p_admin_note" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_s public.business_suggestions%rowtype;
  v_new_business_id uuid;
begin
  if not public.is_admin() then
    raise exception 'not_admin';
  end if;

  select *
  into v_s
  from public.business_suggestions
  where id = p_suggestion_id;

  if v_s.id is null then
    return jsonb_build_object('ok', false, 'error', 'suggestion_not_found');
  end if;

  if v_s.status <> 'pending' then
    return jsonb_build_object('ok', false, 'error', 'not_pending');
  end if;

  insert into public.businesses (
    name,
    category,
    address,
    city,
    district,
    lat,
    lng
  ) values (
    v_s.name,
    v_s.category,
    v_s.address,
    v_s.city,
    v_s.district,
    null,
    null
  )
  returning id into v_new_business_id;

  update public.business_suggestions
  set
    status = 'approved',
    approved_business_id = v_new_business_id,
    admin_note = p_admin_note,
    handled_by = auth.uid(),
    handled_at = now()
  where id = p_suggestion_id;

  -- 🔍 AUDIT LOG
  perform public.log_admin_action_v1(
    'suggestion.approve',
    'business_suggestions',
    p_suggestion_id,
    jsonb_build_object(
      'business_id', v_new_business_id,
      'admin_note', p_admin_note
    )
  );

  return jsonb_build_object(
    'ok', true,
    'business_id', v_new_business_id
  );
end;
$$;


ALTER FUNCTION "public"."admin_approve_business_suggestion_v1"("p_suggestion_id" "uuid", "p_admin_note" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_approve_menu_price_suggestion_v1"("p_suggestion_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_item_id uuid;
  v_business_id uuid;
  v_new integer;
  v_old integer;
  v_cur text;
  v_before jsonb;
  v_after jsonb;
begin
  if not public.is_admin() then
    return jsonb_build_object('ok', false, 'error', 'not_admin');
  end if;

  select
    s.menu_item_id,
    s.business_id,
    s.suggested_price_cents,
    s.currency,
    jsonb_build_object(
      'business_id', s.business_id,
      'menu_item_id', s.menu_item_id,
      'status', s.status,
      'current_price_cents', mi.price_cents,
      'suggested_price_cents', s.suggested_price_cents,
      'currency', s.currency,
      'note', s.note
    )
  into v_item_id, v_business_id, v_new, v_cur, v_before
  from public.menu_item_price_suggestions s
  join public.menu_items mi on mi.id = s.menu_item_id
  where s.id = p_suggestion_id
    and s.status = 'pending';

  if v_item_id is null then
    return jsonb_build_object('ok', false, 'error', 'not_found_or_not_pending');
  end if;

  select price_cents into v_old
  from public.menu_items
  where id = v_item_id;

  update public.menu_items
  set price_cents = v_new,
      currency = v_cur,
      updated_at = now()
  where id = v_item_id;

  update public.menu_item_price_suggestions
  set status = 'approved',
      handled_by = auth.uid(),
      handled_at = now()
  where id = p_suggestion_id;

  insert into public.menu_item_price_history(
    menu_item_id,
    price_cents,
    currency,
    source,
    created_by
  )
  values (
    v_item_id,
    v_new,
    v_cur,
    'suggestion',
    auth.uid()
  );

  v_after := jsonb_build_object(
    'business_id', v_business_id,
    'menu_item_id', v_item_id,
    'status', 'approved',
    'previous_price_cents', v_old,
    'new_price_cents', v_new,
    'currency', v_cur,
    'handled_by', auth.uid()
  );

  perform public.insert_audit_log_v1(
    'price_suggestion.approved',
    'menu_item_price_suggestions',
    p_suggestion_id,
    v_before,
    v_after
  );

  return jsonb_build_object('ok', true, 'old_price_cents', v_old, 'new_price_cents', v_new);
end;
$$;


ALTER FUNCTION "public"."admin_approve_menu_price_suggestion_v1"("p_suggestion_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_approve_mission_claim_v1"("p_claim_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_user_id uuid;
  v_points int;
begin
  if not public.is_admin() then
    return jsonb_build_object('ok', false, 'code', 'not_admin');
  end if;

  select c.user_id, m.reward_points
    into v_user_id, v_points
  from public.user_mission_claims c
  join public.photo_missions m on m.id = c.mission_id
  where c.id = p_claim_id;

  if v_user_id is null then
    return jsonb_build_object('ok', false, 'code', 'not_found');
  end if;

  update public.user_mission_claims
  set status = 'approved',
      updated_at = now()
  where id = p_claim_id;

  insert into public.user_points(user_id, points, updated_at)
  values (v_user_id, coalesce(v_points, 0), now())
  on conflict (user_id) do update
    set points = public.user_points.points + coalesce(excluded.points, 0),
        updated_at = now();

  return jsonb_build_object('ok', true);
end;
$$;


ALTER FUNCTION "public"."admin_approve_mission_claim_v1"("p_claim_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_approve_price_suggestion_v1"("p_suggestion_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  return public.admin_approve_menu_price_suggestion_v1(p_suggestion_id);
