CREATE OR REPLACE FUNCTION "public"."admin_bulk_update_reports_status_v2"("p_report_ids" "uuid"[], "p_status" "text", "p_admin_note" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_count int;
  v_status text;
begin
  if not public.is_admin() then
    raise exception 'not_admin';
  end if;

  v_status := case
    when p_status in ('acik','open') then 'open'
    when p_status in ('inceleniyor','reviewing') then 'reviewing'
    when p_status in ('kapandi','closed','reddedildi','rejected') then 'closed'
    else 'open'
  end;

  update public.reports
  set
    status = v_status,
    handled_by = auth.uid(),
    handled_at = now(),
    admin_note = coalesce(p_admin_note, admin_note)
  where id = any(p_report_ids);

  get diagnostics v_count = row_count;

  perform public.log_admin_action_v1(
    'report.bulk_update',
    'reports',
    null,
    jsonb_build_object('status', v_status, 'count', v_count)
  );

  return jsonb_build_object('ok', true, 'updated', v_count);
end;
$$;


