CREATE OR REPLACE FUNCTION "public"."admin_create_sponsorship_v1"("p_business_id" "uuid", "p_package_id" "uuid", "p_surface" "text", "p_starts_at" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_ends_at" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_targeting" "jsonb" DEFAULT '{}'::"jsonb", "p_daily_cap" integer DEFAULT NULL::integer, "p_total_cap" integer DEFAULT NULL::integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_id uuid;
begin
  if not public.is_admin() then
    return jsonb_build_object('ok', false, 'code', 'not_admin', 'message', 'Not admin');
  end if;

  if p_starts_at is not null and p_ends_at is not null and p_ends_at < p_starts_at then
    return jsonb_build_object('ok', false, 'code', 'invalid', 'message', 'Invalid date range');
  end if;

  insert into public.sponsorships(
    business_id,
    package_id,
    surface,
    starts_at,
    ends_at,
    targeting,
    daily_cap,
    total_cap,
    source,
    created_by
  )
  values (
    p_business_id,
    p_package_id,
    p_surface,
    p_starts_at,
    p_ends_at,
    coalesce(p_targeting, '{}'::jsonb),
    p_daily_cap,
    p_total_cap,
    'manual',
    auth.uid()
  )
  returning id into v_id;

  return jsonb_build_object('ok', true, 'id', v_id);
end;
$$;


