CREATE OR REPLACE FUNCTION "public"."admin_decide_moderation_appeal_v1"("p_appeal_id" "uuid", "p_decision" "text", "p_note" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_uid uuid := auth.uid();
begin
  if v_uid is null then
    return jsonb_build_object('ok', false, 'error', 'not_authenticated');
  end if;
  if not public.is_admin_or_community_mod_v1() then
    return jsonb_build_object('ok', false, 'error', 'forbidden');
  end if;
  if p_appeal_id is null then
    return jsonb_build_object('ok', false, 'error', 'missing_appeal_id');
  end if;
  if p_decision not in ('approved', 'rejected') then
    return jsonb_build_object('ok', false, 'error', 'invalid_decision');
  end if;

  update public.moderation_appeals
  set
    status = p_decision,
    decision_note = nullif(trim(coalesce(p_note, '')), ''),
    decided_by = v_uid,
    decided_at = now(),
    updated_at = now()
  where id = p_appeal_id;

  if not found then
    return jsonb_build_object('ok', false, 'error', 'appeal_not_found');
  end if;

  return jsonb_build_object('ok', true);
end;
$$;


