CREATE OR REPLACE FUNCTION "public"."admin_export_anonymous_trends_csv_v1"("p_days" integer DEFAULT 30) RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_csv text;
begin
  if not public.is_admin() then
    raise exception 'not authorized';
  end if;

  with rows as (
    select
      to_char(date_trunc('day', e.created_at), 'YYYY-MM-DD') as day,
      coalesce(b.city, '-') as city,
      coalesce(b.district, '-') as district,
      e.event_name,
      count(*)::int as event_count
    from public.analytics_events e
    left join public.businesses b on b.id = e.business_id
    where e.created_at >= now() - make_interval(days => greatest(p_days, 1))
    group by 1, 2, 3, 4
    order by 1 desc, 2, 3, 4
  )
  select
    'day,city,district,event_name,event_count' || E'\n' ||
    coalesce(
      string_agg(
        format(
          '%s,%s,%s,%s,%s',
          r.day,
          replace(r.city, ',', ' '),
          replace(r.district, ',', ' '),
          replace(r.event_name, ',', ' '),
          r.event_count::text
        ),
        E'\n'
      ),
      ''
    )
  into v_csv
  from rows r;

  return v_csv;
end;
$$;


ALTER FUNCTION "public"."admin_export_anonymous_trends_csv_v1"("p_days" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_export_business_suggestions_csv_v1"("p_status" "text" DEFAULT NULL::"text", "p_q" "text" DEFAULT NULL::"text") RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_csv text;
begin
  if not public.is_admin() then
    raise exception 'not_admin';
  end if;

  select string_agg(line, E'\n') into v_csv
  from (
    select
      'id,created_at,status,user_id,name,category,address,city,district,notes,admin_note,approved_business_id,handled_by,handled_at' as line
    union all
    select
      concat_ws(',',
        s.id::text,
        to_char(s.created_at, 'YYYY-MM-DD"T"HH24:MI:SS"Z"'),
        replace(coalesce(s.status,''), ',', ' '),
        coalesce(s.user_id::text,''),
        replace(coalesce(s.name,''), ',', ' '),
        replace(coalesce(s.category,''), ',', ' '),
        replace(coalesce(s.address,''), ',', ' '),
        replace(coalesce(s.city,''), ',', ' '),
        replace(coalesce(s.district,''), ',', ' '),
        replace(coalesce(s.notes,''), E'\n', ' '),
        replace(coalesce(s.admin_note,''), E'\n', ' '),
        coalesce(s.approved_business_id::text,''),
        coalesce(s.handled_by::text,''),
        coalesce(to_char(s.handled_at, 'YYYY-MM-DD"T"HH24:MI:SS"Z"'),'')
      ) as line
    from public.business_suggestions s
    where (p_status is null or s.status = p_status)
      and (
        p_q is null
        or s.name ilike ('%'||p_q||'%')
        or s.address ilike ('%'||p_q||'%')
        or s.city ilike ('%'||p_q||'%')
        or s.district ilike ('%'||p_q||'%')
        or s.notes ilike ('%'||p_q||'%')
        or s.admin_note ilike ('%'||p_q||'%')
      )
    order by s.created_at desc
  ) t;

  perform public.log_admin_action_v1(
    'suggestion.export_csv',
    'business_suggestions',
    null,
    jsonb_build_object('status', p_status, 'q', p_q)
  );

  return v_csv;
end;
$$;


ALTER FUNCTION "public"."admin_export_business_suggestions_csv_v1"("p_status" "text", "p_q" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_export_menu_inflation_csv_v1"("p_days" integer DEFAULT 30) RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_csv text;
begin
  if not public.is_admin() then
    raise exception 'not authorized';
  end if;

  with hist as (
    select
      h.menu_item_id,
      mi.name as menu_item_name,
      b.city,
      b.district,
      h.price_cents,
      h.created_at,
      row_number() over (
        partition by h.menu_item_id
        order by h.created_at asc
      ) as rn_first,
      row_number() over (
        partition by h.menu_item_id
        order by h.created_at desc
      ) as rn_last
    from public.menu_item_price_history h
    join public.menu_items mi on mi.id = h.menu_item_id
    join public.businesses b on b.id = mi.business_id
    where h.price_cents is not null
      and h.price_cents > 0
      and h.created_at >= now() - make_interval(days => greatest(p_days, 1))
  ),
  first_last as (
    select
      h1.menu_item_id,
      h1.menu_item_name,
      h1.city,
      h1.district,
      max(case when h1.rn_first = 1 then h1.price_cents end) as first_price_cents,
      max(case when h1.rn_last = 1 then h1.price_cents end) as last_price_cents
    from hist h1
    group by h1.menu_item_id, h1.menu_item_name, h1.city, h1.district
  ),
  rows as (
    select
      coalesce(fl.city, '-') as city,
      coalesce(fl.district, '-') as district,
      replace(fl.menu_item_name, ',', ' ') as menu_item_name,
      fl.first_price_cents::int as first_price_cents,
      fl.last_price_cents::int as last_price_cents,
      case
        when fl.first_price_cents is null or fl.first_price_cents = 0 then null
        else round(((fl.last_price_cents - fl.first_price_cents)::numeric / fl.first_price_cents::numeric) * 100.0, 2)
      end as inflation_pct
    from first_last fl
    where fl.first_price_cents is not null
      and fl.last_price_cents is not null
    order by inflation_pct desc nulls last
    limit 5000
  )
  select
    'city,district,menu_item_name,first_price_cents,last_price_cents,inflation_pct' || E'\n' ||
    coalesce(
      string_agg(
        format(
          '%s,%s,%s,%s,%s,%s',
          r.city,
          r.district,
          r.menu_item_name,
          r.first_price_cents::text,
          r.last_price_cents::text,
          coalesce(r.inflation_pct::text, '')
        ),
        E'\n'
      ),
      ''
    )
  into v_csv
  from rows r;

  return v_csv;
end;
$$;


