CREATE OR REPLACE FUNCTION "public"."admin_find_duplicate_businesses_v1"("p_suggestion_id" "uuid", "p_threshold" double precision DEFAULT 0.6) RETURNS TABLE("business_id" "uuid", "name" "text", "address" "text", "city" "text", "district" "text", "score" double precision)
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  with s as (
    select name, address, city, district
    from public.business_suggestions
    where id = p_suggestion_id
  )
  select
    b.id as business_id,
    b.name,
    b.address,
    b.city,
    b.district,
    (
      similarity(lower(b.name), lower(s.name)) * 0.7 +
      similarity(lower(coalesce(b.address,'')), lower(coalesce(s.address,''))) * 0.3
    ) as score
  from public.businesses b, s
  where public.is_admin()
    and b.city = s.city
    and b.district = s.district
    and (
      similarity(lower(b.name), lower(s.name)) > p_threshold
      or similarity(lower(coalesce(b.address,'')), lower(coalesce(s.address,''))) > p_threshold
    )
  order by score desc
  limit 5;
$$;


