CREATE OR REPLACE FUNCTION "public"."admin_get_receipt_submission_summary_v1"("p_query" "text" DEFAULT NULL::"text", "p_review_status" "text" DEFAULT NULL::"text", "p_only_unmatched" boolean DEFAULT false) RETURNS TABLE("total_count" integer, "pending_count" integer, "reviewed_count" integer, "needs_followup_count" integer, "zero_match_count" integer, "business_count" integer, "recent_24h_count" integer)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  with match_counts as (
    select receipt_id, count(*)::int as cnt
    from public.receipt_matches
    group by receipt_id
  ),
  filtered as (
    select
      s.id,
      s.business_id,
      s.created_at,
      s.review_status,
      coalesce(mc.cnt, 0) as matches_count
    from public.receipt_submissions s
    join public.businesses b on b.id = s.business_id
    left join public.chains ch on ch.id = b.chain_id
    left join match_counts mc on mc.receipt_id = s.id
    where public.is_admin()
      and (
        coalesce(nullif(trim(p_query), ''), '') = ''
        or b.name ilike '%' || trim(p_query) || '%'
        or coalesce(b.city, '') ilike '%' || trim(p_query) || '%'
        or coalesce(b.district, '') ilike '%' || trim(p_query) || '%'
        or coalesce(ch.name, '') ilike '%' || trim(p_query) || '%'
      )
      and (
        coalesce(nullif(trim(p_review_status), ''), '') = ''
        or s.review_status = trim(p_review_status)
      )
      and (
        coalesce(p_only_unmatched, false) = false
        or coalesce(mc.cnt, 0) = 0
      )
  )
  select
    count(*)::int as total_count,
    count(*) filter (where review_status = 'pending')::int as pending_count,
    count(*) filter (where review_status = 'reviewed')::int as reviewed_count,
    count(*) filter (where review_status = 'needs_followup')::int as needs_followup_count,
    count(*) filter (where matches_count = 0)::int as zero_match_count,
    count(distinct business_id)::int as business_count,
    count(*) filter (where created_at >= now() - interval '24 hours')::int as recent_24h_count
  from filtered;
$$;


ALTER FUNCTION "public"."admin_get_receipt_submission_summary_v1"("p_query" "text", "p_review_status" "text", "p_only_unmatched" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_get_sponsorship_summary_v1"() RETURNS TABLE("active_sponsorships" integer, "pending_sponsorships" integer, "open_leads" integer, "impressions_30d" integer, "unique_users_30d" integer, "estimated_active_revenue_cents" bigint)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  with active_sponsorships_cte as (
    select s.id, s.package_id
    from public.sponsorships s
    where s.status = 'active'
      and (s.starts_at is null or s.starts_at <= now())
      and (s.ends_at is null or s.ends_at >= now())
  ),
  perf_cte as (
    select
      coalesce(sum(i.impressions_count), 0)::int as impressions_30d,
      coalesce(sum(i.unique_users_count), 0)::int as unique_users_30d
    from active_sponsorships_cte a
    left join public.sponsorship_impressions_daily i
      on i.sponsorship_id = a.id
     and i.day >= current_date - 29
  ),
  revenue_cte as (
    select coalesce(sum(p.price_cents), 0)::bigint as estimated_active_revenue_cents
    from active_sponsorships_cte a
    join public.sponsorship_packages p on p.id = a.package_id
  )
  select
    (select count(*)::int from active_sponsorships_cte) as active_sponsorships,
    (
      select count(*)::int
      from public.sponsorships s
      where s.status = 'pending'
    ) as pending_sponsorships,
    (
      select count(*)::int
      from public.sponsorship_leads l
      where l.status = 'new'
    ) as open_leads,
    perf_cte.impressions_30d,
    perf_cte.unique_users_30d,
    revenue_cte.estimated_active_revenue_cents
  from perf_cte
  cross join revenue_cte
  where public.is_admin();
$$;


ALTER FUNCTION "public"."admin_get_sponsorship_summary_v1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_kpi_summary_v1"("p_days" integer DEFAULT 30) RETURNS TABLE("dau" integer, "dau_prev" integer, "wau" integer, "wau_prev" integer, "discovery_impressions" integer, "discovery_impressions_prev" integer, "discovery_clicks" integer, "discovery_clicks_prev" integer, "discovery_ctr" double precision, "discovery_ctr_prev" double precision, "business_views" integer, "business_views_prev" integer, "menu_views" integer, "menu_views_prev" integer, "menu_view_rate" double precision, "menu_view_rate_prev" double precision, "price_suggestions" integer, "price_suggestions_prev" integer, "price_verification_rate" double precision, "price_verification_rate_prev" double precision, "reports_avg_resolution_minutes" double precision, "reports_avg_resolution_minutes_prev" double precision)
    LANGUAGE "sql"
    SET "search_path" TO 'public', 'extensions'
    AS $$
with
  events as (
    select *
    from public.analytics_events
    where created_at >= now() - (p_days::text || ' days')::interval
  ),
  discovery_impressions_cte as (
    select
      coalesce(sum(nullif((meta->>'count'), '')::int), count(*))::int as impressions
    from events
    where event_name = 'discovery_impression'
  ),
  prev_events as (
    select *
    from public.analytics_events
    where created_at >= now() - ((p_days * 2)::text || ' days')::interval
      and created_at < now() - (p_days::text || ' days')::interval
  ),
  discovery_impressions_prev_cte as (
    select
      coalesce(sum(nullif((meta->>'count'), '')::int), count(*))::int as impressions
    from prev_events
    where event_name = 'discovery_impression'
  ),
  discovery_clicks_cte as (
    select count(*)::int as clicks
    from events
    where event_name = 'discovery_business_click'
  ),
  discovery_clicks_prev_cte as (
    select count(*)::int as clicks
    from prev_events
    where event_name = 'discovery_business_click'
  ),
  business_views_cte as (
    select count(*)::int as views
    from events
    where event_name = 'business_page_view'
  ),
  business_views_prev_cte as (
    select count(*)::int as views
    from prev_events
    where event_name = 'business_page_view'
  ),
  menu_views_cte as (
    select count(*)::int as views
    from events
    where event_name = 'menu_view'
  ),
  menu_views_prev_cte as (
    select count(*)::int as views
    from prev_events
    where event_name = 'menu_view'
  ),
  price_suggestions_cte as (
    select count(*)::int as cnt
    from events
    where event_name = 'price_suggestion_submitted'
  ),
  price_suggestions_prev_cte as (
    select count(*)::int as cnt
    from prev_events
    where event_name = 'price_suggestion_submitted'
  )
select
  (
    select count(distinct client_id)::int
    from public.analytics_events
    where created_at >= now() - interval '1 day'
      and client_id is not null
      and client_id <> ''
  ) as dau,
  (
    select count(distinct client_id)::int
    from public.analytics_events
    where created_at >= now() - interval '2 days'
      and created_at < now() - interval '1 day'
      and client_id is not null
      and client_id <> ''
  ) as dau_prev,
  (
    select count(distinct client_id)::int
    from public.analytics_events
    where created_at >= now() - interval '7 days'
      and client_id is not null
      and client_id <> ''
  ) as wau,
  (
    select count(distinct client_id)::int
    from public.analytics_events
    where created_at >= now() - interval '14 days'
      and created_at < now() - interval '7 days'
      and client_id is not null
      and client_id <> ''
  ) as wau_prev,
  d.impressions as discovery_impressions,
  dp.impressions as discovery_impressions_prev,
  c.clicks as discovery_clicks,
  cp.clicks as discovery_clicks_prev,
  case when d.impressions > 0 then c.clicks::double precision / d.impressions else 0 end as discovery_ctr,
  case when dp.impressions > 0 then cp.clicks::double precision / dp.impressions else 0 end as discovery_ctr_prev,
  bv.views as business_views,
  bvp.views as business_views_prev,
  mv.views as menu_views,
  mvp.views as menu_views_prev,
  case when bv.views > 0 then mv.views::double precision / bv.views else 0 end as menu_view_rate,
  case when bvp.views > 0 then mvp.views::double precision / bvp.views else 0 end as menu_view_rate_prev,
  ps.cnt as price_suggestions,
  psp.cnt as price_suggestions_prev,
  case when mv.views > 0 then ps.cnt::double precision / mv.views else 0 end as price_verification_rate,
  case when mvp.views > 0 then psp.cnt::double precision / mvp.views else 0 end as price_verification_rate_prev,
  (
    select coalesce(avg(extract(epoch from (handled_at - created_at)) / 60.0), 0)
    from public.reports
    where handled_at is not null
      and created_at >= now() - (p_days::text || ' days')::interval
  ) as reports_avg_resolution_minutes,
  (
    select coalesce(avg(extract(epoch from (handled_at - created_at)) / 60.0), 0)
    from public.reports
    where handled_at is not null
      and created_at >= now() - ((p_days * 2)::text || ' days')::interval
      and created_at < now() - (p_days::text || ' days')::interval
  ) as reports_avg_resolution_minutes_prev
from discovery_impressions_cte d
cross join discovery_impressions_prev_cte dp
cross join discovery_clicks_cte c
cross join discovery_clicks_prev_cte cp
cross join business_views_cte bv
cross join business_views_prev_cte bvp
cross join menu_views_cte mv
cross join menu_views_prev_cte mvp
cross join price_suggestions_cte ps
cross join price_suggestions_prev_cte psp;
$$;


ALTER FUNCTION "public"."admin_kpi_summary_v1"("p_days" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_link_suggestion_to_business_v1"("p_suggestion_id" "uuid", "p_business_id" "uuid", "p_admin_note" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  if not public.is_admin() then
    raise exception 'not_admin';
  end if;

  update public.business_suggestions
  set
    status = 'approved',
    approved_business_id = p_business_id,
    handled_by = auth.uid(),
    handled_at = now(),
    admin_note = p_admin_note
  where id = p_suggestion_id
    and status = 'pending';

  perform public.log_admin_action_v1(
    'suggestion.link_existing',
    'business_suggestions',
    p_suggestion_id,
    jsonb_build_object('business_id', p_business_id)
  );

  return jsonb_build_object('ok', true);
end;
$$;


