CREATE OR REPLACE FUNCTION "public"."admin_list_business_suggestions_v3"("p_status" "text" DEFAULT NULL::"text", "p_limit" integer DEFAULT 50, "p_offset" integer DEFAULT 0, "p_q" "text" DEFAULT NULL::"text", "p_assigned" "text" DEFAULT NULL::"text", "p_sla_only" boolean DEFAULT false) RETURNS TABLE("id" "uuid", "created_at" timestamp with time zone, "status" "text", "user_id" "uuid", "name" "text", "category" "text", "address" "text", "city" "text", "district" "text", "notes" "text", "admin_note" "text", "approved_business_id" "uuid", "assigned_to" "uuid", "assigned_at" timestamp with time zone, "handled_by" "uuid", "handled_at" timestamp with time zone, "age_days" double precision, "sla_breached" boolean)
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  with base as (
    select
      s.*,
      (extract(epoch from (now() - s.created_at))/86400.0)::float as age_days,
      (
        s.handled_at is null
        and s.status = 'pending'
        and s.created_at < now() - interval '7 days'
      ) as sla_breached
    from public.business_suggestions s
    where public.is_admin()
      and (p_status is null or s.status = p_status)
      and (
        p_assigned is null
        or (p_assigned='me' and s.assigned_to = auth.uid())
        or (p_assigned='unassigned' and s.assigned_to is null)
      )
      and (
        p_q is null
        or s.name ilike ('%'||p_q||'%')
        or s.address ilike ('%'||p_q||'%')
        or s.city ilike ('%'||p_q||'%')
        or s.district ilike ('%'||p_q||'%')
        or s.notes ilike ('%'||p_q||'%')
        or s.admin_note ilike ('%'||p_q||'%')
      )
  )
  select
    id, created_at, status, user_id, name, category, address, city, district, notes,
    admin_note, approved_business_id,
    assigned_to, assigned_at, handled_by, handled_at,
    age_days, sla_breached
  from base
  where (not p_sla_only) or sla_breached
  order by
    sla_breached desc,
    created_at desc
  limit greatest(p_limit,0)
  offset greatest(p_offset,0);
$$;


ALTER FUNCTION "public"."admin_list_business_suggestions_v3"("p_status" "text", "p_limit" integer, "p_offset" integer, "p_q" "text", "p_assigned" "text", "p_sla_only" boolean) OWNER TO "postgres";


