CREATE OR REPLACE FUNCTION "public"."admin_list_menu_price_suggestions_v1"("p_status" "text" DEFAULT 'pending'::"text", "p_limit" integer DEFAULT 30, "p_offset" integer DEFAULT 0, "p_sla_only" boolean DEFAULT false) RETURNS TABLE("suggestion_id" "uuid", "status" "text", "created_at" timestamp with time zone, "sla_breached" boolean, "business_id" "uuid", "business_name" "text", "city" "text", "district" "text", "menu_item_id" "uuid", "item_name" "text", "current_price_cents" integer, "suggested_price_cents" integer, "currency" "text", "created_by" "uuid")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  select
    s.id as suggestion_id,
    s.status::text,
    s.created_at,
    (s.status='pending' and s.created_at < now() - interval '48 hours') as sla_breached,

    b.id as business_id,
    b.name as business_name,
    b.city,
    b.district,

    mi.id as menu_item_id,
    mi.name as item_name,
    mi.price_cents as current_price_cents,
    s.suggested_price_cents,
    s.currency,

    s.created_by
  from public.menu_item_price_suggestions s
  join public.menu_items mi on mi.id = s.menu_item_id
  join public.businesses b on b.id = s.business_id
  where public.is_admin()
    and (p_status is null or s.status::text = p_status)
    and (not p_sla_only or (s.status='pending' and s.created_at < now() - interval '48 hours'))
  order by (s.status='pending') desc, s.created_at asc
  limit greatest(p_limit,0) offset greatest(p_offset,0);
$$;


