CREATE OR REPLACE FUNCTION "public"."admin_list_menu_price_suggestions_v2"("p_status" "text" DEFAULT NULL::"text", "p_limit" integer DEFAULT 30, "p_offset" integer DEFAULT 0, "p_sla_only" boolean DEFAULT false, "p_assigned" "text" DEFAULT NULL::"text") RETURNS TABLE("suggestion_id" "uuid", "status" "text", "created_at" timestamp with time zone, "sla_breached" boolean, "business_id" "uuid", "business_name" "text", "city" "text", "district" "text", "menu_item_id" "uuid", "item_name" "text", "current_price_cents" integer, "suggested_price_cents" integer, "currency" "text", "created_by" "uuid", "assigned_to" "uuid", "assigned_at" timestamp with time zone, "quality_confidence" numeric, "anomaly_score" numeric, "anomaly_flags" "jsonb", "conflict_state" "text", "conflict_variants_24h" integer)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  select
    s.id as suggestion_id,
    s.status::text,
    s.created_at,
    (s.status = 'pending' and s.created_at < now() - interval '48 hours') as sla_breached,
    b.id as business_id,
    b.name as business_name,
    b.city,
    b.district,
    mi.id as menu_item_id,
    mi.name as item_name,
    mi.price_cents as current_price_cents,
    s.suggested_price_cents,
    s.currency,
    s.created_by,
    s.handled_by as assigned_to,
    s.handled_at as assigned_at,
    s.quality_confidence,
    s.anomaly_score,
    s.anomaly_flags,
    s.conflict_state,
    s.conflict_variants_24h
  from public.menu_item_price_suggestions s
  join public.menu_items mi on mi.id = s.menu_item_id
  join public.businesses b on b.id = s.business_id
  where public.is_admin()
    and (
      p_status is null
      or p_status = ''
      or s.status::text = p_status
    )
    and (
      p_assigned is null
      or p_assigned = ''
      or (p_assigned = 'me' and s.handled_by = auth.uid())
      or (p_assigned = 'unassigned' and s.handled_by is null)
      or s.handled_by::text = p_assigned
    )
    and (not p_sla_only or (s.status = 'pending' and s.created_at < now() - interval '48 hours'))
  order by
    (s.conflict_state = 'queued') desc,
    (coalesce(s.anomaly_score, 0) >= 0.5) desc,
    (s.status = 'pending') desc,
    s.created_at asc
  limit greatest(p_limit, 0) offset greatest(p_offset, 0);
$$;


ALTER FUNCTION "public"."admin_list_menu_price_suggestions_v2"("p_status" "text", "p_limit" integer, "p_offset" integer, "p_sla_only" boolean, "p_assigned" "text") OWNER TO "postgres";


