CREATE OR REPLACE FUNCTION "public"."admin_list_offline_mutation_outcomes_v1"("p_hours" integer DEFAULT 24, "p_limit" integer DEFAULT 100) RETURNS TABLE("created_at" timestamp with time zone, "source" "text", "kind" "text", "disposition" "text", "retry_category" "text", "retry_count" integer, "detail" "text", "user_id" "uuid", "client_id" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_hours integer := greatest(coalesce(p_hours, 24), 1);
  v_limit integer := least(greatest(coalesce(p_limit, 100), 1), 500);
begin
  if not public.is_admin() then
    raise exception 'not_authorized';
  end if;

  return query
  select
    e.created_at,
    coalesce(e.source, '') as source,
    coalesce(e.meta ->> 'kind', 'unknown') as kind,
    coalesce(e.meta ->> 'disposition', 'unknown') as disposition,
    nullif(e.meta ->> 'retry_category', '') as retry_category,
    case
      when nullif(e.meta ->> 'retry_count', '') is null then null
      else (e.meta ->> 'retry_count')::integer
    end as retry_count,
    nullif(e.meta ->> 'detail', '') as detail,
    e.user_id,
    e.client_id
  from public.analytics_events e
  where e.event_name = 'offline_mutation_outcome'
    and e.created_at >= now() - make_interval(hours => v_hours)
  order by e.created_at desc
  limit v_limit;
end;
$$;


ALTER FUNCTION "public"."admin_list_offline_mutation_outcomes_v1"("p_hours" integer, "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_list_owner_claims_v1"("p_status" "text" DEFAULT NULL::"text", "p_limit" integer DEFAULT 50, "p_offset" integer DEFAULT 0, "p_q" "text" DEFAULT NULL::"text") RETURNS TABLE("id" "uuid", "created_at" timestamp with time zone, "status" "text", "user_id" "uuid", "business_id" "uuid", "full_name" "text", "phone" "text", "evidence_url" "text", "note" "text", "handled_by" "uuid", "handled_at" timestamp with time zone, "admin_note" "text")
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  select
    c.id, c.created_at, c.status, c.user_id, c.business_id,
    c.full_name, c.phone, c.evidence_url, c.note,
    c.handled_by, c.handled_at, c.admin_note
  from public.owner_claims c
  where public.is_admin()
    and (p_status is null or c.status = p_status)
    and (
      p_q is null
      or c.full_name ilike ('%'||p_q||'%')
      or c.phone ilike ('%'||p_q||'%')
      or c.note ilike ('%'||p_q||'%')
      or c.evidence_url ilike ('%'||p_q||'%')
      or c.admin_note ilike ('%'||p_q||'%')
    )
  order by c.created_at desc
  limit greatest(p_limit,0)
  offset greatest(p_offset,0);
$$;


