CREATE OR REPLACE FUNCTION "public"."admin_list_owner_claims_v3"("p_status" "text" DEFAULT NULL::"text", "p_limit" integer DEFAULT 50, "p_offset" integer DEFAULT 0, "p_sla_only" boolean DEFAULT false, "p_assigned" "text" DEFAULT NULL::"text", "p_q" "text" DEFAULT NULL::"text") RETURNS TABLE("claim_id" "uuid", "status" "text", "created_at" timestamp with time zone, "age_days" double precision, "sla_breached" boolean, "business_id" "uuid", "full_name" "text", "phone" "text", "evidence_url" "text", "note" "text", "admin_note" "text", "assigned_to" "uuid", "assigned_at" timestamp with time zone, "auto_moderated" boolean)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  select
    c.id as claim_id,
    c.status::text,
    c.created_at,
    extract(epoch from (now() - c.created_at)) / 86400.0 as age_days,
    (c.status = 'pending' and c.created_at < now() - interval '48 hours') as sla_breached,
    c.business_id,
    c.full_name,
    c.phone,
    c.evidence_url,
    c.note,
    c.admin_note,
    c.handled_by as assigned_to,
    c.handled_at as assigned_at,
    coalesce(c.auto_moderated, false) as auto_moderated
  from public.owner_claims c
  where public.is_admin()
    and (
      p_status is null
      or p_status = ''
      or c.status::text = p_status
    )
    and (
      p_assigned is null
      or p_assigned = ''
      or (p_assigned = 'me' and c.handled_by = auth.uid())
      or (p_assigned = 'unassigned' and c.handled_by is null)
      or c.handled_by::text = p_assigned
    )
    and (
      p_q is null
      or p_q = ''
      or c.id::text ilike ('%' || p_q || '%')
      or coalesce(c.full_name, '') ilike ('%' || p_q || '%')
      or coalesce(c.phone, '') ilike ('%' || p_q || '%')
    )
    and (not p_sla_only or (c.status = 'pending' and c.created_at < now() - interval '48 hours'))
  order by (c.status = 'pending') desc, c.created_at asc
  limit greatest(p_limit, 0) offset greatest(p_offset, 0);
$$;


ALTER FUNCTION "public"."admin_list_owner_claims_v3"("p_status" "text", "p_limit" integer, "p_offset" integer, "p_sla_only" boolean, "p_assigned" "text", "p_q" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_list_receipt_submission_batch_opportunities_v1"("p_limit" integer DEFAULT 8) RETURNS TABLE("business_id" "uuid", "business_name" "text", "chain_id" "uuid", "chain_name" "text", "pending_count" integer, "zero_match_count" integer, "last_submitted_at" timestamp with time zone)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  with match_counts as (
    select receipt_id, count(*)::int as cnt
    from public.receipt_matches
    group by receipt_id
  )
  select
    s.business_id,
    b.name as business_name,
    b.chain_id,
    ch.name as chain_name,
    count(*)::int as pending_count,
    count(*) filter (where coalesce(mc.cnt, 0) = 0)::int as zero_match_count,
    max(s.created_at) as last_submitted_at
  from public.receipt_submissions s
  join public.businesses b on b.id = s.business_id
  left join public.chains ch on ch.id = b.chain_id
  left join match_counts mc on mc.receipt_id = s.id
  where public.is_admin()
    and s.review_status in ('pending', 'needs_followup')
  group by s.business_id, b.name, b.chain_id, ch.name
  order by pending_count desc, zero_match_count desc, last_submitted_at desc
  limit greatest(p_limit, 0);
$$;


ALTER FUNCTION "public"."admin_list_receipt_submission_batch_opportunities_v1"("p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_list_receipt_submission_matches_v1"("p_receipt_id" "uuid") RETURNS TABLE("menu_item_id" "uuid", "item_name" "text", "detected_price_cents" integer, "current_price_cents" integer, "delta_cents" integer)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  select
    rm.menu_item_id,
    mi.name as item_name,
    rm.detected_price_cents,
    mi.price_cents as current_price_cents,
    (rm.detected_price_cents - mi.price_cents) as delta_cents
  from public.receipt_matches rm
  join public.menu_items mi on mi.id = rm.menu_item_id
  where public.is_admin()
    and rm.receipt_id = p_receipt_id
  order by abs(rm.detected_price_cents - mi.price_cents) desc, mi.name;
$$;


