CREATE OR REPLACE FUNCTION "public"."admin_list_receipt_submissions_v1"("p_limit" integer DEFAULT 50, "p_offset" integer DEFAULT 0) RETURNS TABLE("receipt_id" "uuid", "created_at" timestamp with time zone, "user_id" "uuid", "business_id" "uuid", "business_name" "text", "image_url" "text", "matches_count" integer)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  select
    s.id as receipt_id,
    s.created_at,
    s.user_id,
    s.business_id,
    b.name as business_name,
    s.image_url,
    coalesce(m.cnt, 0) as matches_count
  from public.receipt_submissions s
  join public.businesses b on b.id = s.business_id
  left join (
    select receipt_id, count(*)::int as cnt
    from public.receipt_matches
    group by receipt_id
  ) m on m.receipt_id = s.id
  where public.is_admin()
  order by s.created_at desc
  limit greatest(p_limit, 0)
  offset greatest(p_offset, 0);
$$;


ALTER FUNCTION "public"."admin_list_receipt_submissions_v1"("p_limit" integer, "p_offset" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_list_receipt_submissions_v2"("p_query" "text" DEFAULT NULL::"text", "p_review_status" "text" DEFAULT NULL::"text", "p_only_unmatched" boolean DEFAULT false, "p_limit" integer DEFAULT 50, "p_offset" integer DEFAULT 0) RETURNS TABLE("receipt_id" "uuid", "created_at" timestamp with time zone, "user_id" "uuid", "business_id" "uuid", "business_name" "text", "city" "text", "district" "text", "chain_id" "uuid", "chain_name" "text", "image_url" "text", "matches_count" integer, "review_status" "text", "review_note" "text", "reviewed_at" timestamp with time zone, "reviewed_by" "uuid")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  with match_counts as (
    select receipt_id, count(*)::int as cnt
    from public.receipt_matches
    group by receipt_id
  ),
  filtered as (
    select
      s.id as receipt_id,
      s.created_at,
      s.user_id,
      s.business_id,
      b.name as business_name,
      b.city,
      b.district,
      b.chain_id,
      ch.name as chain_name,
      s.image_url,
      coalesce(mc.cnt, 0) as matches_count,
      s.review_status,
      s.review_note,
      s.reviewed_at,
      s.reviewed_by
    from public.receipt_submissions s
    join public.businesses b on b.id = s.business_id
    left join public.chains ch on ch.id = b.chain_id
    left join match_counts mc on mc.receipt_id = s.id
    where public.is_admin()
      and (
        coalesce(nullif(trim(p_query), ''), '') = ''
        or b.name ilike '%' || trim(p_query) || '%'
        or coalesce(b.city, '') ilike '%' || trim(p_query) || '%'
        or coalesce(b.district, '') ilike '%' || trim(p_query) || '%'
        or coalesce(ch.name, '') ilike '%' || trim(p_query) || '%'
      )
      and (
        coalesce(nullif(trim(p_review_status), ''), '') = ''
        or s.review_status = trim(p_review_status)
      )
      and (
        coalesce(p_only_unmatched, false) = false
        or coalesce(mc.cnt, 0) = 0
      )
  )
  select *
  from filtered
  order by
    case review_status
      when 'pending' then 1
      when 'needs_followup' then 2
      when 'reviewed' then 3
      else 99
    end,
    created_at desc
  limit greatest(p_limit, 0)
  offset greatest(p_offset, 0);
$$;


ALTER FUNCTION "public"."admin_list_receipt_submissions_v2"("p_query" "text", "p_review_status" "text", "p_only_unmatched" boolean, "p_limit" integer, "p_offset" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_list_reports_v5"("p_status" "text" DEFAULT NULL::"text", "p_limit" integer DEFAULT 50, "p_offset" integer DEFAULT 0, "p_q" "text" DEFAULT NULL::"text", "p_assigned" "text" DEFAULT NULL::"text", "p_sla_only" boolean DEFAULT false) RETURNS TABLE("id" "uuid", "created_at" timestamp with time zone, "status" "text", "reason" "text", "details" "text", "user_id" "uuid", "business_id" "uuid", "review_id" "uuid", "menu_item_photo_id" "uuid", "target_type" "text", "target_id" "uuid", "assigned_to" "uuid", "assigned_at" timestamp with time zone, "handled_by" "uuid", "handled_at" timestamp with time zone, "admin_note" "text", "age_hours" double precision, "sla_breached" boolean)
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  with params as (
    select case
      when p_status in ('acik','open') then 'open'
      when p_status in ('inceleniyor','reviewing') then 'reviewing'
      when p_status in ('kapandi','closed','reddedildi','rejected') then 'closed'
      else null
    end as status_filter
  ),
  base as (
    select
      r.*,
      (extract(epoch from (now() - r.created_at))/3600.0)::float as age_hours,
      (
        r.handled_at is null
        and r.status in ('open','reviewing')
        and r.created_at < now() - interval '24 hours'
      ) as sla_breached
    from public.reports r
    cross join params p
    where public.is_admin_or_community_mod_v1()
      and (p.status_filter is null or r.status = p.status_filter)
      and (
        p_assigned is null
        or (p_assigned='me' and r.assigned_to = auth.uid())
        or (p_assigned='unassigned' and r.assigned_to is null)
      )
      and (
        p_q is null
        or r.reason ilike ('%'||p_q||'%')
        or r.details ilike ('%'||p_q||'%')
        or r.admin_note ilike ('%'||p_q||'%')
      )
  )
  select
    id, created_at, status, reason, details, user_id, business_id, review_id,
    menu_item_photo_id, target_type, target_id,
    assigned_to, assigned_at, handled_by, handled_at, admin_note,
    age_hours, sla_breached
  from base
  where (not p_sla_only) or sla_breached
  order by sla_breached desc, created_at desc
  limit greatest(p_limit, 1)
  offset greatest(p_offset, 0);
$$;


ALTER FUNCTION "public"."admin_list_reports_v5"("p_status" "text", "p_limit" integer, "p_offset" integer, "p_q" "text", "p_assigned" "text", "p_sla_only" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_list_risky_users_v1"("p_limit" integer DEFAULT 50, "p_offset" integer DEFAULT 0, "p_min_score" integer DEFAULT 20) RETURNS TABLE("user_id" "uuid", "risk_score" integer, "signal_count" integer, "last_signal_at" timestamp with time zone, "new_account_hits" integer, "device_change_hits" integer, "same_ip_hits" integer, "duplicate_text_hits" integer, "soft_limited_until" timestamp with time zone, "auto_pending_until" timestamp with time zone, "shadow_banned_until" timestamp with time zone, "recommended_action" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  if not public.is_admin() then
    return;
  end if;

  return query
  with recent as (
    select
      rs.user_id,
      coalesce(sum(rs.signal_weight), 0)::integer as score_14d,
      count(*)::integer as cnt,
      max(rs.created_at) as last_at,
      count(*) filter (where rs.signal_key = 'new_account')::integer as new_account_hits,
      count(*) filter (where rs.signal_key = 'device_change')::integer as device_change_hits,
      count(*) filter (where rs.signal_key = 'same_ip_burst')::integer as same_ip_hits,
      count(*) filter (where rs.signal_key = 'duplicate_text')::integer as duplicate_text_hits
    from public.user_risk_signals rs
    where rs.created_at >= now() - interval '14 days'
    group by rs.user_id
  )
  select
    r.user_id,
    greatest(r.score_14d, coalesce(usa.risk_score, 0)) as risk_score,
    r.cnt as signal_count,
    coalesce(usa.last_signal_at, r.last_at) as last_signal_at,
    r.new_account_hits,
    r.device_change_hits,
    r.same_ip_hits,
    r.duplicate_text_hits,
    usa.soft_limited_until,
    usa.auto_pending_until,
    usa.shadow_banned_until,
    case
      when coalesce(usa.shadow_banned_until > now(), false) then 'shadow_ban'
      when coalesce(usa.auto_pending_until > now(), false) then 'auto_pending'
      when coalesce(usa.soft_limited_until > now(), false) then 'soft_limit'
      when greatest(r.score_14d, coalesce(usa.risk_score, 0)) >= 80 then 'shadow_ban'
      when greatest(r.score_14d, coalesce(usa.risk_score, 0)) >= 50 then 'auto_pending'
      else 'soft_limit'
    end as recommended_action
  from recent r
  left join public.user_safety_actions usa on usa.user_id = r.user_id
  where greatest(r.score_14d, coalesce(usa.risk_score, 0)) >= greatest(p_min_score, 1)
  order by greatest(r.score_14d, coalesce(usa.risk_score, 0)) desc, coalesce(usa.last_signal_at, r.last_at) desc
  limit greatest(p_limit, 1)
  offset greatest(p_offset, 0);
end;
$$;


ALTER FUNCTION "public"."admin_list_risky_users_v1"("p_limit" integer, "p_offset" integer, "p_min_score" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_list_sponsorship_inventory_v1"() RETURNS TABLE("surface" "text", "active_packages" integer, "total_packages" integer, "inventory_limit" integer, "live_units" integer, "open_inventory_slots" integer, "pending_sponsorships" integer, "open_leads" integer, "impressions_30d" integer, "unique_users_30d" integer, "estimated_active_revenue_cents" bigint)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  with surfaces as (
    select surface::text as surface
    from (
      select p.surface from public.sponsorship_packages p
      union
      select s.surface from public.sponsorships s
      union
      select l.preferred_surface as surface from public.sponsorship_leads l
      union
      select bp.tier as surface from public.business_premium bp
    ) src
  ),
  package_cte as (
    select
      p.surface::text as surface,
      count(*)::int as total_packages,
      count(*) filter (where p.is_active)::int as active_packages,
      coalesce(sum(case when p.is_active then p.inventory_limit else 0 end), 0)::int as inventory_limit
    from public.sponsorship_packages p
    group by p.surface
  ),
  live_sponsorship_units as (
    select
      s.surface::text as surface,
      count(*)::int as live_units,
      coalesce(sum(p.price_cents), 0)::bigint as estimated_active_revenue_cents
    from public.sponsorships s
    join public.sponsorship_packages p on p.id = s.package_id
    where s.status = 'active'
      and (s.starts_at is null or s.starts_at <= now())
      and (s.ends_at is null or s.ends_at >= now())
    group by s.surface
  ),
  live_premium_units as (
    select
      bp.tier::text as surface,
      count(*)::int as live_units
    from public.business_premium bp
    where bp.status = 'active'
      and (bp.ends_at is null or bp.ends_at >= now())
    group by bp.tier
  ),
  live_units_cte as (
    select
      surface,
      sum(live_units)::int as live_units
    from (
      select surface, live_units from live_sponsorship_units
      union all
      select surface, live_units from live_premium_units
    ) combined
    group by surface
  ),
  pending_cte as (
    select
      s.surface::text as surface,
      count(*)::int as pending_sponsorships
    from public.sponsorships s
    where s.status = 'pending'
    group by s.surface
  ),
  lead_cte as (
    select
      l.preferred_surface::text as surface,
      count(*) filter (where l.status = 'new')::int as open_leads
    from public.sponsorship_leads l
    group by l.preferred_surface
  ),
  perf_cte as (
    select
      s.surface::text as surface,
      coalesce(sum(i.impressions_count), 0)::int as impressions_30d,
      coalesce(sum(i.unique_users_count), 0)::int as unique_users_30d
    from public.sponsorships s
    left join public.sponsorship_impressions_daily i
      on i.sponsorship_id = s.id
     and i.day >= current_date - 29
    where s.status = 'active'
      and (s.starts_at is null or s.starts_at <= now())
      and (s.ends_at is null or s.ends_at >= now())
    group by s.surface
  )
  select
    surfaces.surface,
    coalesce(package_cte.active_packages, 0) as active_packages,
    coalesce(package_cte.total_packages, 0) as total_packages,
    coalesce(package_cte.inventory_limit, 0) as inventory_limit,
    coalesce(live_units_cte.live_units, 0) as live_units,
    greatest(
      coalesce(package_cte.inventory_limit, 0) - coalesce(live_units_cte.live_units, 0),
      0
    )::int as open_inventory_slots,
    coalesce(pending_cte.pending_sponsorships, 0) as pending_sponsorships,
    coalesce(lead_cte.open_leads, 0) as open_leads,
    coalesce(perf_cte.impressions_30d, 0) as impressions_30d,
    coalesce(perf_cte.unique_users_30d, 0) as unique_users_30d,
    coalesce(live_sponsorship_units.estimated_active_revenue_cents, 0)::bigint
      as estimated_active_revenue_cents
  from surfaces
  left join package_cte on package_cte.surface = surfaces.surface
  left join live_units_cte on live_units_cte.surface = surfaces.surface
  left join pending_cte on pending_cte.surface = surfaces.surface
  left join lead_cte on lead_cte.surface = surfaces.surface
  left join perf_cte on perf_cte.surface = surfaces.surface
  left join live_sponsorship_units on live_sponsorship_units.surface = surfaces.surface
  where public.is_admin()
  order by
    case surfaces.surface
      when 'discovery' then 1
      when 'business_page' then 2
      when 'stories' then 3
      when 'verified' then 4
      when 'premium' then 5
      else 99
    end,
    surfaces.surface;
$$;


ALTER FUNCTION "public"."admin_list_sponsorship_inventory_v1"() OWNER TO "postgres";


