CREATE OR REPLACE FUNCTION "public"."admin_list_sponsorships_v1"("p_status" "text" DEFAULT NULL::"text", "p_surface" "text" DEFAULT NULL::"text", "p_limit" integer DEFAULT 50, "p_offset" integer DEFAULT 0) RETURNS TABLE("sponsorship_id" "uuid", "status" "text", "surface" "text", "created_at" timestamp with time zone, "business_id" "uuid", "business_name" "text", "city" "text", "district" "text", "package_id" "uuid", "starts_at" timestamp with time zone, "ends_at" timestamp with time zone, "daily_cap" integer, "total_cap" integer, "source" "text", "created_by" "uuid")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  select
    s.id as sponsorship_id,
    s.status::text,
    s.surface::text,
    s.created_at,
    b.id as business_id,
    b.name as business_name,
    b.city,
    b.district,
    s.package_id,
    s.starts_at,
    s.ends_at,
    s.daily_cap,
    s.total_cap,
    s.source,
    s.created_by
  from public.sponsorships s
  join public.businesses b on b.id = s.business_id
  where public.is_admin()
    and (p_status is null or p_status = '' or s.status::text = p_status)
    and (p_surface is null or p_surface = '' or s.surface::text = p_surface)
  order by s.created_at desc
  limit greatest(p_limit, 0) offset greatest(p_offset, 0);
$$;


ALTER FUNCTION "public"."admin_list_sponsorships_v1"("p_status" "text", "p_surface" "text", "p_limit" integer, "p_offset" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_list_suspended_claims_v1"("p_status" "text" DEFAULT 'pending'::"text", "p_limit" integer DEFAULT 30, "p_offset" integer DEFAULT 0, "p_sla_only" boolean DEFAULT false) RETURNS TABLE("claim_id" "uuid", "claim_status" "text", "claim_created_at" timestamp with time zone, "sla_breached" boolean, "meal_id" "uuid", "meal_amount_cents" integer, "meal_currency" "text", "meal_message" "text", "meal_created_at" timestamp with time zone, "business_id" "uuid", "business_name" "text", "city" "text", "district" "text", "claimant_user_id" "uuid", "claimant_name" "text")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  select
    c.id as claim_id,
    c.status::text as claim_status,
    c.created_at as claim_created_at,
    (c.status='pending' and c.created_at < now() - interval '24 hours') as sla_breached,

    m.id as meal_id,
    m.amount_cents as meal_amount_cents,
    m.currency as meal_currency,
    m.message as meal_message,
    m.created_at as meal_created_at,

    b.id as business_id,
    b.name as business_name,
    b.city,
    b.district,

    c.claimant_user_id,
    coalesce(p.display_name,'Kullanıcı') as claimant_name
  from public.suspended_meal_claims c
  join public.suspended_meals m on m.id = c.suspended_meal_id
  join public.businesses b on b.id = m.business_id
  left join public.user_profiles p on p.user_id = c.claimant_user_id
  where public.is_admin()
    and (p_status is null or c.status::text = p_status)
    and (not p_sla_only or (c.status='pending' and c.created_at < now() - interval '24 hours'))
  order by
    (c.status='pending') desc,
    c.created_at asc
  limit greatest(p_limit,0)
  offset greatest(p_offset,0);
$$;


ALTER FUNCTION "public"."admin_list_suspended_claims_v1"("p_status" "text", "p_limit" integer, "p_offset" integer, "p_sla_only" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_list_table_feedback_v1"("p_limit" integer DEFAULT 50, "p_offset" integer DEFAULT 0) RETURNS TABLE("business_id" "uuid", "business_name" "text", "table_no" "text", "rating" integer, "note" "text", "created_at" timestamp with time zone, "client_id" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  if not public.is_admin() then
    raise exception 'not authorized';
  end if;

  return query
  select
    f.business_id,
    b.name as business_name,
    f.table_no,
    f.rating,
    f.note,
    f.created_at,
    f.client_id
  from public.table_feedback f
  join public.businesses b on b.id = f.business_id
  order by f.created_at desc
  limit p_limit offset p_offset;
end;
$$;


ALTER FUNCTION "public"."admin_list_table_feedback_v1"("p_limit" integer, "p_offset" integer) OWNER TO "postgres";


