ALTER FUNCTION "public"."admin_list_user_business_access_v1"("p_user_id" "uuid", "p_role_override" "text", "p_limit" integer, "p_offset" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_log_impersonation_v1"("p_target_user_id" "uuid", "p_action" "text", "p_role_override" "text" DEFAULT NULL::"text", "p_meta" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_action text := lower(nullif(trim(coalesce(p_action, '')), ''));
begin
  if not public.is_admin() then
    return jsonb_build_object('ok', false, 'code', 'forbidden');
  end if;

  if p_target_user_id is null then
    return jsonb_build_object('ok', false, 'code', 'missing_target_user');
  end if;

  if v_action not in ('start', 'stop') then
    return jsonb_build_object('ok', false, 'code', 'invalid_action');
  end if;

  insert into public.admin_audit_log(action, target_table, target_id, meta)
  values (
    case when v_action = 'start' then 'admin.impersonation.start' else 'admin.impersonation.stop' end,
    'auth.users',
    p_target_user_id,
    coalesce(p_meta, '{}'::jsonb) || jsonb_build_object(
      'actor_id', auth.uid(),
      'target_user_id', p_target_user_id,
      'role_override', lower(nullif(trim(coalesce(p_role_override, '')), ''))
    )
  );

  return jsonb_build_object('ok', true);
end;
$$;


ALTER FUNCTION "public"."admin_log_impersonation_v1"("p_target_user_id" "uuid", "p_action" "text", "p_role_override" "text", "p_meta" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_merge_businesses_v1"("p_primary_business_id" "uuid", "p_duplicate_business_id" "uuid", "p_admin_note" "text" DEFAULT NULL::"text", "p_dry_run" boolean DEFAULT false) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_primary_exists boolean := false;
  v_duplicate_exists boolean := false;
  v_now timestamptz := now();
  v_summary jsonb;
begin
  if not public.is_admin() then
    raise exception 'not_admin';
  end if;

  if p_primary_business_id is null or p_duplicate_business_id is null then
    return jsonb_build_object('ok', false, 'error', 'missing_business_id');
  end if;
  if p_primary_business_id = p_duplicate_business_id then
    return jsonb_build_object('ok', false, 'error', 'same_business');
  end if;

  select exists(select 1 from public.businesses b where b.id = p_primary_business_id)
    into v_primary_exists;
  select exists(select 1 from public.businesses b where b.id = p_duplicate_business_id)
    into v_duplicate_exists;

  if not v_primary_exists or not v_duplicate_exists then
    return jsonb_build_object('ok', false, 'error', 'business_not_found');
  end if;

  v_summary := jsonb_build_object(
    'menus', (select count(*) from public.menus where business_id = p_duplicate_business_id),
    'menu_items', (select count(*) from public.menu_items where business_id = p_duplicate_business_id),
    'reviews', (select count(*) from public.reviews where business_id = p_duplicate_business_id),
    'media', (select count(*) from public.business_media where business_id = p_duplicate_business_id),
    'stories', (select count(*) from public.business_stories where business_id = p_duplicate_business_id),
    'favorites', (select count(*) from public.favorites where business_id = p_duplicate_business_id),
    'follows', (select count(*) from public.business_follows where business_id = p_duplicate_business_id),
    'meal_cards', (select count(*) from public.business_meal_card_providers where business_id = p_duplicate_business_id)
  );

  if p_dry_run then
    return jsonb_build_object(
      'ok', true,
      'dry_run', true,
      'summary', v_summary
    );
  end if;

  insert into public.business_follows(user_id, business_id, created_at)
  select bf.user_id, p_primary_business_id, bf.created_at
  from public.business_follows bf
  where bf.business_id = p_duplicate_business_id
    and not exists (
      select 1
      from public.business_follows x
      where x.user_id = bf.user_id
        and x.business_id = p_primary_business_id
    );
  delete from public.business_follows where business_id = p_duplicate_business_id;

  insert into public.favorites(user_id, business_id, created_at)
  select f.user_id, p_primary_business_id, f.created_at
  from public.favorites f
  where f.business_id = p_duplicate_business_id
    and not exists (
      select 1
      from public.favorites x
      where x.user_id = f.user_id
        and x.business_id = p_primary_business_id
    );
  delete from public.favorites where business_id = p_duplicate_business_id;

  insert into public.user_favorites_legacy(user_id, business_id, created_at)
  select f.user_id, p_primary_business_id, f.created_at
  from public.user_favorites_legacy f
  where f.business_id = p_duplicate_business_id
    and not exists (
      select 1
      from public.user_favorites_legacy x
      where x.user_id = f.user_id
        and x.business_id = p_primary_business_id
    );
  delete from public.user_favorites_legacy where business_id = p_duplicate_business_id;

  insert into public.collection_items(collection_id, business_id, note, created_at)
  select c.collection_id, p_primary_business_id, c.note, c.created_at
  from public.collection_items c
  where c.business_id = p_duplicate_business_id
    and not exists (
      select 1
      from public.collection_items x
      where x.collection_id = c.collection_id
        and x.business_id = p_primary_business_id
    );
  delete from public.collection_items where business_id = p_duplicate_business_id;

  insert into public.business_amenity_map(business_id, amenity_id)
  select p_primary_business_id, m.amenity_id
  from public.business_amenity_map m
  where m.business_id = p_duplicate_business_id
    and not exists (
      select 1
      from public.business_amenity_map x
      where x.business_id = p_primary_business_id
        and x.amenity_id = m.amenity_id
    );
  delete from public.business_amenity_map where business_id = p_duplicate_business_id;

  insert into public.business_meal_card_providers(
    business_id,
    provider_id,
    created_at
  )
  select
    p_primary_business_id,
    m.provider_id,
    m.created_at
  from public.business_meal_card_providers m
  where m.business_id = p_duplicate_business_id
    and not exists (
      select 1
      from public.business_meal_card_providers x
      where x.business_id = p_primary_business_id
        and x.provider_id = m.provider_id
    );
  delete from public.business_meal_card_providers where business_id = p_duplicate_business_id;

  update public.owner_claims oc
  set business_id = p_primary_business_id
  where oc.business_id = p_duplicate_business_id
    and not exists (
      select 1
      from public.owner_claims x
      where x.user_id = oc.user_id
        and x.business_id = p_primary_business_id
    );
  delete from public.owner_claims where business_id = p_duplicate_business_id;

  if exists(select 1 from public.business_hours where business_id = p_primary_business_id) then
    delete from public.business_hours where business_id = p_duplicate_business_id;
  else
    update public.business_hours
      set business_id = p_primary_business_id
      where business_id = p_duplicate_business_id;
  end if;

  if exists(select 1 from public.owner_onboarding_progress where business_id = p_primary_business_id) then
    delete from public.owner_onboarding_progress where business_id = p_duplicate_business_id;
  else
    update public.owner_onboarding_progress
      set business_id = p_primary_business_id
      where business_id = p_duplicate_business_id;
  end if;

  if exists(select 1 from public.business_stats where business_id = p_primary_business_id) then
    delete from public.business_stats where business_id = p_duplicate_business_id;
  else
    update public.business_stats
      set business_id = p_primary_business_id
      where business_id = p_duplicate_business_id;
  end if;

  update public.analytics_events set business_id = p_primary_business_id where business_id = p_duplicate_business_id;
  update public.business_activity_log set business_id = p_primary_business_id where business_id = p_duplicate_business_id;
  update public.business_media set business_id = p_primary_business_id where business_id = p_duplicate_business_id;
  update public.business_premium set business_id = p_primary_business_id where business_id = p_duplicate_business_id;
  update public.business_presence_events set business_id = p_primary_business_id where business_id = p_duplicate_business_id;
  update public.business_stories set business_id = p_primary_business_id where business_id = p_duplicate_business_id;
  update public.feed_events set business_id = p_primary_business_id where business_id = p_duplicate_business_id;
  update public.menu_item_photos set business_id = p_primary_business_id where business_id = p_duplicate_business_id;
  update public.menu_item_price_suggestions set business_id = p_primary_business_id where business_id = p_duplicate_business_id;
  update public.menu_item_suggestions set business_id = p_primary_business_id where business_id = p_duplicate_business_id;
  update public.menu_items set business_id = p_primary_business_id where business_id = p_duplicate_business_id;
  update public.menus set business_id = p_primary_business_id where business_id = p_duplicate_business_id;
  update public.reviews set business_id = p_primary_business_id where business_id = p_duplicate_business_id;
  update public.sponsorship_leads set business_id = p_primary_business_id where business_id = p_duplicate_business_id;
  update public.sponsorships set business_id = p_primary_business_id where business_id = p_duplicate_business_id;
  update public.suspended_meals set business_id = p_primary_business_id where business_id = p_duplicate_business_id;
  update public.table_feedback set business_id = p_primary_business_id where business_id = p_duplicate_business_id;
  update public.visits set business_id = p_primary_business_id where business_id = p_duplicate_business_id;

  insert into public.business_merge_log(
    duplicate_business_id,
    primary_business_id,
    merged_by,
    merged_at,
    note
  ) values (
    p_duplicate_business_id,
    p_primary_business_id,
    auth.uid(),
    v_now,
    nullif(trim(coalesce(p_admin_note, '')), '')
  )
  on conflict (duplicate_business_id)
  do update set
    primary_business_id = excluded.primary_business_id,
    merged_by = excluded.merged_by,
    merged_at = excluded.merged_at,
    note = excluded.note;

  update public.businesses
  set
    is_active = false,
    source = 'merged',
    source_id = p_primary_business_id::text
  where id = p_duplicate_business_id;

  perform public.log_admin_action_v1(
    'business.merge',
    'businesses',
    p_duplicate_business_id,
    jsonb_build_object(
      'primary_business_id', p_primary_business_id,
      'duplicate_business_id', p_duplicate_business_id,
      'note', p_admin_note,
      'summary', v_summary
    )
  );

  return jsonb_build_object(
    'ok', true,
    'dry_run', false,
    'summary', v_summary
  );
end;
$$;


ALTER FUNCTION "public"."admin_merge_businesses_v1"("p_primary_business_id" "uuid", "p_duplicate_business_id" "uuid", "p_admin_note" "text", "p_dry_run" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_queue_assign_v1"("p_item_type" "text", "p_item_id" "uuid", "p_assign_to_me" boolean DEFAULT true) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_uid uuid := auth.uid();
begin
  if not public.is_admin() then
    raise exception 'not_admin';
  end if;

  if p_item_id is null then
    raise exception 'missing_item_id';
  end if;

  if p_item_type in ('report', 'media_flag') then
    if p_assign_to_me then
      perform public.admin_assign_report_v1(p_item_id);
    else
      perform public.admin_unassign_report_v1(p_item_id);
    end if;
  elsif p_item_type = 'claim' then
    if p_assign_to_me then
      perform public.admin_assign_owner_claim_v1(p_item_id);
    else
      perform public.admin_unassign_owner_claim_v1(p_item_id);
    end if;
  elsif p_item_type = 'price_suggestion' then
    update public.menu_item_price_suggestions
    set
      handled_by = case when p_assign_to_me then v_uid else null end,
      handled_at = case when p_assign_to_me then now() else null end
    where id = p_item_id;

    if not found then
      return jsonb_build_object('ok', false, 'error', 'not_found');
    end if;

    perform public.log_admin_action_v1(
      case when p_assign_to_me then 'price_suggestion.assigned' else 'price_suggestion.unassigned' end,
      'menu_item_price_suggestions',
      p_item_id,
      jsonb_build_object('assigned_to', case when p_assign_to_me then v_uid else null end)
    );
  elsif p_item_type = 'business_submission' then
    update public.business_submissions
    set
      assigned_to = case when p_assign_to_me then v_uid else null end,
      assigned_at = case when p_assign_to_me then now() else null end
    where id = p_item_id;

    if not found then
      return jsonb_build_object('ok', false, 'error', 'not_found');
    end if;

    perform public.log_admin_action_v1(
      case when p_assign_to_me then 'business_submission.assigned' else 'business_submission.unassigned' end,
      'business_submissions',
      p_item_id,
      jsonb_build_object('assigned_to', case when p_assign_to_me then v_uid else null end)
    );
  else
    raise exception 'unsupported_item_type';
  end if;

  return jsonb_build_object('ok', true);
end;
$$;


ALTER FUNCTION "public"."admin_queue_assign_v1"("p_item_type" "text", "p_item_id" "uuid", "p_assign_to_me" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_queue_v1"("p_type" "text" DEFAULT NULL::"text", "p_status" "text" DEFAULT NULL::"text", "p_city" "text" DEFAULT NULL::"text", "p_from" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_to" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_q" "text" DEFAULT NULL::"text", "p_sort_key" "text" DEFAULT 'created_at'::"text", "p_sort_dir" "text" DEFAULT 'desc'::"text", "p_limit" integer DEFAULT 20, "p_offset" integer DEFAULT 0) RETURNS TABLE("id" "uuid", "item_type" "text", "status" "text", "created_at" timestamp with time zone, "age_hours" numeric, "sla_hours" integer, "sla_breached" boolean, "title" "text", "subtitle" "text", "city" "text", "district" "text", "business_id" "uuid", "business_name" "text", "assigned_to" "uuid", "assigned_at" timestamp with time zone, "detail" "jsonb", "total_count" bigint)
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  with business_submission_base as (
    select
      s.*,
      array_remove(
        array[
          case when coalesce(nullif(trim(s.address), ''), '') = '' then 'address' end,
          case when coalesce(nullif(trim(s.phone), ''), '') = '' then 'phone' end,
          case when coalesce(nullif(trim(s.website), ''), '') = '' then 'website' end,
          case when coalesce(nullif(trim(s.category), ''), '') = '' then 'category' end
        ],
        null
      ) as missing_fields
    from public.business_submissions s
  ),
  report_base as (
    select
      r.*,
      b.city,
      b.district,
      b.name as business_name,
      coalesce(usa.risk_score, 0) as reporter_risk_score,
      case
        when r.user_id is null then 0
        when to_regprocedure('public.get_user_reputation_score_v2(uuid)') is null then 0
        else coalesce(public.get_user_reputation_score_v2(r.user_id), 0)
      end as reporter_reputation
    from public.reports r
    left join public.businesses b on b.id = r.business_id
    left join public.user_safety_actions usa on usa.user_id = r.user_id
  ),
  claim_base as (
    select
      c.*,
      b.city,
      b.district,
      b.name as business_name,
      coalesce(usa.risk_score, 0) as claimant_risk_score,
      coalesce(usa.auto_pending_until > now(), false) as claimant_auto_pending,
      case
        when c.user_id is null then 0
        when to_regprocedure('public.get_user_reputation_score_v2(uuid)') is null then 0
        else coalesce(public.get_user_reputation_score_v2(c.user_id), 0)
      end as claimant_reputation
    from public.owner_claims c
    left join public.businesses b on b.id = c.business_id
    left join public.user_safety_actions usa on usa.user_id = c.user_id
  ),
  price_suggestion_base as (
    select
      s.*,
      mi.name as menu_item_name,
      mi.price_cents as current_price_cents,
      b.city,
      b.district,
      b.name as business_name,
      coalesce(bq.score, 0) as business_quality_score,
      coalesce(usa.risk_score, 0) as created_by_risk_score,
      case
        when s.created_by is null then 0
        when to_regprocedure('public.get_user_reputation_score_v2(uuid)') is null then 0
        else coalesce(public.get_user_reputation_score_v2(s.created_by), 0)
      end as created_by_reputation
    from public.menu_item_price_suggestions s
    join public.menu_items mi on mi.id = s.menu_item_id
    join public.businesses b on b.id = s.business_id
    left join public.business_quality_score_v1 bq on bq.business_id = s.business_id
    left join public.user_safety_actions usa on usa.user_id = s.created_by
  ),
  unioned as (
    select
      s.id,
      'business_submission'::text as item_type,
      s.status::text as status,
      s.created_at,
      extract(epoch from (now() - s.created_at)) / 3600.0 as age_hours,
      24 as sla_hours,
      (s.status = 'new' and s.created_at < now() - interval '24 hours') as sla_breached,
      s.name as title,
      coalesce(nullif(trim(s.category), ''), '-') || ' • ' || coalesce(nullif(trim(s.address), ''), '-') as subtitle,
      s.city,
      s.district,
      null::uuid as business_id,
      s.name as business_name,
      s.assigned_to,
      s.assigned_at,
      jsonb_build_object(
        'submitted_by', s.submitted_by,
        'name', s.name,
        'city', s.city,
        'district', s.district,
        'category', s.category,
        'address', s.address,
        'phone', s.phone,
        'website', s.website,
        'admin_note', s.admin_note,
        'missing_fields', to_jsonb(s.missing_fields),
        'missing_field_count', cardinality(s.missing_fields),
        'review_reason', case
          when cardinality(s.missing_fields) >= 2 then 'missing_submission_data'
          else 'manual_review'
        end
      ) as detail
    from business_submission_base s

    union all

    select
      r.id,
      case
        when r.target_type in ('business_media', 'menu_item_photo') then 'media_flag'
        else 'report'
      end as item_type,
      r.status::text as status,
      r.created_at,
      extract(epoch from (now() - r.created_at)) / 3600.0 as age_hours,
      24 as sla_hours,
      (r.status in ('open', 'reviewing') and r.created_at < now() - interval '24 hours') as sla_breached,
      coalesce(nullif(trim(r.reason), ''), 'report') as title,
      coalesce(nullif(trim(r.details), ''), coalesce(r.target_type, 'report')) as subtitle,
      r.city,
      r.district,
      r.business_id,
      r.business_name,
      r.assigned_to,
      r.assigned_at,
      jsonb_build_object(
        'reason', r.reason,
        'details', r.details,
        'target_type', r.target_type,
        'target_id', r.target_id,
        'reporter_id', r.user_id,
        'admin_note', r.admin_note,
        'handled_by', r.handled_by,
        'handled_at', r.handled_at,
        'reporter_reputation', r.reporter_reputation,
        'reporter_risk_score', r.reporter_risk_score,
        'auto_moderated', coalesce(r.auto_moderated, false),
        'review_reason', case
          when coalesce(r.auto_moderated, false) then 'grey_area'
          when coalesce(r.reporter_risk_score, 0) >= 50 then 'risky_actor'
          else 'manual_review'
        end
      ) as detail
    from report_base r

    union all

    select
      c.id,
      'claim'::text as item_type,
      c.status::text as status,
      c.created_at,
      extract(epoch from (now() - c.created_at)) / 3600.0 as age_hours,
      48 as sla_hours,
      (c.status = 'pending' and c.created_at < now() - interval '48 hours') as sla_breached,
      coalesce(nullif(trim(c.full_name), ''), 'claim') as title,
      coalesce(nullif(trim(c.phone), ''), '-') as subtitle,
      c.city,
      c.district,
      c.business_id,
      c.business_name,
      c.handled_by as assigned_to,
      c.handled_at as assigned_at,
      jsonb_build_object(
        'full_name', c.full_name,
        'phone', c.phone,
        'evidence_url', c.evidence_url,
        'note', c.note,
        'admin_note', c.admin_note,
        'claimant_reputation', c.claimant_reputation,
        'claimant_risk_score', c.claimant_risk_score,
        'claimant_auto_pending', c.claimant_auto_pending,
        'review_reason', case
          when coalesce(nullif(trim(c.evidence_url), ''), '') = '' then 'missing_evidence'
          when c.claimant_auto_pending or coalesce(c.claimant_risk_score, 0) >= 50 then 'claimant_auto_pending'
          else 'manual_review'
        end
      ) as detail
    from claim_base c

    union all

    select
      s.id,
      'price_suggestion'::text as item_type,
      s.status::text as status,
      s.created_at,
      extract(epoch from (now() - s.created_at)) / 3600.0 as age_hours,
      48 as sla_hours,
      (s.status = 'pending' and s.created_at < now() - interval '48 hours') as sla_breached,
      coalesce(nullif(trim(s.menu_item_name), ''), 'price suggestion') as title,
      concat(
        coalesce(s.current_price_cents, 0) / 100.0,
        ' -> ',
        coalesce(s.suggested_price_cents, 0) / 100.0,
        ' ',
        coalesce(s.currency, 'TRY')
      ) as subtitle,
      s.city,
      s.district,
      s.business_id,
      s.business_name,
      s.handled_by as assigned_to,
      s.handled_at as assigned_at,
      jsonb_build_object(
        'menu_item_id', s.menu_item_id,
        'menu_item_name', s.menu_item_name,
        'current_price_cents', s.current_price_cents,
        'suggested_price_cents', s.suggested_price_cents,
        'currency', s.currency,
        'created_by', s.created_by,
        'quality_confidence', s.quality_confidence,
        'anomaly_score', s.anomaly_score,
        'anomaly_flags', s.anomaly_flags,
        'conflict_state', s.conflict_state,
        'conflict_variants_24h', s.conflict_variants_24h,
        'created_by_reputation', s.created_by_reputation,
        'created_by_risk_score', s.created_by_risk_score,
        'business_quality_score', s.business_quality_score,
        'review_reason', case
          when s.conflict_state = 'queued' and coalesce(s.anomaly_score, 0) >= 0.5 then 'conflict_and_anomaly'
          when s.conflict_state = 'queued' then 'price_conflict'
          when coalesce(s.anomaly_score, 0) >= 0.5 then 'anomaly_queue'
          when coalesce(s.quality_confidence, 1) < 0.65 then 'low_confidence'
          else 'manual_review'
        end
      ) as detail
    from price_suggestion_base s
  ),
  filtered as (
    select *
    from unioned q
    where public.is_admin()
      and (p_type is null or p_type = '' or q.item_type = p_type)
      and (p_status is null or p_status = '' or q.status = p_status)
      and (p_city is null or p_city = '' or coalesce(q.city, '') ilike ('%' || p_city || '%'))
      and (p_from is null or q.created_at >= p_from)
      and (p_to is null or q.created_at <= p_to)
      and (
        p_q is null
        or p_q = ''
        or coalesce(q.title, '') ilike ('%' || p_q || '%')
        or coalesce(q.subtitle, '') ilike ('%' || p_q || '%')
        or coalesce(q.business_name, '') ilike ('%' || p_q || '%')
        or coalesce(q.city, '') ilike ('%' || p_q || '%')
        or coalesce(q.district, '') ilike ('%' || p_q || '%')
      )
  ),
  ranked as (
    select
      f.*,
      count(*) over() as total_count
    from filtered f
    order by
      case when p_sort_key = 'item_type' and p_sort_dir = 'asc' then f.item_type end asc nulls last,
      case when p_sort_key = 'item_type' and p_sort_dir = 'desc' then f.item_type end desc nulls last,
      case when p_sort_key = 'title' and p_sort_dir = 'asc' then f.title end asc nulls last,
      case when p_sort_key = 'title' and p_sort_dir = 'desc' then f.title end desc nulls last,
      case when p_sort_key = 'city' and p_sort_dir = 'asc' then f.city end asc nulls last,
      case when p_sort_key = 'city' and p_sort_dir = 'desc' then f.city end desc nulls last,
      case when p_sort_key = 'status' and p_sort_dir = 'asc' then f.status end asc nulls last,
      case when p_sort_key = 'status' and p_sort_dir = 'desc' then f.status end desc nulls last,
      case when p_sort_key = 'age_hours' and p_sort_dir = 'asc' then f.age_hours end asc nulls last,
      case when p_sort_key = 'age_hours' and p_sort_dir = 'desc' then f.age_hours end desc nulls last,
      case when p_sort_key = 'created_at' and p_sort_dir = 'asc' then f.created_at end asc nulls last,
      case when p_sort_key = 'created_at' and p_sort_dir = 'desc' then f.created_at end desc nulls last,
      f.created_at desc
    limit greatest(p_limit, 0)
    offset greatest(p_offset, 0)
  )
  select *
  from ranked;
$$;


ALTER FUNCTION "public"."admin_queue_v1"("p_type" "text", "p_status" "text", "p_city" "text", "p_from" timestamp with time zone, "p_to" timestamp with time zone, "p_q" "text", "p_sort_key" "text", "p_sort_dir" "text", "p_limit" integer, "p_offset" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_reject_business_submission_v1"("p_submission_id" "uuid", "p_note" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  if not public.is_admin() then
    return jsonb_build_object('ok', false, 'error', 'not_admin');
  end if;

  update public.business_submissions
  set status = 'rejected',
      admin_note = p_note
  where id = p_submission_id;

  if not found then
    return jsonb_build_object('ok', false, 'error', 'not_found');
  end if;

  return jsonb_build_object('ok', true);
end;
$$;


ALTER FUNCTION "public"."admin_reject_business_submission_v1"("p_submission_id" "uuid", "p_note" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_reject_business_suggestion_v1"("p_suggestion_id" "uuid", "p_admin_note" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_status text;
begin
  if not public.is_admin() then
    raise exception 'not_admin';
  end if;

  select status
  into v_status
  from public.business_suggestions
  where id = p_suggestion_id;

  if v_status is null then
    return jsonb_build_object('ok', false, 'error', 'suggestion_not_found');
  end if;

  if v_status <> 'pending' then
    return jsonb_build_object('ok', false, 'error', 'not_pending');
  end if;

  update public.business_suggestions
  set
    status = 'rejected',
    admin_note = p_admin_note,
    handled_by = auth.uid(),
    handled_at = now()
  where id = p_suggestion_id;

  -- 🔍 AUDIT LOG
  perform public.log_admin_action_v1(
    'suggestion.reject',
    'business_suggestions',
    p_suggestion_id,
    jsonb_build_object(
      'admin_note', p_admin_note
    )
  );

  return jsonb_build_object('ok', true);
end;
$$;


ALTER FUNCTION "public"."admin_reject_business_suggestion_v1"("p_suggestion_id" "uuid", "p_admin_note" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_reject_menu_price_suggestion_v1"("p_suggestion_id" "uuid", "p_note" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_note text;
  v_before jsonb;
  v_after jsonb;
begin
  if not public.is_admin() then
    return jsonb_build_object('ok', false, 'error', 'not_admin');
  end if;

  v_note := nullif(trim(p_note), '');

  select jsonb_build_object(
    'business_id', s.business_id,
    'menu_item_id', s.menu_item_id,
    'status', s.status,
    'suggested_price_cents', s.suggested_price_cents,
    'currency', s.currency,
    'note', s.note
  )
  into v_before
  from public.menu_item_price_suggestions s
  where s.id = p_suggestion_id
    and s.status = 'pending';

  update public.menu_item_price_suggestions
  set status = 'rejected',
      note = coalesce(note, v_note),
      handled_by = auth.uid(),
      handled_at = now()
  where id = p_suggestion_id
    and status = 'pending';

  if not found then
    return jsonb_build_object('ok', false, 'error', 'not_found_or_not_pending');
  end if;

  select jsonb_build_object(
    'business_id', s.business_id,
    'menu_item_id', s.menu_item_id,
    'status', s.status,
    'suggested_price_cents', s.suggested_price_cents,
    'currency', s.currency,
    'note', s.note,
    'handled_by', s.handled_by
  )
  into v_after
  from public.menu_item_price_suggestions s
  where s.id = p_suggestion_id;

  perform public.insert_audit_log_v1(
    'price_suggestion.rejected',
    'menu_item_price_suggestions',
    p_suggestion_id,
    v_before,
    v_after
  );

  return jsonb_build_object('ok', true);
end;
$$;


ALTER FUNCTION "public"."admin_reject_menu_price_suggestion_v1"("p_suggestion_id" "uuid", "p_note" "text") OWNER TO "postgres";


