CREATE OR REPLACE FUNCTION "public"."admin_reset_user_achievement_v1"("p_user_id" "uuid", "p_achievement_id" "text", "p_reason" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_deleted int := 0;
  v_award_deleted int := 0;
  v_reason text := nullif(trim(p_reason), '');
  v_target_id text := coalesce(p_user_id::text, '') || ':' || coalesce(trim(p_achievement_id), '');
begin
  if not public.is_admin() then
    return jsonb_build_object('ok', false, 'error', 'not_admin');
  end if;

  if p_user_id is null or coalesce(trim(p_achievement_id), '') = '' then
    return jsonb_build_object('ok', false, 'error', 'bad_request');
  end if;

  delete from public.user_achievements ua
  where ua.user_id = p_user_id
    and ua.achievement_id = trim(p_achievement_id);
  get diagnostics v_deleted = row_count;

  delete from public.user_achievement_awards a
  where a.user_id = p_user_id
    and a.achievement_id = trim(p_achievement_id);
  get diagnostics v_award_deleted = row_count;

  perform public.recompute_profile_progress_v1(p_user_id);

  insert into public.admin_audit_log(action, target_table, target_id, meta)
  values (
    'achievement.reset',
    'user_achievements',
    v_target_id,
    jsonb_build_object(
      'user_id', p_user_id,
      'achievement_id', trim(p_achievement_id),
      'deleted', v_deleted > 0,
      'award_rows_deleted', v_award_deleted,
      'reason', v_reason
    )
  );

  return jsonb_build_object(
    'ok', true,
    'deleted', v_deleted > 0,
    'award_rows_deleted', v_award_deleted
  );
end;
$$;


ALTER FUNCTION "public"."admin_reset_user_achievement_v1"("p_user_id" "uuid", "p_achievement_id" "text", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_set_business_media_v1"("p_business_id" "uuid", "p_field" "text", "p_url" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  if not public.is_admin() then raise exception 'not_admin'; end if;
  if p_field not in ('logo_url','cover_url') then
    return jsonb_build_object('ok', false, 'error', 'bad_field');
  end if;

  if p_field = 'logo_url' then
    update public.businesses set logo_url = p_url where id = p_business_id;
  else
    update public.businesses set cover_url = p_url where id = p_business_id;
  end if;

  perform public.log_admin_action_v1(
    'business.set_media',
    'businesses',
    p_business_id,
    jsonb_build_object('field', p_field, 'url', p_url)
  );

  return jsonb_build_object('ok', true);
end;
$$;


