CREATE OR REPLACE FUNCTION "public"."admin_set_business_verified_v1"("p_business_id" "uuid", "p_is_verified" boolean, "p_tier" "text" DEFAULT 'verified'::"text", "p_ends_at" timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_id uuid;
  v_before jsonb;
  v_after jsonb;
begin
  if not public.is_admin() then
    return jsonb_build_object('ok', false, 'code', 'not_admin', 'message', 'Not admin');
  end if;

  select jsonb_build_object(
    'business_id', b.id,
    'is_verified', b.is_verified,
    'verified_at', b.verified_at,
    'verified_by', b.verified_by,
    'tier', bp.tier,
    'premium_status', bp.status,
    'premium_ends_at', bp.ends_at
  )
  into v_before
  from public.businesses b
  left join lateral (
    select p.tier, p.status, p.ends_at
    from public.business_premium p
    where p.business_id = b.id
      and p.tier = p_tier
    order by p.created_at desc
    limit 1
  ) bp on true
  where b.id = p_business_id;

  update public.businesses
  set
    is_verified = p_is_verified,
    verified_at = case when p_is_verified then now() else null end,
    verified_by = case when p_is_verified then auth.uid() else null end
  where id = p_business_id;

  if p_is_verified then
    insert into public.business_premium(
      business_id, tier, status, starts_at, ends_at, source, created_by
    )
    values (
      p_business_id, p_tier, 'active', now(), p_ends_at, 'manual', auth.uid()
    )
    on conflict (business_id, tier) where status = 'active'
    do update set
      ends_at = excluded.ends_at,
      status = 'active';
  else
    update public.business_premium
    set status = 'ended',
        ends_at = coalesce(p_ends_at, now())
    where business_id = p_business_id
      and tier = p_tier
      and status = 'active';
  end if;

  select id into v_id
  from public.business_premium
  where business_id = p_business_id
    and tier = p_tier
  order by created_at desc
  limit 1;

  select jsonb_build_object(
    'business_id', b.id,
    'is_verified', b.is_verified,
    'verified_at', b.verified_at,
    'verified_by', b.verified_by,
    'tier', bp.tier,
    'premium_status', bp.status,
    'premium_ends_at', bp.ends_at,
    'premium_id', v_id
  )
  into v_after
  from public.businesses b
  left join lateral (
    select p.tier, p.status, p.ends_at
    from public.business_premium p
    where p.business_id = b.id
      and p.tier = p_tier
    order by p.created_at desc
    limit 1
  ) bp on true
  where b.id = p_business_id;

  perform public.insert_audit_log_v1(
    'business.verification_changed',
    'business',
    p_business_id,
    v_before,
    v_after
  );

  return jsonb_build_object('ok', true, 'business_id', p_business_id, 'premium_id', v_id);
end;
$$;


ALTER FUNCTION "public"."admin_set_business_verified_v1"("p_business_id" "uuid", "p_is_verified" boolean, "p_tier" "text", "p_ends_at" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_set_menu_item_photo_moderation_v1"("p_photo_id" "uuid", "p_status" "text", "p_is_hidden" boolean DEFAULT false, "p_note" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
