CREATE OR REPLACE FUNCTION "public"."admin_update_receipt_submission_review_v1"("p_receipt_id" "uuid", "p_review_status" "text", "p_review_note" "text" DEFAULT NULL::"text", "p_reviewed_by" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  if not public.is_admin() then
    return jsonb_build_object('ok', false, 'code', 'not_admin');
  end if;

  if p_review_status not in ('pending', 'reviewed', 'needs_followup') then
    return jsonb_build_object('ok', false, 'code', 'invalid_status');
  end if;

  update public.receipt_submissions
  set
    review_status = p_review_status,
    review_note = nullif(trim(coalesce(p_review_note, '')), ''),
    reviewed_at = case
      when p_review_status = 'pending' then null
      else now()
    end,
    reviewed_by = case
      when p_review_status = 'pending' then null
      else p_reviewed_by
    end
  where id = p_receipt_id;

  return jsonb_build_object('ok', true, 'id', p_receipt_id);
end;
$$;


