CREATE OR REPLACE FUNCTION "public"."admin_update_report_v2"("p_report_id" "uuid", "p_status" "text", "p_admin_note" "text" DEFAULT NULL::"text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_status text;
begin
  if not public.is_admin() then
    raise exception 'not_admin';
  end if;

  v_status := case
    when p_status in ('acik','open') then 'open'
    when p_status in ('inceleniyor','reviewing') then 'reviewing'
    when p_status in ('kapandi','closed','reddedildi','rejected') then 'closed'
    else 'open'
  end;

  update public.reports
  set
    status = v_status,
    handled_by = auth.uid(),
    handled_at = now(),
    admin_note = p_admin_note
  where id = p_report_id;

  perform public.log_admin_action_v1(
    'report.update',
    'reports',
    p_report_id,
    jsonb_build_object('status', v_status, 'admin_note', p_admin_note)
  );
end;
$$;


