CREATE OR REPLACE FUNCTION "public"."admin_upsert_sponsorship_package_v1"("p_id" "uuid" DEFAULT NULL::"uuid", "p_name" "text" DEFAULT NULL::"text", "p_surface" "text" DEFAULT NULL::"text", "p_duration_days" integer DEFAULT NULL::integer, "p_price_display" "text" DEFAULT NULL::"text", "p_is_active" boolean DEFAULT true, "p_price_cents" integer DEFAULT 0, "p_currency_code" "text" DEFAULT 'TRY'::"text", "p_inventory_limit" integer DEFAULT 1) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_id uuid;
begin
  if not public.is_admin() then
    return jsonb_build_object('ok', false, 'code', 'not_admin', 'message', 'Not admin');
  end if;

  if p_id is null then
    insert into public.sponsorship_packages(
      name,
      surface,
      duration_days,
      price_display,
      is_active,
      price_cents,
      currency_code,
      inventory_limit
    )
    values (
      p_name,
      p_surface,
      p_duration_days,
      p_price_display,
      p_is_active,
      greatest(coalesce(p_price_cents, 0), 0),
      coalesce(nullif(trim(p_currency_code), ''), 'TRY'),
      greatest(coalesce(p_inventory_limit, 1), 1)
    )
    returning id into v_id;
  else
    update public.sponsorship_packages
    set
      name = p_name,
      surface = p_surface,
      duration_days = p_duration_days,
      price_display = p_price_display,
      is_active = p_is_active,
      price_cents = greatest(coalesce(p_price_cents, 0), 0),
      currency_code = coalesce(nullif(trim(p_currency_code), ''), 'TRY'),
      inventory_limit = greatest(coalesce(p_inventory_limit, 1), 1)
    where id = p_id
    returning id into v_id;
  end if;

  return jsonb_build_object('ok', true, 'id', v_id);
end;
$$;


