CREATE OR REPLACE FUNCTION "public"."analytics_growth_v1"("p_days" integer DEFAULT 30, "p_business_id" "uuid" DEFAULT NULL::"uuid") RETURNS TABLE("day" "date", "menu_link_opened" integer, "qr_scanned" integer, "menu_shared" integer, "app_install_from_menu" integer)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  if not public.is_admin() then
    raise exception 'not authorized';
  end if;

  return query
  select
    d.day::date,
    sum(case when e.event_name = 'menu_link_opened' then 1 else 0 end)::int as menu_link_opened,
    sum(case when e.event_name = 'qr_scanned' then 1 else 0 end)::int as qr_scanned,
    sum(case when e.event_name = 'menu_shared' then 1 else 0 end)::int as menu_shared,
    sum(case when e.event_name = 'app_install_from_menu' then 1 else 0 end)::int as app_install_from_menu
  from generate_series(
    (current_date - greatest(p_days, 1) + 1)::date,
    current_date::date,
    interval '1 day'
  ) as d(day)
  left join public.analytics_events e
    on date_trunc('day', e.created_at) = d.day
   and (p_business_id is null or e.business_id = p_business_id)
  group by d.day
  order by d.day;
end;
$$;


ALTER FUNCTION "public"."analytics_growth_v1"("p_days" integer, "p_business_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."analytics_growth_v2"("p_days" integer DEFAULT 30, "p_business_id" "uuid" DEFAULT NULL::"uuid") RETURNS TABLE("day" "date", "menu_link_opened" integer, "qr_scanned" integer, "menu_shared" integer, "app_install_from_menu" integer, "business_reservation_click" integer, "business_order_click" integer, "business_whatsapp_click" integer, "business_phone_click" integer)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  if not public.is_admin() then
    if p_business_id is null or not public.is_owner_of_business(p_business_id) then
      raise exception 'not authorized';
    end if;
  end if;

  return query
  select
    d.day::date,
    sum(case when e.event_name = 'menu_link_opened' then 1 else 0 end)::int as menu_link_opened,
    sum(case when e.event_name = 'qr_scanned' then 1 else 0 end)::int as qr_scanned,
    sum(case when e.event_name = 'menu_shared' then 1 else 0 end)::int as menu_shared,
    sum(case when e.event_name = 'app_install_from_menu' then 1 else 0 end)::int as app_install_from_menu,
    sum(case when e.event_name = 'business_reservation_click' then 1 else 0 end)::int as business_reservation_click,
    sum(case when e.event_name = 'business_order_click' then 1 else 0 end)::int as business_order_click,
    sum(case when e.event_name = 'business_whatsapp_click' then 1 else 0 end)::int as business_whatsapp_click,
    sum(case when e.event_name = 'business_phone_click' then 1 else 0 end)::int as business_phone_click
  from generate_series(
    (current_date - greatest(p_days, 1) + 1)::date,
    current_date::date,
    interval '1 day'
  ) as d(day)
  left join public.analytics_events e
    on date_trunc('day', e.created_at) = d.day
   and (p_business_id is null or e.business_id = p_business_id)
  group by d.day
  order by d.day;
end;
$$;


ALTER FUNCTION "public"."analytics_growth_v2"("p_days" integer, "p_business_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."analytics_growth_v3"("p_days" integer DEFAULT 30, "p_business_id" "uuid" DEFAULT NULL::"uuid") RETURNS TABLE("day" "date", "menu_link_opened" integer, "qr_scanned" integer, "menu_shared" integer, "app_install_from_menu" integer, "business_reservation_click" integer, "business_order_click" integer, "business_whatsapp_click" integer, "business_phone_click" integer, "price_dropoff_estimate" integer, "district_price_gap_pct" numeric, "district_price_position" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  if not public.is_admin() then
    if p_business_id is null or not public.is_owner_of_business(p_business_id) then
      raise exception 'not authorized';
    end if;
  end if;

  return query
  with events as (
    select
      d.day::date as day,
      sum(case when e.event_name = 'menu_link_opened' then 1 else 0 end)::int as menu_link_opened,
      sum(case when e.event_name = 'qr_scanned' then 1 else 0 end)::int as qr_scanned,
      sum(case when e.event_name = 'menu_shared' then 1 else 0 end)::int as menu_shared,
      sum(case when e.event_name = 'app_install_from_menu' then 1 else 0 end)::int as app_install_from_menu,
      sum(case when e.event_name = 'business_reservation_click' then 1 else 0 end)::int as business_reservation_click,
      sum(case when e.event_name = 'business_order_click' then 1 else 0 end)::int as business_order_click,
      sum(case when e.event_name = 'business_whatsapp_click' then 1 else 0 end)::int as business_whatsapp_click,
      sum(case when e.event_name = 'business_phone_click' then 1 else 0 end)::int as business_phone_click
    from generate_series(
      (current_date - greatest(p_days, 1) + 1)::date,
      current_date::date,
      interval '1 day'
    ) as d(day)
    left join public.analytics_events e
      on date_trunc('day', e.created_at) = d.day
     and (p_business_id is null or e.business_id = p_business_id)
    group by d.day
  ),
  business_ctx as (
    select
      b.id,
      b.city,
      b.district
    from public.businesses b
    where b.id = p_business_id
    limit 1
  ),
  business_price as (
    select percentile_disc(0.5) within group (order by mi.price_cents)::numeric as median_price_cents
    from public.menu_items mi
    where mi.business_id = p_business_id
      and mi.price_cents is not null
      and mi.price_cents > 0
  ),
  district_price as (
    select percentile_disc(0.5) within group (order by mi.price_cents)::numeric as median_price_cents
    from business_ctx bc
    join public.businesses b on b.city = bc.city and b.district = bc.district and b.is_active = true
    join public.menu_items mi on mi.business_id = b.id
    where mi.price_cents is not null
      and mi.price_cents > 0
  ),
  gap as (
    select
      case
        when bp.median_price_cents is null or dp.median_price_cents is null or dp.median_price_cents <= 0
          then null
        else round((((bp.median_price_cents - dp.median_price_cents) / dp.median_price_cents) * 100)::numeric, 1)
      end as district_price_gap_pct
    from business_price bp
    cross join district_price dp
  )
  select
    e.day,
    e.menu_link_opened,
    e.qr_scanned,
    e.menu_shared,
    e.app_install_from_menu,
    e.business_reservation_click,
    e.business_order_click,
    e.business_whatsapp_click,
    e.business_phone_click,
    greatest(
      0,
      round(
        greatest(
          0,
          e.menu_link_opened - (
            e.business_reservation_click +
            e.business_order_click +
            e.business_whatsapp_click +
            e.business_phone_click
          )
        ) * case
          when gap.district_price_gap_pct is null then 0.10
          when gap.district_price_gap_pct <= 0 then 0.08
          else least(0.65, gap.district_price_gap_pct / 100.0)
        end
      )::int
    ) as price_dropoff_estimate,
    gap.district_price_gap_pct,
    case
      when gap.district_price_gap_pct is null then 'unknown'
      when gap.district_price_gap_pct >= 8 then 'higher'
      when gap.district_price_gap_pct <= -8 then 'lower'
      else 'similar'
    end as district_price_position
  from events e
  left join gap on true
  order by e.day;
end;
$$;


ALTER FUNCTION "public"."analytics_growth_v3"("p_days" integer, "p_business_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."anonymize_user_content_v1"("p_user_id" "uuid", "p_reason" "text" DEFAULT 'user_deleted'::"text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_reviews int := 0;
  v_reports int := 0;
  v_suggestions int := 0;
  v_incidents int := 0;
begin
  if p_user_id is null then
    raise exception 'user_id_required';
  end if;

  -- Keep public content but unlink user identity.
  update public.reviews
     set user_id = null
   where user_id = p_user_id;
  get diagnostics v_reviews = row_count;

  update public.reports
     set reporter_user_id = null,
         user_id = null
   where reporter_user_id = p_user_id
      or user_id = p_user_id;
  get diagnostics v_reports = row_count;

  update public.business_suggestions
     set user_id = null
   where user_id = p_user_id;
  get diagnostics v_suggestions = row_count;

  update public.incident_updates
     set created_by = null
   where created_by = p_user_id;
  get diagnostics v_incidents = row_count;

  perform public.insert_audit_log_v1(
    'user.anonymized',
    'user_profile',
    p_user_id,
    null,
    jsonb_build_object(
      'reason', p_reason,
      'reviews_unlinked', v_reviews,
      'reports_unlinked', v_reports,
      'suggestions_unlinked', v_suggestions,
      'incidents_unlinked', v_incidents
    )
  );
end;
$$;


ALTER FUNCTION "public"."anonymize_user_content_v1"("p_user_id" "uuid", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."apply_auto_moderation_rules_v1"("p_target" "text", "p_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_applied boolean := false;
begin
  if not public.is_admin() then
    raise exception 'not_admin';
  end if;

  if p_target = 'report' then
    v_applied := public.auto_close_duplicate_report_v1(p_id)
                 or public.auto_reject_low_quality_report_v1(p_id)
                 or public.auto_queue_grey_report_v1(p_id);
  elsif p_target = 'claim' then
    v_applied := public.auto_approve_trusted_owner_claim_v1(p_id);
  end if;

  return jsonb_build_object('ok', true, 'applied', v_applied);
end;
$$;


