CREATE OR REPLACE FUNCTION "public"."apply_profile_xp_v1"("p_user_id" "uuid", "p_xp" integer) RETURNS TABLE("total_xp" integer, "level" integer, "unlocked_count" integer, "leveled_up" boolean)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_prev_level int;
begin
  if p_user_id is null then
    return;
  end if;

  insert into public.user_profile_progress(user_id)
  values (p_user_id)
  on conflict (user_id) do nothing;

  select upp.level
    into v_prev_level
  from public.user_profile_progress upp
  where upp.user_id = p_user_id
  for update;

  update public.user_profile_progress upp
  set
    total_xp = greatest(0, upp.total_xp + greatest(coalesce(p_xp, 0), 0)),
    unlocked_count = (
      select count(*)
      from public.user_achievements ua
      where ua.user_id = p_user_id
    ),
    updated_at = now()
  where upp.user_id = p_user_id;

  update public.user_profile_progress upp
  set level = public.profile_level_from_xp_v1(upp.total_xp)
  where upp.user_id = p_user_id;

  return query
  select
    upp.total_xp,
    upp.level,
    upp.unlocked_count,
    (upp.level > coalesce(v_prev_level, 1)) as leveled_up
  from public.user_profile_progress upp
  where upp.user_id = p_user_id;
end;
$$;


ALTER FUNCTION "public"."apply_profile_xp_v1"("p_user_id" "uuid", "p_xp" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."approve_business_suggestion"("p_suggestion_id" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_is_admin boolean;
  v_s public.business_suggestions%rowtype;
  v_business_id uuid;
begin
  -- admin check
  select exists(
    select 1 from public.admin_users au
    where au.user_id = auth.uid()
  )
  into v_is_admin;

  if not v_is_admin then
    raise exception 'not_authorized';
  end if;

  -- lock suggestion row
  select *
  into v_s
  from public.business_suggestions
  where id = p_suggestion_id
  for update;

  if not found then
    raise exception 'suggestion_not_found';
  end if;

  if v_s.status <> 'pending' then
    raise exception 'suggestion_not_pending';
  end if;

  -- insert into businesses (YOUR SCHEMA)
  insert into public.businesses (
    name,
    category,
    description,
    phone,
    address,
    city,
    district,
    lat,
    lng,
    is_active
  )
  values (
    v_s.name,
    v_s.category,
    coalesce(nullif(v_s.notes, ''), null), -- description <- notes
    v_s.phone,
    v_s.address,
    v_s.city,
    v_s.district,
    null, -- lat (öneri tablosunda yoksa NULL)
    null, -- lng
    true
  )
  returning id into v_business_id;

  -- mark suggestion approved + link created business
  update public.business_suggestions
  set
    status = 'approved',
    reviewed_at = now(),
    approved_business_id = v_business_id
  where id = p_suggestion_id;

  return v_business_id;
end;
$$;


ALTER FUNCTION "public"."approve_business_suggestion"("p_suggestion_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."approve_business_suggestion"("p_suggestion_id" "uuid") IS 'DEPRECATED: planned removal after compatibility window';



CREATE OR REPLACE FUNCTION "public"."approve_menu_item_suggestion_v1"("p_suggestion_id" "uuid", "p_note" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  s record;
  v_item_id uuid;
  v_note text;
  v_tags jsonb;
begin
  if not public.is_admin() then
    raise exception 'not_admin';
  end if;

  v_note := nullif(trim(p_note), '');

  select * into s
  from public.menu_item_suggestions
  where id = p_suggestion_id and status = 'pending';

  if s is null then
    return jsonb_build_object('ok', false, 'error', 'not_found_or_not_pending');
  end if;

  v_tags := case
    when jsonb_typeof(s.payload->'tags') = 'array' then s.payload->'tags'
    else '[]'::jsonb
  end;

  if s.action = 'create' then
    insert into public.menu_items(
      section_id,
      business_id,
      name,
      description,
      price_cents,
      currency,
      is_available,
      tags,
      sort_order
    )
    values (
      (s.payload->>'section_id')::uuid,
      s.business_id,
      coalesce(s.payload->>'name',''),
      s.payload->>'description',
      nullif(s.payload->>'price_cents','')::int,
      coalesce(s.payload->>'currency','TRY'),
      true,
      v_tags,
      coalesce(nullif(s.payload->>'sort_order','')::int, 0)
    )
    returning id into v_item_id;

  elsif s.action = 'price_update' then
    update public.menu_items
    set price_cents = coalesce(nullif(s.payload->>'price_cents','')::int, price_cents),
        currency = coalesce(s.payload->>'currency', currency),
        updated_at = now()
    where id = s.menu_item_id;

    v_item_id := s.menu_item_id;

  elsif s.action = 'update' then
    update public.menu_items
    set
      name = coalesce(s.payload->>'name', name),
      description = coalesce(s.payload->>'description', description),
      price_cents = coalesce(nullif(s.payload->>'price_cents','')::int, price_cents),
      currency = coalesce(s.payload->>'currency', currency),
      tags = case
        when jsonb_typeof(s.payload->'tags') = 'array' then s.payload->'tags'
        else tags
      end,
      updated_at = now()
    where id = s.menu_item_id;

    v_item_id := s.menu_item_id;

  elsif s.action = 'delete' then
    update public.menu_items
    set is_available = false,
        updated_at = now()
    where id = s.menu_item_id;

    v_item_id := s.menu_item_id;
  end if;

  update public.menu_item_suggestions
  set status = 'approved',
      handled_by = auth.uid(),
      handled_at = now(),
      admin_note = v_note
  where id = p_suggestion_id;

  return jsonb_build_object('ok', true, 'menu_item_id', v_item_id);
end;
$$;


ALTER FUNCTION "public"."approve_menu_item_suggestion_v1"("p_suggestion_id" "uuid", "p_note" "text") OWNER TO "postgres";


