CREATE OR REPLACE FUNCTION "public"."auto_close_duplicate_report_v1"("p_report_id" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_r public.reports%rowtype;
  v_exists boolean;
begin
  select * into v_r from public.reports where id = p_report_id;

  if v_r.id is null then return false; end if;

  select exists(
    select 1
    from public.reports
    where user_id = v_r.user_id
      and target_type = v_r.target_type
      and target_id = v_r.target_id
      and id <> v_r.id
      and created_at >= now() - interval '24 hours'
  ) into v_exists;

  if v_exists then
    update public.reports
    set
      status = 'closed',
      admin_note = 'Otomatik: 24 saat içinde mükerrer bildirim',
      handled_at = now(),
      auto_moderated = true
    where id = p_report_id;

    perform public.log_admin_action_v1(
      'report.auto_close_duplicate',
      'reports',
      p_report_id,
      jsonb_build_object()
    );

    return true;
  end if;

  return false;
end;
$$;


ALTER FUNCTION "public"."auto_close_duplicate_report_v1"("p_report_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."auto_queue_grey_report_v1"("p_report_id" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_r public.reports%rowtype;
  v_len int;
begin
  select * into v_r from public.reports where id = p_report_id;
  v_len := length(coalesce(v_r.details, ''));

  if v_r.id is null then return false; end if;

  if v_r.status = 'closed' then
    return false;
  end if;

  if v_len >= 15 and v_len <= 200 and v_r.reason not in ('spam','duplicate') then
    update public.reports
    set
      status = 'reviewing',
      admin_note = 'Otomatik: gri alan, kuyruğa alındı',
      handled_at = now(),
      auto_moderated = true
    where id = p_report_id;

    perform public.log_admin_action_v1(
      'report.auto_queue_grey',
      'reports',
      p_report_id,
      jsonb_build_object('length', v_len, 'reason', v_r.reason)
    );

    return true;
  end if;

  return false;
end;
$$;


ALTER FUNCTION "public"."auto_queue_grey_report_v1"("p_report_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."auto_reject_low_quality_report_v1"("p_report_id" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_len int;
  v_uid uuid;
begin
  select length(coalesce(details,'')), user_id into v_len, v_uid
  from public.reports
  where id = p_report_id;

  if v_len < 15 then
    update public.reports
    set
      status = 'closed',
      admin_note = 'Otomatik: çok kısa / düşük kaliteli bildirim',
      handled_at = now(),
      auto_moderated = true
    where id = p_report_id;

    perform public.log_admin_action_v1(
      'report.auto_reject_low_quality',
      'reports',
      p_report_id,
      jsonb_build_object('length', v_len)
    );

    perform public.add_moderation_strike_v1(
      v_uid,
      'low_quality_report',
      'report'
    );

    return true;
  end if;

  return false;
end;
$$;


