CREATE OR REPLACE FUNCTION "public"."capture_request_meta_v1"(OUT "o_ip" "text", OUT "o_user_agent" "text") RETURNS "record"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_headers jsonb;
begin
  o_ip := null;
  o_user_agent := null;

  begin
    v_headers := nullif(current_setting('request.headers', true), '')::jsonb;
  exception when others then
    v_headers := null;
  end;

  if v_headers is not null then
    o_ip := coalesce(v_headers ->> 'x-real-ip', v_headers ->> 'x-forwarded-for');
    o_user_agent := v_headers ->> 'user-agent';
  end if;
end;
$$;


ALTER FUNCTION "public"."capture_request_meta_v1"(OUT "o_ip" "text", OUT "o_user_agent" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."capture_request_metadata_v1"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  if tg_table_name in ('user_policy_acceptances', 'privacy_requests', 'account_deletion_requests')
     and new.user_id is null then
    new.user_id := auth.uid();
  end if;

  if tg_table_name in ('user_policy_acceptances', 'business_policy_acceptances') then
    if new.accepted_at is null then
      new.accepted_at := now();
    end if;
    if new.user_agent is null then
      new.user_agent := public.request_header_v1('user-agent');
    end if;
    if new.ip_address is null then
      new.ip_address := public.request_ip_v1();
    end if;
  end if;

  if tg_table_name = 'privacy_requests' and new.submitted_at is null then
    new.submitted_at := now();
  end if;

  if tg_table_name = 'account_deletion_requests' and new.requested_at is null then
    new.requested_at := now();
  end if;

  return new;
end;
$$;


ALTER FUNCTION "public"."capture_request_metadata_v1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."check_price_alerts_for_item_v1"("p_menu_item_id" "uuid", "p_business_id" "uuid", "p_item_name" "text", "p_price_cents" integer, "p_city" "text", "p_district" "text", "p_category" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  insert into public.alert_events (
    user_id,
    alert_id,
    business_id,
    menu_item_id,
    matched_price_cents
  )
  select
    a.user_id,
    a.id,
    p_business_id,
    p_menu_item_id,
    p_price_cents
  from public.price_alerts a
  where a.is_active = true
    and (a.query is null or a.query = '' or p_item_name ilike '%' || a.query || '%')
    and (a.max_price_cents is null or p_price_cents <= a.max_price_cents)
    and (a.city is null or a.city = '' or a.city = p_city)
    and (a.district is null or a.district = '' or a.district = p_district)
    and (a.category is null or a.category = '' or a.category = p_category)
  on conflict do nothing;
end;
$$;


