ALTER FUNCTION "public"."check_price_alerts_for_item_v1"("p_menu_item_id" "uuid", "p_business_id" "uuid", "p_item_name" "text", "p_price_cents" integer, "p_city" "text", "p_district" "text", "p_category" "text", "p_previous_price_cents" integer, "p_district_avg_price_cents" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."check_price_alerts_for_item_v1"("p_menu_item_id" "uuid", "p_business_id" "uuid", "p_item_name" "text", "p_price_cents" integer, "p_city" "text", "p_district" "text", "p_category" "text", "p_previous_price_cents" integer DEFAULT NULL::integer, "p_district_avg_price_cents" integer DEFAULT NULL::integer, "p_is_verified_change" boolean DEFAULT true) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  if coalesce(p_is_verified_change, false) is false then
    return;
  end if;

  -- Ignore noisy updates unless there is at least 10% delta.
  if p_previous_price_cents is not null
     and p_previous_price_cents > 0
     and p_price_cents > 0
     and abs(p_price_cents - p_previous_price_cents)::numeric / p_previous_price_cents::numeric < 0.10
  then
    return;
  end if;

  insert into public.alert_events (
    user_id,
    alert_id,
    business_id,
    menu_item_id,
    matched_price_cents,
    previous_price_cents,
    district_avg_price_cents
  )
  select
    a.user_id,
    a.id,
    p_business_id,
    p_menu_item_id,
    p_price_cents,
    p_previous_price_cents,
    p_district_avg_price_cents
  from public.price_alerts a
  where a.is_active = true
    and exists (
      select 1
      from public.favorites f
      where f.user_id = a.user_id
        and f.business_id = p_business_id
    )
    and (a.query is null or a.query = '' or p_item_name ilike '%' || a.query || '%')
    and (a.max_price_cents is null or p_price_cents <= a.max_price_cents)
    and (a.city is null or a.city = '' or a.city = p_city)
    and (a.district is null or a.district = '' or a.district = p_district)
    and (a.category is null or a.category = '' or a.category = p_category)
  on conflict do nothing;
end;
$$;


