CREATE OR REPLACE FUNCTION "public"."create_group_request_v1"("p_city" "text", "p_districts" "text"[] DEFAULT NULL::"text"[], "p_category" "text" DEFAULT NULL::"text", "p_date_time" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_party_size" integer DEFAULT NULL::integer, "p_budget_total_cents" integer DEFAULT NULL::integer, "p_notes" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_id uuid;
  v_key text;
  v_today date := current_date;
  v_count int;
begin
  if auth.uid() is null then
    return jsonb_build_object('ok', false, 'code', 'not_authenticated');
  end if;

  if p_date_time is null or p_party_size is null or p_budget_total_cents is null then
    return jsonb_build_object('ok', false, 'code', 'invalid_input');
  end if;

  v_key := format('group_request:%s:%s', auth.uid()::text, v_today::text);
  select count into v_count from public.user_rate_limits where key = v_key;
  if coalesce(v_count, 0) >= 3 then
    return jsonb_build_object('ok', false, 'code', 'rate_limited');
  end if;

  insert into public.user_rate_limits (key, user_id, action, day, count, updated_at)
  values (v_key, auth.uid(), 'group_request', v_today, 1, now())
  on conflict (key) do update
    set count = public.user_rate_limits.count + 1,
        updated_at = now();

  insert into public.group_requests(
    created_by, city, districts, category, date_time, party_size,
    budget_total_cents, currency, notes, status
  )
  values (
    auth.uid(),
    trim(p_city),
    p_districts,
    nullif(trim(p_category), ''),
    p_date_time,
    p_party_size,
    p_budget_total_cents,
    'TRY',
    nullif(trim(p_notes), ''),
    'open'
  )
  returning id into v_id;

  return jsonb_build_object('ok', true, 'id', v_id);
end;
$$;


ALTER FUNCTION "public"."create_group_request_v1"("p_city" "text", "p_districts" "text"[], "p_category" "text", "p_date_time" timestamp with time zone, "p_party_size" integer, "p_budget_total_cents" integer, "p_notes" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_menu_snapshot_v1"("p_menu_id" "uuid", "p_reason" "text" DEFAULT 'publish'::"text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_business_id uuid;
  v_snapshot_id uuid;
  v_snapshot jsonb;
  v_menu record;
begin
  if auth.uid() is null then
    raise exception 'not_authenticated';
  end if;

  select *
  into v_menu
  from public.menus
  where id = p_menu_id;

  v_business_id := v_menu.business_id;
  if v_business_id is null then
    raise exception 'menu_not_found';
  end if;

  if not (public.is_admin() or public.has_business_permission_v1(v_business_id, 'menu_write')) then
    raise exception 'forbidden';
  end if;

  v_snapshot := jsonb_build_object(
    'menu',
    jsonb_build_object(
      'title', v_menu.title,
      'kind', v_menu.kind,
      'active_from', v_menu.active_from,
      'active_to', v_menu.active_to,
      'status', v_menu.status,
      'version', coalesce(v_menu.version, 1),
      'source', coalesce(v_menu.source, 'owner'),
      'confidence_score', coalesce(v_menu.confidence_score, 0)
    ),
    'sections',
    coalesce(
      (
        select jsonb_agg(
          jsonb_build_object(
            'title', s.title,
            'sort_order', s.sort_order,
            'items',
            coalesce(
              (
                select jsonb_agg(
                  jsonb_build_object(
                    'name', i.name,
                    'description', i.description,
                    'price_cents', i.price_cents,
                    'currency', i.currency,
                    'catalog_item_id', i.catalog_item_id,
                    'sort_order', i.sort_order,
                    'is_available', i.is_available,
                    'image_url', i.image_url,
                    'tags', coalesce(i.tags, '[]'::jsonb),
                    'category_id', i.category_id
                  )
                  order by coalesce(i.sort_order, 0), i.created_at, i.name
                )
                from public.menu_items i
                where i.section_id = s.id
                  and i.is_available = true
              ),
              '[]'::jsonb
            )
          )
          order by s.sort_order, s.created_at
        )
        from public.menu_sections s
        where s.menu_id = p_menu_id
      ),
      '[]'::jsonb
    )
  );

  insert into public.menu_snapshots(
    business_id,
    source_menu_id,
    menu_version,
    snapshot_reason,
    snapshot_json,
    created_by
  )
  values (
    v_business_id,
    p_menu_id,
    coalesce(v_menu.version, 1),
    coalesce(nullif(trim(p_reason), ''), 'publish'),
    v_snapshot,
    auth.uid()
  )
  returning id into v_snapshot_id;

  return v_snapshot_id;
end;
$$;


ALTER FUNCTION "public"."create_menu_snapshot_v1"("p_menu_id" "uuid", "p_reason" "text") OWNER TO "postgres";


