CREATE OR REPLACE FUNCTION "public"."current_user_role_v1"() RETURNS "text"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_uid uuid := auth.uid();
begin
  if v_uid is null then
    return 'user';
  end if;

  if public.is_admin() then
    return 'admin';
  end if;

  if exists (
    select 1
    from public.owner_claims oc
    where oc.user_id = v_uid
      and oc.status = 'approved'
  ) or exists (
    select 1
    from public.chain_memberships cm
    where cm.user_id = v_uid
  ) or exists (
    select 1
    from public.business_team_memberships btm
    where btm.user_id = v_uid
      and btm.revoked_at is null
  ) then
    return 'owner';
  end if;

  return 'user';
end;
$$;


ALTER FUNCTION "public"."current_user_role_v1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."delete_business_story_v1"("p_story_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_business uuid;
begin
  select business_id into v_business
  from public.business_stories
  where id = p_story_id;

  if v_business is null then
    return jsonb_build_object('ok', false, 'error', 'not_found');
  end if;

  if not (public.is_admin() or public.is_owner_of_business(v_business)) then
    return jsonb_build_object('ok', false, 'error', 'not_owner');
  end if;

  update public.business_stories
  set is_deleted = true
  where id = p_story_id;

  return jsonb_build_object('ok', true);
end;
$$;


