CREATE OR REPLACE FUNCTION "public"."dequeue_notification_dispatch_jobs_v1"("p_limit" integer DEFAULT 20) RETURNS TABLE("job_id" "uuid", "notification_id" "uuid", "user_id" "uuid", "type" "text", "title" "text", "body" "text", "data" "jsonb")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  if p_limit <= 0 then
    p_limit := 20;
  end if;

  return query
  with picked as (
    select j.id
    from public.notification_dispatch_jobs j
    where j.status in ('pending', 'retry')
      and coalesce(j.attempts, 0) < 8
      and (j.locked_at is null or j.locked_at < now() - interval '5 minutes')
    order by j.created_at asc
    limit p_limit
    for update skip locked
  ),
  locked as (
    update public.notification_dispatch_jobs j
    set
      status = 'processing',
      locked_at = now(),
      attempts = coalesce(j.attempts, 0) + 1
    where j.id in (select id from picked)
    returning j.id, j.notification_id
  )
  select
    l.id as job_id,
    n.id as notification_id,
    n.user_id,
    n.type,
    n.title,
    n.body,
    n.data
  from locked l
  join public.notifications n on n.id = l.notification_id;
end;
$$;


ALTER FUNCTION "public"."dequeue_notification_dispatch_jobs_v1"("p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."discover_gourmets_v1"("p_limit" integer DEFAULT 20, "p_offset" integer DEFAULT 0) RETURNS TABLE("user_id" "uuid", "display_name" "text", "avatar_url" "text", "bio" "text", "follower_count" integer)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  select
    p.user_id, p.display_name, p.avatar_url, p.bio,
    (select count(*) from public.user_follows f where f.followee_id = p.user_id)::int as follower_count
  from public.user_profiles p
  where p.is_gourmet = true
  order by follower_count desc, p.created_at desc
  limit greatest(p_limit,0) offset greatest(p_offset,0);
$$;


