CREATE OR REPLACE FUNCTION "public"."enforce_abuse_controls_on_menu_photos_v1"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_uid uuid := coalesce(new.created_by, auth.uid());
begin
  if v_uid is null then
    return new;
  end if;

  if public.is_user_shadowed_v1(v_uid) or public.is_user_auto_pending_v1(v_uid) then
    new.status := 'pending';
  end if;

  return new;
end;
$$;


