CREATE OR REPLACE FUNCTION "public"."enforce_abuse_controls_on_price_suggestions_v1"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_uid uuid := coalesce(new.created_by, auth.uid());
  v_count integer := 0;
begin
  if v_uid is null then
    return new;
  end if;

  if public.is_user_soft_limited_v1(v_uid) then
    select count(*)
      into v_count
    from public.menu_item_price_suggestions s
    where s.created_by = v_uid
      and s.created_at >= now() - interval '24 hours';
    if v_count >= 6 then
      raise exception 'soft_rate_limited';
    end if;
  end if;

  if public.is_user_shadowed_v1(v_uid) or public.is_user_auto_pending_v1(v_uid) then
    new.status := 'pending'::public.menu_price_suggestion_status;
  end if;

  return new;
end;
$$;


ALTER FUNCTION "public"."enforce_abuse_controls_on_price_suggestions_v1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."enforce_abuse_controls_on_reviews_v1"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_count integer := 0;
begin
  if new.user_id is null then
    return new;
  end if;

  if public.is_user_soft_limited_v1(new.user_id) then
    select count(*)
      into v_count
    from public.reviews r
    where r.user_id = new.user_id
      and r.created_at >= now() - interval '24 hours';
    if v_count >= 3 then
      raise exception 'soft_rate_limited';
    end if;
  end if;

  if public.is_user_shadowed_v1(new.user_id) or public.is_user_auto_pending_v1(new.user_id) then
    new.status := 'pending';
  end if;

  return new;
end;
$$;


ALTER FUNCTION "public"."enforce_abuse_controls_on_reviews_v1"() OWNER TO "postgres";


