CREATE OR REPLACE FUNCTION "public"."ensure_default_section_for_business_v1"("p_business_id" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_menu_id uuid;
  v_section_id uuid;
begin
  select id
    into v_menu_id
  from public.menus
  where business_id = p_business_id
  order by created_at asc
  limit 1;

  if v_menu_id is null then
    insert into public.menus (business_id, title, status, created_by)
    values (p_business_id, 'Menü', 'published', auth.uid())
    returning id into v_menu_id;
  end if;

  select id
    into v_section_id
  from public.menu_sections
  where menu_id = v_menu_id
  order by sort_order asc, created_at asc
  limit 1;

  if v_section_id is null then
    insert into public.menu_sections (menu_id, title, sort_order, created_by)
    values (v_menu_id, 'Genel', 0, auth.uid())
    returning id into v_section_id;
  end if;

  return v_section_id;
end;
$$;


ALTER FUNCTION "public"."ensure_default_section_for_business_v1"("p_business_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."ensure_my_profile_v1"("p_display_name" "text" DEFAULT NULL::"text", "p_avatar_url" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_name text;
begin
  if auth.uid() is null then
    return jsonb_build_object('ok', false, 'error', 'not_authenticated');
  end if;

  v_name := nullif(trim(coalesce(p_display_name,'')), '');
  if v_name is null then
    v_name := 'Kullanıcı';
  end if;

  insert into public.user_profiles(user_id, display_name, avatar_url)
  values (auth.uid(), v_name, p_avatar_url)
  on conflict (user_id) do update
    set display_name = coalesce(excluded.display_name, public.user_profiles.display_name),
        avatar_url = coalesce(excluded.avatar_url, public.user_profiles.avatar_url),
        updated_at = now();

  return jsonb_build_object('ok', true);
end;
$$;


