CREATE OR REPLACE FUNCTION "public"."get_app_role_v1"() RETURNS "text"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_claim jsonb := auth.jwt();
  v_role text;
begin
  v_role := lower(
    coalesce(
      v_claim -> 'app_metadata' ->> 'role',
      v_claim -> 'user_metadata' ->> 'role',
      'user'
    )
  );

  if v_role not in ('user', 'owner', 'community_mod', 'admin') then
    v_role := 'user';
  end if;
  return v_role;
end;
$$;


ALTER FUNCTION "public"."get_app_role_v1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_bill_estimate_v1"("p_business_id" "uuid", "p_items" "jsonb", "p_tip_pct" integer DEFAULT NULL::integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_subtotal int := 0;
  v_cover int := 0;
  v_service int := 0;
  v_tip int := 0;
  v_total int := 0;
  v_service_pct int := 0;
  v_tip_pct int := 0;
  v_vat_included boolean := true;
  v_has_rules boolean := false;
begin
  if p_items is null or jsonb_typeof(p_items) <> 'array' then
    return jsonb_build_object(
      'ok', false,
      'error', 'invalid_items'
    );
  end if;

  select
    coalesce(r.service_fee_pct, 0),
    coalesce(r.cover_charge_cents, 0),
    coalesce(r.vat_included, true),
    r.default_tip_pct
  into v_service_pct, v_cover, v_vat_included, v_tip_pct
  from public.business_pricing_rules r
  where r.business_id = p_business_id;

  if found then
    v_has_rules := true;
  end if;

  v_tip_pct := coalesce(p_tip_pct, v_tip_pct, 0);

  select
    coalesce(sum(mi.price_cents * req.qty), 0)
  into v_subtotal
  from (
    select
      (i->>'menu_item_id')::uuid as menu_item_id,
      greatest(coalesce((i->>'qty')::int, 1), 1) as qty
    from jsonb_array_elements(p_items) as i
  ) req
  join public.menu_items mi on mi.id = req.menu_item_id;

  v_service := (v_subtotal * v_service_pct / 100.0)::int;
  v_tip := (v_subtotal * v_tip_pct / 100.0)::int;
  v_total := v_subtotal + v_cover + v_service + v_tip;

  return jsonb_build_object(
    'ok', true,
    'has_rules', v_has_rules,
    'subtotal_cents', v_subtotal,
    'cover_cents', v_cover,
    'service_fee_cents', v_service,
    'service_fee_pct', v_service_pct,
    'tip_cents', v_tip,
    'tip_pct', v_tip_pct,
    'total_cents', v_total,
    'vat_included', v_vat_included
  );
end;
$$;


ALTER FUNCTION "public"."get_bill_estimate_v1"("p_business_id" "uuid", "p_items" "jsonb", "p_tip_pct" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_budget_combos_v1"("p_city" "text", "p_district" "text", "p_party_size" integer, "p_budget_total_cents" integer, "p_category" "text" DEFAULT NULL::"text", "p_limit" integer DEFAULT 30) RETURNS TABLE("business_id" "uuid", "business_name" "text", "combo" "jsonb", "total_cents" integer)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  with base_businesses as (
    select b.id, b.name
    from public.businesses b
    where b.city = p_city
      and (p_district is null or b.district = p_district)
      and (p_category is null or b.category = p_category)
  ),
  main_items as (
    select
      b.id as business_id,
      mi.id as menu_item_id,
      mi.name,
      mi.price_cents,
      mi.currency,
      row_number() over (
        partition by b.id
        order by coalesce(v.verified_ratio, 0) desc,
                 mi.price_cents asc nulls last,
                 mi.created_at desc
      ) as rn
    from base_businesses b
    join public.menu_items mi on mi.business_id = b.id
    left join public.menu_item_value_score_v1 v on v.menu_item_id = mi.id
    left join public.menu_sections s on s.id = mi.section_id
    where mi.is_available = true
      and mi.price_cents is not null
      and not (
        (s.title is not null and lower(s.title) like any(array['%icecek%','%icki%','%drink%','%beverage%']))
        or lower(mi.name) like any(array['%cola%','%soda%','%gazoz%','%su%','%ayran%','%limonata%','%cay%','%kahve%','%juice%','%smoothie%','%bira%','%wine%','%sarap%'])
      )
  ),
  mains as (
    select * from main_items where rn <= 3
  ),
  drink_items as (
    select
      b.id as business_id,
      mi.id as menu_item_id,
      mi.name,
      mi.price_cents,
      mi.currency,
      row_number() over (
        partition by b.id
        order by mi.price_cents asc nulls last, mi.created_at desc
      ) as rn
    from base_businesses b
    join public.menu_items mi on mi.business_id = b.id
    left join public.menu_sections s on s.id = mi.section_id
    where mi.is_available = true
      and mi.price_cents is not null
      and (
        (s.title is not null and lower(s.title) like any(array['%icecek%','%icki%','%drink%','%beverage%']))
        or lower(mi.name) like any(array['%cola%','%soda%','%gazoz%','%su%','%ayran%','%limonata%','%cay%','%kahve%','%juice%','%smoothie%','%bira%','%wine%','%sarap%'])
      )
  ),
  drinks as (
    select * from drink_items where rn <= 2
  ),
  combos_main_only as (
    select
      b.id as business_id,
      b.name as business_name,
      jsonb_build_object(
        'main', jsonb_build_object('id', m.menu_item_id, 'name', m.name, 'price_cents', m.price_cents, 'currency', m.currency),
        'drink', null
      ) as combo,
      (m.price_cents * p_party_size)::int as total_cents
    from base_businesses b
    join mains m on m.business_id = b.id
  ),
  combos_with_drink as (
    select
      b.id as business_id,
      b.name as business_name,
      jsonb_build_object(
        'main', jsonb_build_object('id', m.menu_item_id, 'name', m.name, 'price_cents', m.price_cents, 'currency', m.currency),
        'drink', jsonb_build_object('id', d.menu_item_id, 'name', d.name, 'price_cents', d.price_cents, 'currency', d.currency)
      ) as combo,
      ((m.price_cents + d.price_cents) * p_party_size)::int as total_cents
    from base_businesses b
    join mains m on m.business_id = b.id
    join drinks d on d.business_id = b.id
  ),
  all_combos as (
    select * from combos_main_only
    union all
    select * from combos_with_drink
  )
  select business_id, business_name, combo, total_cents
  from all_combos
  where total_cents <= p_budget_total_cents
  order by total_cents asc
  limit p_limit;
$$;


ALTER FUNCTION "public"."get_budget_combos_v1"("p_city" "text", "p_district" "text", "p_party_size" integer, "p_budget_total_cents" integer, "p_category" "text", "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_business_activity_v1"("p_business_id" "uuid", "p_limit" integer DEFAULT 10) RETURNS TABLE("activity_id" "uuid", "activity_type" "text", "meta" "jsonb", "created_at" timestamp with time zone)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  with base as (
    select
      a.id as activity_id,
      a.type as activity_type,
      a.meta,
      a.created_at
    from public.business_activity_log a
    where a.business_id = p_business_id
  ),
  menu_views as (
    select count(*)::int as count_today
    from public.analytics_events e
    where e.business_id = p_business_id
      and e.event_name = 'menu_view'
      and e.created_at >= date_trunc('day', now())
  ),
  ranked as (
    select
      b.id,
      b.district,
      coalesce(q.score, 0) as score,
      rank() over (
        partition by b.district
        order by coalesce(q.score, 0) desc, b.id
      ) as rank
    from public.businesses b
    left join public.business_quality_score_v1 q
      on q.business_id = b.id
    where b.district is not null
      and b.is_active = true
  ),
  district_rank as (
    select r.rank, r.district
    from ranked r
    where r.id = p_business_id
  ),
  synthetic as (
    select
      '00000000-0000-0000-0000-000000000000'::uuid as activity_id,
      'menu_views' as activity_type,
      jsonb_build_object('count_today', mv.count_today) as meta,
      now() as created_at
    from menu_views mv
    where mv.count_today > 0

    union all

    select
      '00000000-0000-0000-0000-000000000000'::uuid as activity_id,
      'district_rank' as activity_type,
      jsonb_build_object('rank', dr.rank, 'district', dr.district) as meta,
      now() as created_at
    from district_rank dr
    where dr.rank is not null
  )
  select *
  from (
    select * from base
    union all
    select * from synthetic
  ) s
  order by created_at desc
  limit greatest(p_limit, 0);
$$;


ALTER FUNCTION "public"."get_business_activity_v1"("p_business_id" "uuid", "p_limit" integer) OWNER TO "postgres";


