CREATE OR REPLACE FUNCTION "public"."get_business_compare_v1"("p_business_ids" "uuid"[]) RETURNS TABLE("business_id" "uuid", "median_price_cents" integer, "verified_ratio" numeric, "last_update_at" timestamp with time zone)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  select
    b.business_id,
    b.median_price_cents,
    b.verified_ratio,
    b.last_update_at
  from public.business_price_index_v1 b
  where b.business_id = any(p_business_ids);
$$;


