CREATE OR REPLACE FUNCTION "public"."get_business_crowd_v1"("p_business_id" "uuid") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  with last_hour as (
    select
      crowd,
      case crowd
        when 'quiet' then 1
        when 'normal' then 2
        when 'busy' then 3
      end as score
    from public.business_presence_events
    where business_id = p_business_id
      and created_at >= now() - interval '60 minutes'
  ),
  agg as (
    select
      count(*) as n,
      avg(score)::float as avg_score
    from last_hour
  )
  select jsonb_build_object(
    'count_60m', coalesce((select n from agg),0),
    'avg_score', coalesce((select avg_score from agg), null),
    'level',
      case
        when coalesce((select n from agg),0) = 0 then 'unknown'
        when (select avg_score from agg) < 1.6 then 'quiet'
        when (select avg_score from agg) < 2.4 then 'normal'
        else 'busy'
      end
  );
$$;


ALTER FUNCTION "public"."get_business_crowd_v1"("p_business_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_business_detail_v1"("p_business_id" "uuid", "p_latest_reviews_limit" integer DEFAULT 5) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_stats jsonb;
  v_hist jsonb;
  v_latest jsonb;
begin
  select to_jsonb(s)
  into v_stats
  from (
    select
      m.id,
      m.name,
      m.category,
      m.address,
      m.city,
      m.district,
      m.lat,
      m.lng,
      m.avg_rating,
      m.reviews_count
    from public.businesses_with_stats_mv m
    where m.id = p_business_id
    limit 1
  ) s;

  if v_stats is null then
    return jsonb_build_object('ok', false, 'error', 'business_not_found');
  end if;

  -- breakdown stats'tan
  select jsonb_build_object(
    '5', coalesce(bs.rating_5,0),
    '4', coalesce(bs.rating_4,0),
    '3', coalesce(bs.rating_3,0),
    '2', coalesce(bs.rating_2,0),
    '1', coalesce(bs.rating_1,0)
  )
  into v_hist
  from public.business_stats bs
  where bs.business_id = p_business_id;

  if v_hist is null then
    v_hist := jsonb_build_object('5',0,'4',0,'3',0,'2',0,'1',0);
  end if;

  -- latest reviews yine reviews'tan (limitli + index ile hızlı)
  select coalesce(jsonb_agg(to_jsonb(r)), '[]'::jsonb)
  into v_latest
  from (
    select
      id,
      business_id,
      user_id,
      rating,
      title,
      content,
      helpful_count,
      created_at
    from public.reviews
    where business_id = p_business_id
      and status = 'approved'
    order by created_at desc
    limit greatest(p_latest_reviews_limit, 0)
  ) r;

  return jsonb_build_object(
    'ok', true,
    'stats', v_stats,
    'rating_breakdown', v_hist,
    'latest_reviews', v_latest
  );
end;
$$;


ALTER FUNCTION "public"."get_business_detail_v1"("p_business_id" "uuid", "p_latest_reviews_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_business_fee_summary_v1"("p_business_id" "uuid") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  with votes as (
    select
      field,
      count(*) filter (where value = true) as yes_count,
      count(*) filter (where value = false) as no_count,
      count(*) as total_count,
      max(created_at) as last_vote_at
    from public.business_fee_votes
    where business_id = p_business_id
      and created_at >= now() - interval '30 days'
    group by field
  ),
  scored as (
    select
      field,
      yes_count,
      no_count,
      total_count,
      last_vote_at,
      case
        when total_count = 0 then null
        when yes_count >= no_count then true
        else false
      end as value,
      case
        when total_count = 0 then 0
        else least(1.0,
          (abs(yes_count - no_count)::float / total_count) * 0.7 +
          (1 - least(extract(epoch from (now() - last_vote_at)) / (30*86400.0), 1)) * 0.3
        )
      end as confidence
    from votes
  )
  select jsonb_build_object(
    'cover', (
      select jsonb_build_object(
        'value', value,
        'confidence', confidence,
        'total', total_count
      )
      from scored where field = 'cover'
    ),
    'service', (
      select jsonb_build_object(
        'value', value,
        'confidence', confidence,
        'total', total_count
      )
      from scored where field = 'service'
    ),
    'water', (
      select jsonb_build_object(
        'value', value,
        'confidence', confidence,
        'total', total_count
      )
      from scored where field = 'water'
    )
  );
$$;


