CREATE OR REPLACE FUNCTION "public"."get_business_new_items_v1"("p_business_id" "uuid", "p_limit" integer DEFAULT 6) RETURNS TABLE("menu_item_id" "uuid", "item_name" "text", "price_cents" integer, "currency" "text", "created_at" timestamp with time zone)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
begin
  if exists (
    select 1
    from information_schema.columns
    where table_schema = 'public'
      and table_name = 'menu_items'
      and column_name = 'status'
  ) then
    return query execute $query$
      select
        mi.id as menu_item_id,
        mi.name as item_name,
        mi.price_cents,
        mi.currency,
        mi.created_at
      from public.menu_items mi
      where mi.business_id = $1
        and mi.status = 'published'
        and mi.created_at >= now() - interval '7 days'
      order by mi.created_at desc
      limit $2
    $query$ using p_business_id, p_limit;
  else
    return query execute $query$
      select
        mi.id as menu_item_id,
        mi.name as item_name,
        mi.price_cents,
        mi.currency,
        mi.created_at
      from public.menu_items mi
      where mi.business_id = $1
        and mi.created_at >= now() - interval '7 days'
      order by mi.created_at desc
      limit $2
    $query$ using p_business_id, p_limit;
  end if;
end;
$_$;


