CREATE OR REPLACE FUNCTION "public"."get_business_reviews_v2"("p_business_id" "uuid", "p_sort" "text" DEFAULT 'newest'::"text", "p_limit" integer DEFAULT 20, "p_offset" integer DEFAULT 0) RETURNS TABLE("id" "uuid", "business_id" "uuid", "user_id" "uuid", "rating" integer, "title" "text", "content" "text", "helpful_count" integer, "created_at" timestamp with time zone, "status" "text", "quality_score" numeric)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  with base as (
    select
      r.id,
      r.business_id,
      r.user_id,
      r.rating,
      r.title,
      r.content,
      r.helpful_count,
      r.created_at,
      r.status,
      coalesce(rep.open_reports, 0) as open_reports,
      greatest(
        0::numeric,
        least(
          100::numeric,
          (coalesce(r.helpful_count, 0)::numeric * 2.2)
          + (least(length(coalesce(r.content, '')), 400)::numeric / 20)
          + (r.rating::numeric * 1.5)
          - (coalesce(rep.open_reports, 0)::numeric * 3.0)
        )
      ) as quality_score
    from public.reviews r
    left join (
      select
        review_id,
        count(*)::int as open_reports
      from public.reports
      where review_id is not null
        and status in ('open', 'reviewing')
      group by review_id
    ) rep on rep.review_id = r.id
    where r.business_id = p_business_id
      and r.status = 'approved'
  )
  select
    b.id,
    b.business_id,
    b.user_id,
    b.rating,
    b.title,
    b.content,
    b.helpful_count,
    b.created_at,
    b.status,
    b.quality_score
  from base b
  order by
    case when lower(coalesce(p_sort, 'newest')) = 'helpful' then b.quality_score else null end desc,
    case when lower(coalesce(p_sort, 'newest')) = 'helpful' then b.helpful_count else null end desc,
    b.created_at desc
  limit greatest(p_limit, 1)
  offset greatest(p_offset, 0);
$$;


ALTER FUNCTION "public"."get_business_reviews_v2"("p_business_id" "uuid", "p_sort" "text", "p_limit" integer, "p_offset" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_business_reviews_v3"("p_business_id" "uuid", "p_sort" "text" DEFAULT 'newest'::"text", "p_limit" integer DEFAULT 20, "p_offset" integer DEFAULT 0) RETURNS TABLE("id" "uuid", "business_id" "uuid", "user_id" "uuid", "rating" integer, "overall_rating" integer, "taste_rating" integer, "service_speed_rating" integer, "price_performance_rating" integer, "cleanliness_rating" integer, "atmosphere_rating" integer, "title" "text", "content" "text", "helpful_count" integer, "created_at" timestamp with time zone, "status" "text", "quality_score" numeric)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  with base as (
    select
      r.id,
      r.business_id,
      r.user_id,
      r.rating,
      coalesce(r.overall_rating, r.rating::smallint)::integer as overall_rating,
      r.taste_rating::integer as taste_rating,
      r.service_speed_rating::integer as service_speed_rating,
      r.price_performance_rating::integer as price_performance_rating,
      r.cleanliness_rating::integer as cleanliness_rating,
      r.atmosphere_rating::integer as atmosphere_rating,
      r.title,
      r.content,
      r.helpful_count,
      r.created_at,
      r.status,
      coalesce(rep.open_reports, 0) as open_reports,
      greatest(
        0::numeric,
        least(
          100::numeric,
          (coalesce(r.helpful_count, 0)::numeric * 2.2)
          + (least(length(coalesce(r.content, '')), 400)::numeric / 20)
          + (coalesce(r.overall_rating, r.rating::smallint)::numeric * 1.5)
          - (coalesce(rep.open_reports, 0)::numeric * 3.0)
        )
      ) as quality_score
    from public.reviews r
    left join (
      select
        review_id,
        count(*)::int as open_reports
      from public.reports
      where review_id is not null
        and coalesce(status, '') in ('open', 'reviewing', 'acik')
      group by review_id
    ) rep on rep.review_id = r.id
    where r.business_id = p_business_id
      and r.status = 'approved'
  )
  select
    b.id,
    b.business_id,
    b.user_id,
    b.rating,
    b.overall_rating,
    b.taste_rating,
    b.service_speed_rating,
    b.price_performance_rating,
    b.cleanliness_rating,
    b.atmosphere_rating,
    b.title,
    b.content,
    b.helpful_count,
    b.created_at,
    b.status,
    b.quality_score
  from base b
  order by
    case when lower(coalesce(p_sort, 'newest')) = 'helpful' then b.quality_score else null end desc,
    case when lower(coalesce(p_sort, 'newest')) = 'helpful' then b.helpful_count else null end desc,
    b.created_at desc
  limit greatest(p_limit, 1)
  offset greatest(p_offset, 0);
$$;


ALTER FUNCTION "public"."get_business_reviews_v3"("p_business_id" "uuid", "p_sort" "text", "p_limit" integer, "p_offset" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_business_role_v1"("p_business_id" "uuid", "p_actor_user_id" "uuid" DEFAULT NULL::"uuid", "p_role_override" "text" DEFAULT NULL::"text") RETURNS "text"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_actor_id uuid;
  v_override text := lower(nullif(trim(coalesce(p_role_override, '')), ''));
  v_role text;
begin
  if p_business_id is null then
    return null;
  end if;

  if auth.uid() is null then
    return null;
  end if;

  if p_actor_user_id is not null and not public.is_admin() then
    return null;
  end if;

  v_actor_id := coalesce(p_actor_user_id, auth.uid());

  if public.is_admin() and p_actor_user_id is null and v_override is null then
    return 'owner';
  end if;

  if v_override is not null
     and v_override in ('owner', 'manager', 'editor', 'staff', 'viewer')
     and public.is_admin() then
    return v_override;
  end if;

  with candidate_roles as (
    select 'owner'::text as role
    from public.owner_claims oc
    where oc.business_id = p_business_id
      and oc.user_id = v_actor_id
      and oc.status = 'approved'

    union all

    select cm.role
    from public.businesses b
    join public.chain_memberships cm
      on cm.chain_id = b.chain_id
    where b.id = p_business_id
      and cm.user_id = v_actor_id

    union all

    select btm.role
    from public.businesses b
    join public.business_team_memberships btm
      on (
        (btm.business_id = b.id)
        or (btm.chain_id is not null and btm.chain_id = b.chain_id)
      )
    where b.id = p_business_id
      and btm.revoked_at is null
      and btm.user_id = v_actor_id
  )
  select cr.role
  into v_role
  from candidate_roles cr
  order by public.business_role_rank_v1(cr.role) desc
  limit 1;

  return v_role;
end;
$$;


ALTER FUNCTION "public"."get_business_role_v1"("p_business_id" "uuid", "p_actor_user_id" "uuid", "p_role_override" "text") OWNER TO "postgres";


