CREATE OR REPLACE FUNCTION "public"."get_chain_overview_v1"("p_chain_id" "uuid", "p_lat" double precision DEFAULT NULL::double precision, "p_lng" double precision DEFAULT NULL::double precision, "p_limit" integer DEFAULT 20) RETURNS TABLE("chain_id" "uuid", "chain_name" "text", "chain_description" "text", "business_id" "uuid", "business_name" "text", "branch_label" "text", "city" "text", "district" "text", "address" "text", "is_open_now" boolean, "distance_km" double precision)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  select
    ch.id as chain_id,
    ch.name as chain_name,
    ch.description as chain_description,
    b.id as business_id,
    b.name as business_name,
    coalesce(b.branch_label, '') as branch_label,
    b.city,
    b.district,
    b.address,
    null::boolean as is_open_now,
    case
      when p_lat is null or p_lng is null or b.lat is null or b.lng is null then null
      else round((st_distance(
        st_setsrid(st_makepoint(p_lng, p_lat), 4326)::geography,
        st_setsrid(st_makepoint(b.lng, b.lat), 4326)::geography
      ) / 1000.0)::numeric, 2)::double precision
    end as distance_km
  from public.businesses b
  join public.chains ch on ch.id = b.chain_id
  where b.chain_id = p_chain_id
    and b.is_active = true
  order by
    case when p_lat is null or p_lng is null then null else
      st_distance(
        st_setsrid(st_makepoint(p_lng, p_lat), 4326)::geography,
        st_setsrid(st_makepoint(b.lng, b.lat), 4326)::geography
      )
    end asc nulls last,
    b.name asc
  limit greatest(p_limit, 1);
$$;


ALTER FUNCTION "public"."get_chain_overview_v1"("p_chain_id" "uuid", "p_lat" double precision, "p_lng" double precision, "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_chain_overview_v2"("p_chain_id" "uuid", "p_lat" double precision DEFAULT NULL::double precision, "p_lng" double precision DEFAULT NULL::double precision, "p_limit" integer DEFAULT 20) RETURNS TABLE("chain_id" "uuid", "chain_name" "text", "chain_description" "text", "business_id" "uuid", "business_name" "text", "branch_label" "text", "city" "text", "district" "text", "address" "text", "is_open_now" boolean, "distance_km" double precision, "avg_price_cents" integer, "chain_avg_price_cents" integer, "price_delta_pct" numeric)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  with branch_prices as (
    select
      b.id as business_id,
      percentile_disc(0.5) within group (order by mi.price_cents)::int as avg_price_cents
    from public.businesses b
    left join public.menu_items mi
      on mi.business_id = b.id
     and mi.price_cents is not null
     and mi.price_cents > 0
    where b.chain_id = p_chain_id
      and b.is_active = true
    group by b.id
  ),
  chain_price as (
    select
      percentile_disc(0.5) within group (order by bp.avg_price_cents)::int as chain_avg_price_cents
    from branch_prices bp
    where bp.avg_price_cents is not null
  )
  select
    ch.id as chain_id,
    ch.name as chain_name,
    ch.description as chain_description,
    b.id as business_id,
    b.name as business_name,
    coalesce(b.branch_label, '') as branch_label,
    b.city,
    b.district,
    b.address,
    null::boolean as is_open_now,
    case
      when p_lat is null or p_lng is null or b.lat is null or b.lng is null then null
      else round((st_distance(
        st_setsrid(st_makepoint(p_lng, p_lat), 4326)::geography,
        st_setsrid(st_makepoint(b.lng, b.lat), 4326)::geography
      ) / 1000.0)::numeric, 2)::double precision
    end as distance_km,
    bp.avg_price_cents,
    cp.chain_avg_price_cents,
    case
      when cp.chain_avg_price_cents is null or cp.chain_avg_price_cents <= 0 or bp.avg_price_cents is null
        then null
      else round((((bp.avg_price_cents - cp.chain_avg_price_cents)::numeric / cp.chain_avg_price_cents::numeric) * 100), 1)
    end as price_delta_pct
  from public.businesses b
  join public.chains ch on ch.id = b.chain_id
  left join branch_prices bp on bp.business_id = b.id
  left join chain_price cp on true
  where b.chain_id = p_chain_id
    and b.is_active = true
  order by
    case when p_lat is null or p_lng is null then null else
      st_distance(
        st_setsrid(st_makepoint(p_lng, p_lat), 4326)::geography,
        st_setsrid(st_makepoint(b.lng, b.lat), 4326)::geography
      )
    end asc nulls last,
    b.name asc
  limit greatest(p_limit, 1);
$$;


ALTER FUNCTION "public"."get_chain_overview_v2"("p_chain_id" "uuid", "p_lat" double precision, "p_lng" double precision, "p_limit" integer) OWNER TO "postgres";


