    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $$
  select
    k.key as collection_key,
    coalesce(s.followers_count, 0) as followers_count,
    coalesce(s.engagement_count, 0) as engagement_count,
