CREATE OR REPLACE FUNCTION "public"."get_daily_picks"("p_limit" integer DEFAULT 3) RETURNS TABLE("business_id" "uuid", "name" "text", "category" "text", "city" "text", "district" "text", "avg_rating" numeric, "reviews_count" integer)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  with base as (
    select
      b.id as business_id,
      b.name,
      b.category,
      b.city,
      b.district,
      count(r.*)::int as reviews_count,
      coalesce(avg(r.rating), 0)::numeric(3,2) as avg_rating
    from public.businesses b
    left join public.reviews r
      on r.business_id = b.id
     and r.status = 'approved'
     and r.created_at >= (now() - interval '30 days')
    where b.is_active = true
    group by b.id
  ),
  scored as (
    select
      *,
      (
        -- rating ağırlığı
        (avg_rating * 10)
        +
        -- yorum sayısı ağırlığı
        (least(reviews_count, 20) * 1.0)
        +
        -- günlük stabil random: user+date ile
        (
          -- auth yoksa da çalışsın: uid null ise 'anon' kullan
          (abs(hashtext(coalesce(auth.uid()::text, 'anon') || ':' || current_date::text || ':' || business_id::text)) % 1000) / 1000.0
        )
      ) as score
    from base
  )
  select
    business_id, name, category, city, district, avg_rating, reviews_count
  from scored
  order by score desc
  limit p_limit;
$$;


ALTER FUNCTION "public"."get_daily_picks"("p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_district_night_favorites_v1"("p_city" "text", "p_district" "text", "p_limit" integer DEFAULT 10) RETURNS TABLE("id" "uuid", "name" "text", "category" "text", "city" "text", "district" "text", "address" "text", "lat" double precision, "lng" double precision, "distance_km" double precision, "quality_score" double precision, "avg_rating" double precision, "median_price_cents" integer, "is_open_now" boolean, "recent_price_verified_count" integer, "favorites_count" integer)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  with params as (
    select
      nullif(trim(p_city), '') as city,
      nullif(trim(p_district), '') as district
  ),
  favorites as (
    select business_id, count(*) as favorites_count
    from public.business_follows
    group by business_id
  ),
  night_open as (
    select bh.business_id
    from public.business_hours bh
    where (
      bh.mon_open is not null and bh.mon_close is not null and
      (bh.mon_close >= time '23:00' or bh.mon_close < bh.mon_open)
    ) or (
      bh.tue_open is not null and bh.tue_close is not null and
      (bh.tue_close >= time '23:00' or bh.tue_close < bh.tue_open)
    ) or (
      bh.wed_open is not null and bh.wed_close is not null and
      (bh.wed_close >= time '23:00' or bh.wed_close < bh.wed_open)
    ) or (
      bh.thu_open is not null and bh.thu_close is not null and
      (bh.thu_close >= time '23:00' or bh.thu_close < bh.thu_open)
    ) or (
      bh.fri_open is not null and bh.fri_close is not null and
      (bh.fri_close >= time '23:00' or bh.fri_close < bh.fri_open)
    ) or (
      bh.sat_open is not null and bh.sat_close is not null and
      (bh.sat_close >= time '23:00' or bh.sat_close < bh.sat_open)
    ) or (
      bh.sun_open is not null and bh.sun_close is not null and
      (bh.sun_close >= time '23:00' or bh.sun_close < bh.sun_open)
    )
  )
  select
    b.id,
    b.name,
    b.category,
    b.city,
    b.district,
    b.address,
    b.lat,
    b.lng,
    null::double precision as distance_km,
    null::double precision as quality_score,
    null::double precision as avg_rating,
    null::int as median_price_cents,
    null::boolean as is_open_now,
    null::int as recent_price_verified_count,
    coalesce(f.favorites_count, 0)::int as favorites_count
  from params p
  join public.businesses b
    on b.city = p.city and b.district = p.district
  join night_open n on n.business_id = b.id
  left join favorites f on f.business_id = b.id
  where p.city is not null and p.district is not null
  order by f.favorites_count desc nulls last, b.name asc
  limit p_limit;
$$;


ALTER FUNCTION "public"."get_district_night_favorites_v1"("p_city" "text", "p_district" "text", "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_district_night_favorites_v1"("p_city" "text", "p_district" "text", "p_neighborhood" "text" DEFAULT NULL::"text", "p_limit" integer DEFAULT 10) RETURNS TABLE("id" "uuid", "name" "text", "category" "text", "city" "text", "district" "text", "address" "text", "lat" double precision, "lng" double precision, "distance_km" double precision, "quality_score" double precision, "avg_rating" double precision, "median_price_cents" integer, "is_open_now" boolean, "recent_price_verified_count" integer, "favorites_count" integer)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  with params as (
    select
      nullif(trim(p_city), '') as city,
      nullif(trim(p_district), '') as district,
      nullif(trim(p_neighborhood), '') as neighborhood
  ),
  favorites as (
    select business_id, count(*) as favorites_count
    from public.business_follows
    group by business_id
  ),
  night_open as (
    select bh.business_id
    from public.business_hours bh
    where (
      bh.mon_open is not null and bh.mon_close is not null and
      (bh.mon_close >= time '23:00' or bh.mon_close < bh.mon_open)
    ) or (
      bh.tue_open is not null and bh.tue_close is not null and
      (bh.tue_close >= time '23:00' or bh.tue_close < bh.tue_open)
    ) or (
      bh.wed_open is not null and bh.wed_close is not null and
      (bh.wed_close >= time '23:00' or bh.wed_close < bh.wed_open)
    ) or (
      bh.thu_open is not null and bh.thu_close is not null and
      (bh.thu_close >= time '23:00' or bh.thu_close < bh.thu_open)
    ) or (
      bh.fri_open is not null and bh.fri_close is not null and
      (bh.fri_close >= time '23:00' or bh.fri_close < bh.fri_open)
    ) or (
      bh.sat_open is not null and bh.sat_close is not null and
      (bh.sat_close >= time '23:00' or bh.sat_close < bh.sat_open)
    ) or (
      bh.sun_open is not null and bh.sun_close is not null and
      (bh.sun_close >= time '23:00' or bh.sun_close < bh.sun_open)
    )
  )
  select
    bws.id,
    bws.name,
    bws.category,
    bws.city,
    bws.district,
    bws.address,
    bws.lat,
    bws.lng,
    null::double precision as distance_km,
    coalesce(qs.score, 0)::double precision as quality_score,
    bws.avg_rating,
    null::int as median_price_cents,
    null::boolean as is_open_now,
    null::int as recent_price_verified_count,
    coalesce(f.favorites_count, 0)::int as favorites_count
  from params p
  join public.businesses_with_stats bws
    on bws.city = p.city and bws.district = p.district
  join public.businesses b on b.id = bws.id
  left join public.business_quality_score_v1 qs on qs.business_id = bws.id
  join night_open n on n.business_id = bws.id
  left join favorites f on f.business_id = bws.id
  where p.city is not null
    and p.district is not null
    and (p.neighborhood is null or b.neighborhood = p.neighborhood)
  order by f.favorites_count desc nulls last, coalesce(qs.score, 0) desc nulls last
  limit p_limit;
$$;


ALTER FUNCTION "public"."get_district_night_favorites_v1"("p_city" "text", "p_district" "text", "p_neighborhood" "text", "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_district_price_changes_v1"("p_city" "text", "p_district" "text", "p_limit" integer DEFAULT 10) RETURNS TABLE("id" "uuid", "name" "text", "category" "text", "city" "text", "district" "text", "address" "text", "lat" double precision, "lng" double precision, "distance_km" double precision, "quality_score" double precision, "avg_rating" double precision, "median_price_cents" integer, "is_open_now" boolean, "recent_price_verified_count" integer, "price_changes_count" integer)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  with params as (
    select
      nullif(trim(p_city), '') as city,
      nullif(trim(p_district), '') as district
  ),
  changes as (
    select
      mi.business_id,
      count(*) filter (
        where h.created_at >= now() - interval '7 days'
      ) as changes_7d
    from public.menu_item_price_history h
    join public.menu_items mi on mi.id = h.menu_item_id
    group by mi.business_id
  )
  select
    b.id,
    b.name,
    b.category,
    b.city,
    b.district,
    b.address,
    b.lat,
    b.lng,
    null::double precision as distance_km,
    null::double precision as quality_score,
    null::double precision as avg_rating,
    null::int as median_price_cents,
    null::boolean as is_open_now,
    null::int as recent_price_verified_count,
    coalesce(c.changes_7d, 0)::int as price_changes_count
  from params p
  join public.businesses b
    on b.city = p.city and b.district = p.district
  left join changes c on c.business_id = b.id
  where p.city is not null and p.district is not null
  order by c.changes_7d desc nulls last, b.name asc
  limit p_limit;
$$;


