CREATE OR REPLACE FUNCTION "public"."get_menu_items_v1"("p_menu_id" "uuid") RETURNS TABLE("id" "uuid", "section_id" "uuid", "name" "text", "description" "text", "price_cents" integer, "currency" "text", "calories" integer, "is_vegan" boolean, "is_vegetarian" boolean, "is_gluten_free" boolean, "is_lactose_free" boolean, "is_halal" boolean)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  select
    mi.id,
    mi.section_id,
    mi.name,
    mi.description,
    mi.price_cents,
    mi.currency,
    null::integer as calories,
    exists (
      select 1 from jsonb_array_elements_text(coalesce(mi.tags, '[]'::jsonb)) t(tag)
      where lower(t.tag) = 'vegan'
    ) as is_vegan,
    exists (
      select 1 from jsonb_array_elements_text(coalesce(mi.tags, '[]'::jsonb)) t(tag)
      where lower(t.tag) in ('vegetarian','vejetaryen')
    ) as is_vegetarian,
    exists (
      select 1 from jsonb_array_elements_text(coalesce(mi.tags, '[]'::jsonb)) t(tag)
      where lower(t.tag) in ('gluten_free','glutensiz')
    ) as is_gluten_free,
    exists (
      select 1 from jsonb_array_elements_text(coalesce(mi.tags, '[]'::jsonb)) t(tag)
      where lower(t.tag) in ('lactose_free','laktozsuz')
    ) as is_lactose_free,
    exists (
      select 1 from jsonb_array_elements_text(coalesce(mi.tags, '[]'::jsonb)) t(tag)
      where lower(t.tag) = 'halal'
    ) as is_halal
  from public.menu_items mi
  join public.menu_sections ms on ms.id = mi.section_id
  where ms.menu_id = p_menu_id
    and mi.is_available = true
  order by ms.sort_order asc, mi.sort_order asc, mi.created_at asc;
$$;


ALTER FUNCTION "public"."get_menu_items_v1"("p_menu_id" "uuid") OWNER TO "postgres";


