CREATE OR REPLACE FUNCTION "public"."get_menu_items_v2"("p_section_id" "uuid", "p_limit" integer DEFAULT 200, "p_offset" integer DEFAULT 0) RETURNS TABLE("id" "uuid", "section_id" "uuid", "business_id" "uuid", "name" "text", "description" "text", "price_cents" integer, "currency" "text", "calories" integer, "is_vegan" boolean, "is_vegetarian" boolean, "is_gluten_free" boolean, "is_lactose_free" boolean, "is_halal" boolean, "status" "text", "created_at" timestamp with time zone, "updated_at" timestamp with time zone, "catalog_item_id" bigint, "price_status" "text", "total_30d" integer)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  select
    i.id,
    i.section_id,
    i.business_id,
    i.name,
    i.description,
    i.price_cents,
    i.currency,
    null::integer as calories,
    exists (
      select 1 from jsonb_array_elements_text(coalesce(i.tags, '[]'::jsonb)) t(tag)
      where lower(t.tag) = 'vegan'
    ) as is_vegan,
    exists (
      select 1 from jsonb_array_elements_text(coalesce(i.tags, '[]'::jsonb)) t(tag)
      where lower(t.tag) in ('vegetarian','vejetaryen')
    ) as is_vegetarian,
    exists (
      select 1 from jsonb_array_elements_text(coalesce(i.tags, '[]'::jsonb)) t(tag)
      where lower(t.tag) in ('gluten_free','glutensiz')
    ) as is_gluten_free,
    exists (
      select 1 from jsonb_array_elements_text(coalesce(i.tags, '[]'::jsonb)) t(tag)
      where lower(t.tag) in ('lactose_free','laktozsuz')
    ) as is_lactose_free,
    exists (
      select 1 from jsonb_array_elements_text(coalesce(i.tags, '[]'::jsonb)) t(tag)
      where lower(t.tag) = 'halal'
    ) as is_halal,
    case when i.is_available then 'published' else 'archived' end::text as status,
    i.created_at,
    i.updated_at,
    null::bigint as catalog_item_id,
    coalesce(ps.price_status, 'unverified')::text as price_status,
    coalesce(ps.total_30d, 0)::int as total_30d
  from public.menu_items i
  left join public.menu_item_price_status_v1 ps on ps.menu_item_id = i.id
  where i.section_id = p_section_id
    and i.is_available = true
  order by i.sort_order asc, i.created_at desc
  limit greatest(p_limit, 0)
  offset greatest(p_offset, 0);
$$;


ALTER FUNCTION "public"."get_menu_items_v2"("p_section_id" "uuid", "p_limit" integer, "p_offset" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_menu_price_anomalies_v1"("p_city" "text" DEFAULT NULL::"text", "p_district" "text" DEFAULT NULL::"text", "p_days" integer DEFAULT 30, "p_min_change_pct" numeric DEFAULT 40, "p_limit" integer DEFAULT 20) RETURNS TABLE("business_id" "uuid", "business_name" "text", "menu_item_id" "uuid", "menu_item_name" "text", "city" "text", "district" "text", "first_price_cents" integer, "last_price_cents" integer, "change_pct" numeric, "last_changed_at" timestamp with time zone)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  with hist as (
    select
      b.id as business_id,
      b.name as business_name,
      b.city,
      b.district,
      h.menu_item_id,
      mi.name as menu_item_name,
      h.price_cents,
      h.created_at,
      row_number() over (partition by h.menu_item_id order by h.created_at asc) as rn_first,
      row_number() over (partition by h.menu_item_id order by h.created_at desc) as rn_last
    from public.menu_item_price_history h
    join public.menu_items mi on mi.id = h.menu_item_id
    join public.businesses b on b.id = mi.business_id
    where h.created_at >= now() - make_interval(days => greatest(p_days, 1))
      and h.price_cents is not null
      and h.price_cents > 0
      and b.is_active = true
      and (p_city is null or b.city = p_city)
      and (p_district is null or b.district = p_district)
  ),
  first_last as (
    select
      business_id,
      business_name,
      city,
      district,
      menu_item_id,
      menu_item_name,
      max(case when rn_first = 1 then price_cents end)::int as first_price_cents,
      max(case when rn_last = 1 then price_cents end)::int as last_price_cents,
      max(case when rn_last = 1 then created_at end) as last_changed_at
    from hist
    group by business_id, business_name, city, district, menu_item_id, menu_item_name
  )
  select
    fl.business_id,
    fl.business_name,
    fl.menu_item_id,
    fl.menu_item_name,
    fl.city,
    fl.district,
    fl.first_price_cents,
    fl.last_price_cents,
    round((((fl.last_price_cents - fl.first_price_cents)::numeric / nullif(fl.first_price_cents, 0)::numeric) * 100), 1) as change_pct,
    fl.last_changed_at
  from first_last fl
  where fl.first_price_cents is not null
    and fl.last_price_cents is not null
    and fl.first_price_cents > 0
    and abs(((fl.last_price_cents - fl.first_price_cents)::numeric / fl.first_price_cents::numeric) * 100) >= greatest(p_min_change_pct, 1)
  order by abs(((fl.last_price_cents - fl.first_price_cents)::numeric / fl.first_price_cents::numeric) * 100) desc
  limit greatest(p_limit, 1);
$$;


ALTER FUNCTION "public"."get_menu_price_anomalies_v1"("p_city" "text", "p_district" "text", "p_days" integer, "p_min_change_pct" numeric, "p_limit" integer) OWNER TO "postgres";


