CREATE OR REPLACE FUNCTION "public"."get_my_profile_progress_v1"() RETURNS TABLE("total_xp" integer, "level" integer, "xp_in_level" integer, "next_level_xp" integer, "unlocked_count" integer)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_uid uuid := auth.uid();
  v_total_xp int := 0;
  v_level int := 1;
  v_unlocked_count int := 0;
begin
  if v_uid is null then
    return;
  end if;

  perform public.recompute_profile_progress_v1(v_uid);

  select
    upp.total_xp,
    upp.level,
    upp.unlocked_count
  into v_total_xp, v_level, v_unlocked_count
  from public.user_profile_progress upp
  where upp.user_id = v_uid;

  return query
  select
    coalesce(v_total_xp, 0),
    coalesce(v_level, 1),
    (coalesce(v_total_xp, 0) % 100),
    100,
    coalesce(v_unlocked_count, 0);
end;
$$;


