CREATE OR REPLACE FUNCTION "public"."get_my_profile_stats"() RETURNS TABLE("reviews_count" integer, "helpful_received" integer, "favorites_count" integer, "visits_count" integer, "contribution_score" integer)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  with my_reviews as (
    select id, helpful_count
    from public.reviews
    where user_id = auth.uid()
  )
  select
    (select count(*)::int from my_reviews) as reviews_count,
    (select coalesce(sum(helpful_count), 0)::int from my_reviews) as helpful_received,
    (select count(*)::int from public.favorites where user_id = auth.uid()) as favorites_count,
    (select count(*)::int from public.visits where user_id = auth.uid()) as visits_count,
    (
      (select count(*)::int from my_reviews) * 5
      +
      (select coalesce(sum(helpful_count), 0)::int from my_reviews) * 2
      +
      (select count(*)::int from public.favorites where user_id = auth.uid())
      +
      (select count(*)::int from public.visits where user_id = auth.uid()) * 1
    ) as contribution_score;
$$;


ALTER FUNCTION "public"."get_my_profile_stats"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_my_reputation_score_v1"() RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
declare
  v_user uuid := auth.uid();
  v_score int := 50;
  v_approved int := 0;
  v_rejected int := 0;
begin
  if v_user is null then
    return 0;
  end if;

  if to_regclass('public.menu_item_price_suggestions') is not null then
    execute
      'select count(*) from public.menu_item_price_suggestions
       where created_by = $1 and status = any($2)'
      into v_approved using v_user, array['approved','accepted','handled','verified'];
    execute
      'select count(*) from public.menu_item_price_suggestions
       where created_by = $1 and status = any($2)'
      into v_rejected using v_user, array['rejected'];
    v_score := v_score + (v_approved * 3) - (v_rejected * 5);
  end if;

  if to_regclass('public.menu_item_suggestions') is not null then
    execute
      'select count(*) from public.menu_item_suggestions
       where created_by = $1 and status = any($2)'
      into v_approved using v_user, array['approved','accepted'];
    execute
      'select count(*) from public.menu_item_suggestions
       where created_by = $1 and status = any($2)'
      into v_rejected using v_user, array['rejected'];
    v_score := v_score + (v_approved * 2) - (v_rejected * 4);
  end if;

  if to_regclass('public.business_suggestions') is not null then
    execute
      'select count(*) from public.business_suggestions
       where user_id = $1 and status = any($2)'
      into v_approved using v_user, array['approved','accepted'];
    execute
      'select count(*) from public.business_suggestions
       where user_id = $1 and status = any($2)'
      into v_rejected using v_user, array['rejected'];
    v_score := v_score + (v_approved * 4) - (v_rejected * 6);
  end if;

  if to_regclass('public.reviews') is not null then
    execute
      'select count(*) from public.reviews
       where user_id = $1 and status = any($2)'
      into v_approved using v_user, array['approved','published'];
    execute
      'select count(*) from public.reviews
       where user_id = $1 and status = any($2)'
      into v_rejected using v_user, array['rejected'];
    v_score := v_score + (v_approved * 1) - (v_rejected * 3);
  end if;

  if v_score < 0 then
    v_score := 0;
  end if;
  if v_score > 100 then
    v_score := 100;
  end if;

  return v_score;
end;
$_$;


ALTER FUNCTION "public"."get_my_reputation_score_v1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_my_silent_quality_score_v1"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_user uuid := auth.uid();
  v_contribution_count int := 0;
  v_approved_count int := 0;
  v_review_count int := 0;
  v_score int := 0;
begin
  if v_user is null then
    return jsonb_build_object(
      'silent_quality_score', 0,
      'is_silent_quality', false,
      'approved_count', 0,
      'contribution_count', 0
    );
  end if;

  if to_regclass('public.menu_item_price_suggestions') is not null then
    select
      count(*),
      count(*) filter (where status = any(array['approved','accepted','handled','verified']))
    into v_contribution_count, v_approved_count
    from public.menu_item_price_suggestions
    where created_by = v_user
      and created_at >= now() - interval '180 days';
  end if;

  if to_regclass('public.reviews') is not null then
    select count(*)
      into v_review_count
    from public.reviews
    where user_id = v_user
      and created_at >= now() - interval '180 days';
  end if;

  v_score := round(
    least(
      100::numeric,
      greatest(
        0::numeric,
        (
          (coalesce(v_approved_count, 0)::numeric / nullif(v_contribution_count, 0)::numeric) * 80
        ) + least(20, v_approved_count)
      )
    )
  )::int;
  if v_contribution_count = 0 then
    v_score := 0;
  end if;

  return jsonb_build_object(
    'silent_quality_score', v_score,
    'is_silent_quality', (v_review_count <= 2 and v_approved_count >= 5 and v_score >= 70),
    'approved_count', v_approved_count,
    'contribution_count', v_contribution_count
  );
end;
$$;


ALTER FUNCTION "public"."get_my_silent_quality_score_v1"() OWNER TO "postgres";


