CREATE OR REPLACE FUNCTION "public"."get_my_suspended_claims_v1"("p_status" "text" DEFAULT NULL::"text", "p_limit" integer DEFAULT 30, "p_offset" integer DEFAULT 0) RETURNS TABLE("claim_id" "uuid", "claim_status" "text", "created_at" timestamp with time zone, "handled_at" timestamp with time zone, "fulfilled_at" timestamp with time zone, "business_id" "uuid", "business_name" "text", "city" "text", "district" "text", "amount_cents" integer, "currency" "text", "verify_code" "text")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  select
    c.id as claim_id,
    c.status::text as claim_status,
    c.created_at,
    c.handled_at,
    c.fulfilled_at,

    b.id as business_id,
    b.name as business_name,
    b.city,
    b.district,

    m.amount_cents,
