CREATE OR REPLACE FUNCTION "public"."get_my_trust_graph_v1"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_user uuid := auth.uid();
  v_price_approved int := 0;
  v_price_rejected int := 0;
  v_review_published int := 0;
  v_review_rejected int := 0;
  v_report_resolved int := 0;
  v_report_rejected int := 0;
  v_spam_signals int := 0;
  v_accuracy numeric := 0;
  v_trust int := 0;
begin
  if v_user is null then
    return jsonb_build_object(
      'trusted_actions', 0,
      'rejected_actions', 0,
      'spam_signals', 0,
      'accuracy_score', 0,
      'trust_score', 0
    );
  end if;

  if to_regclass('public.menu_item_price_suggestions') is not null then
    select
      count(*) filter (where status = any(array['approved','accepted','handled','verified'])),
      count(*) filter (where status = 'rejected')
    into v_price_approved, v_price_rejected
    from public.menu_item_price_suggestions
    where created_by = v_user;
  end if;

  if to_regclass('public.reviews') is not null then
    select
      count(*) filter (where status = any(array['approved','published'])),
      count(*) filter (where status = 'rejected')
    into v_review_published, v_review_rejected
    from public.reviews
    where user_id = v_user;
  end if;

  if to_regclass('public.reports') is not null then
    select
      count(*) filter (where status = any(array['resolved','handled','accepted'])),
      count(*) filter (where status = 'rejected')
    into v_report_resolved, v_report_rejected
    from public.reports
    where created_by = v_user;
  end if;

  if to_regclass('public.user_rate_limits') is not null then
    select count(*)
      into v_spam_signals
    from public.user_rate_limits
    where user_id = v_user
      and day >= current_date - 30
      and action in (
        'review_submit',
        'price_suggestion_submit',
        'business_media_upload',
        'menu_photo_upload'
      )
      and count >= 10;
  end if;

  v_accuracy :=
    (
      (v_price_approved + v_review_published + v_report_resolved)::numeric /
      nullif(
        (v_price_approved + v_review_published + v_report_resolved + v_price_rejected + v_review_rejected + v_report_rejected),
        0
      )::numeric
    );
  if v_accuracy is null then
    v_accuracy := 0;
  end if;

  v_trust := round(
    least(
      100::numeric,
      greatest(
        0::numeric,
        (v_accuracy * 70) +
        least(20, (v_price_approved + v_review_published + v_report_resolved)) -
        least(30, v_spam_signals * 6)
      )
    )
  )::int;

  return jsonb_build_object(
    'trusted_actions', (v_price_approved + v_review_published + v_report_resolved),
    'rejected_actions', (v_price_rejected + v_review_rejected + v_report_rejected),
    'spam_signals', v_spam_signals,
    'accuracy_score', round(v_accuracy * 100),
    'trust_score', v_trust
  );
end;
$$;


ALTER FUNCTION "public"."get_my_trust_graph_v1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_my_weekly_missions"() RETURNS TABLE("week_start" "date", "reviews_done" integer, "visits_done" integer, "votes_done" integer, "reviews_goal" integer, "visits_goal" integer, "votes_goal" integer, "completed_count" integer)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  with w as (
    select date_trunc('week', now())::date as week_start
  ),
  reviews as (
    select count(*)::int as c
    from public.reviews r, w
    where r.user_id = auth.uid()
      and r.created_at >= w.week_start
  ),
  visits as (
    select count(*)::int as c
    from public.visits v, w
    where v.user_id = auth.uid()
      and v.created_at >= w.week_start
  ),
  votes as (
    select count(*)::int as c
    from public.review_votes rv, w
    where rv.user_id = auth.uid()
      and rv.created_at >= w.week_start
  )
  select
    (select week_start from w) as week_start,
    (select c from reviews) as reviews_done,
    (select c from visits) as visits_done,
    (select c from votes) as votes_done,
    1 as reviews_goal,
    3 as visits_goal,
    3 as votes_goal,
    (
      (case when (select c from reviews) >= 1 then 1 else 0 end) +
      (case when (select c from visits) >= 3 then 1 else 0 end) +
      (case when (select c from votes) >= 3 then 1 else 0 end)
    )::int as completed_count;
$$;


ALTER FUNCTION "public"."get_my_weekly_missions"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_nearby_campaign_stories_v1"("p_lat" double precision DEFAULT NULL::double precision, "p_lng" double precision DEFAULT NULL::double precision, "p_radius_km" integer DEFAULT 10, "p_city" "text" DEFAULT NULL::"text", "p_district" "text" DEFAULT NULL::"text", "p_limit" integer DEFAULT 20) RETURNS TABLE("story_id" "uuid", "business_id" "uuid", "business_name" "text", "city" "text", "district" "text", "caption" "text", "media_url" "text", "media_thumb_url" "text", "created_at" timestamp with time zone, "expires_at" timestamp with time zone, "distance_km" double precision)
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  with src as (
    select
      s.id as story_id,
      s.business_id,
      b.name as business_name,
      b.city,
      b.district,
      s.caption,
      s.media_url,
      coalesce(s.media_thumb_url, s.media_url) as media_thumb_url,
      s.created_at,
      s.expires_at,
      case
        when p_lat is null or p_lng is null or b.lat is null or b.lng is null then null
        else (
          6371.0 * acos(
            least(
              1.0,
              greatest(
                -1.0,
                cos(radians(p_lat)) * cos(radians(b.lat)) * cos(radians(b.lng) - radians(p_lng))
                + sin(radians(p_lat)) * sin(radians(b.lat))
              )
            )
          )
        )
      end as distance_km
    from public.business_stories s
    join public.businesses b on b.id = s.business_id
    where s.is_deleted = false
      and s.type = 'promo'::public.story_type
      and s.expires_at > now()
      and (
        p_lat is not null and p_lng is not null
        or (
          (p_city is null or trim(p_city) = '' or lower(b.city) = lower(trim(p_city)))
          and (p_district is null or trim(p_district) = '' or lower(b.district) = lower(trim(p_district)))
        )
      )
  )
  select
    story_id,
    business_id,
    business_name,
    city,
    district,
    caption,
    media_url,
    media_thumb_url,
    created_at,
    expires_at,
    distance_km
  from src
  where distance_km is null or distance_km <= greatest(coalesce(p_radius_km, 10), 1)
  order by distance_km nulls last, created_at desc
  limit greatest(coalesce(p_limit, 20), 1);
$$;


ALTER FUNCTION "public"."get_nearby_campaign_stories_v1"("p_lat" double precision, "p_lng" double precision, "p_radius_km" integer, "p_city" "text", "p_district" "text", "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_owner_menu_version_detail_v1"("p_snapshot_id" "uuid") RETURNS TABLE("snapshot_id" "uuid", "menu_id" "uuid", "menu_version" integer, "snapshot_reason" "text", "created_at" timestamp with time zone, "menu_title" "text", "menu_kind" "text", "section_titles" "text"[], "item_names" "text"[])
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  select
    s.id as snapshot_id,
    s.source_menu_id as menu_id,
    s.menu_version,
    s.snapshot_reason,
    s.created_at,
    coalesce(s.snapshot_json->'menu'->>'title', '') as menu_title,
    nullif(trim(coalesce(s.snapshot_json->'menu'->>'kind', '')), '') as menu_kind,
    coalesce(
      (
        select array_agg(nullif(trim(section_row->>'title'), ''))
        from jsonb_array_elements(coalesce(s.snapshot_json->'sections', '[]'::jsonb)) section_row
        where nullif(trim(section_row->>'title'), '') is not null
      ),
      '{}'::text[]
    ) as section_titles,
    coalesce(
      (
        select array_agg(nullif(trim(item_row->>'name'), ''))
        from jsonb_array_elements(coalesce(s.snapshot_json->'sections', '[]'::jsonb)) section_row,
             jsonb_array_elements(coalesce(section_row->'items', '[]'::jsonb)) item_row
        where nullif(trim(item_row->>'name'), '') is not null
      ),
      '{}'::text[]
    ) as item_names
  from public.menu_snapshots s
  join public.menus m on m.id = s.source_menu_id
  where s.id = p_snapshot_id
    and (
      public.is_admin()
      or public.has_business_permission_v1(m.business_id, 'business_read')
    );
$$;


ALTER FUNCTION "public"."get_owner_menu_version_detail_v1"("p_snapshot_id" "uuid") OWNER TO "postgres";


