CREATE OR REPLACE FUNCTION "public"."get_owner_price_suggestions_v1"("p_business_id" "uuid" DEFAULT NULL::"uuid", "p_status" "text" DEFAULT 'pending'::"text", "p_limit" integer DEFAULT 30, "p_offset" integer DEFAULT 0) RETURNS TABLE("suggestion_id" "uuid", "status" "text", "created_at" timestamp with time zone, "business_id" "uuid", "business_name" "text", "menu_item_id" "uuid", "item_name" "text", "current_price_cents" integer, "suggested_price_cents" integer, "currency" "text", "created_by" "uuid")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  with owner_businesses as (
    select c.business_id
    from public.owner_claims c
    where c.user_id = auth.uid()
      and c.status = 'approved'
  ),
  target_businesses as (
    select business_id
    from owner_businesses
    where p_business_id is null
    union all
    select p_business_id
    where p_business_id is not null
  )
  select
    s.id as suggestion_id,
    s.status::text,
    s.created_at,
    s.business_id,
    b.name as business_name,
    mi.id as menu_item_id,
    mi.name as item_name,
    mi.price_cents as current_price_cents,
    s.suggested_price_cents,
    s.currency,
    s.created_by
  from public.menu_item_price_suggestions s
  join target_businesses tb on tb.business_id = s.business_id
  join public.menu_items mi on mi.id = s.menu_item_id
  join public.businesses b on b.id = s.business_id
  where (p_status is null or s.status::text = p_status)
  order by (s.status='pending') desc, s.created_at asc
  limit greatest(p_limit,0) offset greatest(p_offset,0);
$$;


ALTER FUNCTION "public"."get_owner_price_suggestions_v1"("p_business_id" "uuid", "p_status" "text", "p_limit" integer, "p_offset" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_perk_feed_v1"("p_limit" integer DEFAULT 30, "p_offset" integer DEFAULT 0, "p_city" "text" DEFAULT NULL::"text", "p_district" "text" DEFAULT NULL::"text", "p_category" "text" DEFAULT NULL::"text") RETURNS TABLE("event_id" "uuid", "business_id" "uuid", "business_name" "text", "title" "text", "description" "text", "starts_at" timestamp with time zone, "ends_at" timestamp with time zone, "created_at" timestamp with time zone)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  select
    e.id as event_id,
    e.business_id,
    b.name as business_name,
    (e.meta->>'title')::text as title,
    (e.meta->>'description')::text as description,
    nullif(e.meta->>'starts_at','')::timestamptz as starts_at,
    nullif(e.meta->>'ends_at','')::timestamptz as ends_at,
    e.created_at
  from public.feed_events e
  join public.businesses b on b.id = e.business_id
  where e.type = 'perk'
    and (p_city is null or b.city = p_city)
    and (p_district is null or b.district = p_district)
    and (p_category is null or b.category = p_category)
  order by e.created_at desc
  limit greatest(p_limit, 0)
  offset greatest(p_offset, 0);
$$;


ALTER FUNCTION "public"."get_perk_feed_v1"("p_limit" integer, "p_offset" integer, "p_city" "text", "p_district" "text", "p_category" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_photo_missions_v1"("p_city" "text" DEFAULT NULL::"text", "p_district" "text" DEFAULT NULL::"text", "p_limit" integer DEFAULT 20) RETURNS TABLE("mission_id" "uuid", "business_id" "uuid", "business_name" "text", "city" "text", "district" "text", "mission_type" "text", "reward_points" integer, "expires_at" timestamp with time zone, "created_at" timestamp with time zone, "my_status" "text", "my_claim_id" "uuid")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  select
    m.id as mission_id,
    m.business_id,
    b.name as business_name,
    coalesce(m.city, b.city) as city,
    coalesce(m.district, b.district) as district,
    m.mission_type,
    m.reward_points,
    m.expires_at,
    m.created_at,
    c.status as my_status,
    c.id as my_claim_id
  from public.photo_missions m
  join public.businesses b on b.id = m.business_id
  left join public.user_mission_claims c
    on c.mission_id = m.id and c.user_id = auth.uid()
  where (m.expires_at is null or m.expires_at >= now())
    and (p_city is null or coalesce(m.city, b.city) = p_city)
    and (p_district is null or coalesce(m.district, b.district) = p_district)
  order by m.created_at desc
  limit greatest(p_limit, 0);
$$;


ALTER FUNCTION "public"."get_photo_missions_v1"("p_city" "text", "p_district" "text", "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_public_collection_v1"("p_collection_id" "uuid") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  select jsonb_build_object(
    'ok', (c.is_public = true),
    'collection', case when c.is_public = true then jsonb_build_object(
      'id', c.id,
      'title', c.title,
      'created_at', c.created_at
    ) else null end,
    'items', case when c.is_public = true then coalesce(jsonb_agg(
      jsonb_build_object(
        'business_id', b.id,
        'business_name', b.name,
        'city', b.city,
        'district', b.district,
        'note', ci.note,
        'created_at', ci.created_at
      ) order by ci.created_at desc
    ), '[]'::jsonb) else '[]'::jsonb end
  )
  from public.collections c
  left join public.collection_items ci on ci.collection_id = c.id
  left join public.businesses b on b.id = ci.business_id
  where c.id = p_collection_id
  group by c.id;
$$;


ALTER FUNCTION "public"."get_public_collection_v1"("p_collection_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_regional_price_index_v2"("p_city" "text" DEFAULT NULL::"text", "p_district" "text" DEFAULT NULL::"text", "p_limit" integer DEFAULT 12) RETURNS TABLE("category" "text", "median_price_cents" integer, "avg_price_cents" integer, "sample_count" integer, "updated_in_30d" integer)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  with base as (
    select
      b.category,
      mi.price_cents,
      mi.updated_at
    from public.menu_items mi
    join public.businesses b on b.id = mi.business_id
    where b.is_active = true
      and mi.price_cents is not null
      and mi.price_cents > 0
      and (p_city is null or b.city = p_city)
      and (p_district is null or b.district = p_district)
  )
  select
    coalesce(category, 'Genel') as category,
    percentile_disc(0.5) within group (order by price_cents)::int as median_price_cents,
    round(avg(price_cents))::int as avg_price_cents,
    count(*)::int as sample_count,
    count(*) filter (where updated_at >= now() - interval '30 days')::int as updated_in_30d
  from base
  group by category
  order by median_price_cents desc nulls last
  limit greatest(p_limit, 1);
$$;


ALTER FUNCTION "public"."get_regional_price_index_v2"("p_city" "text", "p_district" "text", "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_runtime_experiments_v1"("p_user_id" "uuid" DEFAULT "auth"."uid"()) RETURNS "jsonb"
