  v_payload jsonb := '{}'::jsonb;
begin
  select coalesce(
    jsonb_object_agg(
      e.key,
      jsonb_build_object(
        'enabled', e.enabled,
        'variants', e.variants,
        'allowed_regions', e.allowed_regions,
        'blocked_regions', e.blocked_regions
      )
    ),
    '{}'::jsonb
  )
  into v_payload
  from public.runtime_experiments e;
  return v_payload;
end;
$$;


ALTER FUNCTION "public"."get_runtime_experiments_v1"("p_user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_runtime_feature_flags_v1"("p_user_id" "uuid" DEFAULT "auth"."uid"()) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $$
declare
  v_global_kill boolean := false;
  v_flags jsonb := '{}'::jsonb;
begin
  select coalesce(rc.global_kill_switch, false)
    into v_global_kill
  from public.runtime_release_controls rc
  where rc.id = true
  limit 1;

  select coalesce(
    jsonb_object_agg(
      rf.key,
      jsonb_build_object(
        'enabled', rf.enabled,
        'rollout_percent', rf.rollout_percent,
        'allowed_regions', rf.allowed_regions,
        'blocked_regions', rf.blocked_regions
      )
    ),
    '{}'::jsonb
  )
  into v_flags
  from public.runtime_feature_flags rf;

  return jsonb_build_object(
    'global_kill_switch', v_global_kill,
    'flags', v_flags
  );
end;
$$;


ALTER FUNCTION "public"."get_runtime_feature_flags_v1"("p_user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_signal_overlap_examples_v1"("p_other_user_id" "uuid", "p_limit" integer DEFAULT 5) RETURNS TABLE("business_id" "uuid", "business_name" "text", "my_signal" double precision, "other_signal" double precision)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  with my as (
    select business_id, signal_score
    from public.user_business_signals_v1
    where user_id = auth.uid()
  ),
  oth as (
    select business_id, signal_score
    from public.user_business_signals_v1
    where user_id = p_other_user_id
  )
  select
    b.id as business_id,
    b.name as business_name,
    my.signal_score as my_signal,
    oth.signal_score as other_signal
  from my
  join oth on oth.business_id = my.business_id
  join public.businesses b on b.id = my.business_id
  order by (my.signal_score + oth.signal_score) desc
  limit greatest(p_limit,0);
$$;


