CREATE OR REPLACE FUNCTION "public"."get_taste_divergence_examples_v1"("p_other_user_id" "uuid", "p_limit" integer DEFAULT 3) RETURNS TABLE("business_id" "uuid", "business_name" "text", "my_rating" integer, "other_rating" integer, "diff" integer)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  with my as (
    select business_id, rating
    from public.reviews
    where user_id = auth.uid()
      and status='approved'
  ),
  oth as (
    select business_id, rating
    from public.reviews
    where user_id = p_other_user_id
      and status='approved'
  )
  select
    b.id as business_id,
    b.name as business_name,
    my.rating as my_rating,
    oth.rating as other_rating,
    abs(my.rating - oth.rating) as diff
  from my
  join oth on oth.business_id = my.business_id
  join public.businesses b on b.id = my.business_id
  order by diff desc
  limit greatest(p_limit,0);
$$;


