CREATE OR REPLACE FUNCTION "public"."get_taste_matches_hybrid_v1"("p_limit" integer DEFAULT 10, "p_min_overlap" integer DEFAULT 5) RETURNS TABLE("user_id" "uuid", "similarity" double precision, "overlap" integer, "review_similarity" double precision, "signal_similarity" double precision)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  with my_r as (
    select business_id, (rating - 3)::float as r
    from public.reviews
    where user_id = auth.uid() and status='approved'
    order by created_at desc
    limit 200
  ),
  oth_r as (
    select user_id, business_id, (rating - 3)::float as r
    from public.reviews
    where user_id <> auth.uid() and status='approved'
  ),
  review_join as (
    select
      o.user_id,
      count(*) as overlap,
      sum(m.r * o.r) as dot,
      sqrt(sum(m.r*m.r)) as norm_my,
      sqrt(sum(o.r*o.r)) as norm_oth
    from my_r m
    join oth_r o on o.business_id = m.business_id
    group by o.user_id
  ),
  review_sim as (
    select
      user_id,
      overlap,
      case when norm_my=0 or norm_oth=0 then 0 else dot/(norm_my*norm_oth) end as review_similarity
    from review_join
    where overlap >= p_min_overlap
  ),

  my_s as (
    select business_id, signal_score as s
    from public.user_business_signals_v1
    where user_id = auth.uid()
    order by signal_score desc
    limit 300
  ),
  oth_s as (
    select user_id, business_id, signal_score as s
    from public.user_business_signals_v1
    where user_id <> auth.uid()
  ),
  signal_join as (
    select
      o.user_id,
      sum(m.s * o.s) as dot,
      sqrt(sum(m.s*m.s)) as norm_my,
      sqrt(sum(o.s*o.s)) as norm_oth
    from my_s m
    join oth_s o on o.business_id = m.business_id
    group by o.user_id
  ),
  signal_sim as (
    select
      user_id,
      case when norm_my=0 or norm_oth=0 then 0 else dot/(norm_my*norm_oth) end as signal_similarity
    from signal_join
  )

  select
    r.user_id,
    (0.75*r.review_similarity + 0.25*coalesce(s.signal_similarity,0)) as similarity,
    r.overlap,
    r.review_similarity,
    coalesce(s.signal_similarity,0) as signal_similarity
  from review_sim r
  left join signal_sim s on s.user_id = r.user_id
  order by similarity desc, overlap desc
  limit greatest(p_limit,0);
$$;


ALTER FUNCTION "public"."get_taste_matches_hybrid_v1"("p_limit" integer, "p_min_overlap" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_taste_matches_v1"("p_limit" integer DEFAULT 10, "p_min_overlap" integer DEFAULT 5) RETURNS TABLE("user_id" "uuid", "similarity" double precision, "overlap" integer)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  with my as (
    select business_id, (rating - 3)::float as r
    from public.reviews
    where user_id = auth.uid()
      and status = 'approved'
    order by created_at desc
    limit 200
  ),
  others as (
    select user_id, business_id, (rating - 3)::float as r
    from public.reviews
    where user_id <> auth.uid()
      and status = 'approved'
  ),
  joined as (
    select o.user_id,
           count(*) as overlap,
           sum(m.r * o.r) as dot,
           sqrt(sum(m.r*m.r)) as norm_my,
           sqrt(sum(o.r*o.r)) as norm_other
    from my m
    join others o on o.business_id = m.business_id
    group by o.user_id
  )
  select
    user_id,
    case when norm_my = 0 or norm_other = 0 then 0 else (dot / (norm_my * norm_other)) end as similarity,
    overlap
  from joined
  where overlap >= p_min_overlap
  order by similarity desc, overlap desc
  limit greatest(p_limit,0);
$$;


ALTER FUNCTION "public"."get_taste_matches_v1"("p_limit" integer, "p_min_overlap" integer) OWNER TO "postgres";


