CREATE OR REPLACE FUNCTION "public"."get_taste_overlap_examples_v1"("p_other_user_id" "uuid", "p_limit" integer DEFAULT 5) RETURNS TABLE("business_id" "uuid", "business_name" "text", "my_rating" integer, "other_rating" integer, "created_at_my" timestamp with time zone, "created_at_other" timestamp with time zone, "score" double precision)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  with my as (
    select business_id, rating, created_at
    from public.reviews
    where user_id = auth.uid()
      and status='approved'
  ),
  oth as (
    select business_id, rating, created_at
    from public.reviews
    where user_id = p_other_user_id
      and status='approved'
  ),
  joined as (
    select
      b.id as business_id,
      b.name as business_name,
      my.rating as my_rating,
      oth.rating as other_rating,
      my.created_at as created_at_my,
      oth.created_at as created_at_other,
      ((my.rating - 3)::float * (oth.rating - 3)::float) as score
    from my
    join oth on oth.business_id = my.business_id
    join public.businesses b on b.id = my.business_id
  )
  select *
  from joined
  order by score desc, greatest(created_at_my, created_at_other) desc
  limit greatest(p_limit,0);
$$;


