CREATE OR REPLACE FUNCTION "public"."get_top_businesses"("p_period" "text" DEFAULT 'week'::"text", "p_limit" integer DEFAULT 10, "p_min_reviews" integer DEFAULT 2) RETURNS TABLE("business_id" "uuid", "name" "text", "category" "text", "city" "text", "district" "text", "avg_rating" numeric, "reviews_count" integer)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  with period_reviews as (
    select
      r.business_id,
      r.rating
    from public.reviews r
    where r.status = 'approved'
      and r.created_at >= case
        when p_period = 'month' then (now() - interval '30 days')
        else (now() - interval '7 days')
      end
  ),
  agg as (
    select
      business_id,
      count(*)::int as reviews_count,
      avg(rating) as avg_rating
    from period_reviews
    group by business_id
    having count(*) >= p_min_reviews
  )
  select
    b.id as business_id,
    b.name,
    b.category,
    b.city,
    b.district,
    coalesce(a.avg_rating, 0)::numeric(3,2) as avg_rating,
    coalesce(a.reviews_count, 0)::int as reviews_count
  from agg a
  join public.businesses b on b.id = a.business_id
  where b.is_active = true
  order by a.avg_rating desc, a.reviews_count desc
  limit p_limit;
$$;


ALTER FUNCTION "public"."get_top_businesses"("p_period" "text", "p_limit" integer, "p_min_reviews" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_top_businesses"("p_period" "text", "p_limit" integer, "p_min_reviews" integer) IS 'DANGEROUS_TO_REMOVE: still referenced by app/runtime paths';



CREATE OR REPLACE FUNCTION "public"."get_top_businesses_period_v1"("p_period" "text", "p_limit" integer DEFAULT 6, "p_min_reviews" integer DEFAULT 2) RETURNS TABLE("id" "uuid", "name" "text", "category" "text", "city" "text", "district" "text", "avg_rating" double precision, "reviews_count" integer, "score" double precision)
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  with bounds as (
    select
      case
        when p_period='week' then now() - interval '7 days'
        when p_period='month' then now() - interval '30 days'
        else now() - interval '7 days'
      end as since_at
  ),
  agg as (
    select
      r.business_id as id,
      count(*)::int as reviews_count,
      avg(r.rating)::double precision as avg_rating
    from public.reviews r, bounds b
    where r.status='approved'
      and r.created_at >= b.since_at
    group by r.business_id
    having count(*) >= p_min_reviews
  )
  select
    b.id,
    b.name,
    b.category,
    b.city,
    b.district,
    a.avg_rating,
    a.reviews_count,
    -- Basit skor: rating * log(1+count)
    (a.avg_rating * ln(1 + a.reviews_count))::double precision as score
  from agg a
  join public.businesses b on b.id = a.id
  order by score desc
  limit greatest(p_limit, 0);
$$;


ALTER FUNCTION "public"."get_top_businesses_period_v1"("p_period" "text", "p_limit" integer, "p_min_reviews" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_user_location_prefs_v1"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_row record;
begin
  if auth.uid() is null then
    return jsonb_build_object('ok', false, 'error', 'not_authenticated');
  end if;

  select city, district, neighborhood, mode, updated_at
    into v_row
  from public.user_location_prefs
  where user_id = auth.uid();

  if not found then
    return jsonb_build_object('ok', true, 'data', null);
  end if;

  return jsonb_build_object(
    'ok', true,
    'data', jsonb_build_object(
      'city', v_row.city,
      'district', v_row.district,
      'neighborhood', v_row.neighborhood,
      'mode', v_row.mode,
      'updated_at', v_row.updated_at
    )
  );
end;
$$;


