CREATE OR REPLACE FUNCTION "public"."home_feed_v1"("p_city" "text", "p_district" "text", "p_neighborhood" "text" DEFAULT NULL::"text", "p_near_open_limit" integer DEFAULT 8, "p_top_categories_limit" integer DEFAULT 6, "p_trending_limit" integer DEFAULT 8) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_city text := nullif(trim(coalesce(p_city, '')), '');
  v_district text := nullif(trim(coalesce(p_district, '')), '');
  v_neighborhood text := nullif(trim(coalesce(p_neighborhood, '')), '');
  v_near_open jsonb := '[]'::jsonb;
  v_top_categories jsonb := '[]'::jsonb;
  v_top_views jsonb := '[]'::jsonb;
  v_price_changes jsonb := '[]'::jsonb;
  v_night_favorites jsonb := '[]'::jsonb;
begin
  if v_city is null or v_district is null then
    return jsonb_build_object(
      'near_open_businesses', v_near_open,
      'top_categories', v_top_categories,
      'trending_top_views', v_top_views,
      'trending_price_changes', v_price_changes,
      'trending_night_favorites', v_night_favorites,
      'generated_at', now()
    );
  end if;

  select coalesce(jsonb_agg(to_jsonb(x)), '[]'::jsonb)
    into v_near_open
  from (
    select *
    from public.search_businesses_v1(
      p_query => null,
      p_city => v_city,
      p_district => v_district,
      p_limit => greatest(1, least(p_near_open_limit, 20)),
      p_offset => 0
    )
  ) x;

  select coalesce(jsonb_agg(to_jsonb(x)), '[]'::jsonb)
    into v_top_categories
  from (
    select *
    from public.get_regional_price_index_v2(
      p_city => v_city,
      p_district => v_district,
      p_limit => greatest(1, least(p_top_categories_limit, 20))
    )
  ) x;

  select coalesce(jsonb_agg(to_jsonb(x)), '[]'::jsonb)
    into v_top_views
  from (
    select *
    from public.get_district_top_views_v1(
      p_city => v_city,
      p_district => v_district,
      p_neighborhood => v_neighborhood,
      p_limit => greatest(1, least(p_trending_limit, 20))
    )
  ) x;

  select coalesce(jsonb_agg(to_jsonb(x)), '[]'::jsonb)
    into v_price_changes
  from (
    select *
    from public.get_district_price_changes_v1(
      p_city => v_city,
      p_district => v_district,
      p_neighborhood => v_neighborhood,
      p_limit => greatest(1, least(p_trending_limit, 20))
    )
  ) x;

  select coalesce(jsonb_agg(to_jsonb(x)), '[]'::jsonb)
    into v_night_favorites
  from (
    select *
    from public.get_district_night_favorites_v1(
      p_city => v_city,
      p_district => v_district,
      p_neighborhood => v_neighborhood,
      p_limit => greatest(1, least(p_trending_limit, 20))
    )
  ) x;

  return jsonb_build_object(
    'near_open_businesses', v_near_open,
    'top_categories', v_top_categories,
    'trending_top_views', v_top_views,
    'trending_price_changes', v_price_changes,
    'trending_night_favorites', v_night_favorites,
    'generated_at', now()
  );
end;
$$;


ALTER FUNCTION "public"."home_feed_v1"("p_city" "text", "p_district" "text", "p_neighborhood" "text", "p_near_open_limit" integer, "p_top_categories_limit" integer, "p_trending_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."insert_audit_log_v1"("p_action" "text", "p_target_type" "text", "p_target_id" "uuid", "p_before" "jsonb" DEFAULT NULL::"jsonb", "p_after" "jsonb" DEFAULT NULL::"jsonb") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_actor_id uuid := auth.uid();
  v_actor_role text;
  v_admin_user_id uuid;
  v_ip text;
  v_user_agent text;
begin
  v_actor_role := public.resolve_actor_role_v1(v_actor_id);
  v_admin_user_id := case when v_actor_role = 'admin' then v_actor_id else null end;

  select o_ip, o_user_agent
    into v_ip, v_user_agent
  from public.capture_request_meta_v1();

  insert into public.admin_audit_log (
    admin_user_id,
    actor_id,
    actor_role,
    action,
    target_table,
    target_type,
    target_id,
    before_data,
    after_data,
    ip,
    user_agent,
    meta
  ) values (
    v_admin_user_id,
    v_actor_id,
    v_actor_role,
    p_action,
    p_target_type,
    p_target_type,
    p_target_id,
    p_before,
    p_after,
    v_ip,
    v_user_agent,
    jsonb_strip_nulls(
      jsonb_build_object(
        'actor_id', v_actor_id,
        'actor_role', v_actor_role,
        'before', p_before,
        'after', p_after,
        'ip', v_ip,
        'user_agent', v_user_agent
      )
    )
  );
end;
$$;


ALTER FUNCTION "public"."insert_audit_log_v1"("p_action" "text", "p_target_type" "text", "p_target_id" "uuid", "p_before" "jsonb", "p_after" "jsonb") OWNER TO "postgres";


