CREATE OR REPLACE FUNCTION "public"."list_audit_timeline_v1"("p_limit" integer DEFAULT 50, "p_offset" integer DEFAULT 0, "p_action" "text" DEFAULT NULL::"text", "p_target_type" "text" DEFAULT NULL::"text", "p_target_id" "uuid" DEFAULT NULL::"uuid", "p_actor_id" "uuid" DEFAULT NULL::"uuid", "p_from" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_to" timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS TABLE("id" "uuid", "created_at" timestamp with time zone, "actor_id" "uuid", "actor_role" "text", "action" "text", "target_type" "text", "target_id" "uuid", "before_data" "jsonb", "after_data" "jsonb", "ip" "text", "user_agent" "text", "meta" "jsonb")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_uid uuid := auth.uid();
  v_is_admin boolean := false;
begin
  if v_uid is null then
    raise exception 'Not authenticated';
  end if;

  select public.is_admin() into v_is_admin;

  if p_limit is null or p_limit < 1 then
    p_limit := 50;
  end if;
  if p_limit > 200 then
    p_limit := 200;
  end if;
  if p_offset is null or p_offset < 0 then
    p_offset := 0;
  end if;

  return query
  with owner_businesses as (
    select distinct oc.business_id
    from public.owner_claims oc
    where oc.user_id = v_uid
      and oc.status = 'approved'
  ),
  base as (
    select
      l.id,
      l.created_at,
      l.actor_id,
      l.actor_role,
      l.action,
      coalesce(l.target_type, l.target_table) as target_type,
      l.target_id,
      l.before_data,
      l.after_data,
      l.ip,
      l.user_agent,
      l.meta,
      case
        when coalesce(l.target_type, l.target_table) = 'business' then l.target_id
        when coalesce(l.target_type, l.target_table) = 'menu' then coalesce(
          nullif(l.after_data ->> 'business_id','')::uuid,
          nullif(l.before_data ->> 'business_id','')::uuid,
          (select m.business_id from public.menus m where m.id = l.target_id)
        )
        when coalesce(l.target_type, l.target_table) = 'menu_item' then coalesce(
          nullif(l.after_data ->> 'business_id','')::uuid,
          nullif(l.before_data ->> 'business_id','')::uuid,
          (select mi.business_id from public.menu_items mi where mi.id = l.target_id)
        )
        when coalesce(l.target_type, l.target_table) = 'owner_claim' then coalesce(
          nullif(l.after_data ->> 'business_id','')::uuid,
          nullif(l.before_data ->> 'business_id','')::uuid,
          (select oc.business_id from public.owner_claims oc where oc.id = l.target_id)
        )
        when coalesce(l.target_type, l.target_table) = 'report' then coalesce(
          nullif(l.after_data ->> 'business_id','')::uuid,
          nullif(l.before_data ->> 'business_id','')::uuid,
          (select r.business_id from public.reports r where r.id = l.target_id)
        )
        else null::uuid
      end as resolved_business_id
    from public.admin_audit_log l
    where (p_action is null or l.action = p_action)
      and (p_target_type is null or coalesce(l.target_type, l.target_table) = p_target_type)
      and (p_target_id is null or l.target_id = p_target_id)
      and (p_actor_id is null or l.actor_id = p_actor_id)
      and (p_from is null or l.created_at >= p_from)
      and (p_to is null or l.created_at <= p_to)
  )
  select
    b.id,
    b.created_at,
    b.actor_id,
    b.actor_role,
    b.action,
    b.target_type,
    b.target_id,
    b.before_data,
    b.after_data,
    b.ip,
    b.user_agent,
    b.meta
  from base b
  where
    v_is_admin
    or b.resolved_business_id in (select business_id from owner_businesses)
    or (
      b.target_type = 'owner_claim'
      and exists (
        select 1
        from public.owner_claims oc
        where oc.id = b.target_id
          and oc.user_id = v_uid
      )
    )
  order by b.created_at desc
  limit p_limit
  offset p_offset;
end;
$$;


ALTER FUNCTION "public"."list_audit_timeline_v1"("p_limit" integer, "p_offset" integer, "p_action" "text", "p_target_type" "text", "p_target_id" "uuid", "p_actor_id" "uuid", "p_from" timestamp with time zone, "p_to" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."list_audit_timeline_v2"("p_limit" integer DEFAULT 50, "p_offset" integer DEFAULT 0, "p_action" "text" DEFAULT NULL::"text", "p_target_type" "text" DEFAULT NULL::"text", "p_target_id" "uuid" DEFAULT NULL::"uuid", "p_actor_id" "uuid" DEFAULT NULL::"uuid", "p_business_id" "uuid" DEFAULT NULL::"uuid", "p_from" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_to" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_q" "text" DEFAULT NULL::"text") RETURNS TABLE("id" "uuid", "created_at" timestamp with time zone, "actor_id" "uuid", "actor_role" "text", "action" "text", "target_type" "text", "target_id" "uuid", "before_data" "jsonb", "after_data" "jsonb", "ip" "text", "user_agent" "text", "meta" "jsonb")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_uid uuid := auth.uid();
  v_is_admin boolean := false;
  v_q text := nullif(trim(coalesce(p_q, '')), '');
begin
  if v_uid is null then
    raise exception 'Not authenticated';
  end if;

  select public.is_admin() into v_is_admin;

  if p_limit is null or p_limit < 1 then
    p_limit := 50;
  end if;
  if p_limit > 200 then
    p_limit := 200;
  end if;
  if p_offset is null or p_offset < 0 then
    p_offset := 0;
  end if;

  return query
  with owner_businesses as (
    select distinct oc.business_id
    from public.owner_claims oc
    where oc.user_id = v_uid
      and oc.status = 'approved'
    union
    select distinct btm.business_id
    from public.business_team_memberships btm
    where btm.user_id = v_uid
      and btm.revoked_at is null
      and btm.business_id is not null
  ),
  normalized as (
    select
      l.id,
      l.created_at,
      l.actor_id,
      l.actor_role,
      l.action,
      case
        when coalesce(l.target_type, l.target_table) in ('business', 'businesses') then 'business'
        when coalesce(l.target_type, l.target_table) in ('menu', 'menus') then 'menu'
        when coalesce(l.target_type, l.target_table) in ('menu_item', 'menu_items') then 'menu_item'
        when coalesce(l.target_type, l.target_table) in ('owner_claim', 'owner_claims') then 'owner_claim'
        when coalesce(l.target_type, l.target_table) in ('report', 'reports') then 'report'
        when coalesce(l.target_type, l.target_table) in (
          'business_team_memberships',
          'team_member',
          'team_membership'
        ) then 'team_member'
        when coalesce(l.target_type, l.target_table) in (
          'menu_item_price_suggestions',
          'price_suggestion'
        ) then 'price_suggestion'
        when coalesce(l.target_type, l.target_table) in ('auth.users', 'user_profiles', 'user') then 'user'
        else coalesce(l.target_type, l.target_table)
      end as canonical_target_type,
      l.target_id,
      l.before_data,
      l.after_data,
      l.ip,
      l.user_agent,
      l.meta
    from public.admin_audit_log l
    where (p_action is null or l.action = p_action)
      and (p_target_id is null or l.target_id = p_target_id)
      and (p_actor_id is null or l.actor_id = p_actor_id)
      and (p_from is null or l.created_at >= p_from)
      and (p_to is null or l.created_at <= p_to)
      and (
        p_target_type is null
        or case
          when coalesce(l.target_type, l.target_table) in ('business', 'businesses') then 'business'
          when coalesce(l.target_type, l.target_table) in ('menu', 'menus') then 'menu'
          when coalesce(l.target_type, l.target_table) in ('menu_item', 'menu_items') then 'menu_item'
          when coalesce(l.target_type, l.target_table) in ('owner_claim', 'owner_claims') then 'owner_claim'
          when coalesce(l.target_type, l.target_table) in ('report', 'reports') then 'report'
          when coalesce(l.target_type, l.target_table) in (
            'business_team_memberships',
            'team_member',
            'team_membership'
          ) then 'team_member'
          when coalesce(l.target_type, l.target_table) in (
            'menu_item_price_suggestions',
            'price_suggestion'
          ) then 'price_suggestion'
          when coalesce(l.target_type, l.target_table) in ('auth.users', 'user_profiles', 'user') then 'user'
          else coalesce(l.target_type, l.target_table)
        end = p_target_type
      )
      and (
        v_q is null
        or l.action ilike ('%' || v_q || '%')
        or coalesce(l.target_type, l.target_table, '') ilike ('%' || v_q || '%')
        or coalesce(l.actor_role, '') ilike ('%' || v_q || '%')
        or coalesce(l.target_id::text, '') ilike ('%' || v_q || '%')
        or coalesce(l.actor_id::text, '') ilike ('%' || v_q || '%')
        or coalesce(l.meta::text, '') ilike ('%' || v_q || '%')
      )
  ),
  base as (
    select
      n.id,
      n.created_at,
      n.actor_id,
      n.actor_role,
      n.action,
      n.canonical_target_type as target_type,
      n.target_id,
      n.before_data,
      n.after_data,
      n.ip,
      n.user_agent,
      n.meta,
      case
        when n.canonical_target_type = 'business' then n.target_id
        when n.canonical_target_type = 'menu' then coalesce(
          nullif(n.after_data ->> 'business_id', '')::uuid,
          nullif(n.before_data ->> 'business_id', '')::uuid,
          nullif(n.meta ->> 'business_id', '')::uuid,
          (select m.business_id from public.menus m where m.id = n.target_id)
        )
        when n.canonical_target_type = 'menu_item' then coalesce(
          nullif(n.after_data ->> 'business_id', '')::uuid,
          nullif(n.before_data ->> 'business_id', '')::uuid,
          nullif(n.meta ->> 'business_id', '')::uuid,
          (select mi.business_id from public.menu_items mi where mi.id = n.target_id)
        )
        when n.canonical_target_type = 'owner_claim' then coalesce(
          nullif(n.after_data ->> 'business_id', '')::uuid,
          nullif(n.before_data ->> 'business_id', '')::uuid,
          nullif(n.meta ->> 'business_id', '')::uuid,
          (select oc.business_id from public.owner_claims oc where oc.id = n.target_id)
        )
        when n.canonical_target_type = 'report' then coalesce(
          nullif(n.after_data ->> 'business_id', '')::uuid,
          nullif(n.before_data ->> 'business_id', '')::uuid,
          nullif(n.meta ->> 'business_id', '')::uuid,
          (select r.business_id from public.reports r where r.id = n.target_id)
        )
        when n.canonical_target_type = 'team_member' then coalesce(
          nullif(n.after_data ->> 'business_id', '')::uuid,
          nullif(n.before_data ->> 'business_id', '')::uuid,
          nullif(n.meta ->> 'business_id', '')::uuid,
          (select btm.business_id from public.business_team_memberships btm where btm.id = n.target_id)
        )
        when n.canonical_target_type = 'price_suggestion' then coalesce(
          nullif(n.after_data ->> 'business_id', '')::uuid,
          nullif(n.before_data ->> 'business_id', '')::uuid,
          nullif(n.meta ->> 'business_id', '')::uuid,
          (select s.business_id from public.menu_item_price_suggestions s where s.id = n.target_id)
        )
        else null::uuid
      end as resolved_business_id
    from normalized n
  )
  select
    b.id,
    b.created_at,
    b.actor_id,
    b.actor_role,
    b.action,
    b.target_type,
    b.target_id,
    b.before_data,
    b.after_data,
    b.ip,
    b.user_agent,
    b.meta
  from base b
  where
    (p_business_id is null or b.resolved_business_id = p_business_id)
    and (
      v_is_admin
      or b.resolved_business_id in (select ob.business_id from owner_businesses ob)
      or (
        b.target_type = 'owner_claim'
        and exists (
          select 1
          from public.owner_claims oc
          where oc.id = b.target_id
            and oc.user_id = v_uid
        )
      )
    )
  order by b.created_at desc
  limit p_limit
  offset p_offset;
end;
$$;


