CREATE OR REPLACE FUNCTION "public"."list_owner_analytics_v1"("p_business_id" "uuid", "p_days" integer DEFAULT 30, "p_compare_branches" boolean DEFAULT false) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_days integer := greatest(1, least(coalesce(p_days, 30), 365));
  v_since timestamptz := now() - make_interval(days => v_days);
  v_chain_id uuid;
  v_summary jsonb;
  v_daily jsonb;
  v_top_items jsonb;
  v_top_categories jsonb;
  v_source_breakdown jsonb;
  v_branch_compare jsonb := '[]'::jsonb;
begin
  if p_business_id is null then
    raise exception 'missing_business_id';
  end if;

  if not (public.is_admin() or public.has_business_permission_v1(p_business_id, 'business_read')) then
    raise exception 'forbidden';
  end if;

  select b.chain_id
  into v_chain_id
  from public.businesses b
  where b.id = p_business_id;

  with scoped_events as (
    select e.*
    from public.analytics_events e
    where e.business_id = p_business_id
      and e.created_at >= v_since
  )
  select jsonb_build_object(
    'qr_scans', count(*) filter (where event_name = 'qr_scanned'),
    'menu_opens', count(*) filter (where event_name = 'menu_link_opened'),
    'category_views', count(*) filter (
      where event_name = 'menu_view'
        and coalesce(
          nullif(trim(e.meta->>'category_name'), ''),
          nullif(trim(mi.catalog_category_name), '')
        ) is not null
    ),
    'item_clicks', count(*) filter (
      where event_name = 'menu_view'
        and coalesce(nullif(trim(e.meta->>'menu_item_id'), ''), nullif(trim(e.meta->>'menu_item_name'), '')) is not null
    ),
    'source_total', count(*) filter (where event_name in ('menu_link_opened', 'qr_scanned', 'menu_view'))
  )
  into v_summary
  from scoped_events e
  left join public.menu_items mi
    on mi.id::text = nullif(trim(e.meta->>'menu_item_id'), '');

  with daily as (
    select
      d.day::date as day,
      count(*) filter (where e.event_name = 'qr_scanned')::int as qr_scans,
      count(*) filter (where e.event_name = 'menu_link_opened')::int as menu_opens,
      count(*) filter (where e.event_name = 'menu_view')::int as menu_views,
      count(*) filter (
        where e.event_name = 'menu_view'
          and coalesce(nullif(trim(e.meta->>'menu_item_id'), ''), nullif(trim(e.meta->>'menu_item_name'), '')) is not null
      )::int as item_clicks
    from generate_series(
      (current_date - v_days + 1)::date,
      current_date::date,
      interval '1 day'
    ) as d(day)
    left join public.analytics_events e
      on e.business_id = p_business_id
     and e.created_at >= v_since
     and date_trunc('day', e.created_at) = d.day
    group by d.day
    order by d.day
  )
  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'day', to_char(day, 'YYYY-MM-DD'),
        'qr_scans', qr_scans,
        'menu_opens', menu_opens,
        'menu_views', menu_views,
        'item_clicks', item_clicks
      )
      order by day
    ),
    '[]'::jsonb
  )
  into v_daily
  from daily;

  with item_events as (
    select
      coalesce(
        nullif(trim(e.meta->>'menu_item_name'), ''),
        nullif(trim(mi.name), ''),
        e.meta->>'menu_item_id'
      ) as item_name,
      count(*)::int as total_views
    from public.analytics_events e
    left join public.menu_items mi
      on mi.id::text = nullif(trim(e.meta->>'menu_item_id'), '')
    where e.business_id = p_business_id
      and e.created_at >= v_since
      and e.event_name = 'menu_view'
      and coalesce(
        nullif(trim(e.meta->>'menu_item_name'), ''),
        nullif(trim(mi.name), ''),
        e.meta->>'menu_item_id'
      ) is not null
    group by 1
    order by total_views desc, item_name asc
    limit 10
  )
  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'label', item_name,
        'count', total_views
      )
      order by total_views desc, item_name asc
    ),
    '[]'::jsonb
  )
  into v_top_items
  from item_events;

  with category_events as (
    select
      coalesce(
        nullif(trim(e.meta->>'category_name'), ''),
        nullif(trim(mi.catalog_category_name), '')
      ) as category_name,
      count(*)::int as total_views
    from public.analytics_events e
    left join public.menu_items mi
      on mi.id::text = nullif(trim(e.meta->>'menu_item_id'), '')
    where e.business_id = p_business_id
      and e.created_at >= v_since
      and e.event_name = 'menu_view'
      and coalesce(
        nullif(trim(e.meta->>'category_name'), ''),
        nullif(trim(mi.catalog_category_name), '')
      ) is not null
    group by 1
    order by total_views desc, category_name asc
    limit 10
  )
  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'label', category_name,
        'count', total_views
      )
      order by total_views desc, category_name asc
    ),
    '[]'::jsonb
  )
  into v_top_categories
  from category_events;

  with sources as (
    select
      case
        when e.event_name = 'qr_scanned' then 'qr_short_link'
        when coalesce(nullif(trim(e.source), ''), '') = '' then 'normal'
        else trim(e.source)
      end as source_label,
      count(*)::int as total_count
    from public.analytics_events e
    where e.business_id = p_business_id
      and e.created_at >= v_since
      and e.event_name in ('menu_link_opened', 'qr_scanned', 'menu_view')
    group by 1
    order by total_count desc, source_label asc
  )
  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'label', source_label,
        'count', total_count
      )
      order by total_count desc, source_label asc
    ),
    '[]'::jsonb
  )
  into v_source_breakdown
  from sources;

  if p_compare_branches and v_chain_id is not null then
    with accessible_branches as (
      select
        b.id,
        coalesce(nullif(trim(b.branch_label), ''), nullif(trim(b.name), ''), b.id::text) as label
      from public.businesses b
      where b.chain_id = v_chain_id
        and public.has_business_permission_v1(b.id, 'business_read')
    ),
    branch_metrics as (
      select
        ab.id as business_id,
        ab.label,
        count(*) filter (where e.event_name = 'menu_link_opened')::int as menu_opens,
        count(*) filter (where e.event_name = 'qr_scanned')::int as qr_scans,
        count(*) filter (where e.event_name = 'menu_view')::int as menu_views
      from accessible_branches ab
      left join public.analytics_events e
        on e.business_id = ab.id
       and e.created_at >= v_since
      group by ab.id, ab.label
      order by menu_opens desc, qr_scans desc, ab.label asc
    )
    select coalesce(
      jsonb_agg(
        jsonb_build_object(
          'business_id', business_id,
          'label', label,
          'menu_opens', menu_opens,
          'qr_scans', qr_scans,
          'menu_views', menu_views,
          'selected', business_id = p_business_id
        )
        order by menu_opens desc, qr_scans desc, label asc
      ),
      '[]'::jsonb
    )
    into v_branch_compare
    from branch_metrics;
  end if;

  return jsonb_build_object(
    'summary', coalesce(v_summary, '{}'::jsonb),
    'daily', coalesce(v_daily, '[]'::jsonb),
    'top_items', coalesce(v_top_items, '[]'::jsonb),
    'top_categories', coalesce(v_top_categories, '[]'::jsonb),
    'source_breakdown', coalesce(v_source_breakdown, '[]'::jsonb),
    'branch_compare', coalesce(v_branch_compare, '[]'::jsonb)
  );
end;
$$;


ALTER FUNCTION "public"."list_owner_analytics_v1"("p_business_id" "uuid", "p_days" integer, "p_compare_branches" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."list_owner_menu_trash_v1"("p_business_id" "uuid") RETURNS TABLE("entity_type" "text", "entity_id" "uuid", "title" "text", "subtitle" "text", "occurred_at" timestamp with time zone, "menu_id" "uuid", "menu_item_id" "uuid", "photo_url" "text")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  with permission_check as (
    select
      public.is_admin() as is_admin,
      public.has_business_permission_v1(p_business_id, 'business_read') as can_read
  )
  select *
  from (
    select
      'menu'::text as entity_type,
      m.id as entity_id,
      m.title,
      'Menü'::text as subtitle,
      coalesce(m.updated_at, m.created_at) as occurred_at,
      m.id as menu_id,
      null::uuid as menu_item_id,
      null::text as photo_url
    from public.menus m, permission_check pc
    where m.business_id = p_business_id
      and m.status = 'archived'
      and (pc.is_admin or pc.can_read)

    union all

    select
      'item'::text as entity_type,
      i.id as entity_id,
      i.name as title,
      coalesce(ms.title, 'Bölüm') || ' • ' || coalesce(m.title, 'Menü') as subtitle,
      coalesce(i.updated_at, i.created_at) as occurred_at,
      ms.menu_id as menu_id,
      i.id as menu_item_id,
      null::text as photo_url
    from public.menu_items i
    join public.menu_sections ms on ms.id = i.section_id
    join public.menus m on m.id = ms.menu_id,
    permission_check pc
    where i.business_id = p_business_id
      and i.is_available = false
      and (pc.is_admin or pc.can_read)

    union all

    select
      'photo'::text as entity_type,
      p.id as entity_id,
      coalesce(mi.name, 'Ürün fotoğrafı') as title,
      'Fotoğraf'::text as subtitle,
      p.deleted_at as occurred_at,
      ms.menu_id as menu_id,
      p.menu_item_id,
      coalesce(nullif(p.url_thumb, ''), nullif(p.url_large, ''), p.url) as photo_url
    from public.menu_item_photos p
    join public.menu_items mi on mi.id = p.menu_item_id
    join public.menu_sections ms on ms.id = mi.section_id,
    permission_check pc
    where p.business_id = p_business_id
      and p.deleted_at is not null
      and (pc.is_admin or pc.can_read)
  ) rows
  order by occurred_at desc nulls last;
$$;


ALTER FUNCTION "public"."list_owner_menu_trash_v1"("p_business_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."list_owner_menu_versions_v1"("p_menu_id" "uuid") RETURNS TABLE("snapshot_id" "uuid", "menu_id" "uuid", "menu_version" integer, "snapshot_reason" "text", "created_at" timestamp with time zone, "section_count" integer, "item_count" integer)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  select
    s.id as snapshot_id,
    s.source_menu_id as menu_id,
    s.menu_version,
    s.snapshot_reason,
    s.created_at,
    jsonb_array_length(coalesce(s.snapshot_json->'sections', '[]'::jsonb))::int as section_count,
    coalesce(
      (
        select sum(jsonb_array_length(coalesce(section_row->'items', '[]'::jsonb)))::int
        from jsonb_array_elements(coalesce(s.snapshot_json->'sections', '[]'::jsonb)) section_row
      ),
      0
    ) as item_count
  from public.menu_snapshots s
  join public.menus m on m.id = s.source_menu_id
  where s.source_menu_id = p_menu_id
    and (
      public.is_admin()
      or public.has_business_permission_v1(m.business_id, 'business_read')
    )
  order by s.created_at desc;
$$;


ALTER FUNCTION "public"."list_owner_menu_versions_v1"("p_menu_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."list_team_members_v1"("p_business_id" "uuid") RETURNS TABLE("membership_id" "uuid", "user_id" "uuid", "email" "text", "role" "text", "scope" "text", "status" "text", "source" "text", "created_at" timestamp with time zone, "accepted_at" timestamp with time zone)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  with target_business as (
    select b.id, b.chain_id
    from public.businesses b
    where b.id = p_business_id
  )
  select *
  from (
    select
      null::uuid as membership_id,
      oc.user_id,
      lower(u.email::text) as email,
      'owner'::text as role,
      'this_business'::text as scope,
      'active'::text as status,
      'owner_claim'::text as source,
      oc.created_at,
      oc.reviewed_at as accepted_at
    from public.owner_claims oc
    join target_business tb on tb.id = oc.business_id
    left join auth.users u on u.id = oc.user_id
    where oc.status = 'approved'

    union all

    select
      null::uuid as membership_id,
      cm.user_id,
      lower(u.email::text) as email,
      cm.role,
      'all_branches'::text as scope,
      'active'::text as status,
      'chain_membership'::text as source,
      cm.created_at,
      cm.created_at as accepted_at
    from public.chain_memberships cm
    join target_business tb on tb.chain_id = cm.chain_id
    left join auth.users u on u.id = cm.user_id

    union all

    select
      btm.id as membership_id,
      btm.user_id,
      lower(coalesce(u.email::text, btm.invite_email)) as email,
      btm.role,
      case when btm.chain_id is not null then 'all_branches' else 'this_business' end as scope,
      case when btm.user_id is null then 'pending' else 'active' end as status,
      'team_membership'::text as source,
      btm.created_at,
      btm.accepted_at
    from public.business_team_memberships btm
    join target_business tb
      on (
        btm.business_id = tb.id
        or (btm.chain_id is not null and btm.chain_id = tb.chain_id)
      )
    left join auth.users u on u.id = btm.user_id
    where btm.revoked_at is null
  ) x
  where public.has_business_permission_v1(p_business_id, 'team_manage')
     or public.is_admin()
  order by
    case x.role
      when 'owner' then 1
      when 'manager' then 2
      when 'editor' then 3
      when 'staff' then 4
      else 5
    end,
    x.created_at asc;
$$;


ALTER FUNCTION "public"."list_team_members_v1"("p_business_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."log_admin_action_v1"("p_action" "text", "p_target_table" "text", "p_target_id" "uuid", "p_meta" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  if not public.is_admin() then
    raise exception 'not_admin';
  end if;

  perform public.insert_audit_log_v1(
    p_action,
    coalesce(nullif(p_target_table, ''), 'unknown'),
    p_target_id,
    null,
    coalesce(p_meta, '{}'::jsonb)
  );
end;
$$;


ALTER FUNCTION "public"."log_admin_action_v1"("p_action" "text", "p_target_table" "text", "p_target_id" "uuid", "p_meta" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."log_checkin_v1"("p_business_id" "uuid", "p_menu_id" "uuid" DEFAULT NULL::"uuid", "p_table_no" "text" DEFAULT NULL::"text", "p_client_id" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_client_id text := nullif(trim(coalesce(p_client_id, '')), '');
  v_table_no text := nullif(trim(coalesce(p_table_no, '')), '');
  v_exists uuid;
begin
  if p_business_id is null then
    return jsonb_build_object('ok', false, 'code', 'invalid_business');
  end if;

  if v_client_id is null then
    return jsonb_build_object('ok', false, 'code', 'client_required');
  end if;

  if not exists (
    select 1 from public.businesses b where b.id = p_business_id
  ) then
    return jsonb_build_object('ok', false, 'code', 'business_not_found');
  end if;

  if p_menu_id is not null and not exists (
    select 1 from public.menus m where m.id = p_menu_id and m.business_id = p_business_id
  ) then
    return jsonb_build_object('ok', false, 'code', 'menu_mismatch');
  end if;

  select c.id into v_exists
  from public.business_checkins c
  where c.business_id = p_business_id
    and c.client_id = v_client_id
    and coalesce(c.table_no, '') = coalesce(v_table_no, '')
    and c.created_at >= now() - interval '10 minutes'
  limit 1;

  if v_exists is not null then
    return jsonb_build_object('ok', true, 'deduped', true, 'id', v_exists);
  end if;

  insert into public.business_checkins(
    business_id,
    menu_id,
    table_no,
    client_id,
    user_id
  )
  values (
    p_business_id,
    p_menu_id,
    v_table_no,
    v_client_id,
    auth.uid()
  )
  returning id into v_exists;

  return jsonb_build_object('ok', true, 'id', v_exists);
end;
$$;


ALTER FUNCTION "public"."log_checkin_v1"("p_business_id" "uuid", "p_menu_id" "uuid", "p_table_no" "text", "p_client_id" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."log_event_v1"("p_event_name" "text", "p_business_id" "uuid" DEFAULT NULL::"uuid", "p_menu_id" "uuid" DEFAULT NULL::"uuid", "p_source" "text" DEFAULT NULL::"text", "p_client_id" "text" DEFAULT NULL::"text", "p_meta" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_event_name text := coalesce(trim(p_event_name), '');
  v_client text := nullif(trim(p_client_id), '');
  v_key text;
  v_today date := current_date;
  v_current_count int;
  v_user_id uuid := coalesce(auth.uid(), '00000000-0000-0000-0000-000000000000'::uuid);
begin
  if v_event_name not in (
    'menu_shared',
    'qr_scanned',
    'menu_link_opened',
    'app_install_from_menu',
    'business_reservation_click',
    'business_phone_click',
    'business_whatsapp_click',
    'business_order_click',
    'business_directions_click',
    'business_page_view',
    'menu_view',
    'discovery_impression',
    'discovery_business_click',
    'business_impression',
    'price_suggestion_submitted'
  ) then
    return jsonb_build_object('ok', false, 'code', 'invalid_event');
  end if;

  if v_event_name = 'menu_link_opened' and v_client is null then
    return jsonb_build_object('ok', false, 'code', 'client_required');
  end if;

  if v_event_name = 'menu_link_opened' then
    v_key := format('menu_link_opened:%s:%s', v_client, v_today::text);
    select count into v_current_count
    from public.user_rate_limits
    where key = v_key;

    if coalesce(v_current_count, 0) >= 200 then
      return jsonb_build_object('ok', false, 'code', 'rate_limited');
    end if;

    insert into public.user_rate_limits (key, user_id, action, day, count, updated_at)
    values (v_key, v_user_id, 'menu_link_opened', v_today, 1, now())
    on conflict (key) do update
      set count = public.user_rate_limits.count + 1,
          updated_at = now();
  end if;

  insert into public.analytics_events (
    event_name,
    business_id,
    menu_id,
    source,
    client_id,
    user_id,
    meta
  )
  values (
    v_event_name,
    p_business_id,
    p_menu_id,
    nullif(trim(p_source), ''),
    v_client,
    v_user_id,
    coalesce(p_meta, '{}'::jsonb)
  );

  return jsonb_build_object('ok', true);
end;
$$;


ALTER FUNCTION "public"."log_event_v1"("p_event_name" "text", "p_business_id" "uuid", "p_menu_id" "uuid", "p_source" "text", "p_client_id" "text", "p_meta" "jsonb") OWNER TO "postgres";


