CREATE OR REPLACE FUNCTION "public"."mark_expired_temp_uploads_v1"("p_limit" integer DEFAULT 500) RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_count int := 0;
begin
  with target as (
    select
      t.id,
      t.storage_bucket,
      t.storage_path
    from public.temp_uploads t
    where t.status in ('pending', 'rejected')
      and t.expires_at < now()
    order by t.expires_at asc
    limit greatest(coalesce(p_limit, 500), 1)
  ),
  updated as (
    update public.temp_uploads t
    set
      status = 'expired',
      reviewed_at = coalesce(t.reviewed_at, now())
    where t.id in (select id from target)
    returning t.id
  ),
  queued as (
    insert into public.storage_deletion_queue (bucket, path, reason)
    select
      coalesce(nullif(target.storage_bucket, ''), 'temp'),
      target.storage_path,
      'ttl_cleanup'
    from target
    join updated on updated.id = target.id
    where coalesce(target.storage_path, '') <> ''
    on conflict do nothing
    returning id
  )
  select count(*) into v_count
  from updated;

  return v_count;
end;
$$;


ALTER FUNCTION "public"."mark_expired_temp_uploads_v1"("p_limit" integer) OWNER TO "postgres";


