CREATE OR REPLACE FUNCTION "public"."mask_contact_tokens_v1"("p_text" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    AS $$
  select trim(
    regexp_replace(
      regexp_replace(
        regexp_replace(
          coalesce(p_text, ''),
          '(https?://[^\s]+|www\.[^\s]+|t\.me/[^\s]+|wa\.me/[^\s]+|instagram\.com/[^\s]*)',
          '[gizlendi]',
          'gi'
        ),
        '([A-Z0-9._%+\-]+@[A-Z0-9.\-]+\.[A-Z]{2,})',
        '[gizlendi]',
        'gi'
      ),
      '(\+?\d[\d\s\-\(\)]{7,}\d)',
      '[gizlendi]',
      'g'
    )
  );
$$;


ALTER FUNCTION "public"."mask_contact_tokens_v1"("p_text" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."menu_items_assign_section_v1"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
declare
  v_section_business_id uuid;
begin
  if new.section_id is null then
    new.section_id := public.ensure_default_section_for_business_v1(new.business_id);
  end if;

  select m.business_id
    into v_section_business_id
  from public.menu_sections s
  join public.menus m on m.id = s.menu_id
  where s.id = new.section_id
  limit 1;

  if v_section_business_id is null then
    raise exception 'invalid_section_id';
  end if;

  if v_section_business_id <> new.business_id then
    raise exception 'section_business_mismatch';
  end if;

  return new;
end;
$$;


ALTER FUNCTION "public"."menu_items_assign_section_v1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."normalize_for_moderation_v1"("p_text" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    AS $_$
  select regexp_replace(
    replace(
      replace(
        replace(
          replace(
            replace(
              replace(
                replace(
                  replace(
                    replace(
                      replace(
                        translate(lower(coalesce(p_text, '')), 'çğıöşü', 'cgiosu'),
                        '@',
                        'a'
                      ),
                      '4',
                      'a'
                    ),
                    '0',
                    'o'
                  ),
                  '1',
                  'i'
                ),
                '!',
                'i'
              ),
              '$',
              's'
            ),
            '5',
            's'
          ),
          '3',
          'e'
        ),
        '.',
        ''
      ),
      '_',
      ''
    ),
    '[^a-z0-9]+',
    ' ',
    'g'
  );
$_$;


ALTER FUNCTION "public"."normalize_for_moderation_v1"("p_text" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."normalize_tr_text"("p" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO 'public'
    AS $$
  select trim(
    regexp_replace(
      regexp_replace(
        translate(lower(coalesce(p,'')),
          'çğıöşüİÇĞÖŞÜ',
          'cgiosuicgiosu'
        ),
        '[^a-z0-9]+', ' ', 'g'
      ),
      '\s+', ' ', 'g'
    )
  );
$$;


