CREATE OR REPLACE FUNCTION "public"."owner_approve_suspended_claim_v1"("p_claim_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_meal_id uuid;
  v_business_id uuid;
  v_meal_status public.suspended_meal_status;
  v_code text;
begin
  if auth.uid() is null then
    return jsonb_build_object('ok', false, 'error', 'not_authenticated');
  end if;

  select m.id, m.business_id into v_meal_id, v_business_id
  from public.suspended_meal_claims c
  join public.suspended_meals m on m.id = c.suspended_meal_id
  where c.id = p_claim_id and c.status='pending';

  if v_meal_id is null then
    return jsonb_build_object('ok', false, 'error', 'not_found_or_not_pending');
  end if;

  if not public.is_owner_of_business(v_business_id) and not public.is_admin() then
    return jsonb_build_object('ok', false, 'error', 'not_owner');
  end if;

  select status into v_meal_status
  from public.suspended_meals
  where id = v_meal_id;

  if v_meal_status <> 'active' then
    return jsonb_build_object('ok', false, 'error', 'meal_not_active');
  end if;

  -- 6 haneli code
  v_code := lpad((floor(random()*1000000))::int::text, 6, '0');

  update public.suspended_meal_claims
  set status='approved',
      verify_code=v_code,
      handled_by=auth.uid(),
      handled_at=now()
  where id = p_claim_id;

  update public.suspended_meals
  set status='claimed'
  where id = v_meal_id;

  return jsonb_build_object('ok', true, 'verify_code', v_code);
end;
$$;


ALTER FUNCTION "public"."owner_approve_suspended_claim_v1"("p_claim_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."owner_archive_menu_item_v1"("p_item_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_business_id uuid;
  v_section_id uuid;
begin
  if auth.uid() is null then
    return jsonb_build_object('ok', false, 'code', 'not_authenticated', 'message', 'Auth required');
  end if;

  select business_id, section_id into v_business_id, v_section_id
  from public.menu_items
  where id = p_item_id;

  if v_business_id is null then
    return jsonb_build_object('ok', false, 'code', 'not_found', 'message', 'Item not found');
  end if;

  if not (public.is_admin() or public.is_owner_of_business(v_business_id)) then
    return jsonb_build_object('ok', false, 'code', 'not_owner', 'message', 'Not owner');
  end if;

  update public.menu_items
  set is_available = false,
      updated_at = now()
  where id = p_item_id;

  if public.is_admin() then
    insert into public.admin_audit_log(action, target_table, target_id, meta)
    values (
      'menu_item.archive',
      'menu_items',
      p_item_id,
      jsonb_build_object('section_id', v_section_id)
    );
  end if;

  return jsonb_build_object('ok', true, 'id', p_item_id, 'message', 'Archived');
end;
$$;


ALTER FUNCTION "public"."owner_archive_menu_item_v1"("p_item_id" "uuid") OWNER TO "postgres";


