CREATE OR REPLACE FUNCTION "public"."owner_create_menu_item_v1"("p_section_id" "uuid", "p_name" "text", "p_description" "text" DEFAULT NULL::"text", "p_price_cents" integer DEFAULT NULL::integer, "p_currency" "text" DEFAULT 'TRY'::"text", "p_catalog_item_id" bigint DEFAULT NULL::bigint) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_name text;
  v_desc text;
  v_currency text;
  v_item_id uuid;
  v_business_id uuid;
  v_menu_id uuid;
begin
  if auth.uid() is null then
    return jsonb_build_object('ok', false, 'code', 'not_authenticated', 'message', 'Auth required');
  end if;

  select m.business_id, m.id into v_business_id, v_menu_id
  from public.menu_sections s
  join public.menus m on m.id = s.menu_id
  where s.id = p_section_id;

  if v_business_id is null then
    return jsonb_build_object('ok', false, 'code', 'not_found', 'message', 'Section not found');
  end if;

  if not (public.is_admin() or public.is_owner_of_business(v_business_id)) then
    return jsonb_build_object('ok', false, 'code', 'not_owner', 'message', 'Not owner');
  end if;

  v_name := nullif(trim(p_name), '');
  if v_name is null then
    return jsonb_build_object('ok', false, 'code', 'invalid', 'message', 'Name required');
  end if;

  if p_price_cents is not null and p_price_cents < 0 then
    return jsonb_build_object('ok', false, 'code', 'invalid', 'message', 'Invalid price');
  end if;

  v_desc := nullif(trim(p_description), '');
  v_currency := nullif(trim(p_currency), '');
  if v_currency is null then
    return jsonb_build_object('ok', false, 'code', 'invalid', 'message', 'Currency required');
  end if;

  insert into public.menu_items(
    section_id,
    business_id,
    name,
    description,
    price_cents,
    currency,
    is_available,
    tags,
    sort_order
  )
  values (
    p_section_id,
    v_business_id,
    v_name,
    v_desc,
    p_price_cents,
    v_currency,
    false,
    '[]'::jsonb,
    0
  )
  returning id into v_item_id;

  if public.is_admin() then
    insert into public.admin_audit_log(action, target_table, target_id, meta)
    values (
      'menu_item.create',
      'menu_items',
      v_item_id,
      jsonb_build_object('menu_id', v_menu_id, 'section_id', p_section_id)
    );
  end if;

  return jsonb_build_object('ok', true, 'id', v_item_id, 'message', 'Created');
end;
$$;


ALTER FUNCTION "public"."owner_create_menu_item_v1"("p_section_id" "uuid", "p_name" "text", "p_description" "text", "p_price_cents" integer, "p_currency" "text", "p_catalog_item_id" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."owner_create_menu_section_v1"("p_menu_id" "uuid", "p_title" "text", "p_sort_order" integer DEFAULT NULL::integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_title text;
  v_sort integer;
  v_section_id uuid;
  v_business_id uuid;
begin
  if auth.uid() is null then
    return jsonb_build_object('ok', false, 'code', 'not_authenticated', 'message', 'Auth required');
  end if;

  select business_id into v_business_id
  from public.menus
  where id = p_menu_id;

  if v_business_id is null then
    return jsonb_build_object('ok', false, 'code', 'not_found', 'message', 'Menu not found');
  end if;

  if not (public.is_admin() or public.is_owner_of_business(v_business_id)) then
    return jsonb_build_object('ok', false, 'code', 'not_owner', 'message', 'Not owner');
  end if;

  v_title := nullif(trim(p_title), '');
  if v_title is null then
    return jsonb_build_object('ok', false, 'code', 'invalid', 'message', 'Title required');
  end if;

  if p_sort_order is null then
    select coalesce(max(sort_order), 0) + 1 into v_sort
    from public.menu_sections
    where menu_id = p_menu_id;
  else
    v_sort := p_sort_order;
  end if;

  insert into public.menu_sections(menu_id, title, sort_order, created_by)
  values (p_menu_id, v_title, v_sort, auth.uid())
  returning id into v_section_id;

  if public.is_admin() then
    insert into public.admin_audit_log(action, target_table, target_id, meta)
    values ('menu_section.create', 'menu_sections', v_section_id, jsonb_build_object('menu_id', p_menu_id));
  end if;

  return jsonb_build_object('ok', true, 'id', v_section_id, 'message', 'Created');
end;
$$;


ALTER FUNCTION "public"."owner_create_menu_section_v1"("p_menu_id" "uuid", "p_title" "text", "p_sort_order" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."owner_create_menu_v1"("p_business_id" "uuid", "p_title" "text", "p_kind" "text" DEFAULT NULL::"text", "p_active_from" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_active_to" timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_title text;
  v_kind text;
  v_menu_id uuid;
begin
  if auth.uid() is null then
    return jsonb_build_object('ok', false, 'code', 'not_authenticated', 'message', 'Auth required');
  end if;

  if not (public.is_admin() or public.is_owner_of_business(p_business_id)) then
    return jsonb_build_object('ok', false, 'code', 'not_owner', 'message', 'Not owner');
  end if;

  v_title := nullif(trim(p_title), '');
  if v_title is null then
    return jsonb_build_object('ok', false, 'code', 'invalid', 'message', 'Title required');
  end if;

  if p_active_from is not null and p_active_to is not null and p_active_from > p_active_to then
    return jsonb_build_object('ok', false, 'code', 'invalid', 'message', 'Invalid active range');
  end if;

  v_kind := nullif(trim(p_kind), '');

  insert into public.menus(
    business_id, title, kind, status, created_by, active_from, active_to
  )
  values (
    p_business_id, v_title, v_kind, 'draft', auth.uid(), p_active_from, p_active_to
  )
  returning id into v_menu_id;

  if public.is_admin() then
    insert into public.admin_audit_log(action, target_table, target_id, meta)
    values ('menu.create', 'menus', v_menu_id, jsonb_build_object('business_id', p_business_id));
  end if;

  return jsonb_build_object('ok', true, 'id', v_menu_id, 'message', 'Created');
end;
$$;


ALTER FUNCTION "public"."owner_create_menu_v1"("p_business_id" "uuid", "p_title" "text", "p_kind" "text", "p_active_from" timestamp with time zone, "p_active_to" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."owner_create_perk_v1"("p_business_id" "uuid", "p_title" "text", "p_description" "text" DEFAULT NULL::"text", "p_starts_at" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_ends_at" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_requires_checkin" boolean DEFAULT true) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_title text;
  v_id uuid;
begin
  if auth.uid() is null then
    return jsonb_build_object('ok', false, 'code', 'not_authenticated');
  end if;

  if not (public.is_admin() or public.is_owner_of_business(p_business_id)) then
    return jsonb_build_object('ok', false, 'code', 'not_owner');
  end if;

  v_title := nullif(trim(p_title), '');
  if v_title is null then
    return jsonb_build_object('ok', false, 'code', 'invalid', 'message', 'Title required');
  end if;

  if p_starts_at is not null and p_ends_at is not null and p_starts_at > p_ends_at then
    return jsonb_build_object('ok', false, 'code', 'invalid', 'message', 'Invalid date range');
  end if;

  insert into public.business_perks(
    business_id,
    title,
    description,
    starts_at,
    ends_at,
    requires_checkin,
    status,
    created_by
  ) values (
    p_business_id,
    v_title,
    nullif(trim(p_description), ''),
    p_starts_at,
    p_ends_at,
    coalesce(p_requires_checkin, true),
    'active',
    auth.uid()
  ) returning id into v_id;

  return jsonb_build_object('ok', true, 'id', v_id);
end;
$$;


