CREATE OR REPLACE FUNCTION "public"."owner_fulfill_suspended_claim_v1"("p_claim_id" "uuid", "p_code" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_business_id uuid;
  v_code text;
begin
  select m.business_id, c.verify_code into v_business_id, v_code
  from public.suspended_meal_claims c
  join public.suspended_meals m on m.id = c.suspended_meal_id
  where c.id = p_claim_id and c.status='approved';

  if v_business_id is null then
    return jsonb_build_object('ok', false, 'error', 'not_found_or_not_approved');
  end if;

  if not public.is_owner_of_business(v_business_id) and not public.is_admin() then
    return jsonb_build_object('ok', false, 'error', 'not_owner');
  end if;

  if v_code is null or v_code <> p_code then
    return jsonb_build_object('ok', false, 'error', 'bad_code');
  end if;

  update public.suspended_meal_claims
  set status='fulfilled',
      fulfilled_at=now(),
      verify_code=null
  where id = p_claim_id;

  return jsonb_build_object('ok', true);
end;
$$;


ALTER FUNCTION "public"."owner_fulfill_suspended_claim_v1"("p_claim_id" "uuid", "p_code" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."owner_get_sponsorship_catalog_v1"("p_business_id" "uuid") RETURNS TABLE("package_id" "uuid", "package_name" "text", "surface" "text", "duration_days" integer, "price_display" "text", "price_cents" integer, "currency_code" "text", "inventory_limit" integer, "surface_live_units" integer, "surface_open_slots" integer, "business_live_units" integer, "business_impressions_30d" integer, "business_unique_users_30d" integer, "latest_lead_status" "text")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  with access_cte as (
    select (public.is_admin() or public.is_owner_of_business(p_business_id)) as ok
  ),
  live_sponsorship_units as (
    select
      s.surface::text as surface,
      count(*)::int as live_units
    from public.sponsorships s
    where s.status = 'active'
      and (s.starts_at is null or s.starts_at <= now())
      and (s.ends_at is null or s.ends_at >= now())
    group by s.surface
  ),
  live_premium_units as (
    select
      bp.tier::text as surface,
      count(*)::int as live_units
    from public.business_premium bp
    where bp.status = 'active'
      and (bp.ends_at is null or bp.ends_at >= now())
    group by bp.tier
  ),
  surface_live_units_cte as (
    select
      surface,
      sum(live_units)::int as live_units
    from (
      select surface, live_units from live_sponsorship_units
      union all
      select surface, live_units from live_premium_units
    ) combined
    group by surface
  ),
  business_sponsorship_units as (
    select
      s.surface::text as surface,
      count(*)::int as business_live_units
    from public.sponsorships s
    where s.business_id = p_business_id
      and s.status = 'active'
      and (s.starts_at is null or s.starts_at <= now())
      and (s.ends_at is null or s.ends_at >= now())
    group by s.surface
  ),
  business_premium_units as (
    select
      bp.tier::text as surface,
      count(*)::int as business_live_units
    from public.business_premium bp
    where bp.business_id = p_business_id
      and bp.status = 'active'
      and (bp.ends_at is null or bp.ends_at >= now())
    group by bp.tier
  ),
  business_live_units_cte as (
    select
      surface,
      sum(business_live_units)::int as business_live_units
    from (
      select surface, business_live_units from business_sponsorship_units
      union all
      select surface, business_live_units from business_premium_units
    ) combined
    group by surface
  ),
  business_perf_cte as (
    select
      s.surface::text as surface,
      coalesce(sum(i.impressions_count), 0)::int as business_impressions_30d,
      coalesce(sum(i.unique_users_count), 0)::int as business_unique_users_30d
    from public.sponsorships s
    left join public.sponsorship_impressions_daily i
      on i.sponsorship_id = s.id
     and i.day >= current_date - 29
    where s.business_id = p_business_id
      and s.status = 'active'
      and (s.starts_at is null or s.starts_at <= now())
      and (s.ends_at is null or s.ends_at >= now())
    group by s.surface
  ),
  latest_lead_cte as (
    select distinct on (l.preferred_surface)
      l.preferred_surface::text as surface,
      l.status::text as latest_lead_status
    from public.sponsorship_leads l
    where l.business_id = p_business_id
    order by l.preferred_surface, l.created_at desc
  )
  select
    p.id as package_id,
    p.name as package_name,
    p.surface::text,
    p.duration_days,
    p.price_display,
    p.price_cents,
    p.currency_code,
    p.inventory_limit,
    coalesce(surface_live_units_cte.live_units, 0) as surface_live_units,
    greatest(
      p.inventory_limit - coalesce(surface_live_units_cte.live_units, 0),
      0
    )::int as surface_open_slots,
    coalesce(business_live_units_cte.business_live_units, 0) as business_live_units,
    coalesce(business_perf_cte.business_impressions_30d, 0) as business_impressions_30d,
    coalesce(business_perf_cte.business_unique_users_30d, 0) as business_unique_users_30d,
    latest_lead_cte.latest_lead_status
  from public.sponsorship_packages p
  cross join access_cte
  left join surface_live_units_cte on surface_live_units_cte.surface = p.surface
  left join business_live_units_cte on business_live_units_cte.surface = p.surface
  left join business_perf_cte on business_perf_cte.surface = p.surface
  left join latest_lead_cte on latest_lead_cte.surface = p.surface
  where access_cte.ok
    and p.is_active = true
  order by
    case p.surface
      when 'discovery' then 1
      when 'business_page' then 2
      when 'stories' then 3
      when 'verified' then 4
      when 'premium' then 5
      else 99
    end,
    p.price_cents,
    p.duration_days,
    p.name;
$$;


ALTER FUNCTION "public"."owner_get_sponsorship_catalog_v1"("p_business_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."owner_kpi_summary_v1"("p_business_id" "uuid", "p_days" integer DEFAULT 30) RETURNS TABLE("business_views" integer, "outbound_clicks" integer, "directions_clicks" integer, "search_impressions" integer)
    LANGUAGE "sql"
    SET "search_path" TO 'public', 'extensions'
    AS $$
with events as (
  select *
  from public.analytics_events
  where business_id = p_business_id
    and created_at >= now() - (p_days::text || ' days')::interval
)
select
  (select count(*) from events where event_name = 'business_page_view')::int as business_views,
  (select count(*) from events where event_name in (
      'business_reservation_click',
      'business_phone_click',
      'business_whatsapp_click',
      'business_order_click'
    ))::int as outbound_clicks,
  (select count(*) from events where event_name = 'business_directions_click')::int as directions_clicks,
  (select count(*) from events where event_name = 'business_impression')::int as search_impressions;
$$;


ALTER FUNCTION "public"."owner_kpi_summary_v1"("p_business_id" "uuid", "p_days" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."owner_list_accessible_businesses_v1"("p_limit" integer DEFAULT 50, "p_offset" integer DEFAULT 0, "p_actor_user_id" "uuid" DEFAULT NULL::"uuid", "p_role_override" "text" DEFAULT NULL::"text") RETURNS TABLE("business_id" "uuid", "business_name" "text", "city" "text", "district" "text", "claim_status" "text", "claimed_at" timestamp with time zone, "chain_id" "uuid", "chain_name" "text", "branch_label" "text", "owner_role" "text")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  with accessible as (
    select
      b.id as business_id,
      b.name as business_name,
      coalesce(b.city, '') as city,
      coalesce(b.district, '') as district,
      case
        when exists (
          select 1
          from public.owner_claims oc
          where oc.business_id = b.id
            and oc.user_id = coalesce(p_actor_user_id, auth.uid())
            and oc.status = 'approved'
        ) then 'approved'
        else 'team_access'
      end as claim_status,
      coalesce(
        (
          select min(oc.created_at)
          from public.owner_claims oc
          where oc.business_id = b.id
            and oc.user_id = coalesce(p_actor_user_id, auth.uid())
            and oc.status = 'approved'
        ),
        (
          select min(cm.created_at)
          from public.chain_memberships cm
          where cm.chain_id = b.chain_id
            and cm.user_id = coalesce(p_actor_user_id, auth.uid())
        ),
        (
          select min(btm.created_at)
          from public.business_team_memberships btm
          where btm.revoked_at is null
            and btm.user_id = coalesce(p_actor_user_id, auth.uid())
            and (
              btm.business_id = b.id
              or (btm.chain_id is not null and btm.chain_id = b.chain_id)
            )
        ),
        b.created_at
      ) as claimed_at,
      b.chain_id,
      ch.name as chain_name,
      coalesce(b.branch_label, '') as branch_label,
      public.get_business_role_v1(b.id, p_actor_user_id, p_role_override) as owner_role
    from public.businesses b
    left join public.chains ch on ch.id = b.chain_id
    where public.get_business_role_v1(b.id, p_actor_user_id, p_role_override) is not null
  )
  select *
  from accessible
  order by claimed_at desc, business_name asc
  limit greatest(p_limit, 1)
  offset greatest(p_offset, 0);
$$;


ALTER FUNCTION "public"."owner_list_accessible_businesses_v1"("p_limit" integer, "p_offset" integer, "p_actor_user_id" "uuid", "p_role_override" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."owner_list_menu_price_suggestions_v1"("p_business_id" "uuid", "p_status" "text" DEFAULT 'pending'::"text", "p_limit" integer DEFAULT 30, "p_offset" integer DEFAULT 0) RETURNS TABLE("suggestion_id" "uuid", "status" "text", "created_at" timestamp with time zone, "menu_item_id" "uuid", "item_name" "text", "current_price_cents" integer, "suggested_price_cents" integer, "currency" "text", "created_by" "uuid")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  select
    s.id as suggestion_id,
    s.status::text,
    s.created_at,
    mi.id as menu_item_id,
    mi.name as item_name,
    mi.price_cents as current_price_cents,
    s.suggested_price_cents,
    s.currency,
    s.created_by
  from public.menu_item_price_suggestions s
  join public.menu_items mi on mi.id = s.menu_item_id
  where s.business_id = p_business_id
    and public.is_owner_of_business(p_business_id)
    and (p_status is null or s.status::text = p_status)
    and (s.is_shadow is not true)
  order by (s.status='pending') desc, s.created_at asc
  limit greatest(p_limit,0)
  offset greatest(p_offset,0);
$$;


