CREATE OR REPLACE FUNCTION "public"."owner_list_my_business_submissions_v1"("p_status" "text" DEFAULT NULL::"text", "p_limit" integer DEFAULT 50, "p_offset" integer DEFAULT 0) RETURNS TABLE("id" "uuid", "name" "text", "city" "text", "district" "text", "category" "text", "address" "text", "phone" "text", "website" "text", "status" "text", "admin_note" "text", "created_at" timestamp with time zone)
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  select
    s.id,
    s.name,
    s.city,
    s.district,
    s.category,
    s.address,
    s.phone,
    s.website,
    s.status::text,
    s.admin_note,
    s.created_at
  from public.business_submissions s
  where s.submitted_by = auth.uid()
    and (
      p_status is null
      or p_status = ''
      or s.status::text = p_status
    )
  order by s.created_at desc
  limit greatest(p_limit, 0) offset greatest(p_offset, 0);
$$;


ALTER FUNCTION "public"."owner_list_my_business_submissions_v1"("p_status" "text", "p_limit" integer, "p_offset" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."owner_list_my_businesses_v1"("p_status" "text" DEFAULT 'approved'::"text", "p_limit" integer DEFAULT 50, "p_offset" integer DEFAULT 0) RETURNS TABLE("business_id" "uuid", "business_name" "text", "city" "text", "district" "text", "claim_status" "text", "claimed_at" timestamp with time zone)
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  select
    b.id as business_id,
    b.name as business_name,
    b.city,
    b.district,
    c.status::text as claim_status,
    c.created_at as claimed_at
  from public.owner_claims c
  join public.businesses b on b.id = c.business_id
  where c.user_id = auth.uid()
    and (
      p_status is null
      or p_status = ''
      or c.status::text = p_status
    )
  order by c.created_at desc
  limit greatest(p_limit, 0) offset greatest(p_offset, 0);
$$;


ALTER FUNCTION "public"."owner_list_my_businesses_v1"("p_status" "text", "p_limit" integer, "p_offset" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."owner_list_my_businesses_v2"("p_status" "text" DEFAULT 'approved'::"text", "p_limit" integer DEFAULT 50, "p_offset" integer DEFAULT 0) RETURNS TABLE("business_id" "uuid", "business_name" "text", "city" "text", "district" "text", "claim_status" "text", "claimed_at" timestamp with time zone, "chain_id" "uuid", "chain_name" "text", "branch_label" "text", "owner_role" "text")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  select
    b.id as business_id,
    b.name as business_name,
    coalesce(b.city, '') as city,
    coalesce(b.district, '') as district,
    c.status as claim_status,
    c.created_at as claimed_at,
    b.chain_id,
    ch.name as chain_name,
    coalesce(b.branch_label, '') as branch_label,
    coalesce(cm.role, 'owner') as owner_role
  from public.owner_claims c
  join public.businesses b on b.id = c.business_id
  left join public.chains ch on ch.id = b.chain_id
  left join public.chain_memberships cm on cm.chain_id = b.chain_id and cm.user_id = auth.uid()
  where c.user_id = auth.uid()
    and (p_status is null or c.status = p_status)
  order by c.created_at desc
  limit greatest(p_limit, 1)
  offset greatest(p_offset, 0);
$$;


ALTER FUNCTION "public"."owner_list_my_businesses_v2"("p_status" "text", "p_limit" integer, "p_offset" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."owner_list_perks_v1"("p_business_id" "uuid") RETURNS TABLE("id" "uuid", "business_id" "uuid", "title" "text", "description" "text", "starts_at" timestamp with time zone, "ends_at" timestamp with time zone, "requires_checkin" boolean, "status" "text", "created_at" timestamp with time zone)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  select
    p.id,
    p.business_id,
    p.title,
    p.description,
    p.starts_at,
    p.ends_at,
    p.requires_checkin,
    p.status,
    p.created_at
  from public.business_perks p
  where p.business_id = p_business_id
  order by p.created_at desc;
$$;


ALTER FUNCTION "public"."owner_list_perks_v1"("p_business_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."owner_list_price_suggestions_v1"("p_business_id" "uuid", "p_status" "text", "p_limit" integer, "p_offset" integer) RETURNS TABLE("suggestion_id" "uuid", "status" "text", "created_at" timestamp with time zone, "business_id" "uuid", "business_name" "text", "menu_item_id" "uuid", "item_name" "text", "current_price_cents" integer, "suggested_price_cents" integer, "currency" "text", "created_by" "uuid", "quality_confidence" numeric, "anomaly_score" numeric, "anomaly_flags" "jsonb", "conflict_state" "text", "conflict_variants_24h" integer)
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  with owner_businesses as (
    select c.business_id
    from public.owner_claims c
    where c.user_id = auth.uid()
      and c.status = 'approved'
  ),
  target_businesses as (
    select business_id
    from owner_businesses
    where p_business_id is null
    union all
    select p_business_id
    where p_business_id is not null
  )
  select
    s.id as suggestion_id,
    s.status::text,
    s.created_at,
    s.business_id,
    b.name as business_name,
    mi.id as menu_item_id,
    mi.name as item_name,
    mi.price_cents as current_price_cents,
    s.suggested_price_cents,
    s.currency,
    s.created_by,
    s.quality_confidence,
    s.anomaly_score,
    s.anomaly_flags,
    s.conflict_state,
    s.conflict_variants_24h
  from public.menu_item_price_suggestions s
  join target_businesses tb on tb.business_id = s.business_id
  join public.menu_items mi on mi.id = s.menu_item_id
  join public.businesses b on b.id = s.business_id
  where (p_status is null or p_status = '' or s.status::text = p_status)
  order by
    (s.conflict_state = 'queued') desc,
    (coalesce(s.anomaly_score, 0) >= 0.5) desc,
    (s.status = 'pending') desc,
    s.created_at asc
  limit greatest(p_limit, 0) offset greatest(p_offset, 0);
$$;


ALTER FUNCTION "public"."owner_list_price_suggestions_v1"("p_business_id" "uuid", "p_status" "text", "p_limit" integer, "p_offset" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."owner_list_suspended_claims_v1"("p_business_id" "uuid", "p_status" "text" DEFAULT 'pending'::"text", "p_limit" integer DEFAULT 30, "p_offset" integer DEFAULT 0) RETURNS TABLE("claim_id" "uuid", "claim_status" "text", "claim_created_at" timestamp with time zone, "meal_id" "uuid", "amount_cents" integer, "currency" "text", "meal_message" "text", "claimant_user_id" "uuid", "claimant_name" "text", "verify_code" "text", "fulfilled_at" timestamp with time zone)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  select
    c.id,
    c.status::text,
    c.created_at,

    m.id,
    m.amount_cents,
    m.currency,
    m.message,

    c.claimant_user_id,
    coalesce(p.display_name,'Kullanıcı') as claimant_name,

    c.verify_code,
    c.fulfilled_at
  from public.suspended_meal_claims c
  join public.suspended_meals m on m.id = c.suspended_meal_id
  left join public.user_profiles p on p.user_id = c.claimant_user_id
  where m.business_id = p_business_id
    and public.is_owner_of_business(p_business_id)
    and (p_status is null or c.status::text = p_status)
  order by (c.status='pending') desc, c.created_at asc
  limit greatest(p_limit,0) offset greatest(p_offset,0);
$$;


ALTER FUNCTION "public"."owner_list_suspended_claims_v1"("p_business_id" "uuid", "p_status" "text", "p_limit" integer, "p_offset" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."owner_override_price_suggestion_v1"("p_suggestion_id" "uuid", "p_reason" "text", "p_force_price_cents" integer DEFAULT NULL::integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_uid uuid := auth.uid();
  v_reason text := nullif(trim(coalesce(p_reason, '')), '');
  v_s public.menu_item_price_suggestions%rowtype;
  v_price integer;
begin
  if v_uid is null then
    return jsonb_build_object('ok', false, 'error', 'not_authenticated');
  end if;
  if v_reason is null or length(v_reason) < 3 then
    return jsonb_build_object('ok', false, 'error', 'reason_required');
  end if;

  select *
    into v_s
  from public.menu_item_price_suggestions s
  where s.id = p_suggestion_id
  for update;

  if v_s.id is null then
    return jsonb_build_object('ok', false, 'error', 'not_found');
  end if;
  if not public.is_admin() and not public.is_owner_of_business(v_s.business_id) then
    return jsonb_build_object('ok', false, 'error', 'forbidden');
  end if;

  v_price := coalesce(p_force_price_cents, v_s.suggested_price_cents);
  if v_price is null or v_price < 0 then
    return jsonb_build_object('ok', false, 'error', 'bad_price');
  end if;

  update public.menu_items mi
  set price_cents = v_price,
      currency = coalesce(nullif(trim(v_s.currency), ''), mi.currency),
      updated_at = now()
  where mi.id = v_s.menu_item_id;

  insert into public.menu_item_price_history(
    menu_item_id, price_cents, currency, source, created_by
  )
  values (
    v_s.menu_item_id,
    v_price,
    coalesce(nullif(trim(v_s.currency), ''), 'TRY'),
    'owner_override',
    v_uid
  );

  update public.menu_item_price_suggestions s
  set status = 'approved'::public.menu_price_suggestion_status,
      handled_by = v_uid,
      handled_at = now(),
      approved_by = v_uid,
      approved_at = now(),
      quality_confidence = greatest(s.quality_confidence, 0.90),
      conflict_state = case
        when s.conflict_state = 'queued' then 'owner_overridden'
        else s.conflict_state
      end,
      note = coalesce(nullif(s.note, ''), '') || E'\n[owner_override] ' || v_reason
  where s.id = v_s.id;

  insert into public.admin_audit_log(action, target_table, target_id, meta)
  values (
    'owner.price_suggestion.override',
    'menu_item_price_suggestions',
    v_s.id,
    jsonb_build_object(
      'actor_id', v_uid,
      'business_id', v_s.business_id,
      'menu_item_id', v_s.menu_item_id,
      'suggested_price_cents', v_s.suggested_price_cents,
      'applied_price_cents', v_price,
      'reason', v_reason,
      'conflict_state_before', v_s.conflict_state,
      'anomaly_score_before', v_s.anomaly_score
    )
  );

  return jsonb_build_object(
    'ok', true,
    'suggestion_id', v_s.id,
    'applied_price_cents', v_price
  );
end;
$$;


ALTER FUNCTION "public"."owner_override_price_suggestion_v1"("p_suggestion_id" "uuid", "p_reason" "text", "p_force_price_cents" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."owner_publish_menu_item_v1"("p_item_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_business_id uuid;
  v_section_id uuid;
begin
  if auth.uid() is null then
    return jsonb_build_object('ok', false, 'code', 'not_authenticated', 'message', 'Auth required');
  end if;

  select business_id, section_id into v_business_id, v_section_id
  from public.menu_items
  where id = p_item_id;

  if v_business_id is null then
    return jsonb_build_object('ok', false, 'code', 'not_found', 'message', 'Item not found');
  end if;

  if not (public.is_admin() or public.is_owner_of_business(v_business_id)) then
    return jsonb_build_object('ok', false, 'code', 'not_owner', 'message', 'Not owner');
  end if;

  update public.menu_items
  set is_available = true,
      updated_at = now()
  where id = p_item_id;

  if public.is_admin() then
    insert into public.admin_audit_log(action, target_table, target_id, meta)
    values (
      'menu_item.publish',
      'menu_items',
      p_item_id,
      jsonb_build_object('section_id', v_section_id)
    );
  end if;

  return jsonb_build_object('ok', true, 'id', p_item_id, 'message', 'Published');
end;
$$;


ALTER FUNCTION "public"."owner_publish_menu_item_v1"("p_item_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."owner_publish_menu_v1"("p_menu_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_business_id uuid;
  v_snapshot_id uuid;
begin
  if auth.uid() is null then
    return jsonb_build_object('ok', false, 'code', 'not_authenticated', 'message', 'Auth required');
  end if;

  select business_id into v_business_id
  from public.menus
  where id = p_menu_id;

  if v_business_id is null then
    return jsonb_build_object('ok', false, 'code', 'not_found', 'message', 'Menu not found');
  end if;

  if not (public.is_admin() or public.has_business_permission_v1(v_business_id, 'menu_write')) then
    return jsonb_build_object('ok', false, 'code', 'not_owner', 'message', 'Not owner');
  end if;

  v_snapshot_id := public.create_menu_snapshot_v1(p_menu_id, 'publish');

  update public.menus
  set status = 'published',
      updated_at = now()
  where id = p_menu_id;

  return jsonb_build_object(
    'ok', true,
    'id', p_menu_id,
    'message', 'Published',
    'snapshot_id', v_snapshot_id
  );
end;
$$;


ALTER FUNCTION "public"."owner_publish_menu_v1"("p_menu_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."owner_reject_menu_price_suggestion_v1"("p_suggestion_id" "uuid", "p_note" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_business_id uuid;
  v_note text;
  v_before jsonb;
  v_after jsonb;
begin
  if auth.uid() is null then
    return jsonb_build_object('ok', false, 'error', 'not_authenticated');
  end if;

  v_note := nullif(trim(p_note), '');

  select
    s.business_id,
    jsonb_build_object(
      'business_id', s.business_id,
      'menu_item_id', s.menu_item_id,
      'status', s.status,
      'suggested_price_cents', s.suggested_price_cents,
      'currency', s.currency,
      'note', s.note
    )
  into v_business_id, v_before
  from public.menu_item_price_suggestions s
  where s.id = p_suggestion_id
    and s.status = 'pending';

  if v_business_id is null then
    return jsonb_build_object('ok', false, 'error', 'not_found_or_not_pending');
  end if;

  if not public.is_owner_of_business(v_business_id) and not public.is_admin() then
    return jsonb_build_object('ok', false, 'error', 'not_owner');
  end if;

  update public.menu_item_price_suggestions
  set status = 'rejected',
      note = coalesce(note, v_note),
      handled_by = auth.uid(),
      handled_at = now()
  where id = p_suggestion_id
    and status = 'pending';

  select jsonb_build_object(
    'business_id', s.business_id,
    'menu_item_id', s.menu_item_id,
    'status', s.status,
    'suggested_price_cents', s.suggested_price_cents,
    'currency', s.currency,
    'note', s.note,
    'handled_by', s.handled_by
  )
  into v_after
  from public.menu_item_price_suggestions s
  where s.id = p_suggestion_id;

  perform public.insert_audit_log_v1(
    'owner.price_suggestion.rejected',
    'menu_item_price_suggestions',
    p_suggestion_id,
    v_before,
    v_after
  );

  return jsonb_build_object('ok', true);
end;
$$;


ALTER FUNCTION "public"."owner_reject_menu_price_suggestion_v1"("p_suggestion_id" "uuid", "p_note" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."owner_reject_price_suggestion_v1"("p_suggestion_id" "uuid", "p_reason" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  return public.owner_reject_menu_price_suggestion_v1(p_suggestion_id, p_reason);
end;
$$;


ALTER FUNCTION "public"."owner_reject_price_suggestion_v1"("p_suggestion_id" "uuid", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."owner_reorder_menu_sections_v1"("p_menu_id" "uuid", "p_section_ids" "uuid"[]) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_business_id uuid;
  v_count int;
begin
  if auth.uid() is null then
    return jsonb_build_object('ok', false, 'code', 'not_authenticated', 'message', 'Auth required');
  end if;

  select business_id into v_business_id
  from public.menus
  where id = p_menu_id;

  if v_business_id is null then
    return jsonb_build_object('ok', false, 'code', 'not_found', 'message', 'Menu not found');
  end if;

  if not (public.is_admin() or public.is_owner_of_business(v_business_id)) then
    return jsonb_build_object('ok', false, 'code', 'not_owner', 'message', 'Not owner');
  end if;

  if p_section_ids is null or array_length(p_section_ids, 1) is null then
    return jsonb_build_object('ok', false, 'code', 'invalid', 'message', 'Empty section list');
  end if;

  select count(*) into v_count
  from public.menu_sections
  where menu_id = p_menu_id
    and id = any(p_section_ids);

  if v_count <> array_length(p_section_ids, 1) then
    return jsonb_build_object('ok', false, 'code', 'invalid', 'message', 'Section list mismatch');
  end if;

  update public.menu_sections s
  set sort_order = r.ord
  from (
    select unnest(p_section_ids) as id, row_number() over () as ord
  ) r
  where s.id = r.id;

  if public.is_admin() then
    insert into public.admin_audit_log(action, target_table, target_id, meta)
    values ('menu_section.reorder', 'menu_sections', null, jsonb_build_object('menu_id', p_menu_id));
  end if;

  return jsonb_build_object('ok', true, 'id', p_menu_id, 'message', 'Reordered');
end;
$$;


ALTER FUNCTION "public"."owner_reorder_menu_sections_v1"("p_menu_id" "uuid", "p_section_ids" "uuid"[]) OWNER TO "postgres";


