CREATE OR REPLACE FUNCTION "public"."owner_restore_menu_version_v1"("p_snapshot_id" "uuid", "p_archive_current_menu_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_snapshot record;
  v_new_menu_id uuid;
  v_new_section_id uuid;
  v_menu jsonb;
  v_section jsonb;
  v_item jsonb;
begin
  if auth.uid() is null then
    return jsonb_build_object('ok', false, 'code', 'not_authenticated', 'message', 'Auth required');
  end if;

  select *
  into v_snapshot
  from public.menu_snapshots
  where id = p_snapshot_id;

  if v_snapshot.id is null then
    return jsonb_build_object('ok', false, 'code', 'not_found', 'message', 'Snapshot not found');
  end if;

  if not (public.is_admin() or public.has_business_permission_v1(v_snapshot.business_id, 'menu_write')) then
    return jsonb_build_object('ok', false, 'code', 'not_owner', 'message', 'Not owner');
  end if;

  if p_archive_current_menu_id is not null then
    update public.menus
    set status = 'archived',
        updated_at = now()
    where id = p_archive_current_menu_id
      and business_id = v_snapshot.business_id;
  end if;

  v_menu := coalesce(v_snapshot.snapshot_json->'menu', '{}'::jsonb);

  insert into public.menus(
    business_id,
    title,
    status,
    created_by,
    kind,
    active_from,
    active_to,
    source,
    confidence_score
  )
  values (
    v_snapshot.business_id,
    coalesce(nullif(trim(v_menu->>'title'), ''), 'Geri yüklenen menü'),
    'published',
    auth.uid(),
    nullif(trim(v_menu->>'kind'), ''),
    nullif(v_menu->>'active_from', '')::time,
    nullif(v_menu->>'active_to', '')::time,
    coalesce(nullif(trim(v_menu->>'source'), ''), 'owner'),
    coalesce((v_menu->>'confidence_score')::numeric, 0)
  )
  returning id into v_new_menu_id;

  for v_section in
    select value
    from jsonb_array_elements(coalesce(v_snapshot.snapshot_json->'sections', '[]'::jsonb))
  loop
    insert into public.menu_sections(
      menu_id,
      title,
      sort_order,
      created_by
    )
    values (
      v_new_menu_id,
      coalesce(nullif(trim(v_section->>'title'), ''), 'Bölüm'),
      coalesce((v_section->>'sort_order')::int, 0),
      auth.uid()
    )
    returning id into v_new_section_id;

    for v_item in
      select value
      from jsonb_array_elements(coalesce(v_section->'items', '[]'::jsonb))
    loop
      insert into public.menu_items(
        section_id,
        business_id,
        name,
        description,
        price_cents,
        currency,
        catalog_item_id,
        created_by,
        category_id,
        is_available,
        image_url,
        tags,
        sort_order
      )
      values (
        v_new_section_id,
        v_snapshot.business_id,
        coalesce(nullif(trim(v_item->>'name'), ''), 'Ürün'),
        nullif(trim(v_item->>'description'), ''),
        nullif(v_item->>'price_cents', '')::int,
        coalesce(nullif(trim(v_item->>'currency'), ''), 'TRY'),
        nullif(v_item->>'catalog_item_id', '')::bigint,
        auth.uid(),
        nullif(v_item->>'category_id', '')::uuid,
        coalesce((v_item->>'is_available')::boolean, true),
        nullif(trim(v_item->>'image_url'), ''),
        coalesce(v_item->'tags', '[]'::jsonb),
        coalesce((v_item->>'sort_order')::int, 0)
      );
    end loop;
  end loop;

  perform public.create_menu_snapshot_v1(v_new_menu_id, 'restore');

  return jsonb_build_object(
    'ok', true,
    'menu_id', v_new_menu_id,
    'message', 'Restored'
  );
end;
$$;


ALTER FUNCTION "public"."owner_restore_menu_version_v1"("p_snapshot_id" "uuid", "p_archive_current_menu_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."owner_set_onboarding_progress_v1"("p_business_id" "uuid", "p_step_completed" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_step int;
begin
  if not (public.is_admin() or public.is_owner_of_business(p_business_id)) then
    return jsonb_build_object('ok', false, 'code', 'not_owner', 'message', 'Not owner');
  end if;

  v_step := least(greatest(coalesce(p_step_completed, 0), 0), 5);

  insert into public.owner_onboarding_progress(business_id, step_completed, updated_at)
  values (p_business_id, v_step, now())
  on conflict (business_id) do update
    set step_completed = greatest(owner_onboarding_progress.step_completed, excluded.step_completed),
        updated_at = now();

  return jsonb_build_object('ok', true, 'step_completed', v_step);
end;
$$;


ALTER FUNCTION "public"."owner_set_onboarding_progress_v1"("p_business_id" "uuid", "p_step_completed" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."owner_set_perk_status_v1"("p_perk_id" "uuid", "p_status" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_business_id uuid;
  v_status text;
begin
  if auth.uid() is null then
    return jsonb_build_object('ok', false, 'code', 'not_authenticated');
  end if;

  select business_id into v_business_id
  from public.business_perks
  where id = p_perk_id;

  if v_business_id is null then
    return jsonb_build_object('ok', false, 'code', 'not_found');
  end if;

  if not (public.is_admin() or public.is_owner_of_business(v_business_id)) then
    return jsonb_build_object('ok', false, 'code', 'not_owner');
  end if;

  v_status := nullif(trim(p_status), '');
  if v_status is null or v_status not in ('active','paused','ended') then
    return jsonb_build_object('ok', false, 'code', 'invalid');
  end if;

  update public.business_perks
  set status = v_status
  where id = p_perk_id;

  return jsonb_build_object('ok', true);
end;
$$;


ALTER FUNCTION "public"."owner_set_perk_status_v1"("p_perk_id" "uuid", "p_status" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."owner_soft_delete_menu_item_photo_v1"("p_photo_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_business_id uuid;
begin
  if auth.uid() is null then
    return jsonb_build_object('ok', false, 'code', 'not_authenticated');
  end if;

  select business_id into v_business_id
  from public.menu_item_photos
  where id = p_photo_id;

  if v_business_id is null then
    return jsonb_build_object('ok', false, 'code', 'not_found');
  end if;

  if not (public.is_admin() or public.has_business_permission_v1(v_business_id, 'menu_write')) then
    return jsonb_build_object('ok', false, 'code', 'not_owner');
  end if;

  update public.menu_item_photos
  set deleted_at = now(),
      deleted_by = auth.uid()
  where id = p_photo_id
    and deleted_at is null;

  if not found then
    return jsonb_build_object('ok', false, 'code', 'already_deleted');
  end if;

  return jsonb_build_object('ok', true, 'id', p_photo_id);
end;
$$;


