CREATE OR REPLACE FUNCTION "public"."owner_update_menu_item_v1"("p_item_id" "uuid", "p_name" "text" DEFAULT NULL::"text", "p_description" "text" DEFAULT NULL::"text", "p_price_cents" integer DEFAULT NULL::integer, "p_currency" "text" DEFAULT NULL::"text", "p_catalog_item_id" bigint DEFAULT NULL::bigint) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_name text;
  v_desc text;
  v_currency text;
  v_business_id uuid;
  v_section_id uuid;
begin
  if auth.uid() is null then
    return jsonb_build_object('ok', false, 'code', 'not_authenticated', 'message', 'Auth required');
  end if;

  select business_id, section_id into v_business_id, v_section_id
  from public.menu_items
  where id = p_item_id;

  if v_business_id is null then
    return jsonb_build_object('ok', false, 'code', 'not_found', 'message', 'Item not found');
  end if;

  if not (public.is_admin() or public.is_owner_of_business(v_business_id)) then
    return jsonb_build_object('ok', false, 'code', 'not_owner', 'message', 'Not owner');
  end if;

  if p_price_cents is not null and p_price_cents < 0 then
    return jsonb_build_object('ok', false, 'code', 'invalid', 'message', 'Invalid price');
  end if;

  v_name := nullif(trim(p_name), '');
  v_desc := nullif(trim(p_description), '');
  v_currency := nullif(trim(p_currency), '');

  update public.menu_items
  set
    name = coalesce(v_name, name),
    description = coalesce(v_desc, description),
    price_cents = coalesce(p_price_cents, price_cents),
    currency = coalesce(v_currency, currency),
    updated_at = now()
  where id = p_item_id;

  if public.is_admin() then
    insert into public.admin_audit_log(action, target_table, target_id, meta)
    values (
      'menu_item.update',
      'menu_items',
      p_item_id,
      jsonb_build_object('section_id', v_section_id)
    );
  end if;

  return jsonb_build_object('ok', true, 'id', p_item_id, 'message', 'Updated');
end;
$$;


ALTER FUNCTION "public"."owner_update_menu_item_v1"("p_item_id" "uuid", "p_name" "text", "p_description" "text", "p_price_cents" integer, "p_currency" "text", "p_catalog_item_id" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."owner_update_menu_section_v1"("p_section_id" "uuid", "p_title" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_title text;
  v_business_id uuid;
  v_menu_id uuid;
begin
  if auth.uid() is null then
    return jsonb_build_object('ok', false, 'code', 'not_authenticated', 'message', 'Auth required');
  end if;

  select m.business_id, s.menu_id into v_business_id, v_menu_id
  from public.menu_sections s
  join public.menus m on m.id = s.menu_id
  where s.id = p_section_id;

  if v_business_id is null then
    return jsonb_build_object('ok', false, 'code', 'not_found', 'message', 'Section not found');
  end if;

  if not (public.is_admin() or public.is_owner_of_business(v_business_id)) then
    return jsonb_build_object('ok', false, 'code', 'not_owner', 'message', 'Not owner');
  end if;

  v_title := nullif(trim(p_title), '');
  if v_title is null then
    return jsonb_build_object('ok', false, 'code', 'invalid', 'message', 'Title required');
  end if;

  update public.menu_sections
  set title = v_title,
      updated_at = now()
  where id = p_section_id;

  if public.is_admin() then
    insert into public.admin_audit_log(action, target_table, target_id, meta)
    values ('menu_section.update', 'menu_sections', p_section_id, jsonb_build_object('menu_id', v_menu_id));
  end if;

  return jsonb_build_object('ok', true, 'id', p_section_id, 'message', 'Updated');
end;
$$;


ALTER FUNCTION "public"."owner_update_menu_section_v1"("p_section_id" "uuid", "p_title" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."owner_update_menu_v1"("p_menu_id" "uuid", "p_title" "text" DEFAULT NULL::"text", "p_kind" "text" DEFAULT NULL::"text", "p_active_from" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_active_to" timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_title text;
  v_kind text;
  v_business_id uuid;
begin
  if auth.uid() is null then
    return jsonb_build_object('ok', false, 'code', 'not_authenticated', 'message', 'Auth required');
  end if;

  select business_id into v_business_id
  from public.menus
  where id = p_menu_id;

  if v_business_id is null then
    return jsonb_build_object('ok', false, 'code', 'not_found', 'message', 'Menu not found');
  end if;

  if not (public.is_admin() or public.is_owner_of_business(v_business_id)) then
    return jsonb_build_object('ok', false, 'code', 'not_owner', 'message', 'Not owner');
  end if;

  if p_active_from is not null and p_active_to is not null and p_active_from > p_active_to then
    return jsonb_build_object('ok', false, 'code', 'invalid', 'message', 'Invalid active range');
  end if;

  v_title := nullif(trim(p_title), '');
  v_kind := nullif(trim(p_kind), '');

  update public.menus
  set
    title = coalesce(v_title, title),
    kind = coalesce(v_kind, kind),
    active_from = coalesce(p_active_from, active_from),
    active_to = coalesce(p_active_to, active_to),
    updated_at = now()
  where id = p_menu_id;

  if public.is_admin() then
    insert into public.admin_audit_log(action, target_table, target_id, meta)
    values ('menu.update', 'menus', p_menu_id, jsonb_build_object('business_id', v_business_id));
  end if;

  return jsonb_build_object('ok', true, 'id', p_menu_id, 'message', 'Updated');
end;
$$;


ALTER FUNCTION "public"."owner_update_menu_v1"("p_menu_id" "uuid", "p_title" "text", "p_kind" "text", "p_active_from" timestamp with time zone, "p_active_to" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."owner_upsert_business_hours_v1"("p_business_id" "uuid", "p_open" time without time zone, "p_close" time without time zone) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  if not (public.is_admin() or public.is_owner_of_business(p_business_id)) then
    return jsonb_build_object('ok', false, 'code', 'not_owner', 'message', 'Not owner');
  end if;

  if p_open is null or p_close is null then
    return jsonb_build_object('ok', false, 'code', 'invalid', 'message', 'Hours required');
  end if;

  insert into public.business_hours(
    business_id,
    mon_open, mon_close,
    tue_open, tue_close,
    wed_open, wed_close,
    thu_open, thu_close,
    fri_open, fri_close,
    sat_open, sat_close,
    sun_open, sun_close,
    updated_at
  )
  values (
    p_business_id,
    p_open, p_close,
    p_open, p_close,
    p_open, p_close,
    p_open, p_close,
    p_open, p_close,
    p_open, p_close,
    p_open, p_close,
    now()
  )
  on conflict (business_id) do update
    set
      mon_open = excluded.mon_open,
      mon_close = excluded.mon_close,
      tue_open = excluded.tue_open,
      tue_close = excluded.tue_close,
      wed_open = excluded.wed_open,
      wed_close = excluded.wed_close,
      thu_open = excluded.thu_open,
      thu_close = excluded.thu_close,
      fri_open = excluded.fri_open,
      fri_close = excluded.fri_close,
      sat_open = excluded.sat_open,
      sat_close = excluded.sat_close,
      sun_open = excluded.sun_open,
      sun_close = excluded.sun_close,
      updated_at = now();

  return jsonb_build_object('ok', true);
end;
$$;


ALTER FUNCTION "public"."owner_upsert_business_hours_v1"("p_business_id" "uuid", "p_open" time without time zone, "p_close" time without time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."pick_one_menu_item_v1"("p_user_lat" double precision, "p_user_lng" double precision, "p_radius_km" double precision DEFAULT 5) RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  with prof as (
    select *
    from public.user_diet_profiles
    where user_id = auth.uid()
  ),
  items as (
    select *
    from public.search_menu_items_v1(
      p_user_lat, p_user_lng, p_radius_km,
      null,
      coalesce((select is_vegan from prof), false),
      coalesce((select is_vegetarian from prof), false),
      coalesce((select is_gluten_free from prof), false),
      coalesce((select is_lactose_free from prof), false),
      coalesce((select is_halal from prof), false),
      (select max_calories from prof),
      false,
      40, 0
    )
  )
  select to_jsonb(x) from (
    select *
    from items
    order by
      (case when price_status='verified' then 0 else 1 end),
      distance_km asc
    limit 1
  ) x;
$$;


ALTER FUNCTION "public"."pick_one_menu_item_v1"("p_user_lat" double precision, "p_user_lng" double precision, "p_radius_km" double precision) OWNER TO "postgres";


