    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO 'public', 'extensions'
    AS $$
  select greatest(1, (greatest(coalesce(p_total_xp, 0), 0) / 100) + 1)::int;
$$;


ALTER FUNCTION "public"."profile_level_from_xp_v1"("p_total_xp" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."promote_temp_upload_to_menu_asset_v1"("p_temp_upload_id" "uuid", "p_asset_type" "text", "p_menu_version" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_actor uuid := auth.uid();
  v_temp public.temp_uploads%rowtype;
  v_menu_asset_id uuid;
  v_asset_type text;
begin
  if v_actor is null then
    raise exception 'auth_required';
  end if;

  select *
    into v_temp
  from public.temp_uploads t
  where t.id = p_temp_upload_id
  for update;

  if not found then
    return jsonb_build_object('ok', false, 'error', 'temp_upload_not_found');
  end if;

  if not (
    coalesce(public.is_admin(), false)
    or coalesce(public.is_owner_of_business(v_temp.business_id), false)
  ) then
    raise exception 'not_authorized';
  end if;

  if v_temp.status <> 'pending' then
    return jsonb_build_object('ok', false, 'error', 'temp_upload_not_pending');
  end if;

  v_asset_type := lower(trim(coalesce(p_asset_type, 'menu_page')));
  if v_asset_type not in ('menu_page', 'menu_pdf', 'thumbnail') then
    return jsonb_build_object('ok', false, 'error', 'invalid_asset_type');
  end if;

  insert into public.menu_assets (
    business_id,
    menu_version,
    asset_type,
    storage_bucket,
    storage_path,
    source,
    created_by
  )
  values (
    v_temp.business_id,
    greatest(coalesce(p_menu_version, 1), 1),
    v_asset_type,
    v_temp.storage_bucket,
    v_temp.storage_path,
    'user_promoted',
    v_actor
  )
  returning id into v_menu_asset_id;

  update public.temp_uploads t
  set
    status = 'promoted',
    reviewed_by = v_actor,
    reviewed_at = now()
  where t.id = v_temp.id;

  if coalesce(v_temp.storage_path, '') <> '' then
    insert into public.storage_deletion_queue (bucket, path, reason)
    values (
      coalesce(nullif(v_temp.storage_bucket, ''), 'temp'),
      v_temp.storage_path,
      'promoted_cleanup'
    )
    on conflict do nothing;
  end if;

  return jsonb_build_object(
    'ok', true,
    'menu_asset_id', v_menu_asset_id,
    'temp_upload_id', v_temp.id
  );
end;
$$;


ALTER FUNCTION "public"."promote_temp_upload_to_menu_asset_v1"("p_temp_upload_id" "uuid", "p_asset_type" "text", "p_menu_version" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."public_list_incident_updates_v1"("p_limit" integer DEFAULT 100) RETURNS TABLE("id" "uuid", "incident_key" "text", "title" "text", "summary" "text", "action_taken" "text", "status" "text", "created_at" timestamp with time zone)
