CREATE OR REPLACE FUNCTION "public"."public_menu_share_view_v1"("p_menu_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_status text;
  v_menu jsonb;
  v_business jsonb;
  v_sections jsonb;
begin
  select m.status::text into v_status
  from public.menus m
  where m.id = p_menu_id;

  if v_status is null or v_status in ('archived','draft') then
    return jsonb_build_object('ok', false);
  end if;

  select to_jsonb(m)
    into v_menu
  from (
    select
      m.id,
      m.business_id,
      m.title,
      m.kind,
      m.status,
      m.active_from,
      m.active_to,
      m.created_at,
      m.updated_at
    from public.menus m
    where m.id = p_menu_id
  ) m;

  select to_jsonb(b)
    into v_business
  from (
    select b.id, b.name, b.logo_url
    from public.businesses b
    join public.menus m on m.business_id = b.id
    where m.id = p_menu_id
  ) b;

  with sections as (
    select s.id, s.menu_id, s.title, s.sort_order
    from public.menu_sections s
    where s.menu_id = p_menu_id
    order by s.sort_order asc, s.created_at asc
  ),
  items as (
    select
      i.id,
      i.section_id,
      i.business_id,
      i.name,
      i.description,
      i.price_cents,
      i.currency,
      null::integer as calories,
      exists (
        select 1 from jsonb_array_elements_text(coalesce(i.tags, '[]'::jsonb)) t(tag)
        where lower(t.tag) = 'vegan'
      ) as is_vegan,
      exists (
        select 1 from jsonb_array_elements_text(coalesce(i.tags, '[]'::jsonb)) t(tag)
        where lower(t.tag) in ('vegetarian','vejetaryen')
      ) as is_vegetarian,
      exists (
        select 1 from jsonb_array_elements_text(coalesce(i.tags, '[]'::jsonb)) t(tag)
        where lower(t.tag) in ('gluten_free','glutensiz')
      ) as is_gluten_free,
      exists (
        select 1 from jsonb_array_elements_text(coalesce(i.tags, '[]'::jsonb)) t(tag)
        where lower(t.tag) in ('lactose_free','laktozsuz')
      ) as is_lactose_free,
      exists (
        select 1 from jsonb_array_elements_text(coalesce(i.tags, '[]'::jsonb)) t(tag)
        where lower(t.tag) = 'halal'
      ) as is_halal,
      case when i.is_available then 'published' else 'archived' end as status,
      null::bigint as catalog_item_id,
      i.image_url,
      i.tags,
      i.sort_order
    from public.menu_items i
    join sections s on s.id = i.section_id
    where i.is_available = true
    order by i.sort_order asc, i.created_at asc
  )
  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'id', s.id,
        'title', s.title,
        'sort_order', s.sort_order,
        'items', coalesce((
          select jsonb_agg(to_jsonb(i))
          from items i
          where i.section_id = s.id
        ), '[]'::jsonb)
      )
    ),
    '[]'::jsonb
  )
  into v_sections
  from sections s;

  return jsonb_build_object(
    'ok', true,
    'menu', v_menu,
    'business', v_business,
    'sections', v_sections
  );
end;
$$;


ALTER FUNCTION "public"."public_menu_share_view_v1"("p_menu_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."recalc_review_helpful_count"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
begin
  if (tg_op = 'INSERT') then
    update public.reviews
      set helpful_count = helpful_count + 1
    where id = new.review_id;
    return new;
  end if;

  if (tg_op = 'DELETE') then
    update public.reviews
      set helpful_count = greatest(helpful_count - 1, 0)
    where id = old.review_id;
    return old;
  end if;

  return null;
end;
$$;


