CREATE OR REPLACE FUNCTION "public"."register_user_device_v1"("p_fcm_token" "text", "p_platform" "text", "p_app_version" "text" DEFAULT NULL::"text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_user_id uuid := auth.uid();
  v_id uuid;
begin
  if v_user_id is null then
    raise exception 'not_authenticated';
  end if;
  if coalesce(trim(p_fcm_token), '') = '' then
    raise exception 'invalid_token';
  end if;
  if coalesce(trim(p_platform), '') = '' then
    raise exception 'invalid_platform';
  end if;

  insert into public.user_devices(user_id, fcm_token, platform, app_version, last_seen_at)
  values (
    v_user_id,
    trim(p_fcm_token),
    lower(trim(p_platform)),
    nullif(trim(coalesce(p_app_version, '')), ''),
    now()
  )
  on conflict (user_id, fcm_token)
  do update set
    platform = excluded.platform,
    app_version = excluded.app_version,
    last_seen_at = now()
  returning id into v_id;

  delete from public.user_devices d
  where d.user_id = v_user_id
    and (
      d.last_seen_at < now() - interval '120 days'
      or d.id in (
        select stale.id
        from public.user_devices stale
        where stale.user_id = v_user_id
        order by stale.last_seen_at desc
        offset 10
      )
    );

  return v_id;
end;
$$;


ALTER FUNCTION "public"."register_user_device_v1"("p_fcm_token" "text", "p_platform" "text", "p_app_version" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."reject_business_suggestion"("p_suggestion_id" "uuid", "p_admin_note" "text" DEFAULT NULL::"text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_is_admin boolean;
  v_status text;
begin
  select exists(select 1 from public.admin_users where user_id = auth.uid())
  into v_is_admin;

  if not v_is_admin then
    raise exception 'not_authorized';
  end if;

  select status into v_status
  from public.business_suggestions
  where id = p_suggestion_id
  for update;

  if not found then
    raise exception 'suggestion_not_found';
  end if;

  if v_status <> 'pending' then
    raise exception 'suggestion_not_pending';
  end if;

  update public.business_suggestions
  set
    status = 'rejected',
    reviewed_at = now(),
    admin_note = p_admin_note
  where id = p_suggestion_id;
end;
$$;


ALTER FUNCTION "public"."reject_business_suggestion"("p_suggestion_id" "uuid", "p_admin_note" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."reject_owner_claim"("p_claim_id" "uuid", "p_note" "text" DEFAULT NULL::"text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_is_admin boolean;
  v_note text;
begin
  select exists(select 1 from public.admin_users where user_id = auth.uid())
  into v_is_admin;

  if not v_is_admin then
    raise exception 'not_authorized';
  end if;

  v_note := nullif(trim(p_note), '');

  update public.owner_claims
  set status = 'rejected',
      admin_note = v_note,
      reviewed_at = now()
  where id = p_claim_id;
end;
$$;


