CREATE OR REPLACE FUNCTION "public"."request_header_v1"("p_name" "text") RETURNS "text"
    LANGUAGE "sql" STABLE
    AS $$
  select coalesce(
    (coalesce(nullif(current_setting('request.headers', true), ''), '{}')::jsonb ->> lower(p_name)),
    (coalesce(nullif(current_setting('request.headers', true), ''), '{}')::jsonb ->> p_name)
  );
$$;


ALTER FUNCTION "public"."request_header_v1"("p_name" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."request_ip_v1"() RETURNS "inet"
    LANGUAGE "plpgsql" STABLE
    AS $$
declare
  v_ip_text text;
begin
  v_ip_text := coalesce(
    public.request_header_v1('x-forwarded-for'),
    public.request_header_v1('x-real-ip')
  );

  if nullif(trim(coalesce(v_ip_text, '')), '') is null then
    return null;
  end if;

  begin
    return trim(split_part(v_ip_text, ',', 1))::inet;
  exception
    when others then
      return null;
  end;
end;
$$;


ALTER FUNCTION "public"."request_ip_v1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."resolve_actor_role_v1"("p_user_id" "uuid") RETURNS "text"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  if p_user_id is null then
    return 'system';
  end if;

  if exists (
    select 1
    from public.admin_users a
    where a.user_id = p_user_id
  ) then
    return 'admin';
  end if;

  if exists (
    select 1
    from public.owner_claims oc
    where oc.user_id = p_user_id
      and oc.status = 'approved'
    limit 1
  ) then
    return 'owner';
  end if;

  return 'user';
end;
$$;


