CREATE OR REPLACE FUNCTION "public"."round_coord_3dp_v1"("p_value" double precision) RETURNS double precision
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO 'public', 'extensions'
    AS $$
  select case when p_value is null then null else round((p_value::numeric), 3)::double precision end;
$$;


ALTER FUNCTION "public"."round_coord_3dp_v1"("p_value" double precision) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sanitize_geo_jsonb_v1"("p_meta" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO 'public', 'extensions'
    AS $$
declare
  v jsonb := coalesce(p_meta, '{}'::jsonb);
  k text;
  keys text[] := array['lat','lng','latitude','longitude','user_lat','user_lng','device_lat','device_lng'];
  raw_text text;
  num_val double precision;
  nested jsonb;
begin
  if jsonb_typeof(v) <> 'object' then
    return p_meta;
  end if;

  foreach k in array keys loop
    if v ? k then
      raw_text := v ->> k;
      begin
        num_val := raw_text::double precision;
        v := jsonb_set(v, array[k], to_jsonb(public.round_coord_3dp_v1(num_val)), true);
      exception when others then
        -- Non-numeric value: leave untouched
        null;
      end;
    end if;
  end loop;

  if (v ? 'location') and jsonb_typeof(v->'location')='object' then
    nested := v->'location';
    foreach k in array array['lat','lng','latitude','longitude'] loop
      if nested ? k then
        raw_text := nested ->> k;
        begin
          num_val := raw_text::double precision;
          nested := jsonb_set(nested, array[k], to_jsonb(public.round_coord_3dp_v1(num_val)), true);
        exception when others then
          null;
        end;
      end if;
    end loop;
    v := jsonb_set(v, '{location}', nested, true);
  end if;

  return v;
end;
$$;


ALTER FUNCTION "public"."sanitize_geo_jsonb_v1"("p_meta" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sanitize_plain_text_v1"("p_text" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    AS $$
  select trim(
    regexp_replace(
      regexp_replace(
        regexp_replace(coalesce(p_text, ''), '<[^>]*>', ' ', 'gi'),
        '&[a-zA-Z0-9#]+;',
        ' ',
        'g'
      ),
      '[[:cntrl:]]+',
      ' ',
      'g'
    )
  );
$$;


ALTER FUNCTION "public"."sanitize_plain_text_v1"("p_text" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."search_admin_v1"("p_q" "text", "p_limit" integer DEFAULT 6) RETURNS TABLE("category" "text", "item_id" "uuid", "title" "text", "subtitle" "text", "search_token" "text", "created_at" timestamp with time zone, "meta" "jsonb", "score" integer)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_q text := lower(trim(coalesce(p_q, '')));
  v_limit integer := greatest(1, least(coalesce(p_limit, 6), 10));
begin
  if not public.is_admin() then
    raise exception 'not_admin';
  end if;

  if v_q = '' then
    return;
  end if;

  return query
  with candidates as (
    select
      'business'::text as category,
      b.id as item_id,
      coalesce(nullif(trim(b.name), ''), b.id::text) as title,
      trim(
        concat_ws(
          ' • ',
          nullif(trim(coalesce(b.phone, '')), ''),
          nullif(trim(coalesce(b.address, '')), ''),
          nullif(trim(concat_ws(' / ', b.district, b.city)), '')
        )
      ) as subtitle,
      coalesce(nullif(trim(b.name), ''), b.id::text) as search_token,
      b.created_at,
      jsonb_build_object(
        'business_id', b.id,
        'business_name', b.name,
        'phone', b.phone,
        'address', b.address,
        'city', b.city,
        'district', b.district
      ) as meta,
      case
        when b.id::text = v_q then 1000
        when lower(coalesce(b.name, '')) = v_q then 920
        when lower(coalesce(b.phone, '')) = v_q then 900
        when lower(coalesce(b.address, '')) = v_q then 880
        when lower(coalesce(b.name, '')) like (v_q || '%') then 820
        when lower(coalesce(b.phone, '')) like (v_q || '%') then 800
        when lower(coalesce(b.address, '')) like (v_q || '%') then 780
        else 720
      end as score
    from public.businesses b
    where
      b.id::text = v_q
      or lower(coalesce(b.name, '')) like ('%' || v_q || '%')
      or lower(coalesce(b.phone, '')) like ('%' || v_q || '%')
      or lower(coalesce(b.address, '')) like ('%' || v_q || '%')

    union all

    select
      'user'::text as category,
      u.id as item_id,
      lower(u.email::text) as title,
      u.id::text as subtitle,
      lower(u.email::text) as search_token,
      u.created_at,
      jsonb_build_object(
        'user_id', u.id,
        'email', lower(u.email::text)
      ) as meta,
      case
        when u.id::text = v_q then 1000
        when lower(u.email::text) = v_q then 940
        when lower(u.email::text) like (v_q || '%') then 860
        else 760
      end as score
    from auth.users u
    where
      u.id::text = v_q
      or lower(u.email::text) like ('%' || v_q || '%')

    union all

    select
      'report'::text as category,
      r.id as item_id,
      coalesce(nullif(trim(r.reason), ''), 'report') as title,
      trim(
        concat_ws(
          ' • ',
          nullif(trim(coalesce(b.name, '')), ''),
          nullif(trim(coalesce(r.details, '')), ''),
          nullif(trim(coalesce(r.status, '')), '')
        )
      ) as subtitle,
      coalesce(nullif(trim(b.name), ''), nullif(trim(r.reason), ''), r.id::text) as search_token,
      r.created_at,
      jsonb_build_object(
        'report_id', r.id,
        'business_id', r.business_id,
        'business_name', b.name,
        'status', r.status,
        'target_type', r.target_type,
        'target_id', r.target_id
      ) as meta,
      case
        when r.id::text = v_q then 1000
        when lower(coalesce(b.name, '')) = v_q then 900
        when lower(coalesce(r.reason, '')) = v_q then 880
        when lower(coalesce(b.name, '')) like (v_q || '%') then 820
        when lower(coalesce(r.reason, '')) like (v_q || '%') then 800
        else 720
      end as score
    from public.reports r
    left join public.businesses b on b.id = r.business_id
    where
      r.id::text = v_q
      or lower(coalesce(r.reason, '')) like ('%' || v_q || '%')
      or lower(coalesce(r.details, '')) like ('%' || v_q || '%')
      or lower(coalesce(b.name, '')) like ('%' || v_q || '%')

    union all

    select
      'submission'::text as category,
      s.id as item_id,
      coalesce(nullif(trim(s.name), ''), 'submission') as title,
      trim(
        concat_ws(
          ' • ',
          nullif(trim(coalesce(s.phone, '')), ''),
          nullif(trim(coalesce(s.address, '')), ''),
          nullif(trim(concat_ws(' / ', s.district, s.city)), '')
        )
      ) as subtitle,
      coalesce(nullif(trim(s.name), ''), s.id::text) as search_token,
      s.created_at,
      jsonb_build_object(
        'submission_id', s.id,
        'status', s.status,
        'phone', s.phone,
        'address', s.address,
        'city', s.city,
        'district', s.district,
        'category', s.category
      ) as meta,
      case
        when s.id::text = v_q then 1000
        when lower(coalesce(s.name, '')) = v_q then 920
        when lower(coalesce(s.phone, '')) = v_q then 900
        when lower(coalesce(s.name, '')) like (v_q || '%') then 840
        else 760
      end as score
    from public.business_submissions s
    where
      s.id::text = v_q
      or lower(coalesce(s.name, '')) like ('%' || v_q || '%')
      or lower(coalesce(s.phone, '')) like ('%' || v_q || '%')
      or lower(coalesce(s.address, '')) like ('%' || v_q || '%')

    union all

    select
      'claim'::text as category,
      c.id as item_id,
      coalesce(nullif(trim(c.full_name), ''), 'claim') as title,
      trim(
        concat_ws(
          ' • ',
          nullif(trim(coalesce(c.phone, '')), ''),
          nullif(trim(coalesce(b.name, '')), ''),
          nullif(trim(coalesce(c.status, '')), '')
        )
      ) as subtitle,
      coalesce(nullif(trim(c.full_name), ''), nullif(trim(coalesce(b.name, '')), ''), c.id::text) as search_token,
      c.created_at,
      jsonb_build_object(
        'claim_id', c.id,
        'business_id', c.business_id,
        'business_name', b.name,
        'status', c.status,
        'phone', c.phone
      ) as meta,
      case
        when c.id::text = v_q then 1000
        when lower(coalesce(c.full_name, '')) = v_q then 920
        when lower(coalesce(c.phone, '')) = v_q then 900
        when lower(coalesce(c.full_name, '')) like (v_q || '%') then 840
        when lower(coalesce(b.name, '')) like (v_q || '%') then 820
        else 760
      end as score
    from public.owner_claims c
    left join public.businesses b on b.id = c.business_id
    where
      c.id::text = v_q
      or lower(coalesce(c.full_name, '')) like ('%' || v_q || '%')
      or lower(coalesce(c.phone, '')) like ('%' || v_q || '%')
      or lower(coalesce(b.name, '')) like ('%' || v_q || '%')

    union all

    select
      'menu_item'::text as category,
      mi.id as item_id,
      coalesce(nullif(trim(mi.name), ''), 'menu item') as title,
      trim(
        concat_ws(
          ' • ',
          nullif(trim(coalesce(b.name, '')), ''),
          nullif(trim(coalesce(mi.status, '')), '')
        )
      ) as subtitle,
      coalesce(nullif(trim(mi.name), ''), nullif(trim(coalesce(b.name, '')), ''), mi.id::text) as search_token,
      mi.created_at,
      jsonb_build_object(
        'menu_item_id', mi.id,
        'business_id', mi.business_id,
        'business_name', b.name,
        'status', mi.status
      ) as meta,
      case
        when mi.id::text = v_q then 1000
        when lower(coalesce(mi.name, '')) = v_q then 920
        when lower(coalesce(mi.name, '')) like (v_q || '%') then 840
        when lower(coalesce(b.name, '')) like (v_q || '%') then 820
        else 740
      end as score
    from public.menu_items mi
    left join public.businesses b on b.id = mi.business_id
    where
      mi.id::text = v_q
      or lower(coalesce(mi.name, '')) like ('%' || v_q || '%')
      or lower(coalesce(b.name, '')) like ('%' || v_q || '%')
  ),
  ranked as (
    select
      c.*,
      row_number() over (
        partition by c.category
        order by c.score desc, c.created_at desc nulls last, c.item_id
      ) as row_no
    from candidates c
  )
  select
    r.category,
    r.item_id,
    r.title,
    coalesce(nullif(r.subtitle, ''), '-') as subtitle,
    r.search_token,
    r.created_at,
    r.meta,
    r.score
  from ranked r
  where r.row_no <= v_limit
  order by
    case r.category
      when 'business' then 1
      when 'user' then 2
      when 'report' then 3
      when 'submission' then 4
      when 'claim' then 5
      when 'menu_item' then 6
      else 99
    end,
    r.score desc,
    r.created_at desc nulls last,
    r.item_id;
end;
$$;


ALTER FUNCTION "public"."search_admin_v1"("p_q" "text", "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."search_businesses_v1"("p_query" "text", "p_city" "text" DEFAULT NULL::"text", "p_district" "text" DEFAULT NULL::"text", "p_limit" integer DEFAULT 50, "p_offset" integer DEFAULT 0) RETURNS TABLE("id" "uuid", "name" "text", "category" "text", "address" "text", "city" "text", "district" "text", "lat" double precision, "lng" double precision, "rank" double precision)
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  with q as (
    select nullif(trim(coalesce(p_query,'')), '') as query
  ),
  ts as (
    select
      websearch_to_tsquery('turkish', (select query from q)) as tsq
    where (select query from q) is not null
  )
  select
    b.id,
    b.name,
    b.category,
    b.address,
    b.city,
    b.district,
    b.lat,
    b.lng,
    case
      when (select query from q) is null then 0
      when exists (select 1 from ts) then ts_rank_cd(b.search_tsv, (select tsq from ts))
      else 0
    end as rank
  from public.businesses b
  where (p_city is null or b.city = p_city)
    and (p_district is null or b.district = p_district)
    and (
      (select query from q) is null
      or (
        exists (select 1 from ts)
        and b.search_tsv @@ (select tsq from ts)
      )
      or b.name ilike '%' || (select query from q) || '%'
      or b.address ilike '%' || (select query from q) || '%'
      or b.category ilike '%' || (select query from q) || '%'
    )
  order by
    rank desc,
    b.id desc
  limit greatest(p_limit, 0)
  offset greatest(p_offset, 0);
$$;


