CREATE OR REPLACE FUNCTION "public"."search_food_catalog_v1"("p_q" "text", "p_limit" integer DEFAULT 12) RETURNS TABLE("id" bigint, "name" "text", "category_id" "text", "category_name" "text")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  select
    i.id,
    i.name,
    c.id as category_id,
    c.name as category_name
  from public.food_catalog_items i
  join public.food_catalog_categories c on c.id = i.category_id
  where i.name_norm ilike ('%' || lower(p_q) || '%')
  order by i.popularity desc, i.name asc
  limit greatest(p_limit,0);
$$;


