CREATE OR REPLACE FUNCTION "public"."search_menu_items_v1"("p_user_lat" double precision, "p_user_lng" double precision, "p_radius_km" double precision DEFAULT 5, "p_q" "text" DEFAULT NULL::"text", "p_is_vegan" boolean DEFAULT false, "p_is_vegetarian" boolean DEFAULT false, "p_is_gluten_free" boolean DEFAULT false, "p_is_lactose_free" boolean DEFAULT false, "p_is_halal" boolean DEFAULT false, "p_max_calories" integer DEFAULT NULL::integer, "p_verified_price_only" boolean DEFAULT false, "p_limit" integer DEFAULT 20, "p_offset" integer DEFAULT 0) RETURNS TABLE("menu_item_id" "uuid", "item_name" "text", "item_description" "text", "price_cents" integer, "currency" "text", "calories" integer, "is_vegan" boolean, "is_vegetarian" boolean, "is_gluten_free" boolean, "is_lactose_free" boolean, "is_halal" boolean, "business_id" "uuid", "business_name" "text", "address" "text", "city" "text", "district" "text", "distance_km" double precision, "price_status" "text", "ok_30d" integer, "bad_30d" integer)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  with items as (
    select
      mi.id as menu_item_id,
      mi.name as item_name,
      mi.description as item_description,
      mi.price_cents,
      mi.currency,
      null::integer as calories,
      exists (
        select 1 from jsonb_array_elements_text(coalesce(mi.tags, '[]'::jsonb)) t(tag)
        where lower(t.tag) = 'vegan'
      ) as is_vegan,
      exists (
        select 1 from jsonb_array_elements_text(coalesce(mi.tags, '[]'::jsonb)) t(tag)
        where lower(t.tag) in ('vegetarian','vejetaryen')
      ) as is_vegetarian,
      exists (
        select 1 from jsonb_array_elements_text(coalesce(mi.tags, '[]'::jsonb)) t(tag)
        where lower(t.tag) in ('gluten_free','glutensiz')
      ) as is_gluten_free,
      exists (
        select 1 from jsonb_array_elements_text(coalesce(mi.tags, '[]'::jsonb)) t(tag)
        where lower(t.tag) in ('lactose_free','laktozsuz')
      ) as is_lactose_free,
      exists (
        select 1 from jsonb_array_elements_text(coalesce(mi.tags, '[]'::jsonb)) t(tag)
        where lower(t.tag) = 'halal'
      ) as is_halal,
      mi.business_id
    from public.menu_items mi
    where mi.is_available = true
      and (not p_is_vegan or exists (
        select 1 from jsonb_array_elements_text(coalesce(mi.tags, '[]'::jsonb)) t(tag)
        where lower(t.tag) = 'vegan'
      ))
      and (not p_is_vegetarian or exists (
        select 1 from jsonb_array_elements_text(coalesce(mi.tags, '[]'::jsonb)) t(tag)
        where lower(t.tag) in ('vegetarian','vejetaryen')
      ))
      and (not p_is_gluten_free or exists (
        select 1 from jsonb_array_elements_text(coalesce(mi.tags, '[]'::jsonb)) t(tag)
        where lower(t.tag) in ('gluten_free','glutensiz')
      ))
      and (not p_is_lactose_free or exists (
        select 1 from jsonb_array_elements_text(coalesce(mi.tags, '[]'::jsonb)) t(tag)
        where lower(t.tag) in ('lactose_free','laktozsuz')
      ))
      and (not p_is_halal or exists (
        select 1 from jsonb_array_elements_text(coalesce(mi.tags, '[]'::jsonb)) t(tag)
        where lower(t.tag) = 'halal'
      ))
      and (
        p_q is null
        or lower(mi.name) ilike ('%'||lower(p_q)||'%')
        or lower(coalesce(mi.description,'')) ilike ('%'||lower(p_q)||'%')
      )
  ),
  price as (
    select
      v.menu_item_id,
      count(*) filter (where v.created_at >= now() - interval '30 days') as total_30d,
      count(*) filter (where v.vote=1 and v.created_at >= now() - interval '30 days') as ok_30d,
      count(*) filter (where v.vote=-1 and v.created_at >= now() - interval '30 days') as bad_30d
    from public.menu_item_price_votes v
    group by v.menu_item_id
  ),
  joined as (
    select
      i.*,
      b.name as business_name,
      b.address,
      b.city,
      b.district,
      (
        6371.0 * acos(
          cos(radians(p_user_lat)) * cos(radians(b.lat)) *
          cos(radians(b.lng) - radians(p_user_lng)) +
          sin(radians(p_user_lat)) * sin(radians(b.lat))
        )
      ) as distance_km,
      coalesce(p.ok_30d,0) as ok_30d,
      coalesce(p.bad_30d,0) as bad_30d,
      coalesce(p.total_30d,0) as total_30d,
      case
        when coalesce(p.total_30d,0) = 0 then 'unknown'
        when coalesce(p.ok_30d,0) >= 3 and coalesce(p.ok_30d,0) >= coalesce(p.bad_30d,0)*2 then 'verified'
        when coalesce(p.bad_30d,0) >= 3 and coalesce(p.bad_30d,0) > coalesce(p.ok_30d,0) then 'outdated'
        else 'mixed'
      end as price_status
    from items i
    join public.businesses b on b.id = i.business_id
    left join price p on p.menu_item_id = i.menu_item_id
    where b.lat is not null and b.lng is not null
  )
  select
    menu_item_id,
    item_name,
    item_description,
    price_cents,
    currency,
    calories,
    is_vegan,
    is_vegetarian,
    is_gluten_free,
    is_lactose_free,
    is_halal,
    business_id,
    business_name,
    address,
    city,
    district,
    distance_km,
    price_status,
    ok_30d,
    bad_30d
  from joined
  where distance_km <= p_radius_km
    and (not p_verified_price_only or price_status = 'verified')
  order by distance_km asc, price_status desc
  limit greatest(p_limit,0)
  offset greatest(p_offset,0);
$$;


ALTER FUNCTION "public"."search_menu_items_v1"("p_user_lat" double precision, "p_user_lng" double precision, "p_radius_km" double precision, "p_q" "text", "p_is_vegan" boolean, "p_is_vegetarian" boolean, "p_is_gluten_free" boolean, "p_is_lactose_free" boolean, "p_is_halal" boolean, "p_max_calories" integer, "p_verified_price_only" boolean, "p_limit" integer, "p_offset" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."search_nearby_businesses_v1"("p_lat" double precision, "p_lng" double precision, "p_radius_km" integer DEFAULT 5, "p_query" "text" DEFAULT NULL::"text", "p_category" "text" DEFAULT NULL::"text", "p_limit" integer DEFAULT 30) RETURNS TABLE("id" "uuid", "name" "text", "category" "text", "city" "text", "district" "text", "address" "text", "lat" double precision, "lng" double precision, "distance_km" double precision)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  with base as (
    select
      b.*,
      -- Haversine distance (km)
      (6371.0 * 2.0 * asin(
        sqrt(
          power(sin(radians((b.lat - p_lat) / 2.0)), 2)
          + cos(radians(p_lat)) * cos(radians(b.lat))
          * power(sin(radians((b.lng - p_lng) / 2.0)), 2)
        )
      )) as distance_km
    from public.businesses b
    where b.is_active = true
      and b.lat is not null
      and b.lng is not null
      and (p_category is null or p_category = '' or b.category = p_category)
      and (
        p_query is null
        or p_query = ''
        or b.name ilike ('%' || p_query || '%')
        or coalesce(b.address,'') ilike ('%' || p_query || '%')
      )
  )
  select
    id, name, category, city, district, address, lat, lng, distance_km
  from base
  where distance_km <= greatest(1, p_radius_km)::double precision
  order by distance_km asc
  limit p_limit;
$$;


ALTER FUNCTION "public"."search_nearby_businesses_v1"("p_lat" double precision, "p_lng" double precision, "p_radius_km" integer, "p_query" "text", "p_category" "text", "p_limit" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."search_nearby_businesses_v1"("p_lat" double precision, "p_lng" double precision, "p_radius_km" integer, "p_query" "text", "p_category" "text", "p_limit" integer) IS 'DEPRECATED: planned removal after compatibility window';



CREATE OR REPLACE FUNCTION "public"."search_nearby_businesses_v2"("p_lat" double precision, "p_lng" double precision, "p_radius_km" integer DEFAULT 5, "p_query" "text" DEFAULT NULL::"text", "p_category" "text" DEFAULT NULL::"text", "p_limit" integer DEFAULT 30) RETURNS TABLE("id" "uuid", "name" "text", "category" "text", "city" "text", "district" "text", "address" "text", "lat" double precision, "lng" double precision, "distance_km" double precision, "quality_score" integer)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  with base as (
    select
      b.*,
      -- Haversine distance
      (6371.0 * 2.0 * asin(
        sqrt(
          power(sin(radians((b.lat - p_lat) / 2.0)), 2)
          + cos(radians(p_lat)) * cos(radians(b.lat))
          * power(sin(radians((b.lng - p_lng) / 2.0)), 2)
        )
      )) as distance_km,

      -- QUALITY SCORE
      (
        0
        + case when b.phone is not null and length(b.phone) >= 7 then 1 else 0 end
        + case when b.address is not null and length(b.address) >= 6 then 1 else 0 end
        + case when b.category is not null then 1 else 0 end
        + case when length(b.name) >= 6 then 1 else 0 end
        + case
            when lower(b.name) in (
              'restaurant','cafe','bar','pub','mekan','lokanta'
            ) then -3
            else 2
          end
        + case
            when b.phone is null and b.address is null then -2
            else 0
          end
      ) as quality_score

    from public.businesses b
    where b.is_active = true
      and b.lat is not null
      and b.lng is not null
      and (p_category is null or p_category = '' or b.category = p_category)
      and (
        p_query is null
        or p_query = ''
        or b.name ilike ('%' || p_query || '%')
        or coalesce(b.address,'') ilike ('%' || p_query || '%')
      )
  )
  select
    id, name, category, city, district, address, lat, lng,
    distance_km,
    quality_score
  from base
  where distance_km <= greatest(1, p_radius_km)::double precision
  order by
    quality_score desc,      -- 🔥 önce kalite
    distance_km asc          -- sonra mesafe
  limit p_limit;
$$;


ALTER FUNCTION "public"."search_nearby_businesses_v2"("p_lat" double precision, "p_lng" double precision, "p_radius_km" integer, "p_query" "text", "p_category" "text", "p_limit" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."search_nearby_businesses_v2"("p_lat" double precision, "p_lng" double precision, "p_radius_km" integer, "p_query" "text", "p_category" "text", "p_limit" integer) IS 'DEPRECATED: planned removal after compatibility window';



CREATE OR REPLACE FUNCTION "public"."search_nearby_businesses_v3"("p_lat" double precision, "p_lng" double precision, "p_radius_km" integer DEFAULT 5, "p_query" "text" DEFAULT NULL::"text", "p_category" "text" DEFAULT NULL::"text", "p_open_now" boolean DEFAULT false, "p_limit" integer DEFAULT 30) RETURNS TABLE("id" "uuid", "name" "text", "category" "text", "city" "text", "district" "text", "address" "text", "lat" double precision, "lng" double precision, "distance_km" double precision, "quality_score" integer)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  with base as (
    select
      b.*,
      (6371.0 * 2.0 * asin(
        sqrt(
          power(sin(radians((b.lat - p_lat) / 2.0)), 2)
          + cos(radians(p_lat)) * cos(radians(b.lat))
          * power(sin(radians((b.lng - p_lng) / 2.0)), 2)
        )
      )) as distance_km,
      (
        0
        + case when b.phone is not null and length(b.phone) >= 7 then 1 else 0 end
        + case when b.address is not null and length(b.address) >= 6 then 1 else 0 end
        + case when length(b.name) >= 6 then 1 else 0 end
        + case when lower(b.name) in ('restaurant','cafe','bar','pub','mekan','lokanta') then -3 else 2 end
      ) as quality_score
    from public.businesses b
    left join public.business_hours h on h.business_id = b.id
    where b.is_active = true
      and b.lat is not null
      and b.lng is not null
      and (p_category is null or p_category = '' or b.category = p_category)
      and (
        p_query is null
        or p_query = ''
        or b.name ilike ('%' || p_query || '%')
        or coalesce(b.address,'') ilike ('%' || p_query || '%')
      )
      and (
        p_open_now = false
        or (
          h.business_id is not null
          and (
            case extract(dow from now())
              when 1 then (h.mon_open is not null and current_time between h.mon_open and h.mon_close)
              when 2 then (h.tue_open is not null and current_time between h.tue_open and h.tue_close)
              when 3 then (h.wed_open is not null and current_time between h.wed_open and h.wed_close)
              when 4 then (h.thu_open is not null and current_time between h.thu_open and h.thu_close)
              when 5 then (h.fri_open is not null and current_time between h.fri_open and h.fri_close)
              when 6 then (h.sat_open is not null and current_time between h.sat_open and h.sat_close)
              when 0 then (h.sun_open is not null and current_time between h.sun_open and h.sun_close)
            end
          )
        )
      )
  )
  select
    id, name, category, city, district, address, lat, lng,
    distance_km,
    quality_score
  from base
  where distance_km <= greatest(1, p_radius_km)::double precision
  order by quality_score desc, distance_km asc
  limit p_limit;
$$;


ALTER FUNCTION "public"."search_nearby_businesses_v3"("p_lat" double precision, "p_lng" double precision, "p_radius_km" integer, "p_query" "text", "p_category" "text", "p_open_now" boolean, "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."search_nearby_businesses_v3"("p_user_lat" double precision, "p_user_lng" double precision, "p_radius_km" double precision DEFAULT 5, "p_limit" integer DEFAULT 50, "p_offset" integer DEFAULT 0, "p_city" "text" DEFAULT NULL::"text", "p_district" "text" DEFAULT NULL::"text", "p_query" "text" DEFAULT NULL::"text") RETURNS TABLE("id" "uuid", "name" "text", "category" "text", "address" "text", "city" "text", "district" "text", "lat" double precision, "lng" double precision, "distance_km" double precision)
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  with params as (
    select
      st_setsrid(st_makepoint(p_user_lng, p_user_lat), 4326)::geography as user_geog,
      greatest(p_radius_km, 0.1) * 1000.0 as radius_m,
      nullif(trim(coalesce(p_query,'')), '') as q
  )
  select
    b.id,
    b.name,
    b.category,
    b.address,
    b.city,
    b.district,
    b.lat,
    b.lng,
    (st_distance(b.geog, (select user_geog from params)) / 1000.0)::double precision as distance_km
  from public.businesses b, params
  where b.geog is not null
    and st_dwithin(b.geog, params.user_geog, params.radius_m)
    and (p_city is null or b.city = p_city)
    and (p_district is null or b.district = p_district)
    and (
      params.q is null
      or b.search_tsv @@ websearch_to_tsquery('turkish', params.q)
      or b.name ilike '%' || params.q || '%'
      or b.address ilike '%' || params.q || '%'
    )
  order by st_distance(b.geog, params.user_geog) asc
  limit greatest(p_limit, 0)
  offset greatest(p_offset, 0);
$$;


ALTER FUNCTION "public"."search_nearby_businesses_v3"("p_user_lat" double precision, "p_user_lng" double precision, "p_radius_km" double precision, "p_limit" integer, "p_offset" integer, "p_city" "text", "p_district" "text", "p_query" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."set_favorite_v2"("p_business_id" "uuid", "p_is_favorited" boolean, "p_idempotency_key" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_user_id uuid := auth.uid();
  v_is_favorited boolean := coalesce(p_is_favorited, false);
  v_idempotency_key text := nullif(trim(coalesce(p_idempotency_key, '')), '');
  v_cached_response jsonb;
  v_response jsonb;
  v_mode text;
begin
  if v_user_id is null then
    return jsonb_build_object('ok', false, 'error', 'not_authenticated');
  end if;

  if v_idempotency_key is not null then
    perform pg_advisory_xact_lock(
      hashtext('set_favorite_v2'),
      hashtext(v_user_id::text || ':' || v_idempotency_key)
    );

    select k.response
      into v_cached_response
    from public.client_mutation_idempotency_keys k
    where k.user_id = v_user_id
      and k.action = 'set_favorite_v2'
      and k.idempotency_key = v_idempotency_key
    limit 1;

    if v_cached_response is not null then
      return v_cached_response;
    end if;
  end if;

  if v_is_favorited then
    if exists (
      select 1
      from public.favorites
      where user_id = v_user_id
        and business_id = p_business_id
    ) then
      v_mode := 'noop';
    else
      insert into public.favorites(user_id, business_id, created_at)
      values (v_user_id, p_business_id, now())
      on conflict (user_id, business_id) do nothing;
      v_mode := 'insert';
    end if;
  else
    if exists (
      select 1
      from public.favorites
      where user_id = v_user_id
        and business_id = p_business_id
    ) then
      delete from public.favorites
      where user_id = v_user_id
        and business_id = p_business_id;
      v_mode := 'remove';
    else
      v_mode := 'noop';
    end if;
  end if;

  v_response := jsonb_build_object(
    'ok', true,
    'is_favorited', v_is_favorited,
    'mode', v_mode
  );

  if v_idempotency_key is not null then
    insert into public.client_mutation_idempotency_keys(
      user_id,
      action,
      idempotency_key,
      response,
      resource_type,
      resource_id
    )
    values (
      v_user_id,
      'set_favorite_v2',
      v_idempotency_key,
      v_response,
      'favorite',
      p_business_id
    )
    on conflict (user_id, action, idempotency_key) do update
    set response = excluded.response,
        resource_type = excluded.resource_type,
        resource_id = excluded.resource_id;
  end if;

  return v_response;
end;
$$;


ALTER FUNCTION "public"."set_favorite_v2"("p_business_id" "uuid", "p_is_favorited" boolean, "p_idempotency_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."set_follow_v2"("p_followee_id" "uuid", "p_following" boolean, "p_idempotency_key" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_user_id uuid := auth.uid();
  v_following boolean := coalesce(p_following, false);
  v_idempotency_key text := nullif(trim(coalesce(p_idempotency_key, '')), '');
  v_cached_response jsonb;
  v_response jsonb;
  v_current boolean;
  v_legacy jsonb;
begin
  if v_user_id is null then
    return jsonb_build_object('ok', false, 'error', 'not_authenticated');
  end if;

  if p_followee_id is null then
    return jsonb_build_object('ok', false, 'error', 'followee_required');
  end if;

  if p_followee_id = v_user_id then
    return jsonb_build_object('ok', false, 'error', 'cannot_follow_self');
  end if;

  if v_idempotency_key is not null then
    perform pg_advisory_xact_lock(
      hashtext('set_follow_v2'),
      hashtext(v_user_id::text || ':' || v_idempotency_key)
    );

    select k.response
      into v_cached_response
    from public.client_mutation_idempotency_keys k
    where k.user_id = v_user_id
      and k.action = 'set_follow_v2'
      and k.idempotency_key = v_idempotency_key
    limit 1;

    if v_cached_response is not null then
      return v_cached_response;
    end if;
  end if;

  select exists(
    select 1
    from public.user_follows
    where follower_id = v_user_id
      and followee_id = p_followee_id
  )
  into v_current;

  if v_current = v_following then
    v_response := jsonb_build_object(
      'ok', true,
      'following', v_following,
      'mode', 'noop'
    );
  else
    v_legacy := public.toggle_follow_v1(p_followee_id);
    if coalesce((v_legacy ->> 'ok')::boolean, false) is false then
      return v_legacy;
    end if;
    v_response := jsonb_build_object(
      'ok', true,
      'following', coalesce((v_legacy ->> 'following')::boolean, v_following),
      'mode', case when v_following then 'insert' else 'remove' end
    );
  end if;

  if v_idempotency_key is not null then
    insert into public.client_mutation_idempotency_keys(
      user_id,
      action,
      idempotency_key,
      response,
      resource_type,
      resource_id
    )
    values (
      v_user_id,
      'set_follow_v2',
      v_idempotency_key,
      v_response,
      'user_follow',
      p_followee_id
    )
    on conflict (user_id, action, idempotency_key) do update
    set response = excluded.response,
        resource_type = excluded.resource_type,
        resource_id = excluded.resource_id;
  end if;

  return v_response;
end;
$$;


ALTER FUNCTION "public"."set_follow_v2"("p_followee_id" "uuid", "p_following" boolean, "p_idempotency_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."set_group_offer_vote_v2"("p_offer_id" "uuid", "p_voted" boolean, "p_idempotency_key" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_user_id uuid := auth.uid();
  v_voted boolean := coalesce(p_voted, false);
  v_idempotency_key text := nullif(trim(coalesce(p_idempotency_key, '')), '');
  v_cached_response jsonb;
  v_response jsonb;
  v_current smallint;
  v_legacy jsonb;
begin
  if v_user_id is null then
    return jsonb_build_object('ok', false, 'error', 'unauthorized');
  end if;

  if p_offer_id is null then
    return jsonb_build_object('ok', false, 'error', 'offer_required');
  end if;

  if v_idempotency_key is not null then
    perform pg_advisory_xact_lock(
      hashtext('set_group_offer_vote_v2'),
      hashtext(v_user_id::text || ':' || v_idempotency_key)
    );

    select k.response
      into v_cached_response
    from public.client_mutation_idempotency_keys k
    where k.user_id = v_user_id
      and k.action = 'set_group_offer_vote_v2'
      and k.idempotency_key = v_idempotency_key
    limit 1;

    if v_cached_response is not null then
      return v_cached_response;
    end if;
  end if;

  select vote
    into v_current
  from public.group_offer_votes
  where offer_id = p_offer_id
    and user_id = v_user_id;

  if ((v_current = 1) is true) = v_voted then
    v_response := jsonb_build_object(
      'ok', true,
      'vote', case when v_voted then 1 else 0 end,
      'mode', 'noop'
    );
  else
    v_legacy := public.vote_group_offer_v1(p_offer_id);
    if coalesce((v_legacy ->> 'ok')::boolean, false) is false then
      return v_legacy;
    end if;
    v_response := jsonb_build_object(
      'ok', true,
      'vote', case when v_voted then 1 else 0 end,
      'mode', case when v_voted then 'insert' else 'remove' end
    );
  end if;

  if v_idempotency_key is not null then
    insert into public.client_mutation_idempotency_keys(
      user_id,
      action,
      idempotency_key,
      response,
      resource_type,
      resource_id
    )
    values (
      v_user_id,
      'set_group_offer_vote_v2',
      v_idempotency_key,
      v_response,
      'group_offer_vote',
      p_offer_id
    )
    on conflict (user_id, action, idempotency_key) do update
    set response = excluded.response,
        resource_type = excluded.resource_type,
        resource_id = excluded.resource_id;
  end if;

  return v_response;
end;
$$;


ALTER FUNCTION "public"."set_group_offer_vote_v2"("p_offer_id" "uuid", "p_voted" boolean, "p_idempotency_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."set_menu_item_photo_vote_v2"("p_photo_id" "uuid", "p_vote" smallint, "p_idempotency_key" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_user_id uuid := auth.uid();
  v_idempotency_key text := nullif(trim(coalesce(p_idempotency_key, '')), '');
  v_cached_response jsonb;
  v_response jsonb;
  v_prev smallint;
  v_legacy jsonb;
begin
  if v_user_id is null then
    return jsonb_build_object('ok', false, 'error', 'not_authenticated');
  end if;

  if p_photo_id is null then
    return jsonb_build_object('ok', false, 'error', 'photo_required');
  end if;

  if p_vote not in (-1, 0, 1) then
    return jsonb_build_object('ok', false, 'error', 'bad_vote');
  end if;

  if v_idempotency_key is not null then
    perform pg_advisory_xact_lock(
      hashtext('set_menu_item_photo_vote_v2'),
      hashtext(v_user_id::text || ':' || v_idempotency_key)
    );

    select k.response
      into v_cached_response
    from public.client_mutation_idempotency_keys k
    where k.user_id = v_user_id
      and k.action = 'set_menu_item_photo_vote_v2'
      and k.idempotency_key = v_idempotency_key
    limit 1;

    if v_cached_response is not null then
      return v_cached_response;
    end if;
  end if;

  select vote
    into v_prev
  from public.menu_item_photo_votes
  where photo_id = p_photo_id
    and user_id = v_user_id;

  if p_vote = 0 then
    if v_prev is null then
      v_response := jsonb_build_object('ok', true, 'mode', 'noop', 'vote', 0);
    else
      v_legacy := public.vote_menu_item_photo_v1(p_photo_id, v_prev);
      if coalesce((v_legacy ->> 'ok')::boolean, false) is false then
        return v_legacy;
      end if;
      v_response := jsonb_build_object('ok', true, 'mode', 'remove', 'vote', 0);
    end if;
  elsif v_prev = p_vote then
    v_response := jsonb_build_object('ok', true, 'mode', 'noop', 'vote', p_vote);
  else
    v_legacy := public.vote_menu_item_photo_v1(p_photo_id, p_vote);
    if coalesce((v_legacy ->> 'ok')::boolean, false) is false then
      return v_legacy;
    end if;
    v_response := jsonb_build_object(
      'ok', true,
      'mode', case when v_prev is null then 'insert' else 'switch' end,
      'vote', p_vote
    );
  end if;

  if v_idempotency_key is not null then
    insert into public.client_mutation_idempotency_keys(
      user_id,
      action,
      idempotency_key,
      response,
      resource_type,
      resource_id
    )
    values (
      v_user_id,
      'set_menu_item_photo_vote_v2',
      v_idempotency_key,
      v_response,
      'menu_item_photo_vote',
      p_photo_id
    )
    on conflict (user_id, action, idempotency_key) do update
    set response = excluded.response,
        resource_type = excluded.resource_type,
        resource_id = excluded.resource_id;
  end if;

  return v_response;
end;
$$;


ALTER FUNCTION "public"."set_menu_item_photo_vote_v2"("p_photo_id" "uuid", "p_vote" smallint, "p_idempotency_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."set_menu_item_price_vote_v2"("p_menu_item_id" "uuid", "p_vote" smallint, "p_idempotency_key" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_user_id uuid := auth.uid();
  v_idempotency_key text := nullif(trim(coalesce(p_idempotency_key, '')), '');
  v_cached_response jsonb;
  v_response jsonb;
  v_prev smallint;
  v_mode text;
begin
  if v_user_id is null then
    return jsonb_build_object('ok', false, 'error', 'not_authenticated');
  end if;

  if p_vote not in (-1, 0, 1) then
    return jsonb_build_object('ok', false, 'error', 'bad_vote');
  end if;

  if v_idempotency_key is not null then
    perform pg_advisory_xact_lock(
      hashtext('set_menu_item_price_vote_v2'),
      hashtext(v_user_id::text || ':' || v_idempotency_key)
    );

    select k.response
      into v_cached_response
    from public.client_mutation_idempotency_keys k
    where k.user_id = v_user_id
      and k.action = 'set_menu_item_price_vote_v2'
      and k.idempotency_key = v_idempotency_key
    limit 1;

    if v_cached_response is not null then
      return v_cached_response;
    end if;
  end if;

  select vote into v_prev
  from public.menu_item_price_votes
  where menu_item_id = p_menu_item_id
    and user_id = v_user_id;

  if p_vote = 0 then
    if v_prev is null then
      v_mode := 'noop';
    else
      delete from public.menu_item_price_votes
      where menu_item_id = p_menu_item_id
        and user_id = v_user_id;
      v_mode := 'remove';
    end if;
  elsif v_prev is null then
    insert into public.menu_item_price_votes(menu_item_id, user_id, vote)
    values (p_menu_item_id, v_user_id, p_vote);
    v_mode := 'insert';
  elsif v_prev = p_vote then
    v_mode := 'noop';
  else
    update public.menu_item_price_votes
    set vote = p_vote,
        created_at = now()
    where menu_item_id = p_menu_item_id
      and user_id = v_user_id;
    v_mode := 'switch';
  end if;

  v_response := jsonb_build_object(
    'ok', true,
    'vote', p_vote,
    'mode', v_mode
  );

  if v_idempotency_key is not null then
    insert into public.client_mutation_idempotency_keys(
      user_id,
      action,
      idempotency_key,
      response,
      resource_type,
      resource_id
    )
    values (
      v_user_id,
      'set_menu_item_price_vote_v2',
      v_idempotency_key,
      v_response,
      'menu_item_price_vote',
      p_menu_item_id
    )
    on conflict (user_id, action, idempotency_key) do update
    set response = excluded.response,
        resource_type = excluded.resource_type,
        resource_id = excluded.resource_id;
  end if;

  return v_response;
end;
$$;


ALTER FUNCTION "public"."set_menu_item_price_vote_v2"("p_menu_item_id" "uuid", "p_vote" smallint, "p_idempotency_key" "text") OWNER TO "postgres";


