CREATE OR REPLACE FUNCTION "public"."submit_group_offer_v1"("p_request_id" "uuid", "p_business_id" "uuid", "p_offered_total_cents" integer, "p_includes" "jsonb" DEFAULT '{}'::"jsonb", "p_message" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_req_status text;
  v_key text;
  v_today date := current_date;
  v_count int;
begin
  if auth.uid() is null then
    return jsonb_build_object('ok', false, 'code', 'not_authenticated');
  end if;
  if not (public.is_admin() or public.is_owner_of_business(p_business_id)) then
    return jsonb_build_object('ok', false, 'code', 'not_owner');
  end if;

  select status into v_req_status
  from public.group_requests
  where id = p_request_id;

  if v_req_status is distinct from 'open' then
    return jsonb_build_object('ok', false, 'code', 'request_closed');
  end if;

  v_key := format('group_offer:%s:%s', p_business_id::text, v_today::text);
  select count into v_count from public.user_rate_limits where key = v_key;
  if coalesce(v_count, 0) >= 20 then
    return jsonb_build_object('ok', false, 'code', 'rate_limited');
  end if;

  insert into public.user_rate_limits (key, user_id, action, day, count, updated_at)
  values (v_key, auth.uid(), 'group_offer', v_today, 1, now())
  on conflict (key) do update
    set count = public.user_rate_limits.count + 1,
        updated_at = now();

  insert into public.group_offers(
    request_id, business_id, offered_total_cents, includes, message, status, created_by
  )
  values (
    p_request_id, p_business_id, p_offered_total_cents,
    coalesce(p_includes, '{}'::jsonb),
    nullif(trim(p_message), ''),
    'submitted',
    auth.uid()
  )
  on conflict do nothing;

  return jsonb_build_object('ok', true);
end;
$$;


ALTER FUNCTION "public"."submit_group_offer_v1"("p_request_id" "uuid", "p_business_id" "uuid", "p_offered_total_cents" integer, "p_includes" "jsonb", "p_message" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."submit_menu_item_price_suggestion_v1"("p_menu_item_id" "uuid", "p_suggested_price_cents" integer, "p_currency" "text" DEFAULT 'TRY'::"text", "p_note" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_business_id uuid;
  v_cnt int;
  v_note text;
begin
  if auth.uid() is null then
    return jsonb_build_object('ok', false, 'error', 'not_authenticated');
  end if;

  if p_suggested_price_cents < 0 then
    return jsonb_build_object('ok', false, 'error', 'bad_price');
  end if;

  v_note := nullif(trim(p_note), '');

  select business_id into v_business_id
  from public.menu_items
  where id = p_menu_item_id and status='published';

  if v_business_id is null then
    return jsonb_build_object('ok', false, 'error', 'not_found');
  end if;

  -- rate limit: aynı kullanıcı aynı item’e 24 saatte 1
  select count(*) into v_cnt
  from public.menu_item_price_suggestions
  where menu_item_id = p_menu_item_id
    and created_by = auth.uid()
    and created_at >= now() - interval '24 hours';

  if v_cnt > 0 then
    return jsonb_build_object('ok', false, 'error', 'rate_limited_24h');
  end if;

  insert into public.menu_item_price_suggestions(
    menu_item_id, business_id, suggested_price_cents, currency, note, created_by
  )
  values (
    p_menu_item_id, v_business_id, p_suggested_price_cents, p_currency, v_note, auth.uid()
  );

  return jsonb_build_object('ok', true);
end;
$$;


ALTER FUNCTION "public"."submit_menu_item_price_suggestion_v1"("p_menu_item_id" "uuid", "p_suggested_price_cents" integer, "p_currency" "text", "p_note" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."submit_menu_item_price_suggestion_v2"("p_menu_item_id" "uuid", "p_suggested_price_cents" integer, "p_currency" "text" DEFAULT 'TRY'::"text", "p_note" "text" DEFAULT NULL::"text", "p_evidence_url" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_business_id uuid;
  v_cnt int;
  v_note text;
  v_evidence_url text;
  v_current_price int;
  v_ok_30d int := 0;
  v_bad_30d int := 0;
  v_total_30d int := 0;
  v_confidence numeric := 0;
  v_auto_approved boolean := false;
  v_pending_count int := 0;
  v_shadow boolean := false;
  v_rate jsonb;
begin
  if auth.uid() is null then
    return jsonb_build_object('ok', false, 'error', 'not_authenticated');
  end if;

  if p_suggested_price_cents < 0 then
    return jsonb_build_object('ok', false, 'error', 'bad_price');
  end if;

  if p_currency is null or length(trim(p_currency)) <> 3 then
    return jsonb_build_object('ok', false, 'error', 'bad_currency');
  end if;

  v_note := nullif(public.sanitize_plain_text_v1(p_note), '');
  v_evidence_url := nullif(trim(p_evidence_url), '');

  if v_note is not null and public.contains_contact_or_url_v1(v_note) then
    return jsonb_build_object('ok', false, 'error', 'contains_link_or_phone');
  end if;

  if v_note is not null and public.contains_obfuscated_profanity_v1(v_note) then
    return jsonb_build_object('ok', false, 'error', 'contains_profanity');
  end if;

  if v_note is not null
     and length(regexp_replace(v_note, '[[:alnum:][:space:]]', '', 'g')) > 12 then
    return jsonb_build_object('ok', false, 'error', 'emoji_spam');
  end if;

  if v_evidence_url is not null and left(v_evidence_url, 4) <> 'http' then
    return jsonb_build_object('ok', false, 'error', 'bad_evidence_url');
  end if;

  v_rate := public.consume_rate_limit_v1('price_suggestion', 40);
  if coalesce((v_rate->>'ok')::boolean, false) is false then
    return jsonb_build_object('ok', false, 'error', 'price_suggestion_daily_rate_limited');
  end if;

  select mi.business_id, mi.price_cents
    into v_business_id, v_current_price
  from public.menu_items mi
  where mi.id = p_menu_item_id and mi.status = 'published';

  if v_business_id is null then
    return jsonb_build_object('ok', false, 'error', 'not_found');
  end if;

  select count(*) into v_cnt
  from public.menu_item_price_suggestions
  where menu_item_id = p_menu_item_id
    and created_by = auth.uid()
    and created_at >= now() - interval '24 hours';

  if v_cnt > 0 then
    return jsonb_build_object('ok', false, 'error', 'rate_limited_24h');
  end if;

  select
    count(*) filter (where vote = 1 and created_at >= now() - interval '30 days'),
    count(*) filter (where vote = -1 and created_at >= now() - interval '30 days'),
    count(*) filter (where created_at >= now() - interval '30 days')
    into v_ok_30d, v_bad_30d, v_total_30d
  from public.menu_item_price_votes
  where menu_item_id = p_menu_item_id;

  v_confidence :=
    greatest(
      0::numeric,
      least(
        1::numeric,
        (case when v_total_30d <= 0 then 0.2 else (v_ok_30d::numeric / nullif(v_total_30d, 0)) end) * 0.8
        +
        (case
          when v_total_30d >= 12 then 0.2
          when v_total_30d >= 6 then 0.12
          when v_total_30d >= 3 then 0.06
          else 0
        end)
      )
    );

  v_shadow := public.is_shadow_banned_v1();
  if v_shadow then
    v_auto_approved := false;
  end if;

  if v_current_price is not null
     and v_current_price > 0
     and v_total_30d >= 8
     and v_ok_30d >= (v_bad_30d * 3)
     and abs(p_suggested_price_cents - v_current_price)::numeric / v_current_price::numeric <= 0.05
  then
    v_auto_approved := true;
  end if;

  if v_auto_approved then
    update public.menu_items
    set price_cents = p_suggested_price_cents,
        currency = upper(trim(p_currency)),
        updated_at = now()
    where id = p_menu_item_id;

    insert into public.menu_item_price_suggestions(
      menu_item_id, business_id, suggested_price_cents, currency, note, created_by,
      evidence_url, status, handled_at, approved_at, is_shadow
    )
    values (
      p_menu_item_id, v_business_id, p_suggested_price_cents, upper(trim(p_currency)), v_note, auth.uid(),
      v_evidence_url, 'approved', now(), now(), v_shadow
    );

    insert into public.menu_item_price_history(
      menu_item_id, price_cents, currency, source, created_by
    )
    values (
      p_menu_item_id, p_suggested_price_cents, upper(trim(p_currency)), 'auto_rule', auth.uid()
    );

    return jsonb_build_object(
      'ok', true,
      'auto_approved', true,
      'confidence_score', v_confidence,
      'pending_count', 0,
      'shadowed', v_shadow
    );
  end if;

  insert into public.menu_item_price_suggestions(
    menu_item_id, business_id, suggested_price_cents, currency, note, created_by, evidence_url, is_shadow
  )
  values (
    p_menu_item_id, v_business_id, p_suggested_price_cents, upper(trim(p_currency)), v_note, auth.uid(), v_evidence_url, v_shadow
  );

  select count(*) into v_pending_count
  from public.menu_item_price_suggestions
  where menu_item_id = p_menu_item_id
    and status = 'pending';

  return jsonb_build_object(
    'ok', true,
    'auto_approved', false,
    'confidence_score', v_confidence,
    'pending_count', v_pending_count,
    'shadowed', v_shadow
  );
end;
$$;


ALTER FUNCTION "public"."submit_menu_item_price_suggestion_v2"("p_menu_item_id" "uuid", "p_suggested_price_cents" integer, "p_currency" "text", "p_note" "text", "p_evidence_url" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."submit_menu_item_price_suggestion_v3"("p_menu_item_id" "uuid", "p_suggested_price_cents" integer, "p_currency" "text" DEFAULT 'TRY'::"text", "p_note" "text" DEFAULT NULL::"text", "p_evidence_url" "text" DEFAULT NULL::"text", "p_client_id" "text" DEFAULT NULL::"text", "p_captured_at" timestamp with time zone DEFAULT "now"()) RETURNS "jsonb"
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  select public.submit_menu_item_price_suggestion_v4(
    p_menu_item_id,
    p_suggested_price_cents,
    p_currency,
    p_note,
    p_evidence_url,
    p_client_id,
    p_captured_at
  );
$$;


ALTER FUNCTION "public"."submit_menu_item_price_suggestion_v3"("p_menu_item_id" "uuid", "p_suggested_price_cents" integer, "p_currency" "text", "p_note" "text", "p_evidence_url" "text", "p_client_id" "text", "p_captured_at" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."submit_menu_item_price_suggestion_v4"("p_menu_item_id" "uuid", "p_suggested_price_cents" integer, "p_currency" "text" DEFAULT 'TRY'::"text", "p_note" "text" DEFAULT NULL::"text", "p_evidence_url" "text" DEFAULT NULL::"text", "p_client_id" "text" DEFAULT NULL::"text", "p_captured_at" timestamp with time zone DEFAULT "now"()) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_result jsonb;
  v_suggestion_id uuid;
  v_quality jsonb := '{}'::jsonb;
  v_force_pending boolean := false;
  v_prev_price integer := null;
  v_conflict_state text := 'none';
  v_anomaly_score numeric := 0;
  v_quality_confidence numeric := 0;
  v_pending_count integer := 0;
begin
  select mi.price_cents
    into v_prev_price
  from public.menu_items mi
  where mi.id = p_menu_item_id
  limit 1;

  v_result := public.submit_menu_item_price_suggestion_v2(
    p_menu_item_id,
    p_suggested_price_cents,
    p_currency,
    p_note,
    p_evidence_url,
    p_client_id,
    p_captured_at
  );

  if coalesce((v_result->>'ok')::boolean, false) is false then
    return v_result;
  end if;

  select s.id
    into v_suggestion_id
  from public.menu_item_price_suggestions s
  where s.menu_item_id = p_menu_item_id
    and s.created_by = auth.uid()
  order by s.created_at desc
  limit 1;

  if v_suggestion_id is null then
    return v_result;
  end if;

  v_quality := public.compute_price_suggestion_quality_v1(
    p_menu_item_id,
    p_suggested_price_cents,
    p_evidence_url,
    coalesce(p_captured_at, now())
  );
  v_conflict_state := coalesce(v_quality->>'conflict_state', 'none');
  v_anomaly_score := coalesce((v_quality->>'anomaly_score')::numeric, 0);
  v_quality_confidence := coalesce((v_quality->>'quality_confidence')::numeric, 0);
  v_force_pending := (v_conflict_state = 'queued') or (v_anomaly_score >= 0.50);

  update public.menu_item_price_suggestions s
  set quality_user_weight = coalesce((v_quality->>'user_weight')::numeric, 1),
      quality_evidence_weight = coalesce((v_quality->>'evidence_weight')::numeric, 1),
      quality_time_weight = coalesce((v_quality->>'time_weight')::numeric, 1),
      quality_confidence = v_quality_confidence,
      anomaly_score = v_anomaly_score,
      anomaly_flags = coalesce(v_quality->'anomaly_flags', '[]'::jsonb),
      conflict_state = v_conflict_state,
      conflict_variants_24h = coalesce((v_quality->>'conflict_variants_24h')::int, 0),
      status = case
        when v_force_pending then 'pending'::public.menu_price_suggestion_status
        else s.status
      end,
      handled_by = case when v_force_pending then null else s.handled_by end,
      handled_at = case when v_force_pending then null else s.handled_at end,
      approved_by = case when v_force_pending then null else s.approved_by end,
      approved_at = case when v_force_pending then null else s.approved_at end,
      onsite_signal = case
        when v_force_pending and v_conflict_state = 'queued' then 'conflict_queue'
        when v_force_pending and v_anomaly_score >= 0.50 then 'anomaly_queue'
        else s.onsite_signal
      end
  where s.id = v_suggestion_id;

  if v_force_pending and coalesce((v_result->>'auto_approved')::boolean, false) then
    if v_prev_price is not null then
      update public.menu_items mi
      set price_cents = v_prev_price,
          updated_at = now()
      where mi.id = p_menu_item_id;
    end if;
  end if;

  select count(*)
    into v_pending_count
  from public.menu_item_price_suggestions s
  where s.menu_item_id = p_menu_item_id
    and s.status = 'pending'::public.menu_price_suggestion_status;

  return v_result
    || jsonb_build_object(
      'suggestion_id', v_suggestion_id,
      'auto_approved', case when v_force_pending then false else coalesce((v_result->>'auto_approved')::boolean, false) end,
      'pending_count', v_pending_count,
      'quality_confidence', v_quality_confidence,
      'anomaly_score', v_anomaly_score,
      'anomaly_flags', coalesce(v_quality->'anomaly_flags', '[]'::jsonb),
      'conflict_state', v_conflict_state,
      'conflict_variants_24h', coalesce((v_quality->>'conflict_variants_24h')::int, 0),
      'queued_for_review', v_force_pending
    );
end;
$$;


ALTER FUNCTION "public"."submit_menu_item_price_suggestion_v4"("p_menu_item_id" "uuid", "p_suggested_price_cents" integer, "p_currency" "text", "p_note" "text", "p_evidence_url" "text", "p_client_id" "text", "p_captured_at" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."submit_menu_item_price_suggestion_v5"("p_menu_item_id" "uuid", "p_suggested_price_cents" integer, "p_currency" "text" DEFAULT 'TRY'::"text", "p_note" "text" DEFAULT NULL::"text", "p_evidence_url" "text" DEFAULT NULL::"text", "p_client_id" "text" DEFAULT NULL::"text", "p_captured_at" timestamp with time zone DEFAULT "now"(), "p_idempotency_key" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_user_id uuid := auth.uid();
  v_idempotency_key text := nullif(trim(coalesce(p_idempotency_key, '')), '');
  v_cached_response jsonb;
  v_response jsonb;
  v_suggestion_id uuid;
begin
  if v_user_id is null then
    return jsonb_build_object('ok', false, 'error', 'not_authenticated');
  end if;

  if v_idempotency_key is not null then
    perform pg_advisory_xact_lock(
      hashtext('submit_menu_item_price_suggestion_v5'),
      hashtext(v_user_id::text || ':' || v_idempotency_key)
    );

    select k.response
      into v_cached_response
    from public.client_mutation_idempotency_keys k
    where k.user_id = v_user_id
      and k.action = 'submit_menu_item_price_suggestion_v5'
      and k.idempotency_key = v_idempotency_key
    limit 1;

    if v_cached_response is not null then
      return v_cached_response;
    end if;
  end if;

  v_response := public.submit_menu_item_price_suggestion_v4(
    p_menu_item_id,
    p_suggested_price_cents,
    p_currency,
    p_note,
    p_evidence_url,
    p_client_id,
    p_captured_at
  );

  if coalesce((v_response->>'ok')::boolean, false) is false then
    return v_response;
  end if;

  v_suggestion_id := case
    when nullif(v_response->>'suggestion_id', '') is null then null
    else (v_response->>'suggestion_id')::uuid
  end;

  if v_idempotency_key is not null then
    insert into public.client_mutation_idempotency_keys(
      user_id,
      action,
      idempotency_key,
      response,
      resource_type,
      resource_id
    )
    values (
      v_user_id,
      'submit_menu_item_price_suggestion_v5',
      v_idempotency_key,
      v_response,
      'menu_price_suggestion',
      v_suggestion_id
    )
    on conflict (user_id, action, idempotency_key) do update
    set response = excluded.response,
        resource_type = excluded.resource_type,
        resource_id = excluded.resource_id;
  end if;

  return v_response;
end;
$$;


ALTER FUNCTION "public"."submit_menu_item_price_suggestion_v5"("p_menu_item_id" "uuid", "p_suggested_price_cents" integer, "p_currency" "text", "p_note" "text", "p_evidence_url" "text", "p_client_id" "text", "p_captured_at" timestamp with time zone, "p_idempotency_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."submit_menu_item_suggestion_v1"("p_business_id" "uuid", "p_menu_item_id" "uuid", "p_action" "text", "p_payload" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  if auth.uid() is null then
    return jsonb_build_object('ok', false, 'error', 'not_authenticated');
  end if;

  insert into public.menu_item_suggestions(business_id, menu_item_id, action, payload, created_by)
  values (p_business_id, p_menu_item_id, p_action, p_payload, auth.uid());

  return jsonb_build_object('ok', true);
end;
$$;


ALTER FUNCTION "public"."submit_menu_item_suggestion_v1"("p_business_id" "uuid", "p_menu_item_id" "uuid", "p_action" "text", "p_payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."submit_menu_item_suggestion_v2"("p_business_id" "uuid", "p_menu_item_id" "uuid", "p_action" "text", "p_payload" "jsonb", "p_idempotency_key" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_user_id uuid := auth.uid();
  v_action text := nullif(trim(public.sanitize_plain_text_v1(p_action)), '');
  v_payload jsonb := coalesce(p_payload, '{}'::jsonb);
  v_idempotency_key text := nullif(trim(coalesce(p_idempotency_key, '')), '');
  v_cached_response jsonb;
  v_response jsonb;
  v_suggestion_id uuid;
begin
  if v_user_id is null then
    return jsonb_build_object('ok', false, 'error', 'not_authenticated');
  end if;

  if v_action is null then
    return jsonb_build_object('ok', false, 'error', 'action_required');
  end if;

  if v_idempotency_key is not null then
    perform pg_advisory_xact_lock(
      hashtext('submit_menu_item_suggestion_v2'),
      hashtext(v_user_id::text || ':' || v_idempotency_key)
    );

    select k.response
      into v_cached_response
    from public.client_mutation_idempotency_keys k
    where k.user_id = v_user_id
      and k.action = 'submit_menu_item_suggestion_v2'
      and k.idempotency_key = v_idempotency_key
    limit 1;

    if v_cached_response is not null then
      return v_cached_response;
    end if;
  end if;

  insert into public.menu_item_suggestions(
    business_id,
    menu_item_id,
    action,
    payload,
    created_by
  )
  values (
    p_business_id,
    p_menu_item_id,
    v_action,
    v_payload,
    v_user_id
  )
  returning id into v_suggestion_id;

  v_response := jsonb_build_object(
    'ok', true,
    'suggestion_id', v_suggestion_id
  );

  if v_idempotency_key is not null then
    insert into public.client_mutation_idempotency_keys(
      user_id,
      action,
      idempotency_key,
      response,
      resource_type,
      resource_id
    )
    values (
      v_user_id,
      'submit_menu_item_suggestion_v2',
      v_idempotency_key,
      v_response,
      'menu_item_suggestion',
      v_suggestion_id
    )
    on conflict (user_id, action, idempotency_key) do update
    set response = excluded.response,
        resource_type = excluded.resource_type,
        resource_id = excluded.resource_id;
  end if;

  return v_response;
end;
$$;


ALTER FUNCTION "public"."submit_menu_item_suggestion_v2"("p_business_id" "uuid", "p_menu_item_id" "uuid", "p_action" "text", "p_payload" "jsonb", "p_idempotency_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."submit_mission_proof_v1"("p_mission_id" "uuid", "p_photo_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_claim_id uuid;
  v_business_id uuid;
  v_photo_business uuid;
begin
  if auth.uid() is null then
    return jsonb_build_object('ok', false, 'code', 'not_authenticated');
  end if;

  select business_id into v_business_id
  from public.photo_missions
  where id = p_mission_id;

  if v_business_id is null then
    return jsonb_build_object('ok', false, 'code', 'not_found');
  end if;

  select business_id into v_photo_business
  from public.menu_item_photos
  where id = p_photo_id;

  if v_photo_business is null or v_photo_business <> v_business_id then
    return jsonb_build_object('ok', false, 'code', 'invalid_photo');
  end if;

  select id into v_claim_id
  from public.user_mission_claims
  where mission_id = p_mission_id and user_id = auth.uid();

  if v_claim_id is null then
    return jsonb_build_object('ok', false, 'code', 'not_claimed');
  end if;

  update public.user_mission_claims
  set status = 'submitted',
      photo_id = p_photo_id,
      updated_at = now()
  where id = v_claim_id;

  return jsonb_build_object('ok', true, 'claim_id', v_claim_id);
end;
$$;


ALTER FUNCTION "public"."submit_mission_proof_v1"("p_mission_id" "uuid", "p_photo_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."submit_moderation_appeal_v1"("p_source_type" "text", "p_source_id" "uuid", "p_reason" "text", "p_details" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_uid uuid := auth.uid();
  v_appeal_id uuid;
begin
  if v_uid is null then
    return jsonb_build_object('ok', false, 'error', 'not_authenticated');
  end if;

  if coalesce(trim(p_source_type), '') not in ('report', 'claim') then
    return jsonb_build_object('ok', false, 'error', 'invalid_source_type');
  end if;
  if p_source_id is null then
    return jsonb_build_object('ok', false, 'error', 'missing_source_id');
  end if;
  if coalesce(trim(p_reason), '') = '' then
    return jsonb_build_object('ok', false, 'error', 'reason_required');
  end if;

  if exists (
    select 1
    from public.moderation_appeals a
    where a.source_type = p_source_type
      and a.source_id = p_source_id
      and a.appellant_user_id = v_uid
      and a.status = 'pending'
  ) then
    return jsonb_build_object('ok', false, 'error', 'appeal_already_pending');
  end if;

  insert into public.moderation_appeals(
    source_type,
    source_id,
    appellant_user_id,
    reason,
    details
  )
  values (
    trim(p_source_type),
    p_source_id,
    v_uid,
    left(trim(p_reason), 120),
    nullif(trim(coalesce(p_details, '')), '')
  )
  returning id into v_appeal_id;

  return jsonb_build_object('ok', true, 'appeal_id', v_appeal_id);
end;
$$;


ALTER FUNCTION "public"."submit_moderation_appeal_v1"("p_source_type" "text", "p_source_id" "uuid", "p_reason" "text", "p_details" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."submit_owner_claim_v1"("p_business_id" "uuid", "p_full_name" "text", "p_phone" "text", "p_evidence_url" "text" DEFAULT NULL::"text", "p_note" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_uid uuid := auth.uid();
  v_recent_exists boolean;
  v_claim_id uuid;
begin
  if v_uid is null then
    return jsonb_build_object('ok', false, 'error', 'not_authenticated');
  end if;

  if p_business_id is null then
    return jsonb_build_object('ok', false, 'error', 'missing_business_id');
  end if;

  -- 7 gün rate limit (aynı business için)
  select exists(
    select 1
    from public.owner_claims
    where user_id = v_uid
      and business_id = p_business_id
      and created_at >= now() - interval '7 days'
  ) into v_recent_exists;

  if v_recent_exists then
    return jsonb_build_object('ok', false, 'error', 'rate_limited_7d');
  end if;

  insert into public.owner_claims(
    user_id, business_id, full_name, phone, evidence_url, note, status
  ) values (
    v_uid, p_business_id,
    nullif(trim(p_full_name),''),
    nullif(trim(p_phone),''),
    nullif(trim(p_evidence_url),''),
    nullif(trim(p_note),''),
    'pending'
  )
  returning id into v_claim_id;

  return jsonb_build_object('ok', true, 'claim_id', v_claim_id);
exception
  when unique_violation then
    -- unique constraint'a takılırsa user aynı business'e daha önce başvurmuş demektir
    return jsonb_build_object('ok', false, 'error', 'already_submitted');
end;
$$;


ALTER FUNCTION "public"."submit_owner_claim_v1"("p_business_id" "uuid", "p_full_name" "text", "p_phone" "text", "p_evidence_url" "text", "p_note" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."submit_presence_v1"("p_business_id" "uuid", "p_crowd" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_last timestamptz;
begin
  if auth.uid() is null then
    return jsonb_build_object('ok', false, 'error', 'not_authenticated');
  end if;

  if p_crowd not in ('quiet','normal','busy') then
    return jsonb_build_object('ok', false, 'error', 'bad_crowd');
  end if;

  select max(created_at) into v_last
  from public.business_presence_events
  where business_id = p_business_id and user_id = auth.uid();

  if v_last is not null and v_last > now() - interval '15 minutes' then
    return jsonb_build_object('ok', false, 'error', 'rate_limited_15m');
  end if;

  insert into public.business_presence_events(business_id, user_id, crowd)
  values (p_business_id, auth.uid(), p_crowd::public.crowd_level);

  return jsonb_build_object('ok', true);
end;
$$;


ALTER FUNCTION "public"."submit_presence_v1"("p_business_id" "uuid", "p_crowd" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."submit_presence_v2"("p_business_id" "uuid", "p_crowd" "text", "p_idempotency_key" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_user_id uuid := auth.uid();
  v_idempotency_key text := nullif(trim(coalesce(p_idempotency_key, '')), '');
  v_cached_response jsonb;
  v_response jsonb;
  v_last timestamptz;
begin
  if v_user_id is null then
    return jsonb_build_object('ok', false, 'error', 'not_authenticated');
  end if;

  if p_business_id is null then
    return jsonb_build_object('ok', false, 'error', 'business_required');
  end if;

  if p_crowd not in ('quiet','normal','busy') then
    return jsonb_build_object('ok', false, 'error', 'bad_crowd');
  end if;

  if v_idempotency_key is not null then
    perform pg_advisory_xact_lock(
      hashtext('submit_presence_v2'),
      hashtext(v_user_id::text || ':' || v_idempotency_key)
    );

    select k.response
      into v_cached_response
    from public.client_mutation_idempotency_keys k
    where k.user_id = v_user_id
      and k.action = 'submit_presence_v2'
      and k.idempotency_key = v_idempotency_key
    limit 1;

    if v_cached_response is not null then
      return v_cached_response;
    end if;
  end if;

  select max(created_at)
    into v_last
  from public.business_presence_events
  where business_id = p_business_id
    and user_id = v_user_id;

  if v_last is not null and v_last > now() - interval '15 minutes' then
    return jsonb_build_object('ok', false, 'error', 'rate_limited_15m');
  end if;

  insert into public.business_presence_events(business_id, user_id, crowd)
  values (p_business_id, v_user_id, p_crowd::public.crowd_level);

  v_response := jsonb_build_object(
    'ok', true,
    'crowd', p_crowd,
    'mode', 'insert'
  );

  if v_idempotency_key is not null then
    insert into public.client_mutation_idempotency_keys(
      user_id,
      action,
      idempotency_key,
      response,
      resource_type,
      resource_id
    )
    values (
      v_user_id,
      'submit_presence_v2',
      v_idempotency_key,
      v_response,
      'business_presence',
      p_business_id
    )
    on conflict (user_id, action, idempotency_key) do update
    set response = excluded.response,
        resource_type = excluded.resource_type,
        resource_id = excluded.resource_id;
  end if;

  return v_response;
end;
$$;


