CREATE OR REPLACE FUNCTION "public"."submit_report_v1"("p_business_id" "uuid" DEFAULT NULL::"uuid", "p_review_id" "uuid" DEFAULT NULL::"uuid", "p_reason" "text" DEFAULT 'other'::"text", "p_details" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_uid uuid := auth.uid();
  v_recent_exists boolean;
  v_report_id uuid;
begin
  if v_uid is null then
    return jsonb_build_object('ok', false, 'error', 'not_authenticated');
  end if;

  if p_business_id is null and p_review_id is null then
    return jsonb_build_object('ok', false, 'error', 'missing_target');
  end if;

  -- 24 saat rate limit:
  if p_business_id is not null then
    select exists(
      select 1
      from public.reports
      where user_id = v_uid
        and business_id = p_business_id
        and created_at >= now() - interval '24 hours'
    ) into v_recent_exists;
  else
    select exists(
      select 1
      from public.reports
      where user_id = v_uid
        and review_id = p_review_id
        and created_at >= now() - interval '24 hours'
    ) into v_recent_exists;
  end if;

  if v_recent_exists then
    return jsonb_build_object('ok', false, 'error', 'rate_limited_24h');
  end if;

  insert into public.reports(user_id, business_id, review_id, reason, details)
  values (v_uid, p_business_id, p_review_id, coalesce(nullif(trim(p_reason),''),'other'), nullif(trim(p_details),''))
  returning id into v_report_id;

  return jsonb_build_object('ok', true, 'report_id', v_report_id);
end;
$$;


ALTER FUNCTION "public"."submit_report_v1"("p_business_id" "uuid", "p_review_id" "uuid", "p_reason" "text", "p_details" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."submit_report_v1"("p_business_id" "uuid" DEFAULT NULL::"uuid", "p_review_id" "uuid" DEFAULT NULL::"uuid", "p_menu_item_photo_id" "uuid" DEFAULT NULL::"uuid", "p_reason" "text" DEFAULT 'other'::"text", "p_details" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_uid uuid := auth.uid();
  v_recent_exists boolean;
  v_report_id uuid;
  v_target_type text;
  v_target_id uuid;
  v_business_id uuid;
  v_review_id uuid;
  v_photo_id uuid;
  v_reason text := coalesce(nullif(public.sanitize_plain_text_v1(p_reason), ''), 'other');
  v_details text := nullif(public.sanitize_plain_text_v1(p_details), '');
begin
  if v_uid is null then
    return jsonb_build_object('ok', false, 'error', 'not_authenticated');
  end if;

  if p_business_id is null and p_review_id is null and p_menu_item_photo_id is null then
    return jsonb_build_object('ok', false, 'error', 'missing_target');
  end if;

  if p_menu_item_photo_id is not null then
    v_target_type := 'menu_item_photo';
    v_target_id := p_menu_item_photo_id;
    v_photo_id := p_menu_item_photo_id;
    select business_id into v_business_id
    from public.menu_item_photos
    where id = p_menu_item_photo_id;
    if v_business_id is null then
      return jsonb_build_object('ok', false, 'error', 'photo_not_found');
    end if;
  elsif p_review_id is not null then
    v_target_type := 'review';
    v_target_id := p_review_id;
    v_review_id := p_review_id;
  else
    v_target_type := 'business';
    v_target_id := p_business_id;
    v_business_id := p_business_id;
  end if;

  if v_target_type = 'business' then
    select exists(
      select 1
      from public.reports
      where user_id = v_uid
        and business_id = v_business_id
        and created_at >= now() - interval '24 hours'
    ) into v_recent_exists;
  elsif v_target_type = 'review' then
    select exists(
      select 1
      from public.reports
      where user_id = v_uid
        and review_id = v_review_id
        and created_at >= now() - interval '24 hours'
    ) into v_recent_exists;
  else
    select exists(
      select 1
      from public.reports
      where user_id = v_uid
        and menu_item_photo_id = v_photo_id
        and created_at >= now() - interval '24 hours'
    ) into v_recent_exists;
  end if;

  if v_recent_exists then
    return jsonb_build_object('ok', false, 'error', 'rate_limited_24h');
  end if;

  insert into public.reports(
    user_id,
    business_id,
    review_id,
    menu_item_photo_id,
    target_type,
    target_id,
    reason,
    details
  )
  values (
    v_uid,
    v_business_id,
    v_review_id,
    v_photo_id,
    v_target_type,
    v_target_id,
    v_reason,
    v_details
  )
  returning id into v_report_id;

  return jsonb_build_object('ok', true, 'report_id', v_report_id);
end;
$$;


