      and r.created_at >= now() - interval '24 hours';

    if v_recent_count >= 2 then
      return jsonb_build_object('ok', false, 'error', 'new_account_rate_limited');
    end if;
  end if;

  select count(*)
    into v_same_business_count
  from public.reviews r
  where r.user_id = v_user_id
    and r.business_id = p_business_id
    and r.created_at >= now() - interval '12 hours';

  if v_same_business_count > 0 then
    return jsonb_build_object('ok', false, 'error', 'same_business_cooldown');
  end if;

  v_shadow := public.is_shadow_banned_v1();
  v_status := case
    when v_shadow or v_has_contact or v_has_profanity then 'pending'
    else 'approved'
  end;

  insert into public.reviews(
    business_id, user_id, rating, title, content, status
  ) values (
    p_business_id, v_user_id, p_rating, v_title, v_content, v_status
  )
  returning id into v_review_id;

  v_response := jsonb_build_object(
    'ok', true,
    'review_id', v_review_id,
    'shadowed', v_shadow,
    'pending', v_status = 'pending',
    'contains_contact', v_has_contact,
    'contains_profanity', v_has_profanity
  );

  if v_idempotency_key is not null then
    insert into public.client_mutation_idempotency_keys(
      user_id,
      action,
      idempotency_key,
      response,
      resource_type,
      resource_id
    )
    values (
      v_user_id,
      'submit_review_v2',
      v_idempotency_key,
      v_response,
      'review',
      v_review_id
    )
    on conflict (user_id, action, idempotency_key) do update
    set response = excluded.response,
        resource_type = excluded.resource_type,
        resource_id = excluded.resource_id;
  end if;

  return v_response;
end;
$$;


ALTER FUNCTION "public"."submit_review_v2"("p_business_id" "uuid", "p_rating" integer, "p_title" "text", "p_content" "text", "p_idempotency_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."submit_review_v3"("p_business_id" "uuid", "p_overall_rating" integer, "p_title" "text" DEFAULT NULL::"text", "p_content" "text" DEFAULT NULL::"text", "p_taste_rating" integer DEFAULT NULL::integer, "p_service_speed_rating" integer DEFAULT NULL::integer, "p_price_performance_rating" integer DEFAULT NULL::integer, "p_cleanliness_rating" integer DEFAULT NULL::integer, "p_atmosphere_rating" integer DEFAULT NULL::integer, "p_idempotency_key" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_user_id uuid := auth.uid();
  v_content text := public.sanitize_plain_text_v1(p_content);
  v_title text := nullif(public.sanitize_plain_text_v1(p_title), '');
  v_profile_created_at timestamptz;
  v_recent_count int := 0;
  v_same_business_count int := 0;
  v_shadow boolean := false;
  v_rate jsonb;
  v_has_contact boolean := false;
  v_has_profanity boolean := false;
  v_status text := 'approved';
  v_idempotency_key text := nullif(trim(coalesce(p_idempotency_key, '')), '');
  v_cached_response jsonb;
  v_response jsonb;
  v_review_id uuid;
begin
  if v_user_id is null then
    return jsonb_build_object('ok', false, 'error', 'not_authenticated');
  end if;

  if v_idempotency_key is not null then
    perform pg_advisory_xact_lock(
      hashtext('submit_review_v3'),
      hashtext(v_user_id::text || ':' || v_idempotency_key)
    );

    select k.response
      into v_cached_response
    from public.client_mutation_idempotency_keys k
    where k.user_id = v_user_id
      and k.action = 'submit_review_v3'
      and k.idempotency_key = v_idempotency_key
    limit 1;

    if v_cached_response is not null then
      return v_cached_response;
    end if;
  end if;

  if p_business_id is null then
    return jsonb_build_object('ok', false, 'error', 'business_required');
  end if;

  if p_overall_rating < 1 or p_overall_rating > 5 then
    return jsonb_build_object('ok', false, 'error', 'bad_rating');
  end if;

  if p_taste_rating is not null and (p_taste_rating < 1 or p_taste_rating > 5) then
    return jsonb_build_object('ok', false, 'error', 'bad_taste_rating');
  end if;

  if p_service_speed_rating is not null and (p_service_speed_rating < 1 or p_service_speed_rating > 5) then
    return jsonb_build_object('ok', false, 'error', 'bad_service_speed_rating');
  end if;

  if p_price_performance_rating is not null and (p_price_performance_rating < 1 or p_price_performance_rating > 5) then
    return jsonb_build_object('ok', false, 'error', 'bad_price_performance_rating');
  end if;

  if p_cleanliness_rating is not null and (p_cleanliness_rating < 1 or p_cleanliness_rating > 5) then
    return jsonb_build_object('ok', false, 'error', 'bad_cleanliness_rating');
  end if;

  if p_atmosphere_rating is not null and (p_atmosphere_rating < 1 or p_atmosphere_rating > 5) then
    return jsonb_build_object('ok', false, 'error', 'bad_atmosphere_rating');
  end if;

  if length(v_content) < 8 then
    return jsonb_build_object('ok', false, 'error', 'content_too_short');
  end if;

  if length(regexp_replace(v_content, '[[:alnum:][:space:]]', '', 'g')) > 12 then
    return jsonb_build_object('ok', false, 'error', 'emoji_spam');
  end if;

  v_has_contact := public.contains_contact_or_url_v1(coalesce(p_content, ''))
    or public.contains_contact_or_url_v1(v_content);

  v_has_profanity := public.contains_obfuscated_profanity_v1(v_content)
    or public.contains_obfuscated_profanity_v1(coalesce(v_title, ''));

  if v_has_contact then
    v_content := public.mask_contact_tokens_v1(v_content);
    v_title := nullif(public.mask_contact_tokens_v1(coalesce(v_title, '')), '');
  end if;

  v_rate := public.consume_rate_limit_v1('review', 15);
  if coalesce((v_rate->>'ok')::boolean, false) is false then
    return jsonb_build_object('ok', false, 'error', 'review_daily_rate_limited');
  end if;

  select up.created_at
    into v_profile_created_at
  from public.user_profiles up
  where up.user_id = v_user_id;

  if v_profile_created_at is not null and v_profile_created_at >= now() - interval '7 days' then
    select count(*)
      into v_recent_count
    from public.reviews r
    where r.user_id = v_user_id
      and r.created_at >= now() - interval '24 hours';

    if v_recent_count >= 2 then
      return jsonb_build_object('ok', false, 'error', 'new_account_rate_limited');
    end if;
  end if;

  select count(*)
    into v_same_business_count
  from public.reviews r
  where r.user_id = v_user_id
    and r.business_id = p_business_id
    and r.created_at >= now() - interval '12 hours';

  if v_same_business_count > 0 then
    return jsonb_build_object('ok', false, 'error', 'same_business_cooldown');
  end if;

  v_shadow := public.is_shadow_banned_v1();
  v_status := case
    when v_shadow or v_has_contact or v_has_profanity then 'pending'
    else 'approved'
  end;

  insert into public.reviews(
    business_id,
    user_id,
    rating,
    overall_rating,
    taste_rating,
    service_speed_rating,
    price_performance_rating,
    cleanliness_rating,
    atmosphere_rating,
    title,
    content,
    status
  ) values (
    p_business_id,
    v_user_id,
    p_overall_rating,
    p_overall_rating,
    p_taste_rating,
    p_service_speed_rating,
    p_price_performance_rating,
    p_cleanliness_rating,
    p_atmosphere_rating,
    v_title,
    v_content,
    v_status
  )
  returning id into v_review_id;

  v_response := jsonb_build_object(
    'ok', true,
    'review_id', v_review_id,
    'shadowed', v_shadow,
    'pending', v_status = 'pending',
    'contains_contact', v_has_contact,
    'contains_profanity', v_has_profanity,
    'has_detailed_ratings',
      (p_taste_rating is not null
        or p_service_speed_rating is not null
        or p_price_performance_rating is not null
        or p_cleanliness_rating is not null
        or p_atmosphere_rating is not null)
  );

  if v_idempotency_key is not null then
    insert into public.client_mutation_idempotency_keys(
      user_id,
      action,
      idempotency_key,
      response,
      resource_type,
      resource_id
    )
    values (
      v_user_id,
      'submit_review_v3',
      v_idempotency_key,
      v_response,
      'review',
      v_review_id
    )
    on conflict (user_id, action, idempotency_key) do update
    set response = excluded.response,
        resource_type = excluded.resource_type,
        resource_id = excluded.resource_id;
  end if;

  return v_response;
end;
$$;


ALTER FUNCTION "public"."submit_review_v3"("p_business_id" "uuid", "p_overall_rating" integer, "p_title" "text", "p_content" "text", "p_taste_rating" integer, "p_service_speed_rating" integer, "p_price_performance_rating" integer, "p_cleanliness_rating" integer, "p_atmosphere_rating" integer, "p_idempotency_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."submit_sponsorship_lead_v1"("p_business_id" "uuid", "p_phone" "text", "p_message" "text", "p_preferred_surface" "text", "p_preferred_targeting" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_id uuid;
begin
  if auth.uid() is null then
    return jsonb_build_object('ok', false, 'code', 'not_authenticated', 'message', 'Auth required');
  end if;

  if not public.is_owner_of_business(p_business_id) then
    return jsonb_build_object('ok', false, 'code', 'not_owner', 'message', 'Not owner');
  end if;

  insert into public.sponsorship_leads(
    business_id,
    owner_user_id,
    phone,
    message,
    preferred_surface,
    preferred_targeting
  )
  values (
    p_business_id,
    auth.uid(),
    nullif(trim(p_phone), ''),
    nullif(trim(p_message), ''),
    p_preferred_surface,
    coalesce(p_preferred_targeting, '{}'::jsonb)
  )
  returning id into v_id;

  return jsonb_build_object('ok', true, 'id', v_id, 'message', 'Submitted');
end;
$$;


ALTER FUNCTION "public"."submit_sponsorship_lead_v1"("p_business_id" "uuid", "p_phone" "text", "p_message" "text", "p_preferred_surface" "text", "p_preferred_targeting" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."submit_suspended_meal_claim_v1"("p_suspended_meal_id" "uuid", "p_note" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_status public.suspended_meal_status;
  v_note text;
begin
  if auth.uid() is null then
    return jsonb_build_object('ok', false, 'error', 'not_authenticated');
  end if;

  v_note := nullif(trim(p_note), '');

  select status into v_status
  from public.suspended_meals
  where id = p_suspended_meal_id;

  if v_status is null then
    return jsonb_build_object('ok', false, 'error', 'not_found');
  end if;

  if v_status <> 'active' then
    return jsonb_build_object('ok', false, 'error', 'not_active');
  end if;

  -- aynı kullanıcı aynı meal’e tekrar claim atamasın
  if exists (
    select 1 from public.suspended_meal_claims
    where suspended_meal_id = p_suspended_meal_id
      and claimant_user_id = auth.uid()
  ) then
    return jsonb_build_object('ok', false, 'error', 'already_claimed');
  end if;

  insert into public.suspended_meal_claims(suspended_meal_id, claimant_user_id, note)
  values (p_suspended_meal_id, auth.uid(), v_note);

  return jsonb_build_object('ok', true);
end;
$$;


ALTER FUNCTION "public"."submit_suspended_meal_claim_v1"("p_suspended_meal_id" "uuid", "p_note" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."submit_table_feedback_v1"("p_business_id" "uuid", "p_table_no" "text", "p_rating" integer, "p_note" "text" DEFAULT NULL::"text", "p_client_id" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_rating int := coalesce(p_rating, 0);
  v_table text := nullif(trim(p_table_no), '');
  v_client text := nullif(trim(p_client_id), '');
  v_key text;
  v_today date := current_date;
  v_current_count int;
  v_user_id uuid := coalesce(auth.uid(), '00000000-0000-0000-0000-000000000000'::uuid);
begin
  if p_business_id is null then
    return jsonb_build_object('ok', false, 'code', 'invalid_business');
  end if;

  if v_table is null then
    return jsonb_build_object('ok', false, 'code', 'table_required');
  end if;

  if v_rating < 1 or v_rating > 5 then
    return jsonb_build_object('ok', false, 'code', 'invalid_rating');
  end if;

  if v_client is null then
    return jsonb_build_object('ok', false, 'code', 'client_required');
  end if;

  v_key := format('table_feedback:%s:%s', v_client, v_today::text);
  select count into v_current_count
  from public.user_rate_limits
  where key = v_key;

  if coalesce(v_current_count, 0) >= 10 then
    return jsonb_build_object('ok', false, 'code', 'rate_limited');
  end if;

  insert into public.user_rate_limits (key, user_id, action, day, count, updated_at)
  values (v_key, v_user_id, 'table_feedback', v_today, 1, now())
  on conflict (key) do update
    set count = public.user_rate_limits.count + 1,
        updated_at = now();

  insert into public.table_feedback (
    business_id,
    table_no,
    rating,
    note,
    created_at,
    client_id
  ) values (
    p_business_id,
    v_table,
    v_rating,
    nullif(trim(p_note), ''),
    now(),
    v_client
  );

  return jsonb_build_object('ok', true);
end;
$$;


ALTER FUNCTION "public"."submit_table_feedback_v1"("p_business_id" "uuid", "p_table_no" "text", "p_rating" integer, "p_note" "text", "p_client_id" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sync_review_overall_rating_v1"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
begin
  new.overall_rating := coalesce(new.overall_rating, new.rating::smallint);
  new.rating := coalesce(new.overall_rating, new.rating::smallint)::integer;
  return new;
end;
$$;


ALTER FUNCTION "public"."sync_review_overall_rating_v1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."taste_recommendations_from_match_v1"("p_match_user_id" "uuid", "p_limit" integer DEFAULT 10) RETURNS TABLE("business_id" "uuid", "business_name" "text", "city" "text", "district" "text", "match_rating" integer, "match_review_title" "text", "match_review_excerpt" "text")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  with my_seen as (
    select distinct business_id
    from public.reviews
    where user_id = auth.uid()
      and status='approved'
  ),
  match_loved as (
    select r.business_id, r.rating, r.title, r.content
    from public.reviews r
    where r.user_id = p_match_user_id
      and r.status='approved'
      and r.rating >= 5
  )
  select
    b.id as business_id,
    b.name as business_name,
    b.city,
    b.district,
    ml.rating as match_rating,
    ml.title as match_review_title,
    left(ml.content, 140) as match_review_excerpt
  from match_loved ml
  join public.businesses b on b.id = ml.business_id
  left join my_seen ms on ms.business_id = ml.business_id
  where ms.business_id is null
  order by ml.rating desc, b.name asc
  limit greatest(p_limit,0);
$$;


