CREATE OR REPLACE FUNCTION "public"."taste_recommendations_from_match_v2"("p_match_user_id" "uuid", "p_limit" integer DEFAULT 10) RETURNS TABLE("business_id" "uuid", "business_name" "text", "city" "text", "district" "text", "match_rating" integer, "match_review_title" "text", "match_review_excerpt" "text", "match_review_created_at" timestamp with time zone)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  with my_seen as (
    select distinct business_id
    from public.reviews
    where user_id = auth.uid()
      and status='approved'
  ),
  match_loved as (
    select r.business_id, r.rating, r.title, r.content, r.created_at
    from public.reviews r
    where r.user_id = p_match_user_id
      and r.status='approved'
      and r.rating >= 5
  )
  select
    b.id as business_id,
    b.name as business_name,
    b.city,
