CREATE OR REPLACE FUNCTION "public"."toggle_collection_follow_v1"("p_collection_key" "text") RETURNS TABLE("is_following" boolean, "followers_count" integer)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $$
declare
  v_exists boolean;
begin
  select exists(
    select 1
    from public.user_collection_follows
    where user_id = auth.uid()
      and collection_key = p_collection_key
  ) into v_exists;

  if v_exists then
    delete from public.user_collection_follows
    where user_id = auth.uid()
      and collection_key = p_collection_key;

    insert into public.collection_social_stats(collection_key)
    values (p_collection_key)
    on conflict (collection_key) do nothing;

    update public.collection_social_stats
      set followers_count = greatest(followers_count - 1, 0),
          updated_at = now()
    where collection_key = p_collection_key;

    return query
      select false, followers_count
      from public.collection_social_stats
      where collection_key = p_collection_key;
  else
    insert into public.user_collection_follows(user_id, collection_key)
    values (auth.uid(), p_collection_key)
    on conflict do nothing;

    insert into public.collection_social_stats(collection_key)
    values (p_collection_key)
    on conflict (collection_key) do nothing;

    update public.collection_social_stats
      set followers_count = followers_count + 1,
          updated_at = now()
    where collection_key = p_collection_key;

    return query
      select true, followers_count
      from public.collection_social_stats
      where collection_key = p_collection_key;
  end if;
end;
$$;


ALTER FUNCTION "public"."toggle_collection_follow_v1"("p_collection_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."toggle_favorite_v1"("p_business_id" "uuid") RETURNS TABLE("is_favorited" boolean)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_uid uuid := auth.uid();
begin
  if v_uid is null then
    raise exception 'not_authenticated';
  end if;

  if exists (
    select 1
    from public.favorites
    where user_id = v_uid
      and business_id = p_business_id
  ) then
    delete from public.favorites
    where user_id = v_uid
      and business_id = p_business_id;

    return query select false;
  else
    insert into public.favorites(user_id, business_id)
    values (v_uid, p_business_id)
    on conflict (user_id, business_id) do nothing;

    return query select true;
  end if;
end;
$$;


ALTER FUNCTION "public"."toggle_favorite_v1"("p_business_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."toggle_follow_v1"("p_followee_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  if auth.uid() is null then
    return jsonb_build_object('ok', false, 'error', 'not_authenticated');
  end if;

  if p_followee_id = auth.uid() then
    return jsonb_build_object('ok', false, 'error', 'cannot_follow_self');
  end if;

  if exists (
    select 1 from public.user_follows
    where follower_id = auth.uid() and followee_id = p_followee_id
  ) then
    delete from public.user_follows
    where follower_id = auth.uid() and followee_id = p_followee_id;

    return jsonb_build_object('ok', true, 'following', false);
  else
    insert into public.user_follows(follower_id, followee_id)
    values (auth.uid(), p_followee_id);

    return jsonb_build_object('ok', true, 'following', true);
  end if;
end;
$$;


