      ),
      jsonb_build_object(
        'name', NEW.name,
        'category', NEW.category,
        'address', NEW.address,
        'phone', NEW.phone,
        'is_active', NEW.is_active,
        'is_verified', NEW.is_verified
      )
    );
  end if;
  return NEW;
end;
$$;


