CREATE OR REPLACE FUNCTION "public"."trg_audit_owner_claims_update_v1"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_action text := 'claim.updated';
begin
  if NEW.status is distinct from OLD.status then
    if NEW.status = 'approved' then
      v_action := 'claim.approved';
    elsif NEW.status = 'rejected' then
      v_action := 'claim.rejected';
    else
      v_action := 'claim.updated';
    end if;
  elsif NEW.assigned_to is distinct from OLD.assigned_to then
    v_action := 'claim.assigned';
  end if;

  if row(NEW.status, NEW.admin_note, NEW.handled_by, NEW.assigned_to)
     is distinct from
     row(OLD.status, OLD.admin_note, OLD.handled_by, OLD.assigned_to) then
    perform public.insert_audit_log_v1(
      v_action,
      'owner_claim',
      NEW.id,
      jsonb_build_object(
        'business_id', OLD.business_id,
        'user_id', OLD.user_id,
        'status', OLD.status,
        'admin_note', OLD.admin_note,
        'handled_by', OLD.handled_by,
        'assigned_to', OLD.assigned_to
      ),
      jsonb_build_object(
        'business_id', NEW.business_id,
        'user_id', NEW.user_id,
        'status', NEW.status,
        'admin_note', NEW.admin_note,
        'handled_by', NEW.handled_by,
        'assigned_to', NEW.assigned_to
      )
    );
  end if;

  return NEW;
end;
$$;


