CREATE OR REPLACE FUNCTION "public"."trg_require_verified_contact_v1"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_user_id uuid;
  v_role text := current_setting('request.jwt.claim.role', true);
  v_is_verified boolean := false;
begin
  if v_role = 'service_role' then
    return new;
  end if;

  if auth.uid() is null then
    return new;
  end if;

  v_user_id := coalesce(new.user_id, new.created_by, auth.uid());
  if v_user_id is null then
    raise exception 'contact_verification_required';
  end if;

  select
    (u.email_confirmed_at is not null or u.phone_confirmed_at is not null)
  into v_is_verified
  from auth.users u
  where u.id = v_user_id;

  if coalesce(v_is_verified, false) = false then
    raise exception 'contact_verification_required';
  end if;

  return new;
end;
$$;


ALTER FUNCTION "public"."trg_require_verified_contact_v1"() OWNER TO "postgres";


