CREATE OR REPLACE FUNCTION "public"."unregister_user_device_v1"("p_fcm_token" "text" DEFAULT NULL::"text") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_user_id uuid := auth.uid();
  v_count int := 0;
begin
  if v_user_id is null then
    raise exception 'not_authenticated';
  end if;

  if coalesce(trim(coalesce(p_fcm_token, '')), '') = '' then
    update public.user_devices
    set last_seen_at = now() - interval '365 days'
    where user_id = v_user_id;
    get diagnostics v_count = row_count;
    return v_count;
  end if;

  delete from public.user_devices
  where user_id = v_user_id
    and fcm_token = trim(p_fcm_token);
  get diagnostics v_count = row_count;
  return v_count;
end;
$$;


ALTER FUNCTION "public"."unregister_user_device_v1"("p_fcm_token" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_team_member_v1"("p_business_id" "uuid", "p_membership_id" "uuid", "p_role" "text", "p_scope" "text" DEFAULT 'this_business'::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_role text := lower(nullif(trim(coalesce(p_role, '')), ''));
  v_scope text := lower(nullif(trim(coalesce(p_scope, '')), ''));
  v_chain_id uuid;
begin
  if auth.uid() is null then
    return jsonb_build_object('ok', false, 'code', 'not_authenticated');
  end if;

  if not (public.is_admin() or public.has_business_permission_v1(p_business_id, 'team_manage')) then
    return jsonb_build_object('ok', false, 'code', 'forbidden');
  end if;

  if v_role not in ('owner', 'manager', 'editor', 'staff', 'viewer') then
    return jsonb_build_object('ok', false, 'code', 'invalid_role');
  end if;

  if v_scope not in ('this_business', 'all_branches') then
    return jsonb_build_object('ok', false, 'code', 'invalid_scope');
  end if;

  select b.chain_id
  into v_chain_id
  from public.businesses b
  where b.id = p_business_id;

  update public.business_team_memberships
  set
    business_id = case when v_scope = 'this_business' then p_business_id else null end,
    chain_id = case when v_scope = 'all_branches' then v_chain_id else null end,
    role = v_role,
    updated_at = now()
  where id = p_membership_id
    and revoked_at is null;

  insert into public.admin_audit_log(action, target_table, target_id, meta)
  values (
    'owner.team.update',
    'business_team_memberships',
    p_membership_id,
    jsonb_build_object(
      'actor_id', auth.uid(),
      'business_id', p_business_id,
      'role', v_role,
      'scope', v_scope
    )
  );

  return jsonb_build_object('ok', true);
end;
$$;


ALTER FUNCTION "public"."update_team_member_v1"("p_business_id" "uuid", "p_membership_id" "uuid", "p_role" "text", "p_scope" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."upsert_collection_share_v1"("p_collection_key" "text", "p_name" "text", "p_business_ids" "text"[]) RETURNS TABLE("slug" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $$
declare
  v_slug text;
begin
  select cs.slug
    into v_slug
  from public.collection_shares cs
  where cs.collection_key = p_collection_key
    and cs.created_by = auth.uid()
  limit 1;

  if v_slug is not null then
    return query select v_slug;
  end if;

  v_slug := substr(encode(gen_random_uuid(), 'hex'), 1, 10);

  insert into public.collection_shares(
    slug,
    collection_key,
    name,
    business_ids,
    created_by
  ) values (
    v_slug,
    p_collection_key,
    p_name,
    p_business_ids,
    auth.uid()
  );

  return query select v_slug;
end;
$$;


ALTER FUNCTION "public"."upsert_collection_share_v1"("p_collection_key" "text", "p_name" "text", "p_business_ids" "text"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."upsert_my_diet_profile_v1"("p_is_vegan" boolean, "p_is_vegetarian" boolean, "p_is_gluten_free" boolean, "p_is_lactose_free" boolean, "p_is_halal" boolean, "p_max_calories" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  if auth.uid() is null then
    return jsonb_build_object('ok', false, 'error', 'not_authenticated');
  end if;

  insert into public.user_diet_profiles(user_id,is_vegan,is_vegetarian,is_gluten_free,is_lactose_free,is_halal,max_calories)
  values (auth.uid(), p_is_vegan,p_is_vegetarian,p_is_gluten_free,p_is_lactose_free,p_is_halal,p_max_calories)
  on conflict (user_id) do update
    set is_vegan=excluded.is_vegan,
        is_vegetarian=excluded.is_vegetarian,
        is_gluten_free=excluded.is_gluten_free,
        is_lactose_free=excluded.is_lactose_free,
        is_halal=excluded.is_halal,
        max_calories=excluded.max_calories,
        updated_at=now();

  return jsonb_build_object('ok', true);
end;
$$;


ALTER FUNCTION "public"."upsert_my_diet_profile_v1"("p_is_vegan" boolean, "p_is_vegetarian" boolean, "p_is_gluten_free" boolean, "p_is_lactose_free" boolean, "p_is_halal" boolean, "p_max_calories" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."upsert_team_member_v1"("p_business_id" "uuid", "p_email" "text", "p_role" "text", "p_scope" "text" DEFAULT 'this_business'::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_email text := lower(nullif(trim(coalesce(p_email, '')), ''));
  v_role text := lower(nullif(trim(coalesce(p_role, '')), ''));
  v_scope text := lower(nullif(trim(coalesce(p_scope, '')), ''));
  v_chain_id uuid;
  v_user_id uuid;
  v_membership_id uuid;
begin
  if auth.uid() is null then
    return jsonb_build_object('ok', false, 'code', 'not_authenticated');
  end if;

  if not (public.is_admin() or public.has_business_permission_v1(p_business_id, 'team_manage')) then
    return jsonb_build_object('ok', false, 'code', 'forbidden');
  end if;

  if v_email is null then
    return jsonb_build_object('ok', false, 'code', 'email_required');
  end if;

  if v_role not in ('owner', 'manager', 'editor', 'staff', 'viewer') then
    return jsonb_build_object('ok', false, 'code', 'invalid_role');
  end if;

  if v_scope not in ('this_business', 'all_branches') then
    return jsonb_build_object('ok', false, 'code', 'invalid_scope');
  end if;

  select b.chain_id
  into v_chain_id
  from public.businesses b
  where b.id = p_business_id;

  if v_scope = 'all_branches' and v_chain_id is null then
    return jsonb_build_object('ok', false, 'code', 'chain_required');
  end if;

  select u.id
  into v_user_id
  from auth.users u
  where lower(u.email::text) = v_email
  limit 1;

  select btm.id
  into v_membership_id
  from public.business_team_memberships btm
  where btm.revoked_at is null
    and (
      (
        v_scope = 'this_business'
        and btm.business_id = p_business_id
      ) or (
        v_scope = 'all_branches'
        and btm.chain_id = v_chain_id
      )
    )
    and (
      (v_user_id is not null and btm.user_id = v_user_id)
      or lower(coalesce(btm.invite_email, '')) = v_email
    )
  order by btm.created_at desc
  limit 1;

  if v_membership_id is null then
    insert into public.business_team_memberships(
      business_id,
      chain_id,
      user_id,
      invite_email,
      role,
      created_by,
      accepted_at
    )
    values (
      case when v_scope = 'this_business' then p_business_id else null end,
      case when v_scope = 'all_branches' then v_chain_id else null end,
      v_user_id,
      v_email,
      v_role,
      auth.uid(),
      case when v_user_id is not null then now() else null end
    )
    returning id into v_membership_id;
  else
    update public.business_team_memberships
    set
      business_id = case when v_scope = 'this_business' then p_business_id else null end,
      chain_id = case when v_scope = 'all_branches' then v_chain_id else null end,
      user_id = coalesce(v_user_id, user_id),
      invite_email = v_email,
      role = v_role,
      accepted_at = case
        when v_user_id is not null then coalesce(accepted_at, now())
        else accepted_at
      end,
      revoked_at = null,
      updated_at = now()
    where id = v_membership_id;
  end if;

  insert into public.admin_audit_log(action, target_table, target_id, meta)
  values (
    'owner.team.upsert',
    'business_team_memberships',
    v_membership_id,
    jsonb_build_object(
      'actor_id', auth.uid(),
      'business_id', p_business_id,
      'email', v_email,
      'role', v_role,
      'scope', v_scope
    )
  );

  return jsonb_build_object('ok', true, 'membership_id', v_membership_id, 'linked_user_id', v_user_id);
end;
$$;


