CREATE OR REPLACE FUNCTION "public"."upsert_user_location_prefs_v1"("p_city" "text", "p_district" "text", "p_neighborhood" "text" DEFAULT NULL::"text", "p_mode" "text" DEFAULT 'auto'::"text", "p_lat" double precision DEFAULT NULL::double precision, "p_lng" double precision DEFAULT NULL::double precision) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_uid uuid := auth.uid();
  v_lat double precision := null;
  v_lng double precision := null;
begin
  if v_uid is null then
    return jsonb_build_object('ok', false, 'error', 'not_authenticated');
  end if;

  -- PII minimization: keep coarse location only if coordinates are sent.
  if p_lat is not null then
    v_lat := round((p_lat::numeric), 3)::double precision;
  end if;
  if p_lng is not null then
    v_lng := round((p_lng::numeric), 3)::double precision;
  end if;

  insert into public.user_location_prefs (
    user_id, city, district, neighborhood, mode, lat, lng, updated_at
  )
  values (
    v_uid,
    trim(coalesce(p_city, '')),
    trim(coalesce(p_district, '')),
    nullif(trim(coalesce(p_neighborhood, '')), ''),
    coalesce(nullif(trim(coalesce(p_mode, '')), ''), 'auto'),
    v_lat,
    v_lng,
    now()
  )
  on conflict (user_id) do update
    set city = excluded.city,
        district = excluded.district,
        neighborhood = excluded.neighborhood,
        mode = excluded.mode,
        lat = excluded.lat,
        lng = excluded.lng,
        updated_at = now();

  return jsonb_build_object('ok', true);
end;
$$;


ALTER FUNCTION "public"."upsert_user_location_prefs_v1"("p_city" "text", "p_district" "text", "p_neighborhood" "text", "p_mode" "text", "p_lat" double precision, "p_lng" double precision) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."vote_business_fee_v1"("p_business_id" "uuid", "p_field" "text", "p_value" boolean, "p_note" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_limit jsonb;
  v_day date := (now() at time zone 'utc')::date;
  v_key text := 'business_fee_vote:' || auth.uid()::text || ':' || p_field || ':' || v_day::text;
  v_row public.user_rate_limits%rowtype;
  v_yes int;
  v_no int;
  v_total int;
  v_majority boolean;
begin
  if auth.uid() is null then
    return jsonb_build_object('ok', false, 'error', 'not_authenticated');
  end if;

  if p_field not in ('cover','service','water') then
    return jsonb_build_object('ok', false, 'error', 'invalid_field');
  end if;

  -- rate limit (daily 10 per user)
  v_limit := public.consume_rate_limit_v1('business_fee_vote', 10);
  if (v_limit->>'ok')::boolean is false then
    return v_limit;
  end if;

  insert into public.business_fee_votes(business_id, user_id, field, value, note)
  values (p_business_id, auth.uid(), p_field, p_value, p_note);

  select
    count(*) filter (where value = true),
    count(*) filter (where value = false),
    count(*)
  into v_yes, v_no, v_total
  from public.business_fee_votes
  where business_id = p_business_id
    and field = p_field
    and created_at >= now() - interval '30 days';

  v_majority := case
    when v_total = 0 then null
    when v_yes >= v_no then true
    else false
  end;

  insert into public.business_fee_flags(business_id, updated_at)
  values (p_business_id, now())
  on conflict (business_id) do update
  set updated_at = excluded.updated_at;

  if p_field = 'cover' then
    update public.business_fee_flags
    set has_cover_charge = v_majority, updated_at = now()
    where business_id = p_business_id;
  elsif p_field = 'service' then
    update public.business_fee_flags
    set has_service_fee = v_majority, updated_at = now()
    where business_id = p_business_id;
  else
    update public.business_fee_flags
    set bottled_water_paid = v_majority, updated_at = now()
    where business_id = p_business_id;
  end if;

  return jsonb_build_object('ok', true);
exception
  when unique_violation then
    return jsonb_build_object('ok', false, 'error', 'rate_limited');
end;
$$;


ALTER FUNCTION "public"."vote_business_fee_v1"("p_business_id" "uuid", "p_field" "text", "p_value" boolean, "p_note" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."vote_menu_item_photo_v1"("p_photo_id" "uuid", "p_vote" smallint) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_prev smallint;
begin
  if auth.uid() is null then
    return jsonb_build_object('ok', false, 'error', 'not_authenticated');
  end if;

  if p_vote not in (-1,1) then
    return jsonb_build_object('ok', false, 'error', 'bad_vote');
  end if;

  select vote into v_prev
  from public.menu_item_photo_votes
  where photo_id = p_photo_id and user_id = auth.uid();

  if v_prev is null then
    insert into public.menu_item_photo_votes(photo_id, user_id, vote)
    values (p_photo_id, auth.uid(), p_vote);

    update public.menu_item_photos
    set up_votes = up_votes + case when p_vote=1 then 1 else 0 end,
        down_votes = down_votes + case when p_vote=-1 then 1 else 0 end
    where id = p_photo_id;

    return jsonb_build_object('ok', true, 'mode', 'insert', 'vote', p_vote);

  elsif v_prev = p_vote then
    -- toggle off
    delete from public.menu_item_photo_votes
    where photo_id = p_photo_id and user_id = auth.uid();

    update public.menu_item_photos
    set up_votes = up_votes - case when p_vote=1 then 1 else 0 end,
        down_votes = down_votes - case when p_vote=-1 then 1 else 0 end
    where id = p_photo_id;

    return jsonb_build_object('ok', true, 'mode', 'remove', 'vote', 0);

  else
    -- switch vote
    update public.menu_item_photo_votes
    set vote = p_vote
    where photo_id = p_photo_id and user_id = auth.uid();

    update public.menu_item_photos
    set up_votes = up_votes + case when p_vote=1 then 1 else -1 end,
        down_votes = down_votes + case when p_vote=-1 then 1 else -1 end
    where id = p_photo_id;

    return jsonb_build_object('ok', true, 'mode', 'switch', 'vote', p_vote);
  end if;
end;
$$;


ALTER FUNCTION "public"."vote_menu_item_photo_v1"("p_photo_id" "uuid", "p_vote" smallint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."vote_menu_item_price_v1"("p_menu_item_id" "uuid", "p_vote" smallint) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_prev smallint;
begin
  if auth.uid() is null then
    return jsonb_build_object('ok', false, 'error', 'not_authenticated');
  end if;

  if p_vote not in (-1,1) then
    return jsonb_build_object('ok', false, 'error', 'bad_vote');
  end if;

  select vote into v_prev
  from public.menu_item_price_votes
  where menu_item_id = p_menu_item_id and user_id = auth.uid();

  if v_prev is null then
    insert into public.menu_item_price_votes(menu_item_id, user_id, vote)
    values (p_menu_item_id, auth.uid(), p_vote);
    return jsonb_build_object('ok', true, 'mode', 'insert', 'vote', p_vote);

  elsif v_prev = p_vote then
    delete from public.menu_item_price_votes
    where menu_item_id = p_menu_item_id and user_id = auth.uid();
    return jsonb_build_object('ok', true, 'mode', 'remove', 'vote', 0);

  else
    update public.menu_item_price_votes
    set vote = p_vote, created_at = now()
    where menu_item_id = p_menu_item_id and user_id = auth.uid();
    return jsonb_build_object('ok', true, 'mode', 'switch', 'vote', p_vote);
  end if;
end;
$$;


ALTER FUNCTION "public"."vote_menu_item_price_v1"("p_menu_item_id" "uuid", "p_vote" smallint) OWNER TO "postgres";

