    CONSTRAINT "user_policy_acceptances_source_app_check" CHECK (("source_app" = ANY (ARRAY['mobile_flutter'::"text", 'panel_flutter_web'::"text", 'next'::"text"])))
);


ALTER TABLE "public"."user_policy_acceptances" OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."user_profile_progress" (
    "user_id" "uuid" NOT NULL,
    "total_xp" integer DEFAULT 0 NOT NULL,
    "level" integer DEFAULT 1 NOT NULL,
    "unlocked_count" integer DEFAULT 0 NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "user_profile_progress_level_check" CHECK (("level" >= 1)),
    CONSTRAINT "user_profile_progress_total_xp_check" CHECK (("total_xp" >= 0)),
    CONSTRAINT "user_profile_progress_unlocked_count_check" CHECK (("unlocked_count" >= 0))
);


ALTER TABLE "public"."user_profile_progress" OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."user_profiles" (
    "user_id" "uuid" NOT NULL,
    "display_name" "text" NOT NULL,
    "avatar_url" "text",
    "bio" "text",
    "is_gourmet" boolean DEFAULT false NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "shadow_banned" boolean DEFAULT false NOT NULL,
    CONSTRAINT "user_profiles_bio_len_chk" CHECK ((("bio" IS NULL) OR ("char_length"("bio") <= 280))),
    CONSTRAINT "user_profiles_display_name_len_chk" CHECK ((("display_name" IS NULL) OR ("char_length"("display_name") <= 60)))
);


